// 생성 파일. 직접 고치지 않는다. 원고 packages/seasonal/content/foods/*.md를 고치고 `pnpm foods:content`로 다시 만든다.
// 원고가 있는 품종 278개.

import type { FoodContent } from "./food-content"

export const FOOD_CONTENT: Readonly<Record<string, FoodContent>> = {
  "abalone": {"summary":"전복은 5~10월이 제철이고 8~10월에 가장 맛있어요. 껍데기와 살에 흠이 없고 통통한 것을 고르세요. 살과 내장 떼는 손질법과 보관법을 정리했어요.","origin":"남해안(양식)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"전복은 조개처럼 보이지만 소라, 달팽이와 같은 복족류로, 미역과 다시마를 먹고 자랍니다. 1960년대부터 양식을 시작해 지금은 남해안 양식 전복을 흔히 볼 수 있습니다. 해양수산부는 전복을 5월과 7월의 수산물로 골랐습니다. 장에서는 살아 있는 것인지, 양식인지 자연산인지 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"회로 먹으면 오돌오돌하고, 죽에 넣으면 쫄깃합니다. 해조류를 먹고 자라 내장에서 바다 향과 감칠맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍데기와 살에 흠집이 없는 것을 고르세요."},{"text":"살이 통통하게 찌고 탄력이 좋은 것이 싱싱합니다."},{"text":"껍데기가 울퉁불퉁하고 굴, 홍합, 해조류가 붙어 있으면 대개 자연산이고, 겉이 깨끗하면 대개 양식입니다. 다만 오래 기른 양식에도 붙을 수 있습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"살아 있는 전복은 5℃ 안팎 냉장에서 2~3일 둘 수 있고, 그보다 지나면 익혀 드세요. 더 오래 두려면 살과 내장을 떼어 냉동합니다."},{"label":"손질법","text":"소금을 살짝 뿌리고 솔로 껍데기와 발 부분을 문질러 씻습니다. 숟가락을 머리 쪽부터 밀어 넣어 내장이 터지지 않게 살을 떼고, 살에 붙은 이빨을 떼어 냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"전복죽. 부드럽게 퍼진 쌀알에 전복살과 내장을 넣어 끓입니다."},{"text":"버터 전복구이. 중불에 버터를 녹이고 편 썬 마늘과 손질한 전복을 노릇하게 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"우리 바다에는 북방전복(참전복), 둥근전복(까막전복), 말전복, 오분자기 등이 삽니다. 손질해 소분 냉동한 전복도 구이, 죽, 볶음에 그대로 쓸 수 있습니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 산삼 ‘전복’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=25483&select_list_no=84","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 5월 수산물 ‘전복’, ‘기름가자미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33539&select_list_no=42","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"여름철 바다의 보양식 ‘전복, 민어’ 이달의 수산물로 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=1175&menuSeq=971","checkedAt":"2026-11-12"}]},
  "adlay": {"summary":"율무는 9~10월이 제철이에요. 낟알이 튼실하고 윤기가 돌며 다른 냄새가 없는 것을 고르세요. 율무쌀과 현율무 차이, 국산 구별법과 냉동 보관법을 정리했어요.","origin":"연천·영월·제천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"율무는 껍질을 벗겨 밥이나 죽, 차로 먹는 잡곡입니다. 쌀처럼 하얗게 깎은 것을 율무쌀, 속껍질을 남긴 것을 현율무라고 부릅니다. 수입산도 함께 팔리니 빛깔과 골의 폭을 보고 구별하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"구수한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 완전히 제거되어 낟알이 튼실하고 윤기가 도는 것을 고르세요."},{"text":"고유의 향이 좋고 이물질이나 다른 냄새가 없어야 합니다."},{"text":"국산은 골의 폭이 좁고 연한 갈색입니다. 수입산은 골의 폭이 넓고 윤기와 찰기가 적습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"습기를 잘 빨아들이니 비닐팩에 밀봉해 냉동하세요. 냉장하면 상태나 향이 변할 수 있습니다."},{"label":"손질법","text":"도정 과정에서 이물질이 많이 들어가니 흐르는 물에 여러 번 문질러 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"율무밥. 율무쌀이나 현율무를 쌀과 섞어 짓습니다."},{"text":"율무차. 껍질째 볶아 달이거나 율무 가루를 따뜻한 물에 탑니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 연천, 영월, 제천을, 품종으로 조현, 상강, 밀양, 대청, 풍성, 율무1호를 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘율무’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219897&menuNo=300063","checkedAt":"2026-11-12"}]},
  "aengdu": {"summary":"앵두는 6~7월이 제철이에요. 윤기가 나고 손에 닿아도 무너지지 않는 탄탄한 알을 고르세요. 쉽게 무르는 앵두를 씻는 법과 앵두화채, 잼을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"앵두는 초여름에 만나는 작은 붉은 열매입니다. 한 알씩 먹으면 새콤한 즙과 부드러운 과육을 함께 느낄 수 있지만 알이 작아 씨를 빼는 데 시간이 걸립니다. 화채나 잼을 만들 때는 눌려 즙이 새는 열매부터 골라내고 나머지를 체에 받쳐 씻으면 으깨지는 알을 줄일 수 있습니다. 생과는 사 온 뒤 오래 두지 않고 먹는 편이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과즙이 많고 새콤달콤하며 과육이 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"겉에 윤기가 있는 것을 고르세요."},{"text":"손에 닿았을 때 무너지지 않고 탄탄한 알이 좋습니다."},{"text":"눌린 자국이나 즙이 샌 흔적을 살피세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생과는 얕은 용기에 담아 냉장하고 빨리 드세요. 잼용은 씨를 빼고 냉동할 수 있습니다."},{"label":"손질법","text":"체에 받쳐 흐르는 물로 가볍게 씻고 씨를 제거하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"앵두화채. 씨를 뺀 열매를 차가운 화채 국물에 띄웁니다."},{"text":"앵두잼. 과육을 설탕과 함께 약불에서 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"생앵두와 말린 앵두인 앵도육이 유통됩니다. 앵도육을 살 때는 포장일과 원산지 표시를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘앵두’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219955&pageIndex=1&selectMonth=6","checkedAt":"2026-11-12"}]},
  "aged-pumpkin": {"summary":"늙은 호박은 8~11월이 제철이에요. 껍질이 단단하고 골이 뚜렷하며 꼭지 주변이 무르지 않은 것을 고르세요. 통째 보관법과 호박죽, 호박전을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"늙은 호박은 충분히 익혀 거둔 호박으로 껍질이 단단하고 골이 뚜렷합니다. 늦가을에는 그해 수확한 호박을 구하기 좋고, 다른 계절에는 저장해 둔 호박이 유통되기도 합니다. 한 통이 크다면 자른 뒤 씨와 속을 덜어내고, 죽을 끓일 양과 전을 부칠 양을 나눠 두세요. 바로 쓰지 않을 과육은 손질해 냉동하면 조리할 때 필요한 만큼 덜어 쓸 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 은은하게 달고 과육이 부드럽게 풀어집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 단단하고 골이 뚜렷한 것을 고르세요."},{"text":"꼭지 주변에 무른 부분이 없는지 보세요."},{"text":"깊은 상처나 곰팡이가 있는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통째로는 서늘하고 통풍이 되는 곳에 두세요. 자른 뒤 남은 과육은 손질해 소분 냉동합니다."},{"label":"손질법","text":"안정된 도마 위에서 잘라 씨와 섬유질을 긁어내고 단단한 껍질을 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"호박죽. 과육을 푹 삶아 으깬 뒤 찹쌀가루를 풀어 농도를 맞춥니다."},{"text":"늙은 호박전. 과육을 가늘게 채 썰어 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 늦가을 수확분과 수확 후 저장해 다른 계절에 파는 물량을 구분합니다. 잘라 파는 호박은 과육이 마르거나 물러진 곳이 없는지 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘늙은 호박’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219873","checkedAt":"2026-11-12"}]},
  "alpine-leek": {"summary":"산마늘은 3~5월이 제철이에요. 잎이 푸르고 탄력 있으며 줄기 끝이 마르지 않은 것을 고르세요. 명이나물 생잎과 절임 제품 차이, 장아찌 손질법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"산마늘은 잎에서 마늘 향이 나며 명이나물이라는 이름으로도 팔립니다. 봄에 나는 어린 잎은 데쳐 먹거나 장아찌로 담가 두고 고기 요리에 곁들이기 좋습니다. 장아찌에 쓸 때는 넓은 잎의 앞뒤에 흙이 남지 않도록 씻고 물기를 충분히 빼세요. 잎이 크더라도 끝이 누렇거나 줄기까지 힘없이 늘어진 것은 골라내야 씹는 맛이 고르게 남습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"마늘을 닮은 알싸한 향이 나며 어린 잎은 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 푸르고 탄력이 있는 것을 고르세요."},{"text":"잎 끝이 누렇거나 찢어지지 않았는지 보세요."},{"text":"줄기 끝이 마르거나 끈적이지 않은지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"잎이 눌리지 않게 싸서 냉장하세요. 데쳐 쓸 양은 물기를 빼고 소분해 얼릴 수 있습니다."},{"label":"손질법","text":"잎의 앞뒤와 줄기가 겹친 틈을 씻고 물기를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"산마늘 장아찌. 물기를 뺀 잎을 간장 절임에 사용합니다."},{"text":"산마늘 무침. 데친 잎을 먹기 좋게 잘라 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"장에서는 명이나물이라는 이름으로도 만납니다. 생잎과 절인 제품은 용도와 보관 조건이 다르므로 제품 표시를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘산마늘’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227366&deleteCd=0&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"}]},
  "amaranth": {"summary":"아마란스는 10월이 제철이에요. 씨앗, 생잎, 말린 잎, 가루 중 쓸 곳에 맞는 형태를 고르세요. 밥에 섞어 짓는 법과 씻고 보관하는 법을 정리했어요.","origin":"평창·원주·영월·정선","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"아마란스는 작은 씨앗을 곡물처럼 먹는 작물로, 국내에서는 강원 평창, 원주, 영월, 정선에서 나옵니다. 씨앗뿐 아니라 생잎, 말린 잎, 가루로도 팔리니 쓸 곳에 맞춰 형태를 고르세요. 정보누리 생산시기는 10월입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"씨앗은 쌀과 섞어 밥을 짓거나 수프로 끓이고, 잎은 샐러드처럼 생으로 곁들입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"밥이나 수프에 쓸 때는 씨앗, 샐러드에 곁들일 때는 생잎을 고르세요."},{"text":"말린 잎과 가루도 따로 팔리니 포장에 적힌 형태를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"직사광선을 피해 통풍이 잘 되는 곳에 밀폐해 두세요."},{"label":"손질법","text":"씨앗은 흐르는 물에 여러 번 씻어 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"아마란스밥. 쌀이나 다른 곡류에 섞어 밥을 짓습니다."},{"text":"아마란스 샐러드. 씨앗을 샐러드 위에 뿌리거나 잎을 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"씨앗은 곡물로, 잎은 생잎과 말린 잎으로 따로 유통됩니다. 국내 주산지는 강원 평창, 원주, 영월, 정선입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘아마란스’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227354&menuNo=300063","checkedAt":"2026-11-12"}]},
  "anchovy": {"summary":"멸치는 4~5월이 제철이에요. 쌈밥에는 살이 도톰한 생멸치, 볶음에는 크기가 고른 잔멸치를 고르세요. 마른 멸치 냉동 보관법과 멸치쌈밥을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"멸치는 크기와 가공 상태에 따라 반찬과 국물에 두루 씁니다. 부산 기장 대변항에서 나는 봄 대멸치는 살이 도톰해 쌈밥이나 조림에 어울립니다. 마른 멸치는 큰 것을 육수에 쓰고 작은 것은 볶음에 쓰기 편합니다. 생멸치를 사려면 봄철 출하 사례를 참고하고, 마른 멸치는 원산지와 포장 상태를 보고 용도에 맞게 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생멸치는 익히면 고소하고 부드럽습니다. 마른 멸치는 크기와 건조 정도에 따라 단단함이 다릅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생멸치는 살이 도톰하고 짓무르지 않은 것을 고르세요."},{"text":"마른 멸치는 크기가 고르고 부스러기가 적은 것을 보세요."},{"text":"포장 안에 습기나 곰팡이 흔적이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생멸치는 냉장해 빨리 익히세요. 마른 멸치는 밀폐해 냉동하면 습기를 줄일 수 있습니다."},{"label":"손질법","text":"생물은 내장을 손질해 익힙니다. 국물용 큰 마른 멸치는 쓴맛을 줄이려면 내장을 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"멸치쌈밥. 생멸치를 매콤하게 조려 쌈채소에 올립니다."},{"text":"멸치볶음. 잔멸치를 짧게 볶아 양념합니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"해수부가 소개한 기장 봄멸치는 생물의 사례입니다. 말린 멸치는 어획 시기와 구매 시기가 다릅니다."}]}],"sources":[{"org":"해양수산부","title":"4월의 수산물 ‘멸치’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=38331&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"10월의 수산물 ‘미꾸라지·멸치’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=68834&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"제철수산물 ‘멸치’","url":"https://fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=14543&select_list_no=8","checkedAt":"2026-11-12"}]},
  "apple": {"summary":"사과는 7~11월이 제철이에요. 꼭지가 푸르고 물기가 있으며 꼭지 반대쪽에 녹색이 남지 않은 것을 고르세요. 품종과 한두 달 보관하는 법을 정리했어요.","origin":"청송·영천·의성·충주·장수","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"사과는 7월부터 11월까지 품종을 바꿔 가며 이어서 나옵니다. 가을에 맛이 가장 좋다고 하며, 다른 과일과 함께 두면 그 과일이 빨리 익으니 보관 자리를 따로 정하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과육이 아삭하고 단맛과 신맛이 어우러집니다. 차갑게 먹으면 단맛이 더 느껴집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼭지가 푸른빛이 돌고 물기가 있는 것이 갓 수확한 것입니다."},{"text":"꼭지 반대쪽 부위에 녹색이 사라지고 색이 고르게 든 것을 고르세요."},{"text":"표면이 끈끈하게 묻어나는 것은 오래된 것이니 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"하나씩 랩이나 비닐로 싸서 냉장하면 수분이 덜 빠져 한두 달 둘 수 있습니다. 다른 과일과 따로 두세요."},{"label":"손질법","text":"깎은 사과는 소금물이나 설탕물에 잠깐 담가 갈변을 막으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"사과 샐러드. 껍질째 얇게 썰어 잎채소에 올립니다."},{"text":"사과잼. 잘게 썰어 설탕과 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 부사(후지), 홍로, 홍옥, 아오리 등을 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘사과’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219919&menuNo=300063","checkedAt":"2026-11-12"}]},
  "apple-mango": {"summary":"애플망고는 5~10월이 제철이에요. 검은 반점 없이 껍질이 탱탱하고 윤기 나며 향이 진한 것을 고르세요. 후숙 판단법과 자르는 법, 보관법을 정리했어요.","origin":"제주·통영·고흥","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"애플망고는 껍질이 사과처럼 붉은 망고로, 국산은 제주를 중심으로 5~10월에 나옵니다. 수입산은 유통 과정이 길어 후숙 기간도 길어지므로, 정보누리는 국산이 더 싱싱하다고 설명합니다. 수확 뒤 저장 기간이 짧으니 먹을 날짜에 맞춰 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과육이 부드럽고 과즙이 많으며 향이 진합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"검은 반점이 없고 껍질이 탱탱하고 매끈하며 윤기가 나는 것을 고르세요. 검은 반점은 싱싱하지 않다는 표시입니다."},{"text":"꼭지 부분이 두껍고 둥글며 특유의 향이 진하게 나는 것이 좋습니다."},{"text":"붉은색이 많을수록 단맛이 많습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"눌렀을 때 단단하면 덜 익은 것이니 실온에 며칠 두어 익히세요. 농촌진흥청은 망고를 18℃ 안팎에서 3~4일 익힌 뒤, 익은 것은 신문지에 싸서 냉장하라고 권합니다."},{"label":"손질법","text":"납작한 씨를 기준으로 세로로 3등분한 뒤, 양쪽 과육에 가로세로 칼집을 내고 뒤집어 깍둑 모양으로 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"애플망고 빙수. 냉동해 둔 과육을 빙수에 올립니다."},{"text":"애플망고 화채. 과육을 썰어 화채에 띄웁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 제주도, 통영, 고흥을, 품종으로 아윈을 듭니다. 국산은 6월에 수확한 것의 당도가 가장 좋다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘애플망고’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219870&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"보도자료 ‘더 오래 신선하게’ 똑똑한 과일, 채소 보관법","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&prgId=day_farmprmninfoEntry&mode=updateCnt&dataNo=100000790713","checkedAt":"2026-11-12"}]},
  "apricot": {"summary":"살구는 6~7월이 제철이에요. 노란색이 얼룩 없이 고르고 껍질에 상처가 없는 단단한 것을 고르세요. 잘 익었는지 보는 법과 씨 손질 주의점을 정리했어요.","origin":"경북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"살구는 6~7월에 나오는 노란 열매로, 생으로 먹거나 말리고 잼으로 만듭니다. 정보누리는 덜 익은 열매는 먹지 않는 것이 좋다고 설명합니다. 씨에는 독성이 있으니 씨까지 쓰려면 따로 손질해야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"신맛과 단맛이 함께 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"노르스름한 색이 얼룩지지 않고 고르게 퍼진 것을 고르세요."},{"text":"껍질에 상처가 없고 단단한 것이 좋습니다."},{"text":"잘 익은 살구는 양손으로 쪼갰을 때 쉽게 벌어지며 씨가 빠집니다. 씨가 잘 빠지지 않으면 덜 익은 것입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"상온에서 7일 정도 둘 수 있지만 그 사이에도 무를 수 있으니 밀폐용기에 담아 냉장고 신선실에 넣어 두세요."},{"label":"손질법","text":"흐르는 물에 씻어 물기를 완전히 뺀 뒤 쓰세요. 씨는 뾰족한 안쪽 부분에 독성이 있으니 씨를 쓸 때는 그 부분을 떼어 내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"살구잼. 껍질과 씨를 뺀 과육을 졸여 잼으로 만듭니다."},{"text":"살구편. 손질한 과육을 썰어 만듭니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경상북도, 주요 품종으로 초하를 듭니다. 살구는 잼, 통조림, 주스, 건살구 등 가공용으로도 많이 쓰입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘살구’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219956&menuNo=300063","checkedAt":"2026-11-12"}]},
  "aralia-shoot": {"summary":"두릅은 4~5월이 제철이에요. 독성분이 조금 있어 반드시 끓는 물에 데쳐 먹고, 순이 짧고 통통한 것을 고르세요. 땅두릅과 나무두릅 차이를 정리했어요.","origin":"경기·순창·보령·서천·제천·강릉","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"두릅은 4~5월에 나오는 산나물로, 새순을 데쳐 먹습니다. 땅에서 돋아난 새순을 자른 땅두릅과 나무에 달리는 새순인 나무두릅으로 나뉩니다. 순이 너무 자라면 맛이 떨어지니 작고 잎이 덜 핀 것을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 강하고 쓴맛이 있습니다. 끓는 물에 데쳐 찬물에 담그면 쓴맛이 줄어듭니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"향이 강하고 가지가 없이 통통하며, 순의 길이가 길지 않은 것을 고르세요."},{"text":"윤기가 돌고 색이 선명하며 껍질이 마르지 않은 것이 좋습니다."},{"text":"줄기의 가시를 만졌을 때 아플 정도로 싱싱한 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"2~3일은 작은 구멍을 뚫은 비닐팩이나 종이봉지에 싸서 냉장하세요. 오래 두려면 살짝 데쳐 물기를 빼고 냉동합니다. 데친 두릅을 상온에 오래 두면 색이 변합니다."},{"label":"손질법","text":"두릅은 독성분을 미량 가지고 있어 반드시 끓는 물에 데쳐 먹어야 합니다. 손질하지 않은 두릅은 잎을 떼고 씻어 연한 소금물에 데친 뒤 다시 씻어 쓰세요. 껍질을 벗기면 약한 독성이 줄어듭니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"두릅숙회. 살짝 데친 두릅을 초고추장에 찍어 먹습니다."},{"text":"두릅산적. 데친 두릅을 꼬치에 끼워 지집니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 땅두릅, 개두릅, 참두릅을 듭니다. 자연산과 무농약 재배가 많고, 향을 즐기는 나물이라 오래 두지 말고 빨리 먹는 것이 좋습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘두릅’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219838&menuNo=300063","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"산나물 채취 시 주의사항","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?menu_no=3120&bbs_no=bbs001&ntctxt_no=21779&menu_grp=MENU_NEW01","checkedAt":"2026-11-12"}]},
  "aronia": {"summary":"아로니아는 7~9월이 제철이에요. 검붉은빛이 돌고 표면에 주름 없이 탱탱한 것을 고르세요. 떫은맛을 줄이는 보관법과 요거트·잼 활용법을 정리했어요.","origin":"고창·무주·단양·옥천·문경·상주·거창·금산","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"아로니아는 블루베리보다 알이 작고 단단한 열매로, 떫은맛이 강해 초크베리라고도 부릅니다. 생과는 7~9월에 나오는데, 생으로 먹기보다 냉동하거나 잼, 주스, 절임으로 만들어 먹는 경우가 많습니다. 바로 먹을지 가공할지에 따라 익은 정도를 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"새콤하면서 쌉쌀하고 떫은맛이 강합니다. 숙성될수록 떫은맛이 약해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붉은색이 돌면서 푸르스름한 검은빛을 띠는 것이 잘 익은 것입니다."},{"text":"물기가 너무 많은 것은 지나치게 익은 것이니 피하고, 꼭지 쪽에 곰팡이가 없는지 보세요."},{"text":"표면에 주름이 있으면 수확 후 오래된 것입니다. 탱탱한 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생으로 먹기 어려우면 냉동하거나 절임, 효소로 만들어 두세요. 숙성되면 떫은맛이 약해집니다."},{"label":"손질법","text":"먹기 직전에 흐르는 물에 씻어 꼭지를 떼고 물기를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"아로니아 요거트. 씻은 열매를 요거트에 넣어 먹습니다."},{"text":"아로니아잼. 잼으로 졸여 두고 빵이나 구움과자에 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 고창, 무주, 단양, 옥천, 문경, 상주, 거창, 금산을, 품종으로 레드, 블랙, 퍼플을 듭니다. 대표 달은 7월로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘아로니아’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219861&menuNo=300063","checkedAt":"2026-11-12"}]},
  "ashitaba": {"summary":"신선초는 8~9월이 제철이에요. 줄기가 가늘고 진녹색에 윤기가 돌며 밑동 단면이 싱싱한 것을 고르세요. 쓴맛 줄이는 손질법과 쌈·튀김 활용을 정리했어요.","origin":"제주·원주·횡성·양주·음성·증평","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"신선초는 미나리과 식물로, 명일엽이라고도 부릅니다. 줄기를 잘라도 바로 싹이 날 만큼 잘 자랍니다. 다 자라면 길이가 1m 정도 되는데, 녹즙용으로는 다 자란 것을, 샐러드나 나물용으로는 어린 순을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"특유의 은은한 쓴 향이 있습니다. 살짝 데치거나 기름에 볶고 튀기면 쓴맛이 줄어듭니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 싱싱하고 깨끗하며 은은한 쓴 향이 살아 있는 것을 고르세요."},{"text":"줄기는 가늘고 진녹색에 윤기가 있는 것이 좋습니다."},{"text":"밑동 잘린 단면이 갓 딴 듯 싱싱하고, 상처나 무른 곳이 없는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀폐한 비닐봉지에 넣어 5℃ 이하로 냉장하세요."},{"label":"손질법","text":"상한 잎을 다듬고, 쓴 향이 부담스러우면 살짝 데쳐 바로 찬물에 헹구세요. 데칠 때는 두꺼운 줄기를 먼저 넣어야 고루 익습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"신선초 쌈. 어린잎을 생으로 쌈 채소나 샐러드에 씁니다."},{"text":"신선초 튀김. 어린 순을 튀기면 쓴맛이 줄어듭니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 제주, 원주, 횡성, 양주, 음성, 증평 등을 들고, 생산시기를 8~9월로 적습니다. 다 자란 것과 어린 순의 쓰임이 다르니, 녹즙용인지 반찬용인지에 맞춰 크기를 보고 고르세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘신선초(명일엽)’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219888&menuNo=300063","checkedAt":"2026-11-12"}]},
  "asparagus": {"summary":"아스파라거스는 4~5월이 제철이에요. 굵은 것은 겉껍질을 벗겨야 하니 그대로 먹으려면 가는 것을 고르세요. 밑동 손질법과 세워 두는 보관법을 정리했어요.","origin":"제주·남원·홍천·양구·평택·보령·김해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"아스파라거스는 유럽 남부와 소아시아가 원산지인 채소입니다. 햇빛을 조절해 색을 낼 수 있어 흰색, 보라색, 초록색이 있고, 지금은 초록색이 주로 나옵니다. 흰색은 햇빛을 막아 키운 것으로, 예전에는 통조림으로 많이 가공되었습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"끓는 물에 데친 뒤 식히면 초록색이 선명해집니다. 기름에 살짝 볶으면 밝은 초록색을 띠며 아삭하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"연하고 어린 것은 그대로 요리할 수 있지만 굵은 것은 겉 섬유질이 질겨 벗겨야 하니, 쓰임에 맞게 굵기를 고르세요."},{"text":"보라색은 껍질에 색소가 쌓인 것이니 요리 색감에 맞춰 색을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밑동 끝을 잘라 물이 조금 담긴 그릇에 세워 두거나, 키친타월에 싸서 비닐봉지에 담아 냉장하면 5일 정도 신선합니다."},{"label":"손질법","text":"딱딱한 밑동은 칼로 자르거나 살짝 구부려 꺾어 내고, 굵은 것은 필러나 칼로 겉껍질을 얇게 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"아스파라거스볶음. 5cm 길이로 썰어 기름에 향신료, 소금과 함께 살짝 볶습니다."},{"text":"아스파라거스 데침. 끓는 물에 짧게 데쳐 식힌 뒤 곁들입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 제주, 남원, 홍천, 양구, 평택, 보령, 김해를 들고, 생산시기를 4~5월로 적습니다. 오래 데치면 맛과 향이 떨어지니 짧게 익히라고 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘아스파라거스’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219846&menuNo=300063","checkedAt":"2026-11-12"}]},
  "aster-scaber": {"summary":"취나물은 3~5월이 제철이에요. 잎이 밝은 연녹색이고 뒷면에 윤기가 돌며 줄기에 붉은빛이 감도는 것을 고르세요. 묵나물 만들기와 보관법을 정리했어요.","origin":"충남 보령·태안·논산·부여, 전남 고흥","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"취나물은 참취, 개미취, 각시취, 미역취 등을 아우르는 이름으로, 가장 많이 거두는 것은 참취입니다. 생것과 삶은 것, 말린 것으로 나뉘어 팔리니 형태에 맞는 기준으로 고르세요. 정월 대보름에 오곡밥을 싸 먹는 복쌈 재료로도 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 짙고 쌉싸름한 맛이 납니다. 연한 잎은 생으로도 먹을 수 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 밝은 연녹색이고 변색된 것이 없으며 뒷면에 윤기가 도는 것을 고르세요."},{"text":"잎 생김새가 고르고 줄기에 붉은빛이 감돌며 향이 퍼지는 것이 좋습니다."},{"text":"말린 것은 이물질과 부서진 것이 없는지, 삶은 것은 줄기 변색과 짓무름이 덜한지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"봉지에 담아 냉장하면 2~3일 갑니다. 오래 두려면 데쳐서 물기를 꼭 짠 뒤 냉동하거나 말리세요."},{"label":"손질법","text":"억센 줄기는 겉을 살짝 벗겨 다듬고, 소금을 조금 넣은 물에 살짝 데치세요. 말린 것은 따뜻한 물에 충분히 불린 뒤 잎이 펴질 때까지 삶아 찬물에 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"취나물무침. 소금물에 살짝 데쳐 무칩니다."},{"text":"취나물볶음. 말린 취나물을 불려 들기름에 볶고 간장으로 간합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 충남 보령·태안·논산·부여와 전남 고흥 등을 듭니다. 우리나라에 60여 종이 자생하고 그중 24종가량을 먹을 수 있다고 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘취나물’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219850&menuNo=300063","checkedAt":"2026-11-12"}]},
  "atka-mackerel": {"summary":"임연수어는 12월~이듬해 5월이 제철이에요. 구이용은 살이 도톰하고 껍질이 찢기지 않은 것을 고르세요. 생물·냉동·염장별 조리 차이와 조림을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"임연수어는 담백한 살과 구웠을 때 고소한 껍질이 어울리는 생선입니다. 해양수산부는 겨울부터 봄까지를 제철로 소개하며 3월 이달의 수산물로 선정했습니다. 구이용으로 사면 살 두께가 고르고 껍질이 심하게 손상되지 않았는지 살펴보세요. 냉동 손질품은 냉장고에서 해동해 물기를 닦은 다음 구우면 팬에 물이 덜 고입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 담백하고 익히면 부드럽게 갈라집니다. 구운 껍질은 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"살이 도톰한 토막을 고르세요."},{"text":"껍질이 찢기거나 마르지 않았는지 확인하세요."},{"text":"염장 여부와 냉장·냉동 표시를 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생물은 냉장해 빨리 조리하고, 냉동품은 냉장고에서 해동하세요."},{"label":"손질법","text":"손질 상태와 가시를 확인한 뒤 물기를 닦습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"임연수어구이. 껍질을 붙인 채 살 속까지 굽습니다."},{"text":"임연수어조림. 무를 먼저 익히고 생선을 넣습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"3월 선정은 맛보기 좋은 달의 사례입니다. 구입할 때 생물·냉동·염장 여부에 따라 조리와 간을 달리하세요."}]}],"sources":[{"org":"해양수산부","title":"3월 이달의 수산물 ‘임연수어·바지락’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=55827&menuSeq=971","checkedAt":"2026-11-12"}]},
  "bamboo-shoot": {"summary":"죽순은 5~6월이 제철이에요. 껍질이 단단히 붙어 있고 자른 면이 흰 것을 고르세요. 쌀뜨물에 통째로 삶는 손질법과 물에 담가 두는 보관법을 정리했어요.","origin":"담양·고흥·거제·서천·당진","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"죽순은 봄에 땅속 영양분으로 빠르게 자라 올라와, 5월 무렵 짧은 기간에만 채취합니다. 채취 뒤 선도가 빨리 떨어져 생산량의 80%가 통조림으로 가공됩니다. 생죽순을 산다면 시간이 지날수록 떫어지니 산 날 바로 삶으세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"부드럽고 아삭하며 맛이 담백합니다. 시간이 지나면 떫은맛이 강해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 단단하게 붙어 있고, 자른 면은 희며 머리 부분은 갈색인 것을 고르세요."},{"text":"껍질에 녹색이 돌수록 채취한 지 얼마 안 된 것이고, 짙은 고동색 잔털이 많은 것이 좋습니다."},{"text":"부드러운 식감을 원하면 5월쯤 나오는 왕대, 솜대 죽순을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"삶은 죽순은 유리용기에 담아 물에 완전히 잠기게 해 냉장하면 열흘 정도 둘 수 있습니다. 설탕을 조금 넣으면 변색이 늦어집니다."},{"label":"손질법","text":"껍질을 벗기지 말고 통째로 쌀뜨물에 삶아 식힌 뒤 껍질을 벗기세요. 떫고 아린 맛이 빠집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"죽순나물볶음. 삶은 죽순을 썰어 연하게 간해 볶습니다."},{"text":"죽순밥. 가운데 부드러운 부분을 썰어 넣고 밥을 짓습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 담양, 고흥, 거제, 서천, 당진을, 품종으로 맹종죽, 왕죽, 솜죽, 시누대 등을 듭니다. 한 개를 부위별로 나눠 안쪽 껍질은 국물 요리에, 가운데는 죽순밥에, 단단한 밑부분은 조림에 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘죽순’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219845&menuNo=300063","checkedAt":"2026-11-12"}]},
  "banded-grouper": {"summary":"능성어는 12월~이듬해 2월이 달력상 제철이에요. 비린내가 없고 살을 눌렀을 때 탄력 있는 것을 고르세요. 다금바리와 구분하는 법과 손질법을 정리했어요.","origin":"남해안·제주도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"능성어는 회갈색 몸에 진한 갈색 띠 일곱 개가 있는 바리과 대형 어류로, 구문쟁이라고도 부릅니다. 남해안과 제주도에서 잡히지만 양이 많지 않아 고급 어종으로 거래됩니다. 생김새가 다금바리와 비슷해 능성어를 다금바리로 속여 파는 일이 있었으니 판매명과 어종을 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 찰지고 달큰한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"비린내가 나지 않는 것을 고르세요."},{"text":"살을 눌러 보았을 때 탄력이 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"보관 기간이 짧으니 사서 바로 드시고, 둘 때는 밀봉해 냉장하세요."},{"label":"손질법","text":"지느러미를 떼고 내장과 살을 분리해 깨끗이 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"능성어회. 주로 회로 먹습니다."},{"text":"능성어 매운탕. 남은 머리와 뼈로 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"남해안 가두리에서 양식되는 바리과 어종은 능성어가 유일하며, 활어 수입량도 늘고 있습니다. 원산지 표시와 양식 여부를 함께 확인하세요."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"바다의 귀족 ‘능성어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=27485","checkedAt":"2026-11-13"}]},
  "bangah-leaf": {"summary":"방아잎은 8~11월이 제철이에요. 깻잎보다 갸름하고 꼭지가 보랏빛이라 구분돼요. 너무 크지 않은 잎 고르는 법과 마르지 않게 보관하는 법을 정리했어요.","origin":"경산·해남·순천·구례·여수·하동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"방아잎은 깻잎과 비슷하게 생긴 향채로, 주로 어린잎을 먹습니다. 깻잎보다 잎이 갸름하고 꼭지 부분이 보랏빛을 띠어 구분할 수 있습니다. 어린잎은 생으로, 다 자란 잎은 향을 내는 부재료로 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"들깨잎과 비슷한 향이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 너무 크지 않은 것을 고르세요."},{"text":"벌레 먹은 자국이 없는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"수분이 마르지 않게 밀봉해 냉장하세요."},{"label":"손질법","text":"흐르는 물에 한 장씩 씻어 물기를 털어 내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"방아잎 생채. 어린잎을 생으로 무치거나 곁들여 먹습니다."},{"text":"방아잎 향 부재료. 다 자란 잎을 썰어 요리에 넣어 향을 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지로 경북 경산, 전남 해남·순천·구례·여수, 경남 하동을 듭니다. 생산시기는 8~11월입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘방아잎’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227361&menuNo=300063","checkedAt":"2026-11-12"}]},
  "bangpung-namul": {"summary":"방풍나물은 5월이 제철이에요. 너무 크면 질기니 줄기가 길지 않고 잎색이 연한 어린순을 고르세요. 식방풍과 원방풍 차이와 데친 나물 물기 빼는 법을 정리했어요.","origin":"여수·고흥·포항·강릉","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"방풍나물은 바닷가 모래밭에서 잘 자라는 식물의 잎과 어린순으로, 5월에 나옵니다. 뿌리는 주로 약용으로 쓰고, 잎은 나물이나 쌈으로 먹습니다. 우리나라에서 나물로 나오는 것은 식방풍으로, 약으로 쓰는 원방풍과는 다릅니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쌉쌀한 맛에 당귀와 미나리를 합친 듯한 향이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 신선하고 줄기가 길지 않으며 향이 좋은 것을 고르세요."},{"text":"너무 큰 것은 질기니 크기가 작고 잎색이 연한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"남은 방풍나물은 비닐팩에 넣어 냉장하세요. 말려 두고 쓸 수도 있습니다."},{"label":"손질법","text":"흐르는 물에 씻고 굵은 줄기는 떼어 내세요. 데친 뒤에는 김발로 말아 눌러 물기를 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"방풍나물무침. 잎과 줄기를 데쳐 나물로 무칩니다."},{"text":"방풍 장아찌. 싱싱한 방풍잎을 장아찌로 담급니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 원방풍, 갯방풍, 식방풍을 들고, 국내산 식방풍은 원방풍과 달리 약리작용이 확인되지 않았다고 설명합니다. 쌈, 생채, 죽, 전, 튀김으로도 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘방풍나물’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219837&menuNo=300063","checkedAt":"2026-11-12"}]},
  "barley": {"summary":"보리는 6월이 제철이에요. 연한 노란빛으로 투명하고 쌀겨가 완전히 벗겨져 알이 온전한 것을 고르세요. 겉보리와 쌀보리 차이, 불리기와 보관법을 정리했어요.","origin":"전북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"우리나라에서 거두는 보리는 크게 겉보리와 쌀보리로 나뉩니다. 쌀보리는 겨울에 씨를 뿌려 여름 무렵 거두고, 겉보리는 사료나 맥주 원료로 많이 쓰입니다. 밥에 넣을 보리를 살 때는 도정 상태와 묵은 냄새를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"밥에 섞어 먹거나 볶아서 보리차로 끓이는 등 익혀 먹는 곡물입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"곰팡이나 묵은 냄새가 없고 연한 노란색(담황색)으로 투명한 것을 고르세요."},{"text":"쌀겨가 완전히 제거되고 보리알이 깨지지 않고 온전한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"벌레가 생기기 쉬우니 밀봉해 직사광선을 피해 서늘한 곳(10~15℃)에 두세요. 볶은 보리는 밀봉해 냉장하세요."},{"label":"손질법","text":"물을 부어 하룻밤 불린 뒤 깨끗이 씻고 물기를 빼세요. 씻은 뒤 충분히 말리지 않으면 썩을 수 있습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"보리밥. 불린 보리를 쌀과 섞어 짓습니다."},{"text":"식혜. 보리 싹을 틔워 말린 엿기름으로 만듭니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전라북도, 품종으로 부농, 올보리, 강보리, 밀양6호를 듭니다. 보리는 통보리 외에 가루나 정맥(납작하게 누른 보리) 형태로도 팔립니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘보리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219965&menuNo=300063","checkedAt":"2026-11-12"}]},
  "beet": {"summary":"비트는 3~6월이 제철이에요. 뿌리가 단단하고 묵직하며 쭈글쭈글하지 않은 것을 고르세요. 잎과 뿌리를 나눠 쓰는 법과 구운 비트 샐러드, 피클을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"비트는 자른 단면에서 붉은 즙이 나오는 뿌리채소입니다. 생으로 얇게 썰면 단단하고 아삭하며, 구우면 속이 부드러워져 샐러드에 곁들이기 좋습니다. 도마와 다른 채소에 붉은 물이 들기 쉬우니 조리하기 직전에 따로 손질하세요. 잎이 달린 채로 샀다면 뿌리와 분리해 보관하고, 신선한 어린잎은 뿌리와 다른 요리에 쓸 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"뿌리는 은은한 단맛과 흙을 닮은 향이 나며, 익히면 부드러워집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리가 단단하고 묵직한 것을 고르세요."},{"text":"표면이 심하게 쭈글쭈글하지 않은지 보세요."},{"text":"갈라져 무르거나 즙이 새는 것을 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"잎을 뗀 뿌리는 냉장하세요. 구워 식힌 과육은 나눠 냉동할 수 있습니다."},{"label":"손질법","text":"흐르는 물에 문질러 흙을 씻고, 조리할 때 껍질을 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"구운 비트 샐러드. 익혀 식힌 비트에 치즈를 곁들입니다."},{"text":"비트 피클. 얇게 썰어 식초 절임에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"잎이 붙은 상태로 구입하면 어린잎과 뿌리를 나누어 씁니다. 뿌리는 굽거나 삶고, 어린잎은 데쳐 곁들일 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘비트’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219830&deleteCd=0&pageIndex=1&selectMonth=3","checkedAt":"2026-11-12"}]},
  "bell-pepper": {"summary":"피망은 4~12월이 제철이에요. 짙은 녹색에 윤기가 나고 꼭지가 신선하며 반듯하고 통통한 것을 고르세요. 꼭지째 씻는 손질법과 피망볶음을 정리했어요.","origin":"충남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"피망은 매운맛 없이 단맛이 있는 채소로, 샐러드나 볶음, 조림, 전에 씁니다. 수분이 94%로 많아 물기가 있으면 상하기 쉽습니다. 생으로 먹을지 익혀 먹을지에 따라 크기와 껍질 상태를 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"매운맛이 없고 단맛이 있으며, 기름과 잘 어울립니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"짙은 녹색에 윤기가 나고 꼭지가 신선하며 기형이 아닌 것을 고르세요."},{"text":"표피가 두껍고 광택이 나며 과육이 단단하고, 전체 모양이 반듯하고 통통한 것이 좋습니다."},{"text":"샐러드용은 껍질이 단단하고 색이 선명한 것을, 볶음용은 크기가 작은 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 없애고 신문지에 싸거나 랩, 비닐팩에 담아 냉장하세요."},{"label":"손질법","text":"먹기 직전에 통째로 씻으세요. 꼭지를 먼저 따고 씻으면 영양소가 물에 빠지니, 씻은 뒤 꼭지 부분을 얇게 썰고 심을 떼어 낸 다음 세로로 잘라 하얀 심을 제거하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"피망볶음. 식용유에 볶아 간을 합니다."},{"text":"피망전. 피망을 썰어 전으로 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 충청남도를, 품종으로 경유타카, 오리엔탈글로리를 들고, 생산시기를 4~12월로 적습니다. 출하 기간이 길어 연중 대부분 장에서 볼 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘피망’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219822&menuNo=300063","checkedAt":"2026-11-12"}]},
  "bellflower-root": {"summary":"도라지는 7~9월이 제철이에요. 통도라지는 흙이 많이 묻고 연노랑이나 흰빛을 띠는 것을 고르세요. 국산 구별법과 쓴맛 빼는 손질법을 정리했어요.","origin":"여주·이천·김포·홍천·삼척","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"도라지는 7~9월에 많이 나오는 뿌리채소로, 생채나 나물로 먹습니다. 장에서는 흙에서 캔 통도라지와 껍질을 벗겨 가늘게 찢어 놓은 손질 도라지가 함께 나옵니다. 두 형태 모두 국산과 수입산을 생김새로 어느 정도 구별할 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쓴맛과 아린 맛이 있어 소금물이나 쌀뜨물에 담가 우려낸 뒤 먹습니다. 생채로 무치면 산뜻하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"통도라지는 흙이 많이 묻어 있고 연노랑이나 흰색을 띠며 상처나 짓무름이 없는 것을 고르세요."},{"text":"손질 도라지는 희고 부드러우며 향이 강한 것이 좋습니다."},{"text":"국산 통도라지는 가늘고 짧으며 잔뿌리가 많고 원뿌리가 2~3개로 갈라진 것이 많습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통도라지는 종이에 싸서 서늘한 곳에 두세요. 껍질을 벗긴 도라지는 색이 변하니 물에 담가 둡니다. 오래 두려면 껍질을 벗겨 햇볕에 말리세요."},{"label":"손질법","text":"잔뿌리를 떼고 칼로 겉껍질을 긁어 벗겨 씻으세요. 손질한 도라지는 소금에 주물러 찬물에 담가 아린 맛을 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"도라지생채. 가늘게 채 썬 도라지를 소금에 재웠다가 양념에 무칩니다."},{"text":"도라지나물. 쓴맛을 뺀 도라지를 기름에 볶다가 양념해 한 번 더 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"통도라지는 대개 2~3년근입니다. 정보누리는 손질 도라지 중 대가 짧고 가늘며 둥글게 말리는 것이 국산이라고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘도라지’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219858&menuNo=300063","checkedAt":"2026-11-12"}]},
  "benimadonna": {"summary":"황금향은 8~12월이 제철이에요. 꼭지 주변에 잔금이나 무른 곳이 없는지 먼저 보세요. 하우스와 노지 출하 시기 차이, 빨리 먹어야 하는 이유를 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"황금향은 제주에서 재배하는 만감류로, 품종 이름은 베니마돈나(에히메28호)입니다. 하우스 재배분은 추석 출하를 목표로 8월 하순부터 수확하고, 노지 재배분은 12월에 수확합니다. 일찍 출하한 것은 산함량이 높다고 농업기술원은 설명합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"껍질은 등황색이고 얇고 매끄럽습니다. 품종 특성상 산이 매우 낮습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"착색기 이후 꼭지 부분에 물이 닿으면 미세한 균열이 생겨 유통 중 썩는 원인이 됩니다. 꼭지 주변에 잔금이나 무른 곳이 없는지 보세요."},{"text":"껍질이 등황색으로 고르고 매끄러운 것을 고르세요. 제주 상품 기준은 한 개 150g 이상, 당도 11.0브릭스 이상입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"저장성이 약하고 유통기간이 짧은 품종입니다. 사 온 뒤 빨리 드세요."},{"label":"손질법","text":"흐르는 물에 씻고, 꼭지 주변에 갈라지거나 무른 곳이 있으면 그 부분을 도려낸 뒤 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"생과. 껍질을 벗겨 쪽으로 나눠 먹습니다."},{"text":"과일 샐러드. 쪽으로 나눈 과육을 다른 과일과 섞습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"제주의 황금향 재배면적은 2010년 15ha에서 2018년 353ha로 늘었습니다. 노지 황금향은 12월에 수확하는 장점이 있지만, 9~12월에 비가 잦으면 껍질에 미세한 균열이 생겨 품질이 떨어질 수 있습니다."}]}],"sources":[{"org":"제주특별자치도농업기술원","title":"영농상담 ‘노지황금향 수확량과 저장기간 어느정도 되는지 궁금합니다’","url":"https://agri.jeju.go.kr/agri/communication/hardship.htm?act=view&seq=42923","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원","title":"영농상담 ‘농지에 과수(감귤묘목) 식재에 따른 문의사항입니다’","url":"https://agri.jeju.go.kr/agri/communication/hardship.htm?page=4&act=view&seq=56845","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원","title":"인터넷영농소식지 e제주농업농촌 48호(2019-08)","url":"https://agri.jeju.go.kr/files/board/83769525-4df3-4ed0-bb17-1aad905d3d0f.pdf","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원 서귀포농업기술센터","title":"2020년 새해영농실용화교육 ‘고품질 만감류 재배기술’","url":"https://agri.jeju.go.kr/files/board/40a561f6-e5de-4e68-bdbd-1405b53c239d.pdf","checkedAt":"2026-11-12"}]},
  "bird-clam": {"summary":"새조개는 11월~이듬해 2월이 제철이에요. 부리 부분이 진한 초콜릿색이고 껍데기에 윤이 나는 것을 고르세요. 해감하는 법과 새조개 샤브샤브를 정리했어요.","origin":"진해만·득량만·가막만, 천수만","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"새조개는 속살에 붙은 발이 새 부리를 닮은 조개입니다. 서해안과 남해안에서 잡히고, 양식이 되지 않아 어획량에 따라 값이 크게 오르내립니다. 산란기인 6~9월은 금어기라 채취하지 않고, 11월부터 살이 차올라 겨울에 맛이 가장 좋습니다. 껍데기가 얇고 약해 손으로 비틀기만 해도 쉽게 부서집니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쫄깃한 식감과 감칠맛이 있습니다. 덜 익히면 비린 맛이 강하고 오래 익히면 질겨집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기가 고르고 껍데기에 윤이 나는 것을 고르세요."},{"text":"부리 부분이 진하고 선명한 초콜릿색인 것이 좋습니다. 이 부분이 하얗게 벗겨졌으면 신선도가 떨어진 것입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"껍질 벗긴 조갯살은 뚜껑 있는 용기에 담아 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"맑은 물이 나올 때까지 문질러 닦은 뒤 소금물에 담가 해감합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"새조개 샤브샤브. 냉이, 시금치, 미나리를 넣은 육수를 80℃ 정도로 끓이고 새조개를 15~20초 담갔다 건집니다."},{"text":"새조개 초밥과 무침. 손질한 살을 회나 초밥, 무침으로 씁니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"부산, 진해, 창원에서는 갈매기조개, 여수에서는 도리가이라고도 부릅니다. 충청남도 수산자원연구소가 2019년 인공 새조개 생산에 성공했지만, 시장에 나오는 것은 잡은 것입니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 새부리를 닮은 귀족조개 ‘새조개’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=28541&select_list_no=70","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"2월 어식백세 수산물 ‘물메기·새조개’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=6765&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "bireum-namul": {"summary":"비름나물은 7~9월이 제철이에요. 잎이 싱싱하고 가는 줄기가 많은 단을 고르세요. 억센 밑동 다듬는 법과 데쳐 냉동하는 법, 된장·고추장 무침을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"비름나물은 어린 잎과 줄기를 데쳐 먹는 여름 나물입니다. 재배 물량은 봄부터 가을까지 장에 나올 수 있지만 농식품정보누리는 생산기를 7~9월로 안내합니다. 나물로 무칠 때는 줄기 끝에서 단단하게 굳은 부분을 잘라내고, 잎과 가는 줄기를 한꺼번에 데치면 부드럽게 먹을 수 있습니다. 데친 다음에는 물기를 짜야 양념 맛이 묽어지지 않습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎은 순한 풋맛이 나고 데치면 부드러우며, 연한 줄기는 가볍게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"싱싱하고 색이 고른 잎을 고르세요."},{"text":"가느다란 줄기가 많은 단이 무침에 편합니다."},{"text":"누렇거나 검게 짓무른 잎은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장하고 가능한 빨리 손질하세요. 한 번에 쓸 만큼 데쳐 물기를 짠 뒤 냉동할 수 있습니다."},{"label":"손질법","text":"억센 밑동과 상한 잎을 제거하고, 깨끗이 씻어 데칩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"비름 된장무침. 데친 나물을 된장과 참기름에 무칩니다."},{"text":"비름 고추장무침. 물기를 짜고 고추장 양념을 조금씩 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농식품정보누리는 재배로 판매 시기가 봄~가을로 넓어졌다고 설명합니다. 장에 보이는 전체 기간과 대표 생산기를 구분하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘비름’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219860&deleteCd=0&pageIndex=1&selectMonth=7","checkedAt":"2026-11-12"}]},
  "bitter-melon": {"summary":"여주는 6~8월이 제철이에요. 볶음용은 녹색이 선명하고 돌기에 탄력 있는 열매를 고르세요. 씨와 흰 속을 긁어내는 손질법과 여주 달걀볶음을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"여주는 표면에 돌기가 많고 쓴맛이 두드러지는 여름 채소입니다. 볶음에는 아직 초록색이고 단단한 열매를 사용하며, 속을 긁어낸 다음 얇게 썰면 다른 재료와 익는 시간을 맞추기 좋습니다. 처음 요리한다면 다른 채소나 달걀과 함께 볶아 쓴맛을 조절하세요. 썰어 둔 여주는 물기를 닦아야 볶을 때 팬에 물이 덜 고입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쓴맛이 뚜렷하고 짧게 볶으면 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"녹색이 선명한 것을 고르세요."},{"text":"돌기와 과육에 탄력이 있는지 보세요."},{"text":"갈라지거나 물러진 열매는 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 닦아 냉장하세요. 익혀 쓸 양은 손질해 데친 뒤 소분해 얼릴 수 있습니다."},{"label":"손질법","text":"반으로 갈라 씨와 흰 속을 긁어내고 얇게 써세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"여주 달걀볶음. 여주를 짧게 익힌 뒤 달걀을 섞습니다."},{"text":"여주 채소볶음. 양파와 함께 볶아 단맛을 더합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"볶음에는 익어 색이 바뀐 열매보다 초록색의 단단한 열매를 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘여주’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219894&deleteCd=0&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"}]},
  "black-raspberry": {"summary":"복분자는 6~8월이 제철이고 6월에 가장 많이 나와요. 알이 굵고 떨어지지 않은 것을 고르세요. 씻지 않고 나눠 얼리는 보관법을 정리했어요.","origin":"고창·정읍·순창","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"복분자는 나무에 열리는 검은 베리로 블랙라즈베리라고도 부릅니다. 고창, 정읍, 순창이 대표 산지이고, 6월에 수확이 몰립니다. 생과는 금방 무르므로 사 오면 그날 먹을 양과 얼릴 양을 나누세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"산딸기보다 단맛이 적고 약간 씁쓸한 맛이 납니다. 알갱이가 톡톡 터집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 굵고 탱글탱글하며 낱알이 떨어지지 않은 것을 고르세요."},{"text":"너무 검게 익은 것보다 붉은빛이 살짝 도는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻으면 과즙이 빠지니 씻지 말고 조금씩 나눠 냉동하세요."},{"label":"손질법","text":"바로 먹을 것만 흐르는 물에 가볍게 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"복분자 스무디. 언 복분자를 우유나 요구르트와 갑니다."},{"text":"복분자잼. 설탕과 함께 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"산딸기와 달리 노지 재배에 맞게 개량되어 검은색을 띱니다. 생과 외에 냉동 과실과 즙으로도 많이 팔리니 용도에 맞춰 고르세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘복분자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219862&menuNo=300063","checkedAt":"2026-11-12"}]},
  "black-rice": {"summary":"흑미는 9~10월이 제철이에요. 깨진 알과 이물질이 적고 낟알 크기가 고른 것을 고르세요. 불린 흑미를 백미에 섞는 흑미밥과 품종별 수확 시기를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"흑미는 겉층에 검은빛이 도는 쌀로 백미에 섞어 밥을 짓거나 죽을 끓입니다. 가을에 햇곡이 나오며 실제 수확 적기는 품종과 이삭이 나온 시기에 따라 다릅니다. 장에서는 검은색이 얼마나 진한지만 보기보다 깨진 알이 적고 크기가 고른지 확인하세요. 백미와 섞어 먹을 때는 흑미를 먼저 불리면 같은 냄비에서 씹는 정도를 맞추기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"밥을 지으면 구수한 향이 나고 겉층이 남은 알은 씹는 맛이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"깨진 알이나 이물질이 적은 것을 고르세요."},{"text":"낟알 크기가 비교적 고른지 보세요."},{"text":"원산지와 수확·도정 또는 포장 표기를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀폐해 서늘한 곳에 두고 개봉 후 오래 둘 양은 냉장하세요."},{"label":"손질법","text":"이물질을 골라 헹구고 물에 불린 뒤 백미와 섞습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"흑미밥. 불린 흑미를 백미에 섞어 짓습니다."},{"text":"흑미죽. 씻은 쌀을 충분히 익혀 농도를 맞춥니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"국립식량과학원은 이삭이 나온 뒤 조생흑찰과 흑설은 40~45일, 신토흑미는 45~50일 무렵 수확한다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘흑미’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219959&deleteCd=0&pageIndex=1&selectMonth=9","checkedAt":"2026-11-12"},{"org":"국립식량과학원","title":"색깔 있는 쌀 적정 수확 시기","url":"https://www.nics.go.kr/bbs/view.do?bbsId=news&bbsSn=13172&m=100000020","checkedAt":"2026-11-12"}]},
  "black-scraper": {"summary":"말쥐치는 9~10월이 제철이에요. 눈동자가 선명하고 아가미가 선홍색이며 껍질에 광택 있는 것을 고르세요. 껍질 벗기는 손질법과 회·쥐포볶음을 정리했어요.","origin":"남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"말쥐치는 쥐포를 만드는 쥐치류 가운데 우리 바다에서 가장 많이 잡히는 종입니다. 작고 거친 비늘 때문에 껍질이 꺼칠꺼칠하지만 한 번에 잘 벗겨져 손질이 쉽습니다. 뼈가 연해 뼈째 썰어 회로도 먹습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살 생선으로 살이 단단하고 쫄깃하며, 얇게 회를 뜨면 씹을수록 감칠맛이 납니다. 간은 크고 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈동자가 선명하고 아가미가 선홍색인 것을 고르세요."},{"text":"살이 통통하게 오르고 껍질에 광택이 있는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"5℃ 이하 냉장으로 이틀 정도 둘 수 있고, 오래 두려면 잘 밀봉해 냉동하세요."},{"label":"손질법","text":"머리 쪽 가시를 먼저 떼고 배를 갈라 내장을 빼세요. 머리에서 지느러미 위까지 칼집을 내고 지느러미와 주둥이를 자른 뒤 껍질을 잡아당기면 살과 쉽게 분리됩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"쥐치회. 뼈가 연해 뼈째 썰거나 얇게 떠서 먹습니다."},{"text":"쥐치포볶음. 쥐포를 고추장, 간장, 물엿 양념에 볶습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"우리나라에는 쥐치류 14종이 기록되어 있고, 주로 잡히는 것은 말쥐치로 트롤과 선망으로 어획합니다. 어획량이 줄어 5월 1일부터 7월 31일까지 포획이 금지되고 18cm 이하는 잡을 수 없습니다. 말린 쥐포는 1960년대 이후 남해안에서 쥐치가 많이 잡히면서 삼천포를 중심으로 만들어졌습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"쥐포로 유명한 ‘쥐치’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32030","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"자주 묻는 질문 ‘우리나라 바다에서 잡히는 쥐고기’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?docSeq=21004&menuSeq=929&bbsSeq=27","checkedAt":"2026-11-13"}]},
  "black-seabream": {"summary":"감성돔은 10월과 12월이 제철이에요. 아가미가 선명하고 살에 탄력이 있는 것을 고르세요. 판매처에 맡기는 손질 요령과 소금구이, 매운탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"감성돔은 담백한 살을 구이나 탕에 쓰는 돔류로, 해양수산부는 10월 이달의 수산물로 소개했습니다. 손질해서 살 때는 조리 방법을 먼저 정하세요. 구이용은 두께가 고르면 뒤집기 편하고, 탕용은 먹기 좋은 크기로 토막 낸 것을 구입하면 다듬는 수고를 줄일 수 있습니다. 같은 이름으로 팔려도 산지와 생산 방식이 다를 수 있으니 판매 표시를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살 맛이 담백하고 익혔을 때 살이 탄탄하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"통생선은 눈이 맑은지 보세요."},{"text":"아가미가 선명하고 살에 탄력이 있는 것을 고르세요."},{"text":"손질 살은 표면이 마르지 않았는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 냉장하고 빠르게 조리하세요. 오래 둘 것은 나눠 냉동합니다."},{"label":"손질법","text":"비늘과 내장, 아가미는 판매처에 손질을 요청할 수 있습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"감성돔 소금구이. 물기를 닦고 살 속까지 익힙니다."},{"text":"감성돔 매운탕. 토막과 무를 넣고 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"자연산·양식 여부는 외형으로 단정하지 말고 원산지와 판매 표시를 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"10월의 수산물 ‘삼치·감성돔’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=58804&menuSeq=971","checkedAt":"2026-11-12"}]},
  "blackfish": {"summary":"벵에돔은 7월에 회로 즐기기 좋은 생선이에요. 꼬리지느러미 가운데가 둥글게 패어 8자처럼 보이는 것이 특징이에요. 생김새와 고르는 법, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"벵에돔은 우리나라와 일본, 동중국해, 대만 연안에 사는 연안성 어종으로, 해초가 무성한 암초나 자갈 지대에 삽니다. 몸은 짧고 옆으로 납작하며 비교적 큰 빗비늘로 덮여 있고, 최대 전장 50cm까지 자랍니다. 꼬리지느러미 가운데가 둥글게 패어 8자 모양입니다. 이름이 비슷한 긴꼬리벵에돔과는 다른 종입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"참돔, 돌돔, 감성돔과 함께 주로 횟감으로 쓰는 고급 어종으로 꼽힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼬리지느러미가 8자 모양인지 보고 판매 이름과 함께 확인하세요."},{"text":"아가미가 선홍색이고 살을 눌렀을 때 탄력 있게 되돌아오는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"회로 뜬 살은 비닐봉지나 용기에 밀봉한 뒤 얼음을 덮어 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"등지느러미 앞쪽은 가시로 되어 있으니 조심해서 다루세요. 비늘과 내장을 뺀 뒤 살을 떠서 회로 먹습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"벵에돔회. 손질한 살을 떠서 회로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"벵에돔의 산란기는 2~6월로 추정되며, 산란 기간에 한 번 알을 낳습니다."}]}],"sources":[{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 벵에돔","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=10406","checkedAt":"2026-11-13"},{"org":"대한민국 정책브리핑","title":"영양가 풍부한 8월 수산물 2가지","url":"https://www.korea.kr/news/healthView.do?newsId=148906075","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "blue-crab": {"summary":"꽃게는 3~6월, 9~12월이 제철이에요. 봄에는 알 밴 암게, 가을에는 살 찬 수게가 좋고 들었을 때 묵직한 것을 고르세요. 암수 구분과 손질법을 정리했어요.","origin":"서해·남해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"꽃게는 우리나라에서 가장 많이 잡히는 식용 게로, 서해와 남해에 주로 삽니다. 일 년 내내 시장에 나오지만 봄과 가을을 제철로 칩니다. 봄에는 알을 밴 암게가, 가을에는 살이 오른 수게가 맛이 좋으니 계절에 맞춰 암수를 골라 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적어 맛이 담백합니다. 글리신, 베타인 같은 아미노산이 꽃게 특유의 맛을 냅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"배를 눌렀을 때 단단하고 들었을 때 크기에 비해 묵직한 것을 고르세요."},{"text":"다리가 뻣뻣하고 몸통에 단단히 붙어 있는지 보세요."},{"text":"배딱지가 둥글면 암게, 삼각형으로 모가 나 있으면 수게입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"제철에 산 꽃게는 손질해 냉동해 두면 두고 쓸 수 있습니다."},{"label":"손질법","text":"흐르는 물에서 솔로 등딱지와 배, 다리를 문질러 씻고 뾰족한 다리 끝은 잘라내세요. 등딱지를 떼고 아가미와 모래주머니를 제거합니다. 살아 있는 꽃게는 다치지 않게 조심해서 다루세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"꽃게탕. 된장이나 고추장 국물에 채소와 함께 끓입니다."},{"text":"꽃게찜. 생물 꽃게를 등딱지째 쪄서 살을 발라 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"꽃게의 주 생산 시기는 봄철 3~6월과 가을철 9~12월이고, 산란기인 7~8월은 금어기입니다. 국산은 몸 길이에 비해 몸통이 크고 등이 황갈색이며, 수입 게는 집게다리가 길고 가늘며 푸른색을 띱니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"제철수산물- 가을 ‘꽃게’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=16479","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"가을 건강 먹거리, 꽃게","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=13683","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"알아두면 좋은 꽃게 tip","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=7768","checkedAt":"2026-11-13"}]},
  "blueberry": {"summary":"블루베리는 6~8월이 제철이에요. 푸른색이 선명하고 표면에 은백색 가루가 묻은 단단한 것을 고르세요. 씻지 않고 냉장·냉동하는 보관법을 정리했어요.","origin":"전남·전북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"국내 블루베리는 2010년 무렵부터 본격적으로 재배되었습니다. 아직 시장에는 수입산이 많으니 국산 생과를 찾는다면 원산지 표시를 확인하세요. 생과, 냉동, 건조 제품이 함께 팔립니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"알이 단단하고 터지면서 새콤달콤한 과즙이 나옵니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"푸른색이 선명하고 단단한 것을 고르세요."},{"text":"표면에 은백색 가루(과분)가 묻어 있는 것이 좋습니다."},{"text":"붉은빛이 도는 것은 덜 익은 것입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻지 않은 채 냉장하고 먹기 직전에 씻으세요. 씻었다면 물기를 모두 빼고 밀폐용기에 담으세요. 오래 두려면 냉동합니다."},{"label":"손질법","text":"흐르는 물에 살살 헹궈 체에 밭쳐 물기를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"블루베리 요거트. 생과나 언 과실을 요구르트에 올립니다."},{"text":"블루베리잼. 설탕과 함께 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 듀크, 노스랜드, 블루크롭을 소개합니다. 건조 블루베리는 성분표에 블루베리 함량이 따로 적혀 있으니 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘블루베리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219953&menuNo=300063","checkedAt":"2026-11-12"}]},
  "bluefin-tuna": {"summary":"참다랑어는 회로 즐기는 12월~이듬해 2월이 제철이에요. 원산지와 자연산·양식 표시를 확인하세요. 참치 어종 구분과 임신부·어린이 섭취 기준을 정리했어요.","origin":"제주·남해·동해 연근해, 거문도(양식)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"흔히 참치라고 부르는 생선은 다랑어류이고, 그중 회로 먹는 것이 참다랑어입니다. 참다랑어는 몸길이가 3m에 이르는 고등어과의 대형 회유어로, 우리 바다에서는 제주도, 남해, 동해에 나타납니다. 어획 한도가 정해져 있어 잡은 참다랑어는 모두 수협 위판장을 거쳐야 합니다. 2018년부터는 국내 양식 참다랑어도 출하되고 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"육질이 부드럽고 맛이 좋아 주로 회로 먹으며, 뱃살 부위를 특히 귀하게 칩니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"회로 먹는 참치는 참다랑어, 통조림 참치는 가다랑어입니다. 포장이나 차림표에 적힌 어종명을 확인하세요."},{"text":"국내산은 자연산과 양식산이 함께 나오니 원산지와 양식 여부 표시를 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 밀봉해 냉장고에서 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"참다랑어는 오래 사는 대형 어종이라 메틸수은이 많이 쌓입니다. 식품의약품안전처 생선 섭취 가이드라인은 임신·수유부와 어린이에게 다랑어류를 일반 어류보다 적게 먹도록 한 주 섭취량을 따로 정해 두었습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"참다랑어회. 부드러운 살을 썰어 회로 먹습니다."},{"text":"뱃살 회. 기름진 뱃살은 따로 썰어 냅니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"다랑어류는 눈다랑어, 황다랑어, 가다랑어 같은 열대성과 태평양참다랑어, 남방참다랑어 같은 온대성으로 나뉩니다. 2015년 국립수산과학원 주관으로 거문도 양식장에서 양식에 성공했고, 2018년부터 양식 참다랑어가 출하됐습니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 참 좋은 고기 ‘참다랑어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=26786&select_list_no=78","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 3월 수산물 ‘참다랑어’, ‘가자미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=36548&select_list_no=20","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "bok-choy": {"summary":"청경채는 1~12월이 제철이에요. 잎줄기가 엷은 청록색으로 윤기 나고 시들지 않은 것을 고르세요. 데치는 순서와 남은 청경채 보관법을 정리했어요.","origin":"경기 일대","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"청경채는 중국 배추의 한 종류로, 잎과 줄기를 함께 데치거나 국거리, 겉절이로 씁니다. 연중 살 수 있지만 정보누리는 10월에 수확한 것이 가장 맛이 좋다고 소개합니다. 남기지 않고 한 번에 쓰는 편이 좋으니 쓸 양만큼 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로도 먹을 만큼 잎줄기가 연해 데칠 때는 끓는 물에 살짝만 담갔다 꺼냅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎줄기가 엷은 청록색을 띠고 광택이 있는 것을 고르세요."},{"text":"잎 끝까지 시들지 않은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"쓰고 남은 청경채는 밀봉해 냉장하세요."},{"label":"손질법","text":"잎 끝의 시든 부분을 잘라 내고 흐르는 물에 씻습니다. 데칠 때는 끓는 물에 뿌리 쪽부터 살짝 담갔다가 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"청경채 겉절이. 씻은 청경채를 생으로 양념에 가볍게 버무립니다."},{"text":"청경채국. 국거리로 넣어 짧게 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 적경채와 백경채를 듭니다. 농사로 농작업 일정은 봄 씨뿌림 재배와 가을 씨뿌림 재배를 나눠 안내하고 씨뿌림 시기를 4월 하순~9월 상순으로 잡아, 여러 차례 수확하며 연중 출하됩니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘청경채’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227350&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"청경채 농작업 일정","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbl/workScheduleDtl.ps?cntntsNo=30643&menuId=PS00087&sKidofcomdtySeCode=VC","checkedAt":"2026-11-12"}]},
  "bomdong": {"summary":"봄동은 2~4월이 제철이에요. 떡잎이 적고 연한 녹색이며 속잎이 노랄수록 고소하고 달아요. 한 잎씩 씻는 손질법과 겉절이 활용법을 정리했어요.","origin":"진도·해남·완도·칠곡","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"봄동은 겨울을 나고 2~4월에 나오는 배추로, 추위 때문에 잎이 옆으로 퍼진 개장형인 것이 특징입니다. 조직이 연하고 아삭해 겉절이로 많이 먹습니다. 너무 크지 않은 것을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"조직이 연하고 아삭합니다. 속잎이 노란색일수록 고소하고 달큰합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"떡잎이 적고 연한 녹색을 띠며 잎에 반점이 없는 것을 고르세요."},{"text":"하얀 부분이 짧고 선명한 것이 좋습니다."},{"text":"속잎이 노랗고 전체 크기가 너무 크지 않은 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"타월로 물기를 닦아 밀봉해 냉장하고, 되도록 빨리 드세요."},{"label":"손질법","text":"벌어진 잎을 모아 밑동을 자르고, 한 잎씩 떼어 흐르는 물에 여러 번 씻어 물기를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"봄동 겉절이. 아삭한 생잎을 양념에 바로 무칩니다."},{"text":"봄동전. 잎을 한 장씩 반죽에 묻혀 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지로 전남 진도, 해남, 완도와 경북 칠곡을, 품종으로 납작배추와 개장형 배추를 소개합니다. 국, 샐러드, 무침, 전에 두루 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘봄동’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227337&menuNo=300063","checkedAt":"2026-11-12"}]},
  "borimyeol": {"summary":"보리멸은 6~7월에 회로 즐기기 좋은 생선이에요. 몸이 가늘고 길며 주둥이가 길게 튀어나온 것이 특징이에요. 생김새와 고르는 법, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"보리멸은 한국과 일본에서 호주에 이르는 태평양 서부와 인도양에 사는 바닷물고기입니다. 몸은 낮고 길며 옆으로 납작하고, 주둥이가 매우 길게 튀어나와 있습니다. 비교적 큰 빗비늘로 덮여 있고, 등지느러미는 가까이 붙어 있지만 둘로 나뉘어 있습니다. 예부터 '봄 보리멸, 가을 망둑'이라는 말이 전해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"비늘이 단단히 붙어 반짝이고 눈알이 투명하게 튀어나온 것을 고르세요."},{"text":"몸에서 끈적한 점액이 나오는 것은 신선도가 떨어진 것이니 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"포장되지 않은 생선은 흐르는 찬물에 씻어 물기를 닦고, 랩으로 싸서 밀폐 용기에 넣어 냉장한 뒤 1~2일 안에 드세요."},{"label":"손질법","text":"비늘이 큰 편이니 먼저 비늘을 긁어내고, 내장을 뺀 뒤 살을 떠서 회로 먹습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"보리멸회. 손질한 살을 떠서 회로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"보리멸은 연안성 어류로 산란기는 6~8월이고, 산란 수온은 21℃ 정도입니다. 만 1년, 체장 14cm 정도가 되면 성숙해 산란에 참여합니다."}]}],"sources":[{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 보리멸","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11824","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"10월 이달의 수산물 ‘망둑어(망둥어)’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32897","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "bracken": {"summary":"고사리는 4~6월이 제철이에요. 생고사리는 반드시 끓는 물에 데쳐 먹고, 끝이 주먹처럼 말린 통통한 것을 고르세요. 묵나물 만드는 법을 정리했어요.","origin":"정선·양양·남원·구례·하동·함양","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"고사리는 4~5월에 어린 순을 꺾어 데치고 말려 묵나물로 많이 먹는 산나물입니다. 장에서는 생고사리, 말린 고사리, 삶은 고사리가 함께 나오며 고르는 기준이 각각 다릅니다. 생고사리는 날로 먹으면 안 되고 반드시 삶아야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생고사리와 묵나물 모두 쓰고 아린 맛이 있어, 데친 뒤 물에 불려 우려내고 먹습니다. 잎이 퍼진 것은 질기고 쓴맛이 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생고사리는 줄기가 굵고 곧으며 끝이 주먹처럼 말려 있고 잎이 크게 피지 않은 것을 고르세요."},{"text":"말린 고사리는 연한 갈색에 대가 통통하고 쭈글쭈글하지 않은 것이 좋습니다."},{"text":"삶은 고사리는 약간 밝은 갈색이고 너무 무르지 않은 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생고사리는 소금을 조금 넣은 끓는 물에 데쳐 햇볕에 말려 묵나물로 두세요. 데친 고사리는 물에 잠기게 담아 냉장하고, 말린 것은 밀봉해 냉장합니다."},{"label":"손질법","text":"고사리에는 비타민 B1을 분해하는 효소(티아미나아제)가 있어 반드시 끓는 물에 데치거나 삶아 먹어야 합니다. 식약처도 고사리처럼 독성분을 미량 가진 산나물은 끓는 물에 데쳐 먹으라고 안내합니다. 묵나물은 물에 불려 여러 번 우려내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"고사리나물. 데쳐서 쓴맛을 뺀 고사리를 간장과 들기름으로 볶습니다."},{"text":"육개장. 데친 고사리를 건더기로 넣고 얼큰하게 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 강릉, 정선부터 하동, 산청까지 여러 지역을 주산지로 듭니다. 야생 산나물은 독초와 헷갈리기 쉬우므로 식약처는 확실하지 않은 것은 채취하지 말라고 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘고사리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219829&menuNo=300063","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"산나물 채취 시 주의사항","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?menu_no=3120&bbs_no=bbs001&ntctxt_no=21779&menu_grp=MENU_NEW01","checkedAt":"2026-11-12"}]},
  "branching-mushroom": {"summary":"가지버섯은 10~11월이 제철이에요. 야생 버섯은 생김새가 비슷한 종이 있으니 식용으로 확인된 제품만 사세요. 손질법과 볶음, 국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"가지버섯은 농식품정보누리에서 민자주방망이버섯으로 소개하는 가을 버섯입니다. 갓과 주름이 연한 자주색을 띨 수 있지만 자라면서 색이 달라지므로 겉모양만으로 야생 버섯을 식별하지 마세요. 장에서는 식용으로 확인된 유통품을 구입해 밑동의 흙을 정리하고 충분히 익힙니다. 한 번에 먹을 양을 골라 볶음이나 국에 쓰기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 촘촘해 익히면 씹는 맛이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"식용으로 확인된 제품과 판매처를 확인하세요."},{"text":"갓이 무르거나 변질된 것은 피하세요."},{"text":"표면에 곰팡이나 물러진 자국이 없는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생버섯은 종이로 감싸 냉장하고 빨리 조리하세요."},{"label":"손질법","text":"밑동의 흙 묻은 부분을 잘라내고 깨끗이 씻은 뒤 충분히 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"가지버섯볶음. 손질해 데친 식용 제품을 채소와 볶습니다."},{"text":"가지버섯국. 데쳐 준비한 버섯을 국물에 넣어 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"여기서 가지버섯은 민자주방망이버섯을 뜻합니다. 야생 버섯은 생김새가 비슷한 종이 있어 외형만으로 식용 여부를 판단할 수 없습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘가지버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219928&deleteCd=0&pageIndex=1&selectMonth=11","checkedAt":"2026-11-12"}]},
  "broccoli": {"summary":"브로콜리는 9~12월이 제철이에요. 봉오리가 촘촘하고 노랗게 핀 곳이 없는 것을 고르세요. 줄기 겉을 벗기는 손질법과 데쳐 냉동하는 법, 무침을 정리했어요.","origin":"제주·횡성·제천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"브로콜리는 꽃이 피기 전의 작은 봉오리와 줄기를 먹는 채소입니다. 봉오리가 빽빽한 것은 데치면 모양이 잘 살아 샐러드나 볶음에 넣기 좋습니다. 굵은 줄기도 겉의 질긴 부분을 벗기면 속은 아삭하게 먹을 수 있으므로, 한 송이를 다듬을 때 따로 썰어 두세요. 익히는 시간이 다른 두 부위를 한 냄비에 조리할 때는 줄기를 먼저 넣습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"풋향과 은은한 단맛이 나고, 살짝 익힌 줄기는 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"봉오리가 촘촘하고 초록빛이 고른 것을 고르세요."},{"text":"꽃이 노랗게 벌어지지 않았는지 보세요."},{"text":"줄기 절단면이 말라 갈라지지 않은 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻기 전에는 냉장하세요. 데쳐 식힌 뒤 물기를 빼면 소분해 얼리기 좋습니다."},{"label":"손질법","text":"송이를 나눠 사이사이를 씻고 줄기는 질긴 겉을 벗깁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"브로콜리 무침. 데쳐 참깨 양념에 버무립니다."},{"text":"브로콜리 볶음. 줄기부터 넣고 봉오리를 나중에 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리의 생산기 표는 9~12월입니다. 같은 문서의 소개에서는 겨울과 이른 봄을 맛보기 좋은 시기로 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘브로콜리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219813","checkedAt":"2026-11-12"}]},
  "brussels-sprout": {"summary":"방울양배추는 1~2월이 제철이에요. 500원 동전만 하게 작을수록 달고 녹색이 진할수록 신선해요. 쓴맛 나지 않게 익히는 요령과 보관법을 정리했어요.","origin":"전남·제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"방울양배추는 1~2월에 나오는 작은 양배추로, 방울다다기양배추라고도 부릅니다. 크기에 따라 맛이 달라 작을수록 달고 클수록 쓴맛이 강합니다. 저장성이 좋아 한 번에 넉넉히 사도 됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"일반 양배추보다 식감이 부드럽고 단맛이 납니다. 익힐수록 단맛이 강해지지만 너무 익히면 쓴맛이 올라옵니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"500원 동전 크기 정도로 작은 것을 고르세요."},{"text":"녹색이 진한 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기 없이 밀폐용기에 넣어 냉장하면 2주까지 둘 수 있습니다."},{"label":"손질법","text":"겉잎을 떼고 꼭지 부분만 잘라 내고 조리하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"방울양배추 생식. 부드럽고 단맛이 있어 과일처럼 먹습니다."},{"text":"익힌 방울양배추. 단맛이 나도록 익히되 너무 오래 익히지 않습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지로 전라남도와 제주도를 소개합니다. 겨울 이슬이 내린 직후에 가장 맛있다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘방울양배추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227334&menuNo=300063","checkedAt":"2026-11-12"}]},
  "buckwheat": {"summary":"메밀은 10~11월이 제철이에요. 가루는 원재료 표시에서 메밀 함량을 확인하세요. 뭉치지 않게 찬물에 푸는 법과 메밀전병, 메밀묵을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"메밀은 국수나 전병, 묵으로 먹는 잡곡입니다. 가을에 수확한 곡물은 제분하거나 건조해 두므로 가루와 면 제품은 다른 계절에도 살 수 있습니다. 전병 반죽이나 묵을 만들 때는 제품에 따라 메밀과 다른 곡물의 비율이 다를 수 있으니 포장 표시를 확인하세요. 가루는 물에 조금씩 풀면 덩어리가 줄고 조리할 양만 꺼내 보관하기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"메밀 향은 은은하고 구수하며 묵으로 익히면 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"가루의 원재료와 메밀 함량을 보세요."},{"text":"포장에 습기가 차거나 가루가 굳지 않았는지 확인하세요."},{"text":"통곡은 깨진 알이나 이물질이 적은 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통곡은 밀폐해 습기를 피하고, 가루는 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"가루는 찬물에 조금씩 풀어 뭉침을 줄이세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"메밀전병. 가루 반죽을 얇게 펴 익힌 뒤 소를 넣습니다."},{"text":"메밀묵. 가루를 물에 풀어 저으며 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"국립식량과학원은 봄메밀과 가을메밀의 작기를 구분합니다. 정보누리의 10~11월은 가을 생산기이며 가공품 판매 시기와 다릅니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘메밀’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219912&deleteCd=0&pageIndex=1&selectMonth=10","checkedAt":"2026-11-12"},{"org":"국립식량과학원","title":"가을메밀 파종한계기 연구","url":"https://www.nics.go.kr/bbs/view.do?bbsId=research&bbsSn=202906&m=100000126","checkedAt":"2026-11-12"}]},
  "burdock": {"summary":"우엉은 1~3월이 제철이에요. 뿌리가 곧고 탄탄하며 껍질이 말라 주름지지 않은 것을 고르세요. 칼등으로 겉을 긁는 손질법과 우엉조림, 우엉김밥을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"우엉은 길고 가느다란 뿌리를 먹는 채소로, 손질할 때 흙 냄새와는 다른 특유의 향이 납니다. 채 썬 우엉은 볶거나 조리면 씹는 맛이 남아 김밥 속으로도 쓰기 좋습니다. 껍질을 두껍게 벗기기보다 흙을 먼저 씻어내고 칼등으로 겉을 얇게 긁으세요. 썰고 나면 색이 변하기 쉬워 조리를 바로 하거나 식초를 푼 물에 잠깐 담가 둘 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 구수하고 가늘게 채 썰어 조리해도 씹는 맛이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"곧고 탄탄한 뿌리를 고르세요."},{"text":"껍질이 심하게 말라 주름지지 않았는지 보세요."},{"text":"끝에 물러지거나 검게 상한 곳이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기 없이 싸서 냉장하세요. 조림에 쓸 양은 채 썰어 데친 뒤 냉동할 수 있습니다."},{"label":"손질법","text":"흙을 씻고 칼등으로 겉을 얇게 긁어 써세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"우엉조림. 채 썬 우엉을 간장 양념에 조립니다."},{"text":"우엉김밥. 조린 우엉의 물기를 덜어 속에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"통뿌리를 사면 껍질과 굵기를 직접 확인할 수 있습니다. 손질 우엉은 단면이 마르거나 물러지지 않았는지 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘우엉’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219816&deleteCd=0&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"}]},
  "butterbur": {"summary":"머위는 3~4월이 제철이에요. 잎은 진한 녹색, 대는 두껍지 않고 붉은빛이 도는 것을 고르세요. 아린 맛 빼는 손질법과 머윗잎 쌈밥을 정리했어요.","origin":"논산·서천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"머위는 3~4월에 나오는 봄나물로, 잎과 머윗대라고 부르는 잎자루를 먹습니다. 어린 머위는 쓴맛이 약하고 부드러워 잎과 줄기를 통째로 쓰기 좋습니다. 장에서는 생머위와 삶아 껍질을 벗긴 머위가 함께 나옵니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"독특한 풍미에 쌉싸래한 맛이 나고, 생것은 아린 맛이 있어 삶아서 우려낸 뒤 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎은 진한 녹색이고 검게 변색되지 않은 것을 고르세요."},{"text":"대는 두껍지 않고 붉은빛이 돌며 곧게 뻗은 것이 좋습니다."},{"text":"삶아서 파는 것은 껍질이 깨끗하게 잘 벗겨진 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"삶아 껍질을 벗긴 머위는 비닐봉지에 담아 냉장하고, 오래 두려면 냉동하세요."},{"label":"손질법","text":"공기에 닿으면 갈색으로 변하니 빠르게 끓는 물에 넣어 삶고, 찬물에 담가 아린 맛을 뺀 뒤 질긴 껍질을 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"머윗잎 쌈밥. 데친 머윗잎에 밥을 싸 먹습니다."},{"text":"머위 된장국. 손질한 머위를 넣고 된장국을 싱겁게 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 새끼손가락 굵기에 대가 곧고 길이가 50~60cm인 머윗대를 좋은 것으로 칩니다. 나물, 볶음, 조림, 장아찌로 두루 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘머위’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219840&menuNo=300063","checkedAt":"2026-11-12"}]},
  "butterbur-stalk": {"summary":"머위대는 3~4월이 제철이에요. 붙은 잎이 시들지 않고 줄기를 눌렀을 때 단단한 것을 고르세요. 고구마순과 구별하는 법과 껍질 쉽게 벗기는 법을 정리했어요.","origin":"충북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"머위대는 머위의 잎자루로, 3~4월에 나물거리로 나옵니다. 껍질을 벗겨 삶아 양념에 무치거나 생채로 무쳐 먹습니다. 생김새가 고구마순과 비슷하니 장에서 헷갈리지 않게 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생채로 무치면 새콤하고 쌉쌀한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붙어 있는 잎이 시들지 않은 것을 고르세요."},{"text":"줄기를 눌러 봤을 때 단단한 것이 좋습니다."},{"text":"고구마순은 머위대보다 가늘고 잎색이 진하며 보랏빛을 띠기도 하니 구별해서 사세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"삶지 않은 머위대는 마르지 않게 비닐팩에 넣어 0~5℃로 냉장하세요."},{"label":"손질법","text":"겉껍질이 두꺼우니 소금물에 삶은 뒤 벗기면 수월합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"머위대 들깨볶음. 껍질을 벗긴 머위대를 들깨와 함께 볶습니다."},{"text":"머위대 나물. 삶아 껍질을 벗긴 머위대를 양념에 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 물머위와 조생머위를, 주요산지로 충청북도를 소개합니다. 삶아서 나물로 무치거나 탕에 넣어 국을 끓입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘머위대’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219951&menuNo=300063","checkedAt":"2026-11-12"}]},
  "button-mushroom": {"summary":"양송이버섯은 시설 재배로 1~12월 내내 나와요. 갓이 동글고 갓 아래 피막이 터지지 않은 것을 고르세요. 변색을 막는 손질과 보관법을 정리했어요.","origin":"충남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"양송이버섯은 흰 갓이 동그랗게 오므라진 재배 버섯으로, 정보누리 생산시기가 1~12월이라 연중 살 수 있습니다. 주산지는 충남입니다. 갓이 피었거나 뒷면이 검게 변한 것은 신선도가 떨어진 것이니 갓 모양과 뒷면을 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"육질이 두껍고 단단하며 탄력이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"흰 빛깔에 갓이 동글동글하고 줄기가 통통한 것을 고르세요."},{"text":"갓이 너무 피지 않고 갓과 자루를 잇는 피막이 터지지 않은 것이 좋습니다."},{"text":"갓 뒷면이 검게 변한 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"키친타월로 물기를 닦고 2~3개씩 신문지에 싸서 냉장하세요. 오래 둘 것은 먹기 좋게 썰어 지퍼백에 담아 냉동하고, 해동 없이 바로 조리합니다."},{"label":"손질법","text":"기둥 밑을 살짝 도려내고 얇은 갈색 막을 칼로 긁어 냅니다. 조리 직전에 썰거나 레몬즙을 뿌리면 색이 변하지 않습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"양송이 치즈구이. 기둥을 떼어 낸 자리에 치즈를 넣어 굽습니다."},{"text":"양송이 수프. 세로로 썰어 수프나 카레에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 다향, 새아, 새정, 설원을 듭니다. 연중 생산되지만 정보누리는 10월의 제철농식품으로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘양송이버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219827&menuNo=300063","checkedAt":"2026-11-12"}]},
  "cabbage": {"summary":"양배추는 5~7월이 제철이에요. 봉긋하고 묵직하며 눌러도 쉽게 들어가지 않는 것을 고르세요. 겉잎으로 감싸고 심을 채워 두는 보관법을 정리했어요.","origin":"경남 밀양·전남 해남·전남 진도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"양배추는 생으로 샐러드에 곁들이거나 익혀서 먹는 잎채소입니다. 통째로 사면 실온에서 금세 마르거나 색이 변하고, 심 쪽이 먼저 상하기 쉽습니다. 다 쓸 수 있는 양인지 생각하고 통으로 살지 정하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎이 부드럽고, 찬물에 잠깐 담갔다 꺼내면 더 아삭해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"모양이 봉긋하고 둥글며 겉잎이 연한 녹색인 것을 고르세요."},{"text":"묵직하고 단단하면서 잎은 부드러운 것이 좋습니다."},{"text":"시든 겉잎, 상처, 벌레 먹은 자국이 있거나 손으로 눌렀을 때 쉽게 들어가는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바깥 잎 2~3장을 떼어 그 잎으로 몸통을 감싸 두세요. 심을 잘라 내고 물에 적신 키친타월을 채운 뒤 랩으로 싸 두면 싱싱하게 보관할 수 있습니다."},{"label":"손질법","text":"생으로 먹을 때는 찬물에 담갔다가 10분 안에 건지세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"양배추 샐러드. 찬물에 잠깐 담가 아삭해진 잎을 샐러드에 곁들입니다."},{"text":"양배추주스. 토마토나 사과와 함께 갈아 마십니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경남 밀양, 전남 해남·진도를 들고, 품종을 조생종, 중생종, 만생종으로 나눕니다. 반으로 잘라 파는 것은 꽃대가 올라와 있거나 노랗게 변한 부분이 많은지 단면을 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘양배추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219841&menuNo=300063","checkedAt":"2026-11-12"}]},
  "carrot": {"summary":"당근은 10~12월이 제철이에요. 색이 선명하고 눌러도 휘지 않는 단단한 것을 고르세요. 볶음용으로 데쳐 냉동하는 법과 당근 라페, 당근볶음을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"당근은 뿌리를 먹는 채소로 생으로 채 썰면 아삭하고 익히면 단맛이 두드러집니다. 농식품정보누리는 가을부터 초겨울까지를 대표 생산기로 안내하면서 계절에 따라 국내 생산 지역이 달라진다고 설명합니다. 장에서는 주황빛이 고르고 단단한 뿌리를 고르세요. 볶음이나 카레에 쓸 양이 많다면 비슷한 굵기로 잘라야 익는 시간을 맞추기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로 먹으면 아삭하고 은근히 달며, 익히면 부드러워지고 단맛이 도드라집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색이 선명하고 고른 것을 고르세요."},{"text":"표면에 깊게 갈라진 곳이 없는지 보세요."},{"text":"누를 때 휘거나 물러지지 않는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 닦아 냉장하세요. 볶음용은 잘라 데친 뒤 식혀 냉동할 수 있습니다."},{"label":"손질법","text":"흙을 물로 씻고 상처나 마른 끝을 다듬으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"당근 라페. 가늘게 채 썰어 식초와 기름으로 무칩니다."},{"text":"당근볶음. 두께를 맞춰 썬 뒤 짧게 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"대표 생산기와 판매 시기는 다릅니다. 계절에 따라 출하 산지가 달라져 연중 구매할 수 있으니 포장에 적힌 원산지를 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘당근’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219814&deleteCd=0&pageIndex=1&selectMonth=12","checkedAt":"2026-11-12"}]},
  "cassia-seed": {"summary":"결명자는 9~11월이 제철이에요. 볶은 것은 국산과 중국산 구별이 어려우니 원산지가 확실한 곳에서 사세요. 결명자차 끓이는 법과 습기 막는 보관법을 정리했어요.","origin":"전북·충북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"결명자는 씨앗을 볶아 보리차처럼 끓여 마시는 작물입니다. 껍질이 단단해 대개 볶은 상태로 팔립니다. 볶은 뒤에는 국산과 중국산을 구별하기 어려우니 원산지를 확인하고, 볶지 않은 것도 함께 파는 곳에서 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"특이한 냄새와 맛이 있습니다. 차로 끓일 때 양이 많거나 오래 끓이면 쓴맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"짧은 원기둥 모양에 한쪽 끝은 뾰족하고 다른 끝은 매끈한 것을 고르세요."},{"text":"원산지가 분명하고 볶지 않은 결명자도 함께 파는 곳에서 사세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"볶은 결명자는 방습제를 넣은 통에 담아 서늘하고 통풍이 잘 되는 곳에 두고, 오래 둘 것은 냉동하세요. 흑미와 헷갈려 밥에 넣는 일이 있으니 따로 표시해 두세요."},{"label":"손질법","text":"깨끗이 씻어 물기를 뺀 뒤 약한 불에 볶아 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"결명자차. 볶은 결명자를 물 1L에 10~15g 넣고 끓기 시작하면 약불에서 20분쯤 끓입니다."},{"text":"직접 볶은 결명자차. 볶지 않은 결명자를 씻어 약한 불에 볶은 뒤 같은 방법으로 끓입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 명윤결명(수원1호)을 들고 생산시기를 9~11월로 안내합니다. 대부분 볶은 상태로 팔리므로 원산지 표시가 고르는 기준이 됩니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘결명자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219958&menuNo=300063","checkedAt":"2026-11-12"}]},
  "catfish": {"summary":"메기는 6~8월이 제철이에요. 살이 탄탄하고 단면이 마르지 않은 토막을 고르세요. 바닷물고기 물메기와 구분하는 법과 미나리 넣은 메기 매운탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"메기는 입가에 수염이 달린 민물고기입니다. 여름에는 콩나물이나 미나리를 넣어 끓이는 메기 매운탕으로 자주 먹으며, 해양수산부도 8월 이달의 수산물로 메기를 소개했습니다. 집에서 탕을 끓일 계획이면 가시와 지느러미가 남기 쉬운 부위의 손질을 미리 부탁하세요. 토막 크기를 비슷하게 맞춰 구입하면 냄비에서 고르게 익히기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익힌 살은 부드럽고 맛은 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"살이 탄탄하고 단면이 마르지 않은 것을 고르세요."},{"text":"포장 안에 핏물이 과하게 고이지 않았는지 보세요."},{"text":"탕용은 고르게 토막을 낸 것이 편합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 빨리 조리하고, 오래 둘 분량은 냉동하세요."},{"label":"손질법","text":"판매처에서 지느러미와 내장 손질을 요청하세요. 민물 생선은 속까지 익혀 먹습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"메기 매운탕. 미나리와 콩나물을 넣어 끓입니다."},{"text":"메기찜. 토막 낸 메기를 채소와 함께 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"메기는 민물에서 살며 양식으로도 유통됩니다. 바닷물고기인 물메기와 구분해 사세요."}]}],"sources":[{"org":"해양수산부","title":"8월의 수산물 ‘메기·농어’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=62602&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"수산물 원산지 표시 대상","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=32033&select_list_no=25","checkedAt":"2026-11-12"}]},
  "cauliflower": {"summary":"콜리플라워는 9~12월이 제철이에요. 흰색이 고르고 얼룩 없이 꽃봉오리가 촘촘한 것을 고르세요. 떫은맛 없이 데치는 법과 냉동 보관법을 정리했어요.","origin":"제주·강원 평창·경기 용인·대전·경남 김해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"콜리플라워는 양배추에서 변이해 나온 채소로 꽃양배추라고도 부릅니다. 브로콜리와 모양은 같지만 색이 희고 단맛이 더 많습니다. 다른 채소보다 오래 두기 어려우니 먹을 만큼만 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로 먹으면 떫은맛이 강해 데쳐 먹습니다. 데칠 때 쌀뜨물을 쓰면 특유의 유황 냄새가 줄어듭니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꽃봉오리가 크지 않고 깨끗하며 빈틈없이 촘촘한 것을 고르세요."},{"text":"전체가 고른 흰색이고 얼룩 없이 둥근 모양인 것이 좋습니다."},{"text":"솜털이나 벌레가 있거나 작은 잎이 돋은 것, 잘랐을 때 회색 반점이 보이는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비닐에 담아 냉장하고, 오래 두려면 살짝 데쳐 냉동하세요. 꺼내 쓸 때는 물기를 충분히 빼세요."},{"label":"손질법","text":"물에 씻어 큰 줄기를 자르고 꽃봉오리의 작은 가지를 칼로 조각내세요. 식초와 밀가루를 조금 푼 물에 데친 뒤 찬물에 헹구지 말고 그대로 물기를 빼며 식히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"콜리플라워 샐러드. 데쳐서 식힌 뒤 샐러드에 넣습니다."},{"text":"콜리플라워볶음. 데친 콜리플라워를 기름에 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 제주, 강원 평창, 경기 용인, 대전, 경남 김해를 듭니다. 원산지는 지중해 연안이며, 국내에서는 1970년대 말부터 재배했습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘콜리플라워’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219811&menuNo=300063","checkedAt":"2026-11-12"}]},
  "celery": {"summary":"샐러리는 6~7월과 9~11월이 제철이에요. 줄기가 단단하고 잎이 누렇게 뜨지 않은 포기를 고르세요. 질긴 섬유 벗기는 법과 샐러드, 채소 수프를 정리했어요.","origin":"강원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"샐러리는 줄기가 길고 잎에서 향이 강하게 나는 미나리과 채소입니다. 생으로 먹을 때는 줄기를 얇게 썰고, 질긴 섬유가 느껴지면 바깥쪽 결을 벗기세요. 국이나 수프에는 잎을 조금만 넣어도 향이 더해집니다. 한 포기에서 줄기와 잎을 나눠 쓰려면 구입할 때 줄기의 단단함과 잎의 상태를 함께 보는 것이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"줄기는 아삭하고 씹으면 향이 강하게 퍼집니다. 잎은 줄기보다 향이 도드라집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 초록색이고 누렇게 뜨지 않은 것을 고르세요."},{"text":"줄기가 단단하고 눌러 움푹 들어가지 않는지 보세요."},{"text":"포기가 갈라져 마른 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장하고, 수프용으로 남긴 줄기는 다져 소분해 얼릴 수 있습니다."},{"label":"손질법","text":"줄기 사이의 흙을 씻고 바깥 대의 질긴 섬유를 벗깁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"샐러리 샐러드. 줄기를 얇게 썰어 다른 채소에 섞습니다."},{"text":"채소 수프. 줄기를 잘게 썰어 끓이고 마지막에 잎을 조금 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 재배되는 종류로 동양재래종과 황색종군 등을 소개합니다. 잎줄기를 사는 경우 생식과 가열에 각각 맞는 굵기를 골라 쓰세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘샐러리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219942&deleteCd=0&pageIndex=1&selectMonth=7","checkedAt":"2026-11-12"}]},
  "chamnamul": {"summary":"참나물은 4~9월이 제철이에요. 진한 청색이 선명하고 잎이 가늘며 잎자루가 연한 것을 고르세요. 재배 개량참나물과의 차이와 생으로 먹는 법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"참나물은 서늘하고 높은 지대, 계곡물이 흐르는 곳에서 잘 자라는 산나물입니다. 대량 재배가 어려워 시중에는 파드득나물이나 삼엽채를 개량참나물로 재배한 것이 많이 나오며, 토종 야생 참나물과는 다릅니다. 시설 재배로 사철 나오지만 자연산은 제철에 재래시장이나 장날에 잠깐 나옵니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 은은하고 상큼하며, 생으로 씹으면 식감이 좋습니다. 재배한 개량종은 야생과 향, 조직감이 다릅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"고유의 진한 청색이 선명하고 잎이 가늘며 신선한 것을 고르세요."},{"text":"잎과 잎자루가 연하고 부드러우며 잎 크기가 고른 것이 좋습니다."},{"text":"말린 참나물은 이물질이 없고 향이 살아 있는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기 없이 키친타월로 감싸 비닐봉지에 밀봉해 냉장하면 4~5일 갑니다."},{"label":"손질법","text":"시든 부분과 뿌리, 질긴 줄기를 다듬으세요. 데칠 때는 줄기처럼 단단한 부분부터 넣으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"참나물 겉절이. 생으로 양념에 가볍게 버무립니다."},{"text":"참나물무침. 데쳐서 나물로 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 참나물, 노루참나물, 가는참나물을 주요품종으로 소개합니다. 데친 참나물을 말려 묵나물로 두고 사철 먹기도 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘참나물’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219898&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chard": {"summary":"근대는 6~8월이 제철이에요. 잎이 짙은 녹색이고 줄기 끝이 시들지 않은 단을 고르세요. 굵은 줄기를 잎보다 먼저 익히는 요령과 근대 된장국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"근대는 잎과 줄기를 먹는 채소로, 여름에는 된장국이나 데친 나물로 먹기 좋습니다. 넓은 잎은 뜨거운 국물에서 금방 부드러워지고 줄기는 익는 데 시간이 조금 더 걸립니다. 한 단을 살 때 줄기가 굵고 질겨 보이면 잎과 나눠 손질하세요. 어린잎은 데쳐 무치고 굵은 줄기는 잘게 썰어 국에 넣으면 한 단을 두 가지 요리에 나눠 쓸 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎은 익히면 부드럽고 줄기는 씹는 맛이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 짙은 녹색인 것을 고르세요."},{"text":"잎에 누렇게 변한 곳이 적은지 보세요."},{"text":"줄기 끝이 시들거나 무르지 않은 단을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻기 전에는 봉지에 넣어 냉장하세요. 국에 쓸 것은 데쳐 물기를 짜고 소분해 얼립니다."},{"label":"손질법","text":"잎 사이 흙을 씻고 굵은 줄기는 잘게 썰어 잎보다 먼저 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"근대 된장국. 줄기를 먼저 넣고 잎을 나중에 넣습니다."},{"text":"근대나물. 데쳐 물기를 빼고 된장이나 참기름으로 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"질긴 줄기도 데치면 쓸 수 있습니다. 잎과 줄기의 두께가 다르면 따로 데쳐 식감을 맞추세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘근대’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219854&deleteCd=0&pageIndex=1&selectMonth=6","checkedAt":"2026-11-12"}]},
  "cheonhyehyang": {"summary":"천혜향은 2~3월이 제철이에요. 크기에 비해 묵직하고 꼭지가 잘 붙은 것을 고르세요. 얇은 껍질을 반으로 갈라 벗기는 법과 천혜향 주스를 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"천혜향은 제주에서 재배하는 만감류로 표면이 매끈하고 겉껍질과 속껍질이 얇습니다. 손으로 껍질을 잡아당기다 과육을 누르기 쉬워, 칼로 잘라 조각을 낸 뒤 벗기면 먹기 편합니다. 생과로 먹을 때는 같은 크기 중 묵직하고 탄력 있는 것을 고르고, 여러 개를 사면 눌리지 않도록 여유 있게 담아 두는 것이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단맛이 나고 향이 은은합니다. 속껍질이 얇아 과육이 부드럽게 느껴집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기에 비해 묵직하고 표면이 매끈한 것을 고르세요."},{"text":"꼭지가 잘 붙어 있는지 확인하세요."},{"text":"눌려 무르거나 껍질에 상처가 난 과실은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"얇은 껍질이 눌리지 않게 담아 냉장하세요. 주스용 과육은 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"씻은 뒤 반으로 가르고 먹기 좋은 크기로 나눠 껍질을 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"천혜향 주스. 손질한 과육을 갈거나 짭니다."},{"text":"천혜향 요거트. 과육을 한입 크기로 나눠 얹습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"레드향이 굵고 탄탄한 알맹이로 알려진 데 비해 천혜향은 얇은 속껍질과 부드러운 식감이 특징입니다. 제주 농업기술원은 수확 뒤 공동선과장에서 품질을 확인해 출하한 사례를 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘천혜향’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219821&pageIndex=1&selectMonth=2","checkedAt":"2026-11-12"},{"org":"제주특별자치도 농업기술원","title":"왜 최고가격 농산물인가 12호","url":"https://agri.jeju.go.kr/files/board/%EC%99%9C%EC%B5%9C%EA%B3%A0%EA%B0%80%EA%B2%A9%EB%86%8D%EC%82%B0%EB%AC%BC%EC%9D%B8%EA%B0%80%2812%ED%98%B8%29.pdf","checkedAt":"2026-11-12"}]},
  "cherry": {"summary":"체리는 5~6월이 제철이에요. 알이 크고 단단하며 과즙이 많고 적갈색을 띠는 것을 고르세요. 국산 체리 산지와 냉장·냉동 보관법을 정리했어요.","origin":"경북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"체리는 새콤달콤한 맛의 작은 과일입니다. 정보누리는 국산 체리의 생산시기를 5~6월, 주산지를 경북 지역으로 소개합니다. 보관 기간이 일주일 정도로 짧으니 먹을 만큼 나눠 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"새콤달콤하고 과즙이 많습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 크고 단단한 것을 고르세요."},{"text":"과즙이 풍부하고 적갈색을 띠는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"7일 정도 보관할 수 있으니 냉장해 두고 드세요. 냉동실에서 살짝 얼려 먹어도 좋습니다."},{"label":"손질법","text":"먹기 직전에 흐르는 물에 깨끗이 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"생체리. 흐르는 물에 씻어 꼭지째 냅니다."},{"text":"살짝 얼린 체리. 씻어서 물기를 닦고 냉동실에 잠깐 두었다가 먹습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 6월을 대표 달로 소개합니다. 국산 출하 기간이 짧으니 원산지 표시를 확인하고 사세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘체리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227342&menuNo=300063","checkedAt":"2026-11-12"}]},
  "cherry-tomato": {"summary":"방울토마토는 6~9월이 제철이에요. 꼭지가 싱싱하게 붙어 있고 탱탱한 것을 고르세요. 꼭지를 떼고 보관해야 하는 이유와 씻는 법, 파스타 활용을 정리했어요.","origin":"칠곡·논산·충주·김천·해남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"방울토마토는 6~9월에 많이 나오는 과채류로, 일반 토마토보다 작고 당도가 높습니다. 간식이나 후식으로 생으로 먹는 경우가 가장 많습니다. 품종 개량으로 색과 맛이 다양해졌으니 용도에 맞게 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"새콤달콤하고, 입안에서 톡 터지는 식감이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼭지가 시들거나 마르지 않고 싱싱하게 붙어 있는 것을 고르세요."},{"text":"과실이 둥글고 색이 일정하며 손으로 만졌을 때 탱탱한 것이 좋습니다."},{"text":"말랑하게 무르거나 병충해 흔적, 기형이 섞여 있지 않은지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"꼭지를 떼고 씻어 물기를 말린 뒤 키친타월로 싸서 비닐봉지에 넣어 냉장하세요. 밀폐용기에 넣으면 1~2주 갑니다. 꼭지를 달아 두면 쉽게 물러집니다."},{"label":"손질법","text":"꼭지를 떼고 식초물에 씻어 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"방울토마토 파스타 소스. 올리브기름에 살짝 익히고 허브를 뿌려 파스타에 버무립니다."},{"text":"방울토마토 새우 스파게티. 2~4등분한 방울토마토를 새우와 함께 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"방울토마토는 보통 60%쯤 익었을 때 따서 후숙하며, 나무에 달린 채 완숙된 것이 맛이 좋습니다. 정보누리는 주요품종으로 뽀또, 미니캐롤, 킹캐롤, 오렌지캐롤 등을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘방울토마토’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219882&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chestnut": {"summary":"밤은 8~10월이 제철이에요. 알이 굵고 윤기 나는 갈색이며 쥐었을 때 단단하고 무거운 것을 고르세요. 껍질 쉽게 벗기는 법과 보관 온도를 정리했어요.","origin":"전남 광양·충남 부여·경남 하동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"밤은 늦여름부터 10월 중순까지 수확하는 가을 견과입니다. 껍질째 파는 생밤과 깐 밤이 있고 수입산도 함께 팔립니다. 정보누리는 수입산이 알이 작고 윤기가 없으며 껍질에 흙과 먼지가 많이 묻은 경우가 많다고 설명합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로 먹으면 고소하고 아삭하며, 삶거나 구우면 달고 든든합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 굵고 모양이 도톰하며 껍질에 윤기가 도는 선명한 갈색인 것을 고르세요."},{"text":"벌레 먹은 곳이 없는지 확인하고, 쥐었을 때 단단하고 무거운 것이 좋습니다."},{"text":"겉껍질에 주름이 있거나 모양이 기형인 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생각보다 잘 상하고 곰팡이가 생기니 -1~0℃에 보관하세요. 껍질 벗긴 밤은 하룻밤 물에 담갔다가 말려 냉동하면 밥이나 요리에 쓰기 좋습니다."},{"label":"손질법","text":"생밤에 끓는 물을 부어 10분쯤 두었다가 바로 까면 겉껍질이 쉽게 벗겨집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"밤밥. 햇밤을 넣어 밥을 짓습니다."},{"text":"송편. 밤을 소로 넣거나 약식에 함께 넣습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전남 광양, 충남 부여, 경남 하동을, 품종으로 은기, 옥광, 축파, 대한을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘밤’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219916&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chestnut-bean": {"summary":"밤콩은 7월이 제철이에요. 껍질이 얇고 깨끗하며 밤색 윤기가 돌고 콩알이 고른 것을 고르세요. 울타리콩이라는 다른 이름과 밀봉 보관법을 정리했어요.","origin":"전국","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"밤콩은 밤 맛이 난다고 해서 붙은 이름으로, 울타리콩이라고도 부르는 토종콩입니다. 정보누리는 생산시기를 7월, 산지를 국내 전국으로 소개합니다. 타원형 콩알이 밤색을 띠어 다른 콩과 구분됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"이름처럼 밤 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 얇고 깨끗하며 밤색 윤기가 많이 나는 것을 고르세요."},{"text":"타원형이고 콩알 크기가 고른 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻어서 진공포장하거나 밀봉해 통풍이 잘 되는 곳에 두세요."},{"label":"손질법","text":"깨끗하게 씻어 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"밤콩밥. 씻은 콩을 쌀과 함께 안칩니다."},{"text":"밤콩조림. 삶은 콩을 간장 양념에 조립니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 밤콩을 채소류로 분류하고 생산시기를 7월 한 달로 적습니다. 울타리콩이라는 이름으로도 팔리니 두 이름을 함께 찾아보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘밤콩’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227364&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chicken-grunt": {"summary":"벤자리는 6월이 제철이에요. 회로 먹으려면 30cm가 넘는 돗벤자리를 고르고, 조리 전에 단단한 지느러미 침을 떼세요. 크기별 이름과 손질법을 정리했어요.","origin":"제주도, 추자도, 여서도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"벤자리는 난류성 물고기로, 우리나라에서는 제주도와 추자도, 여서도처럼 난류 영향을 강하게 받는 섬 지역에 여름에만 나타납니다. 30cm 미만은 아롱이, 40cm가 넘는 것은 돗벤자리라고 부릅니다. 양식이 안 되고 성질이 급해 활어로 다루기 어려워 산지에서는 여름 내내 선어로 팝니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살생선으로 담백하고, 산란 전에는 기름기가 많아 고소하고 차집니다. 열을 가하면 살의 탄력이 더 좋아집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"회로 먹을 것은 30cm 이상인 돗벤자리를 고르세요."},{"text":"선어로 팔리니 눈알이 밝고 투명하며 툭 튀어나온 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 얼음 위에 올려 포장해 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"지느러미의 침이 매우 단단하니 조리 전에 미리 떼어 내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"벤자리 물회. 담백한 살을 물회로 먹습니다."},{"text":"벤자리 구이. 산지에서는 구이나 조림으로 많이 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"산란기는 6~8월입니다. 저층 트롤과 낚시로 잡지만 양이 많지 않고 어획량이 줄어 귀한 생선이 되었습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"여름 최고의 횟감 ‘벤자리’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=31106","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "chicory": {"summary":"치커리는 7~8월이 제철이에요. 잎이 시들지 않고 연한 녹색이며 넓은 것을 고르세요. 금방 시드는 치커리를 촉촉하게 보관하는 법과 쌈·샐러드 활용을 정리했어요.","origin":"충북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"치커리는 쌉쌀한 맛과 독특한 향을 지닌 잎채소로, 일 년 내내 나오지만 한여름이 제철입니다. 주로 쌈과 샐러드로 생으로 먹고, 수프나 볶음에 넣기도 합니다. 보관이 어려운 채소라 한 번에 많이 사지 말고 먹을 만큼 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쓴맛이 있어 상추, 물냉이, 단맛 나는 피망과 함께 쌈이나 샐러드로 많이 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 시들지 않고 연한 녹색이며, 잎이 넓고 줄기가 긴 것을 고르세요."},{"text":"상처나 흠이 있는 것은 피하고, 씻어 나온 제품은 냉장 진열된 것을 사세요."},{"text":"고기나 생선과 함께 살 때는 핏물이 묻지 않게 봉지를 따로 담으세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지나 키친타월로 감싸고 분무기로 물을 뿌려 촉촉하게 한 뒤, 비닐봉지에 담아 구멍을 뚫어 냉장하세요."},{"label":"손질법","text":"흐르는 물에 잎을 깨끗이 씻어 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"치커리 샐러드. 상추, 피망과 함께 생으로 버무립니다."},{"text":"치커리무침. 쌉쌀한 잎을 양념에 무쳐 반찬으로 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 충청북도를, 품종으로 엔다이브, 적치커리, 트레비소치커리를 듭니다. 색과 잎 모양이 다른 여러 품종이 쌈 채소로 함께 팔립니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘치커리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219938&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chinese-yam": {"summary":"마는 10~11월이 제철이에요. 껍질이 고르게 희고 수염뿌리가 적으며 묵직하고 굵은 것을 고르세요. 갈변 막는 법과 신문지 보관법을 정리했어요.","origin":"안동·안성·진주·공주·용인","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"마는 10~11월에 캐는 뿌리채소로, 생으로 먹거나 갈아서 먹는 경우가 많습니다. 장에서는 통째로 파는 것과 잘라서 파는 것이 있으며, 잘린 것은 단면이 싱싱한지 보세요. 품종으로는 장마, 단마, 둥근마가 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"점성이 있어 미끌거리는 식감이 납니다. 생으로 먹는 경우가 많고, 미끌거림이 거북하면 갈아서 주스로 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"들었을 때 탱탱하고 무게감이 있으며 굵은 것을 고르세요."},{"text":"껍질이 하얗게 고르게 착색되고 수염뿌리가 적으며 울퉁불퉁하지 않은 것이 좋습니다."},{"text":"흙이 적당히 털리고 표면에 물기가 없는 것이 손질하기 쉽습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"햇볕에 한 번 말린 뒤 하나씩 신문지에 싸서 통풍이 잘 되는 곳에 두세요. 여름에는 비닐봉지에 밀봉해 냉장합니다. 오래 두려면 말려서 가루로 만드세요."},{"label":"손질법","text":"깨끗이 씻어 껍질을 벗기세요. 강판에 갈면 거무스름하게 변하니 묽은 식초를 바르세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"마 김쌈. 껍질 벗긴 마를 썰어 참기름 소금장에 찍고 김에 싸 먹습니다."},{"text":"마 주스. 간 마에 요구르트나 우유, 과일즙을 섞습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 장마, 단마, 둥근마를 듭니다. 밑부분도 맛이 좋으니 상태를 함께 살피세요. 조림, 전, 튀김, 구이, 죽 등으로도 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘마’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219881&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chonggak-radish": {"summary":"총각무는 10~12월이 제철이에요. 무청이 파랗고 짧으며 무청 쪽으로 갈수록 굵어지는 단단한 것을 고르세요. 껍질째 손질하는 법과 총각김치를 정리했어요.","origin":"전라도·충남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"총각무는 알타리무, 달랑무, 알무로도 불리며, 무청 모양이 총각의 땋은 머리를 닮아 붙은 이름입니다. 거의 김치용으로 쓰고, 무청은 말려 시래기로 씁니다. 깨끗하게 손질해 놓은 총각무는 들어온 지 오래된 것일 수 있으니 손질하지 않은 것을 사는 편이 낫습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"김치로 담그면 아삭하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"육질이 단단하고 매끈하며 심이 없는 것을 고르세요."},{"text":"무청이 파랗고 싱싱하며 짧은 것이 좋습니다."},{"text":"둥글둥글하면서 무청이 달린 쪽으로 갈수록 굵어지는 모양을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"4℃ 정도로 저온 보관하고, 냉장고를 쓸 수 없으면 신문지에 싸서 얼지 않게 베란다에 두세요."},{"label":"손질법","text":"껍질은 깎지 말고 겉을 깨끗이 씻은 뒤, 칼로 잔털과 불순물을 긁어내고 상투 같은 뿌리만 자르세요. 시든 무청은 떼고 잎 끝을 반쯤 잘라 두면 먹기 편합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"총각김치. 작은 것은 통째로, 굵은 것은 쪼개 무청째 새우젓, 고춧가루, 마늘, 생강으로 버무립니다."},{"text":"시래기 된장국. 말린 무청을 된장국에 넣어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전라도와 충청남도를, 품종으로 노루배기, 서울봄무, 쥐꼬리무 등을 듭니다. 홍토에서 자란 것을 가장 좋게 친다고 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘총각무’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219939&menuNo=300063","checkedAt":"2026-11-12"}]},
  "chwicheong-cucumber": {"summary":"취청오이는 12월~이듬해 2월이 제철이에요. 색이 진하고 단단하며 너무 굵지 않은 것을 고르세요. 오래 두기 어려운 취청오이의 냉장·냉동 보관법을 정리했어요.","origin":"호남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"취청오이는 남부 지방에서 겨울철에 시설 재배로 주로 키우는 청록색 오이입니다. 추위에 강해 12월부터 2월까지 가장 많이 나옵니다. 육질이 무른 편이라 오래 두기 어려우니 며칠 안에 먹을 만큼만 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"육질이 무른 편이라 날것으로 썰어 먹거나 생채, 무침으로 먹기 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기와 두께, 모양이 일정한 것을 고르세요."},{"text":"고유의 색이 진하고 단단한 느낌이 드는 것이 좋습니다."},{"text":"너무 굵은 것은 씨가 많아 맛이 떨어질 수 있으니 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻어서 키친타월이나 랩으로 싸 세워서 냉장하세요. 냉동할 때는 얇게 썰어 소금에 절이고 물기를 뺀 뒤 나눠 담습니다."},{"label":"손질법","text":"씻어서 바로 썰어 생으로 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"오이생채. 얇게 썰어 양념에 무칩니다."},{"text":"오이 샐러드. 썰어서 샐러드에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 호남 지역을 들고, 주요품종 칸에 청장계오이, 청오이, 가시오이 등을 함께 적습니다. 여름 오이와 달리 겨울에 많이 나오는 오이입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘취청오이’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227336&menuNo=300063","checkedAt":"2026-11-12"}]},
  "cockle": {"summary":"꼬막은 11월~이듬해 4월이 제철이에요. 껍데기가 깨지지 않고 무늬가 선명하며 윤이 나는 것을 고르세요. 참꼬막·새꼬막 구분과 해감하는 법을 정리했어요.","origin":"보성 벌교, 여자만 등 남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"꼬막은 서해와 남해 갯벌에서 나는 조개로, 시장에서는 참꼬막, 새꼬막, 피꼬막(피조개)을 주로 만납니다. 식당에서 흔히 먹는 것은 껍질에 솜털이 있는 새꼬막입니다. 산란기인 7~8월에는 맛이 떨어지고, 날이 추운 11월부터 4월까지 채취한 것이 맛이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"겨울 꼬막은 살이 차올라 쫄깃합니다. 참꼬막은 수분이 많고 살이 쫄깃하고, 새꼬막은 조갯살이 미끈합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"냄새가 나지 않고 껍데기가 깨지지 않은 것을 고르세요."},{"text":"무늬가 선명하고 윤이 나는 것이 싱싱합니다."},{"text":"털이 없으면 참꼬막, 껍데기 골이 좁고 털이 있으면 새꼬막입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"수분이 많아 오래 두면 맛이 떨어지니 빨리 드세요. 바로 못 먹으면 삶아서 살만 발라 밀폐해 냉동하세요."},{"label":"손질법","text":"굵은소금으로 문질러 씻고 소금물(물 5컵에 소금 1~2큰술)에 2~3시간 담가 해감하세요. 익혀도 입을 벌리지 않으니 뒤쪽 맞물린 부분에 젓가락을 끼워 비틀어 까세요. 피꼬막은 되도록 익혀 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"꼬막 양념무침. 살짝 데친 꼬막에 양념장을 얹습니다."},{"text":"꼬막 초무침. 데친 꼬막을 채소, 초고추장과 버무립니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"참꼬막은 사람이 갯벌에서 직접 캐고 자라는 데 4년쯤 걸려 값이 비싸고, 새꼬막은 2년이면 자라 배로 대량 채취하므로 저렴합니다. ‘보성벌교꼬막’과 ‘여자만새고막’은 지리적표시로 등록되어 있습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"11월 이달의 수산물 ‘꼬막’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=13870","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"2월 이달의 수산물 ‘꼬막, 대게, 홍게’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34597","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"2월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=55289&menuSeq=971","checkedAt":"2026-11-13"}]},
  "cod": {"summary":"대구는 11월~이듬해 2월이 제철이에요. 아가미가 선홍색이고 배가 단단하며 비늘이 단단히 붙은 것을 고르세요. 대구탕·뽈찜과 손질·보관법을 정리했어요.","origin":"거제","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"대구는 머리와 입이 큰 한류성 흰살 생선으로, 추운 계절에 주로 잡히고 주요 생산지는 거제 인근입니다. 산란기인 12~1월 무렵 살이 많아지고 알이 차서 겨울에 가장 맛이 좋습니다. 명태와 비슷해 보이지만 머리와 입이 더 크고 입 주위에 수염이 있습니다. 살이 물러 쉽게 상하니 신선도를 꼼꼼히 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"비린내가 적고 담백하며, 흰 살이 쫀득합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"아가미를 들췄을 때 선홍색인 것을 고르세요."},{"text":"빛깔이 푸르스름하고 배 부분이 단단한 것이 좋습니다."},{"text":"눈이 크게 튀어나와 있고 비늘이 연한 회색으로 광택이 나며 단단히 붙어 있는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통으로 샀다면 머리와 내장을 떼고 껍질을 벗겨 얇게 포를 뜬 뒤 소금을 뿌려 랩으로 싸서 냉장하거나 냉동하세요."},{"label":"손질법","text":"비늘을 긁고 깨끗이 씻어 4~5cm 길이로 어슷하게 토막 내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"대구탕. 콩나물, 무와 함께 된장을 풀어 끓입니다."},{"text":"대구 뽈찜. 살이 많은 머리로 만드는 부산 명물 음식입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"대구의 금어기는 1월 16일부터 2월 15일까지이고, 강원도는 3월 1일부터 15일까지입니다. 알, 아가미, 창자는 젓갈로 담그고, 통으로 말려 포로도 씁니다. 거제 외포항 일원에서는 매년 12월에 대구수산물축제가 열립니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"제철수산물- 겨울 ‘대구’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=16935","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"어두육미의 대표생선, 대구","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=14395","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"12월 이달의 수산물 ‘대게류, 대구’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38077","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"11월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=59115&menuSeq=971","checkedAt":"2026-11-13"}]},
  "conger-eel": {"summary":"바다장어는 6~8월이 제철이에요. 붕장어인지 어종을 확인하고 가시 손질이 된 것을 고르세요. 갯장어와 다른 점과 붕장어 소금구이, 양념구이를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"바다장어라는 판매명은 여러 어종에 쓰이지만, 이 페이지는 구이로 자주 먹는 붕장어를 다룹니다. 해양수산부는 붕장어를 7월 이달의 수산물로 선정했습니다. 한 마리를 구입할 때는 살을 펼치고 뼈와 가시를 손질해 달라고 부탁하면 집에서 굽기 편합니다. 양념이 발린 제품을 사면 추가 간을 하기 전에 포장의 원재료와 조리법을 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"구우면 고소하고 살은 부드러우면서 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붕장어인지 어종을 확인하세요."},{"text":"구이용은 가시 손질이 된 것을 고르세요."},{"text":"살이 마르거나 포장 안에 물이 많이 고인 제품은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질품은 냉장해 빠르게 익혀 먹고 나머지는 소분 냉동하세요."},{"label":"손질법","text":"뼈와 내장 손질은 판매처에 요청하고 양념 여부와 관계없이 속까지 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"붕장어 소금구이. 표면의 물기를 닦아 굽습니다."},{"text":"붕장어 양념구이. 살이 익어갈 때 양념을 발라 마저 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"갯장어와 붕장어는 모두 바다에 살지만 다른 어종입니다. 판매명이 바다장어일 때는 포장에서 실제 어종을 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"7월의 수산물 ‘붕장어·문어’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=62134&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"여름철 장어류","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=39584&select_list_no=1","checkedAt":"2026-11-12"}]},
  "corn": {"summary":"옥수수는 7~9월이 제철이에요. 껍질이 선명한 녹색이고 알이 촘촘하며 눌렀을 때 탄력 있는 것을 고르세요. 찰옥수수 찌는 법과 냉동 보관법을 정리했어요.","origin":"강원 홍천·영월·평창, 충북 괴산","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"옥수수는 강원도 산간을 중심으로 7~9월에 나옵니다. 쪄 먹는 풋옥수수는 쫀득한 찰옥수수와 단맛이 강한 단옥수수로 나뉩니다. 수확 뒤 시간이 지나면 당분이 전분으로 바뀌어 단맛이 떨어지니 산 날 바로 찌세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"찰옥수수는 쫀득하고 단옥수수는 달콤합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 선명한 녹색이고 알맹이가 촘촘히 박힌 것을 고르세요."},{"text":"찰옥수수는 알맹이가 꽉 차고 눌렀을 때 탄력이 있는 것이 좋습니다."},{"text":"껍질 가장자리가 말랐으면 알이 딱딱해지기 시작한 것입니다. 흰찰옥수수는 알이 반투명하지 않고 우윳빛인 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바로 먹지 않을 것은 한 번 쪄서 식힌 뒤 굳기 전에 냉동하세요."},{"label":"손질법","text":"찰옥수수는 껍질을 한 겹 남기고 찌세요. 알을 뗄 때는 칼보다 손으로 떼는 것이 좋습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"찐 옥수수. 찜통에 물을 조금 넣고 센 불에서 20~30분 찐 뒤 10분 뜸을 들입니다."},{"text":"옥수수밥. 냉동해 둔 알을 떼어 밥에 넣습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 강원 홍천, 영월, 평창과 충북 괴산을 듭니다. 품종은 마치종, 경립종, 감미종, 폭립종, 연립종, 나종 등으로 나뉩니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘옥수수’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219869&menuNo=300063","checkedAt":"2026-11-12"}]},
  "croaker": {"summary":"민어는 6~8월이 제철이에요. 살이 도톰하고 단면이 마르지 않은 것을 고르세요. 구이용 살과 탕용 뼈를 나눠 보관하는 법과 민어구이, 민어탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"민어는 여름에 탕으로 자주 먹는 흰살생선입니다. 해양수산부는 7월과 8월에 민어를 이달의 수산물로 선정한 바 있으며, 구이와 조림에도 쓸 수 있다고 소개합니다. 한 마리를 손질해 살과 뼈를 따로 받으면 도톰한 살은 굽고, 손질된 뼈와 머리는 무와 함께 국물에 쓸 수 있습니다. 살만 구입할 때는 두께와 단면의 상태를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살이 담백하고 부드러우면서도 탄력이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"도톰하고 탄력 있는 살을 고르세요."},{"text":"단면이 심하게 마르거나 물러지지 않았는지 보세요."},{"text":"탕용 뼈와 머리는 손질 상태를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 빨리 조리하고, 탕용과 구이용을 나눠 냉동할 수 있습니다."},{"label":"손질법","text":"판매처에 내장과 아가미를 제거해 달라고 요청하세요. 살은 남은 가시를 확인합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"민어구이. 두께가 비슷한 살을 골라 속까지 익힙니다."},{"text":"민어탕. 손질한 뼈와 무로 국물을 냅니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"민어는 민어과 바닷물고기입니다. 구입 시에는 포장의 어종과 산지를 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"7월의 수산물 ‘민어·전복’","url":"https://www.fsis.go.kr/front/api/totalView.do?cnts_id=39421&select_list_no=43&title=","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"8월 이달의 수산물","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=42549&menuSeq=971","checkedAt":"2026-11-12"}]},
  "crown-daisy": {"summary":"쑥갓은 5~6월이 제철이에요. 줄기가 짧고 가늘며 아래쪽까지 잎이 빽빽하고 광택 나는 것을 고르세요. 금방 시드는 쑥갓의 냉장·냉동 보관법을 정리했어요.","origin":"김해·하남·성남·이천·남양주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쑥갓은 국화과 채소로 향이 강해 탕이나 전골에 많이 넣습니다. 상추쌈에 곁들이거나 데쳐서 나물로도 먹습니다. 조금만 말라도 금방 시드니 바로 쓸 만큼만 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"독특한 향이 강합니다. 어리고 부드러운 잎은 날로 먹을 수 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 싱싱하고 색이 진하며 광택이 있는 것을 고르세요."},{"text":"줄기가 굵지 않고 짧고 가늘며, 아래쪽까지 잎이 빽빽한 것이 좋습니다."},{"text":"잎이 짓무르거나 찢긴 것, 대가 탄력이 없고 쉽게 부러지지 않는 오래된 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생으로 둘 때는 물을 촉촉하게 적셔 비닐팩에 담아 냉장하세요. 오래 두려면 소금물에 데쳐 물기를 빼고 랩으로 싸서 냉동합니다."},{"label":"손질법","text":"물에 너무 오래 씻지 마세요. 데칠 때는 살짝 데쳐 찬물에 넣으면 색이 살아납니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"쑥갓두부무침. 데친 쑥갓을 두부와 함께 무칩니다."},{"text":"해물전골. 쑥갓을 넣으면 향이 더해지고 해산물 비린내가 줄어듭니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 잎의 크기와 갈라진 정도에 따라 대엽종, 중엽종, 소엽종으로 나눈다고 설명합니다. 주산지는 김해, 하남, 성남, 이천, 남양주입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘쑥갓’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219839&menuNo=300063","checkedAt":"2026-11-12"}]},
  "cucumber": {"summary":"오이는 5~8월이 제철이에요. 위아래 굵기가 고르고 표면이 주름지지 않은 것을 고르세요. 백오이·청오이·취청오이 구분과 오이냉국, 오이소박이를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"오이는 물기가 많고 아삭해서 여름에 냉국이나 무침, 김치로 자주 먹는 채소입니다. 냉국이나 샐러드에 바로 쓸 때는 껍질이 마르지 않고 눌러도 단단한 것을 고르세요. 오이소박이용은 위아래 굵기가 비슷해야 썰고 절이기 쉽습니다. 꼭지 쪽에 쓴맛이 느껴지면 그 부분을 다듬고, 한 번에 먹을 양만 썰어 물기가 많이 빠지지 않게 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛이 산뜻하고 과육에 물기가 많으며 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"위아래 굵기가 고른 것을 고르세요."},{"text":"표면이 주름지거나 짓무른 곳이 없는지 보세요."},{"text":"손에 들었을 때 단단한 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 닦아 봉지에 담아 냉장하고 빠르게 드세요."},{"label":"손질법","text":"표면을 흐르는 물에서 문질러 씻고 꼭지 끝을 다듬습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"오이냉국. 채 썬 오이에 차가운 식초 국물을 붓습니다."},{"text":"오이소박이. 굵기가 비슷한 토막을 내어 절인 뒤 소를 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"백오이·청오이·취청오이 등 여러 종류가 있습니다. 정보누리는 겨울 시설 취청오이 생산기를 12~2월로 따로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘오이’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219868&deleteCd=0&pageIndex=1&selectMonth=5","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘취청오이’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227336&deleteCd=0&pageIndex=1&selectMonth=1","checkedAt":"2026-11-12"}]},
  "cuttlefish": {"summary":"갑오징어는 5월이 제철이에요. 몸통 살이 도톰하고 탄력 있는 것을 고르세요. 몸속의 갑과 먹물주머니를 빼는 손질법과 갑오징어 숙회, 볶음을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"갑오징어는 몸통 안에 납작하고 단단한 갑이 있는 오징어류입니다. 해양수산부는 5월에 맛보기 좋은 봄철 수산물로 갑오징어를 골랐습니다. 한 마리를 살 때는 몸통을 데침에 쓰고 다리는 볶음에 넣으면 두 부위의 씹는 맛을 각각 즐길 수 있습니다. 손질이 익숙하지 않으면 갑과 내장, 먹물주머니를 제거한 상태로 구입하는 편이 간편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛은 담백하고 몸통 살은 도톰하고 탄력이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통 살이 도톰하고 탄력 있는 것을 고르세요."},{"text":"표면이 마르거나 지나치게 끈적이지 않았는지 보세요."},{"text":"손질품은 냉장 상태와 포장 손상을 살피세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 빨리 익혀 먹고, 남은 것은 손질해 한 번에 쓸 양씩 냉동하세요."},{"label":"손질법","text":"몸통의 갑과 내장, 먹물주머니를 분리하고 다리의 눈과 입을 제거하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"갑오징어 숙회. 손질한 몸통을 썰어 속까지 익힙니다."},{"text":"갑오징어 볶음. 두께를 맞춰 썰고 채소와 볶습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"갑오징어의 갑은 몸 안에 있는 단단한 구조물입니다. 5월 선정은 월별 추천이며 어획기의 범위를 뜻하지 않습니다."}]}],"sources":[{"org":"해양수산부","title":"5월 이달의 수산물 ‘갑오징어·넙치’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=45819&menuSeq=971","checkedAt":"2026-11-12"}]},
  "daejeo-tomato": {"summary":"대저토마토는 2~5월이 제철이에요. 단단한 맛을 원하면 붉은빛과 초록빛이 함께 도는 것을 고르세요. 산지 표시 확인법과 토마토 구이를 정리했어요.","origin":"부산 강서구 대저동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"대저토마토는 낙동강 하류의 부산 강서구 대저동에서 재배합니다. 부산시 농업기술센터에 따르면 2~3월에 첫 수확을 시작하고 늦어도 5월 안에 출하를 마칩니다. 대저산 가운데서도 생식용은 단맛을 중시하고 요리용은 단단함과 신선도를 중시해 재배하는 품종이 다를 수 있습니다. 샐러드용을 살 때는 산지 표시와 꼭지 쪽 색을 함께 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단맛이 나고 과육이 단단해 한입 베어 물면 씹는 맛이 또렷합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"산지 표시에서 부산 강서구 대저를 확인하세요."},{"text":"단단한 과육을 좋아하면 붉은빛과 초록빛이 함께 도는 것을 고르세요."},{"text":"껍질이 갈라지거나 눌려 즙이 새는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"익은 것은 냉장하고, 잘라 남은 것은 밀폐해 냉장하세요. 소스용은 잘라 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"흐르는 물에 씻고 꼭지를 뗀 뒤 용도에 맞게 자르세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"대저토마토 샐러드. 과육을 얇게 썰어 올리브유를 곁들입니다."},{"text":"토마토 구이. 두껍게 썰어 자른 면을 팬에 굽습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"대저는 산지를 가리킵니다. 부산시 농업기술센터는 생식용에 단맛을 중시한 동양계 품종을, 요리용에 경도를 중시한 유럽계 품종을 쓰는 사례를 소개합니다."}]}],"sources":[{"org":"부산광역시 농업기술센터","title":"부산지역농산물 ‘토마토’","url":"https://www.busan.go.kr/nongup/agri","checkedAt":"2026-11-12"}]},
  "deodeok": {"summary":"더덕은 11월~이듬해 4월이 제철이에요. 껍질이 억세고 주름이 많으며 뿌리가 굵게 쭉 뻗은 것을 고르세요. 껍질 쉽게 벗기는 법과 더덕구이를 정리했어요.","origin":"정선·횡성·홍성·평창·가평","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"더덕은 뿌리를 먹는 산채로, 생육이 멈춘 가을부터 이듬해 봄 싹이 트기 전까지 캡니다. 뿌리 전체에 혹이 많아 껍질 벗기기가 번거롭습니다. 향이 진하고 속살이 흰 것을 고르면 손질한 뒤에도 맛이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 매우 강하고, 달면서도 쌉쌀한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 억세고 주름이 많으며 뿌리가 굵고 쭉 뻗은 것을 고르세요."},{"text":"크기가 일정하고 실뿌리가 적으며, 냄새를 맡았을 때 더덕 향이 나는 것이 좋습니다."},{"text":"표면에 상처나 짓무름이 있거나 말라서 변색된 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지에 싸서 마르지 않게 10℃ 이하에 두세요."},{"label":"손질법","text":"흙을 씻어 내고 칼집을 넣어 껍질을 벗기세요. 물에 불리거나 불에 살짝 구우면 껍질이 쉽게 벗겨집니다. 벗긴 더덕은 가볍게 두드려 소금을 넣은 찬물에 담가 쓴맛을 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"더덕구이. 얇게 저민 더덕을 참기름으로 무치고 양념장을 발라 석쇠에 굽습니다."},{"text":"더덕장아찌. 손질한 더덕을 고추장에 박아 둡니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농사로는 더덕을 아주심기 2~3년째에 10월 중순 이후부터 이듬해 봄 싹이 나오기 전까지 캔다고 안내합니다. 정보누리는 3~4월을 생산시기로 소개하고, 햇더덕을 구이로 먹기 좋다고 설명합니다. 어린잎은 나물이나 쌈으로도 먹습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘더덕’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219836&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"농작업일정 ‘더덕(양유)’","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbl/workScheduleDtl.ps?menuId=PS00087&cntntsNo=30741&sKidofcomdtySeCode=IC03","checkedAt":"2026-11-12"}]},
  "dragon-fruit": {"summary":"용과는 7~10월이 제철이에요. 겉에 상처 없이 매끈하고 빛깔이 선명한 것을 고르세요. 흰 과육과 붉은 과육의 맛 차이와 껍질 벗기는 법을 정리했어요.","origin":"제주·통영","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"용과는 선인장과의 열대 과일로, 국내에서는 제주와 통영 등에서 재배합니다. 과육 색에 따라 맛과 먹는 법이 다르니 속살 색을 확인하고 고르세요. 제주산 용과는 보존제 처리를 하지 않으므로 사 온 뒤 바로 냉장해야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰 과육은 아삭하고 새콤한 편이고, 붉은 과육은 부드럽고 단맛이 더 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"겉에 상처가 없고 매끈하며 빛깔이 선명한 것을 고르세요."},{"text":"같은 종류라면 열매가 클수록 상품입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비닐봉지에 담아 바로 냉장하세요. 껍질을 벗긴 과육은 밀폐용기에 담고, 쉽게 무르니 빨리 드세요."},{"label":"손질법","text":"물에 담가 흔들어 불순물을 털고 흐르는 물에 씻은 뒤 초록 돌기를 가위로 잘라 냅니다. 흰 과육은 손으로 껍질을 벗길 수 있고, 붉은 과육은 색소가 손에 묻으니 반으로 잘라 숟가락으로 떠먹으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"용과 과일샐러드. 다른 과일과 함께 썰어 담으면 과육 색이 돋보입니다."},{"text":"용과 요구르트 주스. 과육을 요구르트나 꿀물과 함께 믹서에 갑니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 품종을 백육종, 적육종, 황육종으로 나누고 제주에서는 백육종과 적육종을 재배한다고 소개합니다. 농촌진흥청은 국내 용과 수확이 농가에 따라 6월 중순부터 11월 중순까지 이어진다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘용과’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219871&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"국산 용과 더 달콤하고 맛있게 품질 높이기","url":"https://rda.go.kr/middlePopOpenPopNongsaroDBView.do?no=1901","checkedAt":"2026-11-12"}]},
  "east-sea-hanchi": {"summary":"동해한치는 12월~이듬해 5월이 제철이에요. 몸통에 탄력이 있고 광택이 도는 것을 고르세요. 제주한치와 다른 점, 손질법과 냉동 보관법을 정리했어요.","origin":"동해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"한치는 다리가 한 치(약 3cm)밖에 안 될 만큼 짧아 붙은 이름으로, 오징어보다 몸통이 길쭉합니다. 동해한치의 표준명은 화살꼴뚜기이고, 제주한치(창꼴뚜기)와는 생김새와 제철이 다릅니다. 동해한치는 봄에 산란하며 겨울부터 봄까지 맛이 좋으니, 같은 '한치'라도 산지를 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"오징어보다 씹히는 맛이 부드럽고 감칠맛이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통에 탄력이 있고 광택이 도는 것을 고르세요."},{"text":"판매명이 한치라도 동해산인지 제주산인지 산지 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생것을 그대로 얼려도 맛이 유지됩니다. 오래 두려면 손질해 껍질을 벗기고 씻은 뒤 쓰기 좋게 썰어 밀봉해 냉동하세요."},{"label":"손질법","text":"내장이 터지지 않게 조심해서 분리한 뒤 껍질을 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"한치회. 살이 연해 회로 많이 먹습니다."},{"text":"한치물회. 내장과 먹물을 뺀 한치를 가늘게 썰어 채소와 양념에 버무리고 찬 육수를 붓습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"제주한치는 여름에 산란하고 이때 가장 많이 잡히는 반면, 동해한치는 겨울부터 봄까지가 맛이 좋습니다. 한치는 오징어보다 값이 두 배 이상 비쌉니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"오징어보다 한 수 위, 한치","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=18408","checkedAt":"2026-11-13"}]},
  "eggplant": {"summary":"가지는 6~10월이 제철이에요. 짙은 보랏빛에 윤기가 돌고 꼭지가 마르지 않은 것을 고르세요. 냉장고보다 실온이 나은 이유와 손질법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"가지는 6~10월에 많이 나오는 과채류로, 껍질째 볶음·조림·절임으로 먹습니다. 매장에서는 보랏빛이 선명한지, 굵기가 고른지를 먼저 보세요. 몸통이 지나치게 굵은 것은 씨가 많으니 요리에 맞는 굵기를 고르는 것이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"날가지는 떫은맛이 있어 물에 담가 두면 떫은맛이 우러나 먹기 편해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"짙은 보랏빛이 선명하고 껍질에 광택이 나며 통통하게 탄력 있는 것을 고르세요."},{"text":"꼭지가 마르지 않고 까끌까끌한 가시가 그대로 만져지는 것이 신선합니다."},{"text":"껍질이 갈색을 띠거나 쭈글쭈글한 것, 들었을 때 가벼운 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"저온에 약해 8℃ 이하에서는 속살 색이 변하므로 실온에 두세요. 냉장할 때는 종이로 싸서 비닐봉지에 넣습니다. 오래 두려면 썰어서 말리세요."},{"label":"손질법","text":"껍질째 먹으니 깨끗이 씻고, 끝부분은 잘라 내세요. 물에 담가 두면 떫은맛이 빠집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"가지볶음. 껍질째 썬 가지를 기름에 볶아 양념합니다."},{"text":"가지치즈오븐구이. 가지 위에 치즈를 올려 오븐에 굽습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 품종을 조생종, 만생종, 대과종으로 나눠 소개합니다. 예전에는 나물과 찜 정도로 먹었지만, 외국 조리법이 알려지면서 파스타, 라자냐, 가지마파두부처럼 쓰임새가 넓어졌습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘가지’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219855&menuNo=300063","checkedAt":"2026-11-12"}]},
  "enoki-mushroom": {"summary":"팽이버섯은 시설 재배로 1~12월 내내 나와요. 하얀색이 탁하지 않고 밑동이 갈색으로 변하지 않은 것을 고르세요. 남은 팽이버섯 보관 요령을 정리했어요.","origin":"경북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"팽이버섯은 가늘고 긴 대에 작은 갓이 달린 재배 버섯으로, 봉지에 포장되어 팔립니다. 정보누리 생산시기는 1~12월이고 주산지는 경북입니다. 포장 안에 물기가 차 있거나 밑동이 변색된 것은 신선도가 떨어진 것이니 봉지 겉에서 살펴보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"씻어서 생으로 샐러드에 넣기도 하고, 찌개와 전골, 구이로 익혀 먹기도 합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"순백색이나 크림색으로 탁하지 않고 가지런한 것을 고르세요."},{"text":"뿌리 쪽이 짙은 다갈색으로 변했거나 줄기가 가느다란 것은 피하세요."},{"text":"흰 솜 같은 균사가 피어오르지 않고 물기가 차지 않은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지에 싸서 냉장하거나 포장을 뜯지 않은 채 두세요. 남으면 봉지째 밑동을 잘라 버섯을 위쪽으로 밀어 두고 남은 봉지를 끈으로 묶어 둡니다."},{"label":"손질법","text":"누르스름한 밑동을 잘라 내고 소쿠리에 담아 결결이 뜯어 가며 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"팽이버섯 베이컨말이. 베이컨에 돌돌 말아 굽습니다."},{"text":"버섯전골. 다른 버섯과 함께 전골이나 된장찌개에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 백로, 백설, 팽이버섯2호를 듭니다. 연중 생산되지만 정보누리는 1월의 제철농식품으로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘팽이버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219931&menuNo=300063","checkedAt":"2026-11-12"}]},
  "eolgari-cabbage": {"summary":"얼갈이배추는 11~12월이 제철이에요. 뿌리가 시들지 않고 흰 줄기를 눌렀을 때 탄력 있는 것을 고르세요. 크기별 쓰임과 데쳐서 냉동하는 법을 정리했어요.","origin":"전국","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"얼갈이배추는 속이 꽉 차지 않고 잎 끝이 벌어진 채 자라는 반결구형 배추입니다. 저장용 김치보다 바로 먹는 겉절이로 많이 담그고, 된장국이나 나물로도 먹습니다. 어린 배추라 커도 억세지 않으니 큰 것은 국거리로, 작은 것은 겉절이나 나물용으로 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"아삭한 식감이 있고, 된장국으로 끓이면 달면서 시원한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리 부분이 시들지 않고, 줄기의 흰 부분을 눌렀을 때 탄력이 있는 것을 고르세요."},{"text":"겉잎과 오염된 잎이 잘 정리되어 깨끗하고 선명한 녹색인 것이 좋습니다."},{"text":"벌레를 많이 먹었거나 곰팡이가 핀 것, 짓무른 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생것은 키친타월이나 신문지에 싸서 뿌리가 아래로 가게 세워 서늘한 곳에 두세요. 국거리로 쓸 것은 삶아서 적당히 뭉쳐 비닐팩에 담아 냉동합니다."},{"label":"손질법","text":"무른 잎을 떼고 줄기 끝을 잘라 깨끗이 씻으세요. 가운데 대가 억세면 끓는 물에 살짝 데쳐 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"얼갈이 겉절이. 싱싱할 때 바로 무쳐 먹는 김치로 담급니다."},{"text":"얼갈이 된장국. 된장을 풀어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 전국에서 재배하며 생산시기를 11~12월로 적습니다. 물기가 많은 채로 두면 곰팡이가 생기기 쉬우니, 젖은 채로 묶여 있는 것은 피하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘얼갈이배추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219895&menuNo=300063","checkedAt":"2026-11-12"}]},
  "fat-greenling": {"summary":"쥐노래미는 7월에 회로 즐기기 좋은 생선이에요. 몸 옆에 옆줄이 5줄 있고 눈 위에 촉수 한 쌍이 있어요. 생김새와 고르는 법, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쥐노래미는 쥐노래미과의 바다 생선으로, 우리나라 전 연안과 중국 북부, 일본 연안에 분포합니다. 모래나 펄, 암초 지대에 머무는 연안 정착성 어류로, 활동이 활발하지 않고 배를 암초에 댄 채 지냅니다. 소비 선호도가 높아 넙치보다 산지 출하 가격이 높은 고급 어종으로 소개됩니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸이 옆으로 납작하고, 몸 옆에 옆줄이 등 쪽 3줄과 배 쪽 2줄로 모두 5줄 있으며 눈 위에 촉수 한 쌍이 있습니다."},{"text":"눈알이 밝고 투명하며 튀어나와 있고, 아가미가 선홍색이나 분홍색인 것을 고르세요."},{"text":"손가락으로 살짝 눌렀을 때 살이 원래대로 돌아오고, 몸에 점액이 없는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"양턱 앞쪽에 날카로운 송곳니가 무리 지어 있으니 입 주변을 만질 때 조심하세요. 포장되지 않은 생선은 흐르는 찬물에 씻고 종이타월로 물기를 닦은 뒤 조리합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"쥐노래미회. 이 달력에서 7월 회로 소개하는 생선입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"쥐노래미의 산란기는 10~1월입니다. 다른 어종보다 겨울에도 빨리 자라며, 국립수산과학원은 2010년 인공 종자로 기른 어린 쥐노래미를 울진 바다목장 해역에 방류했습니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산생물종 정보 쥐노래미","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=10538","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"울진 바다목장해역에 고급어종 쥐노래미 방류","url":"https://www.fsis.go.kr/front/api/totalView.do?cnts_id=7055","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "fig": {"summary":"무화과는 9~10월이 제철이에요. 붉은색이 고르고 밑동 갈라진 부분이 마르지 않은 것을 고르세요. 쉽게 무르는 무화과의 보관법과 잼 만들기를 정리했어요.","origin":"영암","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"무화과는 가을 한철 짧게 나오고 껍질이 약해 쉽게 무릅니다. 껍질과 씨까지 함께 먹는 과일이라, 살 때는 바로 먹을 양만 고르고 남는 것은 잼으로 만들 계획을 세우면 버리는 것이 줄어듭니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익을수록 말랑하고 단맛이 강해집니다. 씨가 톡톡 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붉은색이 전체적으로 고르고 향이 진한 것을 고르세요."},{"text":"표면에 상처가 없고 둥글게 부푼 모양이 좋습니다."},{"text":"밑 부분 십자 모양으로 갈라진 곳이 마르지 않았는지, 꼭지가 싱싱한지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀봉해 냉장하고 되도록 빨리 드세요. 오래 두려면 말리거나 잼으로 만드세요."},{"label":"손질법","text":"흐르는 물에 살살 씻어 껍질째 먹고, 껍질 느낌이 불편하면 벗겨 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"무화과 샐러드. 반으로 갈라 잎채소와 치즈를 곁들입니다."},{"text":"무화과잼. 무른 무화과를 설탕과 함께 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 영암을 들고, 품종으로 승정도핀, 화이트제노아, 카도타 등을 소개합니다. 수확 뒤 오래 버티지 못하므로 산지와 가까운 시기에 사는 것이 좋습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘무화과’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219883&menuNo=300063","checkedAt":"2026-11-12"}]},
  "foxtail-millet": {"summary":"조는 9~10월이 제철이에요. 낟알이 작고 고르며 약간 납작한 것을 고르세요. 밥에 넣을 차조와 메조를 구분하는 법, 흘리지 않고 씻는 법을 정리했어요.","origin":"전북·강원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"조는 껍질을 벗기면 노란 좁쌀이 되는 잡곡입니다. 찰기가 있는 차조와 찰기가 없는 메조로 나뉘며, 밥에 넣을 것은 차조를 고르세요. 수입산은 낟알이 크고 고르지 않아 눈으로도 구분할 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"차조는 찰기가 있어 밥에 넣기 좋고, 메조는 찰기가 없고 식감이 까칠합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"낟알이 작고 고르며 약간 납작하고 가벼운 것을 고르세요."},{"text":"수입산은 낟알이 크고 고르지 않으며 구슬처럼 동글동글합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"충분히 말린 뒤 벌레가 생기지 않게 밀봉해 직사광선을 피해 서늘한 곳(10~15℃)에 두세요."},{"label":"손질법","text":"흐르는 물에 씻으면 다 쓸려 나가니, 바가지에 담고 물을 부어 손으로 비비며 여러 번 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"좁쌀밥. 차조를 쌀에 섞어 짓습니다."},{"text":"오메기떡. 제주에서 차조(청차조)로 만드는 떡입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전라북도와 강원도, 품종으로 황금조, 경관1호, 경관2호를 듭니다. 메조는 막걸리, 가자미식해 같은 음식에 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘조’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219962&menuNo=300063","checkedAt":"2026-11-12"}]},
  "freshwater-snail": {"summary":"다슬기는 7월이 제철이에요. 껍질이 깨지지 않고 길쭉하며 표면이 깨끗한 것을 고르세요. 3시간 넘게 해감하는 법과 날로 먹으면 안 되는 이유를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"다슬기는 맑은 하천 중·상류에 사는 민물 고둥으로, 지역에 따라 올갱이, 고디, 대사리 등으로 부릅니다. 주로 삶아서 살을 빼 먹고 국이나 수제비에 넣습니다. 폐흡충의 중간숙주라 날것으로 먹으면 안 됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"삶으면 국물이 우러나 그 국물째 국이나 수제비에 씁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 깨지지 않고 길쭉하며 큼직한 것을 고르세요."},{"text":"표면이 깨끗하고 살을 건드렸을 때 움직임이 좋은 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"해감한 뒤 헹궈 물기를 빼고 냉동하거나, 삶아서 살만 발라 보관하세요."},{"label":"손질법","text":"껍질을 세게 비벼 씻고 물에 3시간 넘게 담가 해감합니다. 반드시 익혀 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"다슬기수제비. 다슬기 삶은 국물에 수제비를 떠 넣고 살을 얹습니다."},{"text":"다슬기국. 아욱이나 부추를 넣고 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"국내 하천의 다슬기과 고둥은 8종인데 현지에서는 모두 다슬기라고 부릅니다. 해양수산부는 2023년 7월 이달의 수산물로 다슬기를 선정했습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"민물의 웅담 ‘다슬기’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=20519","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"민물장어, 다슬기, 조피볼락","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33822","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"2023년 7월 이달의 수산물 민물장어·다슬기·조피볼락","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=52144&menuSeq=971","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"수산물 구매, 운반, 보관 등 요령","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?bbs_no=bbs160617&menu_grp=MENU_NEW01&menu_no=4846&ntctxt_no=1096183","checkedAt":"2026-11-12"}]},
  "ganjaemi": {"summary":"간재미는 4월이 제철이에요. 지역에 따라 부르는 이름이 다르니 어종과 산지 표시를 확인하세요. 손질한 살 고르는 법과 간재미 초무침, 탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"간재미는 서해와 서남해안 등에서 부르는 이름으로, 지역에 따라 갱개미라고도 합니다. 한국학호남진흥원은 서해에서 4~6월에 맛이 좋고 진도에서는 12월부터 이듬해 3월까지를 제철로 소개합니다. 얇게 썰면 씹는 맛이 잘 드러나고, 탕에는 한입 크기로 토막 낸 것을 쓰기 좋습니다. 시장에서는 참홍어와 섞어 부르기도 하므로 어종을 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"얇게 썰면 연골의 오독한 식감이 남고 살은 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"간재미의 어종과 산지를 확인하세요."},{"text":"손질한 살은 표면이 지나치게 마르지 않았는지 보세요."},{"text":"냉장 포장 안에 즙이 많이 고이거나 살이 물러지지 않았는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장 상태를 유지해 빠르게 조리하고, 오래 둘 것은 소분 냉동하세요."},{"label":"손질법","text":"껍질과 내장 손질은 판매처에 요청하세요. 조리용은 먹기 좋은 크기로 잘라 충분히 익힙니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"간재미 초무침. 익혀 식힌 살을 채소와 무칩니다."},{"text":"간재미탕. 토막 낸 살을 무와 함께 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"한국학호남진흥원은 간재미를 홍어로 설명하고 흑산도 참홍어와 구분합니다. 구입할 때 지역 판매명과 실제 어종을 함께 확인하세요."}]}],"sources":[{"org":"한국학호남진흥원","title":"봄철 간재미, 흑산홍어가 부럽지 않다","url":"https://www.hiks.or.kr/HonamHeritage/8/read/634","checkedAt":"2026-11-12"}]},
  "garlic": {"summary":"마늘은 3~5월이 제철이에요. 겉껍질이 단단하고 묵직하며 쪽이 너무 벌어지지 않은 것이 덜 매워요. 껍질 쉽게 까는 법과 망 보관법을 정리했어요.","origin":"전남·충청","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"마늘은 3~5월에 나오는 양념 채소로, 생으로 먹거나 다져서 국과 찌개에 넣습니다. 정보누리는 6월 중순 이후 망마늘을 직거래로 사면 값이 싸다고 안내합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맵고 아린 맛이 납니다. 마늘쪽이 너무 크지 않고 대에서 많이 벌어지지 않은 것이 덜 맵고 덜 아립니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"겉껍질이 단단하고 하얗게 부풀어 있으며 무게감이 있는 것을 고르세요."},{"text":"쪽수가 적고 짜임새가 알찬 것이 좋습니다."},{"text":"싹이 돋거나 썩은 부분이 있는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"망에 넣어 10~15℃의 서늘한 곳에 두고 1개월 안에 쓰세요. 미리 까서 갈아 두면 냉장하거나 냉동해 쓰기 편합니다."},{"label":"손질법","text":"물에 불려 두면 껍질이 쉽게 벗겨집니다. 손에 밴 냄새는 식초 몇 방울을 떨어뜨려 씻으면 없어집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"마늘장아찌. 통마늘을 삭혀 장아찌로 담급니다."},{"text":"마늘구이. 통으로 구워 먹습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지로 전라남도와 충청도를, 품종으로 누리, 만산, 한산을 소개합니다. 통으로 넣어 육수를 내거나 편으로 썰어 양념에 찍어 먹기도 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘마늘’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219934&menuNo=300063","checkedAt":"2026-11-12"}]},
  "garlic-chive": {"summary":"부추는 6~10월이 제철이에요. 잎끝까지 짙은 초록색이고 밑동이 짓무르지 않은 단을 고르세요. 물기 없이 싸서 냉장하는 법과 부추전, 겉절이를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"부추는 잎이 길고 납작하며, 썰면 마늘이나 파를 닮은 알싸한 향이 납니다. 잎이 연한 한 단은 겉절이로 먹고, 굵은 잎은 잘라 전을 부치거나 볶음에 넣기 좋습니다. 밑동에 흙이 끼어 있을 수 있으니 묶음을 풀어 마른 잎을 골라내고 여러 번 헹구세요. 전을 부칠 때는 씻은 부추의 물기를 빼야 반죽이 묽어지지 않습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로는 알싸하고 익히면 향이 부드러워집니다. 어린 잎은 연합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎끝까지 짙은 초록색인 것을 고르세요."},{"text":"밑동이 짓무르지 않았는지 보세요."},{"text":"무침용은 잎이 여리고 지나치게 굵지 않은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기가 없도록 싸서 냉장하세요. 전이나 국에 쓸 분량은 썰어 냉동할 수 있습니다."},{"label":"손질법","text":"묶음을 풀고 누런 잎과 밑동의 흙을 제거해 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"부추전. 부추가 잠기지 않을 만큼 반죽을 얇게 묻혀 부칩니다."},{"text":"부추겉절이. 먹기 직전에 양념합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"한 단 안에서도 굵기에 차이가 있습니다. 생으로 먹을 잎과 익혀 먹을 잎을 손질할 때 나눠 두면 편합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘부추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219866","checkedAt":"2026-11-12"}]},
  "garlic-scape": {"summary":"마늘종은 4~5월이 제철이에요. 끝의 꽃봉오리가 단단히 닫혀 있어야 줄기가 연하니 꼭 확인하세요. 냉장 보관법과 장아찌·볶음 요리를 정리했어요.","origin":"고흥","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"마늘종은 마늘의 꽃줄기로, 4~5월 마늘을 키우는 동안 거둬들입니다. 장아찌나 볶음 반찬으로 많이 씁니다. 누런빛이 돌고 억센 것은 오래된 것이니 피하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로는 매운맛이 진하고, 기름에 볶으면 단맛이 생기며 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"줄기에 물이 올라 통통하고 진한 녹색인 것을 고르세요."},{"text":"줄기가 곧고 탄력 있으며 굵기가 일정하고 단단한 것이 좋습니다."},{"text":"끝의 꽃봉오리가 단단하게 닫혀 있어야 줄기가 연합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"적당한 길이로 잘라 비닐봉지에 싸서 냉장하면 일주일쯤 신선합니다. 간장에 절여 두어도 됩니다."},{"label":"손질법","text":"마르고 질긴 꼭지 부분을 잘라 내세요. 매운맛을 줄이려면 끓는 물에 살짝 데칩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"마늘종장아찌. 간장과 식초에 담그거나, 그늘에서 한나절 말려 고추장에 박습니다."},{"text":"마늘종 새우볶음. 마른새우와 함께 기름에 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"마늘종을 그대로 두면 마늘 구근이 제대로 자라지 못해 농가에서 따로 거둬들입니다. 장아찌를 담갔던 간장은 생선조림이나 볶음에 넣어 쓸 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘마늘종’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219835&menuNo=300063","checkedAt":"2026-11-12"}]},
  "ginger": {"summary":"생강은 8~11월이 제철이에요. 마디에 힘이 있고 주름이나 곰팡이가 없는 것을 고르세요. 숟가락으로 껍질 긁는 손질법과 썰거나 다져 냉동하는 법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"생강은 울퉁불퉁한 땅속줄기를 향신 재료로 쓰는 채소입니다. 얇게 썰어 차에 우리거나 다져 양념에 넣으면 알싸한 향이 납니다. 살 때는 평평한 부분만 보지 말고 마디가 갈라진 곳이나 틈에 곰팡이가 없는지 확인하세요. 손질할 때는 마디를 나눠 틈에 낀 흙을 씻고, 조림이나 양념에 한 번 넣을 만큼씩 나누면 꺼내 쓰기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로는 매운맛과 향이 또렷하고 섬유질이 씹힙니다. 끓이면 향이 국물에 퍼집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"마디에 힘이 있고 손에 들어 단단한 것을 고르세요."},{"text":"표면이 말라 주름지지 않았는지 보세요."},{"text":"틈에 곰팡이가 있거나 물러진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻기 전에는 물기 없이 냉장하고, 손질한 것은 얇게 썰거나 다져 소분해 얼리세요."},{"label":"손질법","text":"마디를 나눠 틈의 흙을 씻고, 껍질을 벗길 때는 숟가락으로 얇게 긁습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"생강차. 편으로 썰어 물에 우립니다."},{"text":"생강 조림 양념. 얇게 썬 생강을 조림 국물에 넣어 향을 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"생강은 땅속줄기라 마디 사이에 흙이 끼기 쉽습니다. 차나 절임에는 편으로 썰고 양념에는 다져 쓰면 편합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘생강’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219921&deleteCd=0&pageIndex=1&selectMonth=10","checkedAt":"2026-11-12"}]},
  "ginkgo-nut": {"summary":"은행은 9~11월이 제철이에요. 깨끗하고 은행 특유의 향이 나며 누렇게 변하지 않은 알을 고르세요. 속껍질 벗기는 법과 곰팡이 막는 냉동 보관법을 정리했어요.","origin":"양평·완도·광주·울산·대구·공주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"시장에 나오는 은행은 냄새가 고약한 겉 과육을 벗기고 씻은 상태로, 알만 팔거나 단단한 속껍질까지 까서 팝니다. 직접 주워 손질하면 냄새가 심하니 손질된 것을 사는 편이 쉽습니다. 오래된 것은 곰팡이가 피거나 색이 누렇게 변합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"볶거나 삶아 익혀 먹고, 밥이나 계란찜에 넣기도 합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"깨끗하고 은행 특유의 향이 나는 것을 고르세요."},{"text":"곰팡이가 피었거나 색이 누렇게 변한 것은 오래된 것이니 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"수분을 없앤 뒤 냉동하세요. 냉장하면 곰팡이가 필 때가 있습니다."},{"label":"손질법","text":"끓는 물에 살짝 데치면 속껍질을 벗기기 쉽습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"은행밥. 데쳐서 껍질을 벗긴 은행을 쌀에 넣어 밥을 짓습니다."},{"text":"은행 꼬치. 볶거나 삶은 은행을 꼬치에 꽂습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 양평, 완도, 광주, 울산, 대구, 공주를 들고 생산시기를 9~10월로 적습니다. 껍질째 파는 알과 속껍질까지 깐 알이 있으니 손질 상태를 보고 고르세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘은행’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219899&menuNo=300063","checkedAt":"2026-11-12"}]},
  "ginseng-root": {"summary":"인삼은 9~10월이 제철이에요. 수삼은 몸통이 단단하고 머리 쪽이 무르지 않은 것을 고르세요. 잔뿌리 틈을 솔로 씻는 법과 수삼·백삼·홍삼 구분을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"인삼을 생뿌리로 구입하면 수삼이라고 부릅니다. 가을에는 햇수삼을 구하기 좋으며, 바로 조리할 때는 몸통과 잔뿌리 사이의 흙을 솔로 조심스럽게 씻어냅니다. 몸통은 얇게 썰어 조리에 쓰고, 손질한 잔뿌리는 물에 넣어 향을 우릴 수 있습니다. 생뿌리와 건조·가공한 인삼은 수분과 향이 달라 조리법에 맞춰 고르는 편이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쌉쌀한 맛과 인삼 향이 나고, 생뿌리는 단단하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통이 단단하고 탄탄한 것을 고르세요."},{"text":"머리 쪽이 무르지 않았는지 보세요."},{"text":"은은한 황백색이고 곰팡이가 없는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"수삼은 냉장하고 가급적 빨리 사용하세요. 오래 둘 분량은 씻어 썰고 충분히 말릴 수 있습니다."},{"label":"손질법","text":"흙이 붙은 수삼은 물에 잠깐 불린 뒤 틈을 솔로 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"인삼차. 손질한 잔뿌리를 물에 우립니다."},{"text":"삼계탕. 씻은 수삼을 넣어 국물에 향을 더합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"수삼은 생인삼이며, 백삼은 건조하고 홍삼은 쪄서 말린 형태입니다. 이 초안의 제철은 햇수삼을 기준으로 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘인삼’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219902&deleteCd=0&pageIndex=1&selectMonth=9","checkedAt":"2026-11-12"}]},
  "gizzard-shad": {"summary":"전어는 8~10월이 제철이에요. 비늘이 많이 붙어 윤기가 나고 배는 은백색, 등은 초록빛인 것을 고르세요. 크기별 맛 차이와 구이·회무침 손질법을 정리했어요.","origin":"서해·남해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"전어는 청어과의 바닷물고기로, 서해와 남해를 중심으로 8월 중순부터 잡히기 시작합니다. 봄에 산란을 마치고 여름 동안 지방을 쌓아 가을에 고소한 맛이 납니다. 같은 가을 전어라도 크기에 따라 지방 함량 차이가 커서, 만 2년 이상 자란 큰 것이 더 고소합니다. 서해안 양식장에서 기른 전어도 나오는데, 겨울을 나지 못해 1년생 미만의 작은 것입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"가을 전어는 지방이 올라 고소하고, 구워도 회로 먹어도 맛이 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"비늘이 많이 붙어 있고 윤기가 나는 것을 고르세요."},{"text":"배는 은백색, 등은 초록빛인 것이 좋습니다."},{"text":"13cm 전어의 지방 함량은 5% 안팎, 18cm는 18% 안팎이니 고소한 맛을 원하면 큰 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 밀봉해 냉장고에서 가장 차가운 곳에 두고 1~2일 안에 드세요. 구이용은 내장을 그대로 둔 채 조리합니다."},{"label":"손질법","text":"구이는 비늘만 긁고 등에 칼집 2~3개를 넣어 소금을 뿌립니다. 회나 무침은 비늘, 머리, 지느러미, 꼬리, 내장을 떼고 흐르는 물에 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"전어 소금구이. 천일염을 뿌려 통째로 노릇하게 굽습니다."},{"text":"전어회무침. 채 썬 채소와 초고추장 양념에 전어회를 무칩니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"산란기는 3~8월(성기 4~5월)입니다. 자연산과 양식산이 함께 나오니 크기를 보고 고르세요. 8월 말부터 9월까지 여러 지역에서 전어 축제가 열립니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 가을 별미 ‘전어’ 맛보셨나요","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=13441&select_list_no=132","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 전어에 관한 진실 혹은 거짓","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=7622&select_list_no=151","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 9월 수산물 ‘대하’, ‘전어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=35570&select_list_no=26","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "glutinous-rice": {"summary":"찹쌀은 9~10월이 제철이에요. 입자가 고르고 부서진 가루가 적으며 붉거나 검은 쌀알이 없는 것을 고르세요. 멥쌀과 구별하는 법, 불리는 시간을 정리했어요.","origin":"전북·강원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"찹쌀은 익혔을 때 끈기가 매우 강한 쌀로 떡, 약식, 찰밥에 주로 씁니다. 멥쌀은 반투명하지만 찹쌀은 대부분 희고 불투명해 눈으로 구별할 수 있습니다. 도정일자가 최근일수록 밥맛이 좋으니 포장 날짜를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 멥쌀보다 끈기가 훨씬 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"부서지지 않고 입자가 고르며 쌀알이 깨끗한 것을 고르세요."},{"text":"쌀알에 골이 없고, 곰팡이로 생긴 붉거나 검은 쌀알이 섞이지 않은 것이 좋습니다."},{"text":"쌀알이 부서져 생긴 가루가 많지 않은지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"10~12℃에서 햇빛이 들지 않고 바람이 잘 통하는 곳에 두세요. 마른 홍고추나 통마늘을 함께 넣으면 벌레를 막는 데 도움이 됩니다."},{"label":"손질법","text":"흐르는 물에 씻고, 3~4시간 넉넉히 불린 뒤 조리하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"약밥. 찹쌀에 대추 등을 넣어 찝니다."},{"text":"인절미. 찹쌀로 찰떡을 쳐서 고물을 묻힙니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전라북도와 강원도, 품종으로 백옥찰, 화선찰을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘찹쌀’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219960&menuNo=300063","checkedAt":"2026-11-12"}]},
  "goby": {"summary":"망둥어는 9~10월이 제철이에요. 눈알이 밝고 투명하며 툭 튀어나온 것을 고르고, 사 오면 바로 내장을 빼세요. 회·조림 손질법과 짱뚱어 구분법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"망둥어(표준명 망둑어)는 갯벌에 많이 사는 물고기로, “봄 보리멸, 가을 망둑”이라는 말이 전해질 만큼 가을에 친숙합니다. 우리나라에는 문절망둑, 풀망둑, 말뚝망둥어 등 60여 종이 있고 대부분 20cm 미만입니다. 문절망둑은 꼬시래기라고도 부르니 이름이 달라도 같은 무리일 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적어 맛이 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈알이 밝고 투명하며 툭 튀어나온 것을 고르세요."},{"text":"눈알이 뿌옇거나 푹 꺼진 것은 신선도가 떨어진 것이니 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"되도록 빨리 내장을 빼고, 손질한 생선은 얼음 위에 올려 냉장해 1~2일 안에 드세요."},{"label":"손질법","text":"배를 갈라 내장을 꺼내고 지느러미를 뗀 뒤 칼등으로 비늘을 긁으세요. 회로 먹을 때는 뼈를 바르고 껍질을 벗기고, 튀김이나 매운탕에는 뼈를 그대로 둡니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"망둑어조림(꼬시락조림). 간장과 고춧가루 조림장에 졸입니다."},{"text":"망둑어 튀김. 뼈째 손질해 튀깁니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"짱뚱어는 망둑어와 사는 곳과 생김새가 비슷하지만 등지느러미가 화려하고, 망둑어는 등지느러미가 밋밋합니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"10월 이달의 수산물 ‘망둑어(망둥어)’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32897","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "goji-berry": {"summary":"구기자는 7~11월이 제철이에요. 색이 붉고 벌레 먹은 흔적이 없는 열매를 고르세요. 여름 구기자와 가을 구기자의 차이와 말려서 냉동 보관하는 법을 정리했어요.","origin":"충남 청양","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"구기자는 붉은 열매를 주로 말려 차로 우려 마시는 작물입니다. 청양군에 따르면 청양이 전국 생산량의 70%를 차지합니다. 말린 열매, 알구기자, 분말, 차 등 여러 형태로 팔리니 생열매인지 말린 것인지 확인하고 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"열매와 잎을 차로 우려 마시고, 여린 잎은 밥에 넣어 쪄 먹습니다. 여름에 딴 구기자는 가을에 딴 것보다 빛깔이 옅습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색이 붉은 열매를 고르세요."},{"text":"벌레 먹은 흔적이 있는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"햇볕에 곰팡이가 피지 않도록 바싹 말린 뒤 밀봉해 냉동하세요."},{"label":"손질법","text":"흙탕물이 나오지 않을 때까지 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"구기자차. 열매나 잎을 물에 우려 마십니다."},{"text":"구기자잎밥. 여린 잎을 밥에 넣어 함께 찝니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"청양에서는 8월부터 12월 초까지 수확하는데, 여름에 딴 것을 여름 구기자, 다시 열린 열매를 가을에 딴 것을 가을 구기자로 부릅니다. 정보누리는 생산시기를 7~11월로 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘구기자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227344&menuNo=300063","checkedAt":"2026-11-12"},{"org":"청양군농업기술센터","title":"청양군 구기자 재배 농가 여름 구기자 수확","url":"https://www.cheongyang.go.kr/cop/bbs/BBSMSTR_000000000152/selectBoardArticle.do?mno=sitemap_02&nttId=147624&pageIndex=47&searchCnd=&searchWrd=","checkedAt":"2026-11-12"}]},
  "gomchwi": {"summary":"곰취는 4~6월이 제철이에요. 잎이 크고 부드러우며 연한 녹색을 띠는 것을 고르세요. 쌈과 장아찌 활용법, 독초 동의나물과 구별하는 법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"곰취는 4~6월에 나오는 취나물의 한 종류로, 어린잎을 쌈이나 나물로 먹습니다. 잎이 거세지면 데치거나 장아찌로 만듭니다. 산에서 직접 뜯을 때는 생김새가 비슷한 독초 동의나물과 헷갈리지 않도록 주의해야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"부드럽게 쌉싸름한 맛과 은은한 향이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 크고 부드러우며 연한 녹색을 띠는 것을 고르세요."},{"text":"곰취 잎은 부드러운 털로 덮여 있습니다. 잎이 두껍고 표면에 광택이 있으면 독초인 동의나물일 수 있습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지에 싸서 냉장고 신선실에 두세요."},{"label":"손질법","text":"흐르는 물에 깨끗이 씻어 물기를 빼고 쓰세요. 잎이 거센 것은 끓는 물에 살짝 데칩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"곰취쌈. 어린잎에 고기를 싸 먹습니다."},{"text":"곰취 장아찌. 잎이 거세진 곰취를 간장이나 된장에 담급니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지를 한국 전역으로 적고, 주요품종 칸에 참취, 미역취, 개미취를 적습니다. 식약처는 산나물을 경험 없이 임의로 채취해 먹지 말라고 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘곰취’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227341&menuNo=300063","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"산나물 채취 시 주의사항","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?menu_no=3120&bbs_no=bbs001&ntctxt_no=21779&menu_grp=MENU_NEW01","checkedAt":"2026-11-12"}]},
  "gondeure": {"summary":"곤드레는 5~6월이 제철이에요. 많이 나올 때 넉넉히 사서 말려 두면 오래 먹을 수 있어요. 말린 곤드레 불리는 법과 곤드레나물밥을 정리했어요.","origin":"태백·정선·평창","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"곤드레는 정식 이름이 고려엉겅퀴인 산나물로, 잎이 부드러운 5~6월에 채취합니다. 강원 태백, 정선, 평창의 특산물로 알려져 있습니다. 장에서는 생나물과 말린 묵나물이 함께 나오니 바로 먹을지 두고 먹을지에 맞춰 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛이 담백하고, 어린잎과 줄기는 데치면 부드러운 나물이 됩니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 부드러운 어린잎과 줄기를 고르세요."},{"text":"자연산은 꺼끌꺼끌하지 않고 매끈합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생것은 습기 없이 서늘하고 통풍 좋은 곳에 두세요. 삶은 곤드레는 찬물에 헹궈 냉동하면 필요할 때 해동해 씁니다."},{"label":"손질법","text":"말린 곤드레는 물에 2~3시간 우렸다가 30분쯤 삶아 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"곤드레나물밥. 데친 곤드레를 썰어 들기름과 소금으로 양념해 쌀 위에 얹고 밥을 짓습니다."},{"text":"곤드레 장아찌. 간장, 설탕, 물, 식초를 끓여 식힌 뒤 곤드레에 붓습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"자연산과 재배한 것이 함께 유통됩니다. 생장점의 순이 연해 한 포기에서 여러 번 채취할 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘곤드레’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219853&menuNo=300063","checkedAt":"2026-11-12"}]},
  "gray-rockfish": {"summary":"볼락은 3월에 회로 즐기기 좋은 생선이에요. 눈 앞쪽 아래에 날카로운 가시가 두 개 있으니 손질할 때 조심하세요. 회와 볼락구이, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"볼락은 우리나라 전 연안의 암초가 많은 곳에 사는 정착성 어류입니다. 몸은 옆으로 납작한 타원형이고 눈이 크며, 몸색은 황갈색, 회갈색, 회흑색 등으로 다양하고 몸 옆에 흐린 가로무늬가 5~6개 있습니다. 지역에 따라 뽈락, 뽈라구, 열기, 우래기 등으로 부릅니다. 우럭으로 불리는 조피볼락과는 다른 종입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"구우면 껍질은 쫄깃하고 짭짤하며, 하얀 속살은 부드럽고 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸색은 황갈색부터 회흑색까지 다양하니, 색보다 눈알이 투명하고 아가미가 선홍색인지를 보세요."},{"text":"살을 눌렀을 때 단단하고 바로 되돌아오는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 생선은 0℃에 가까운 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"눈 앞쪽 아래의 날카로운 가시 두 개에 찔리지 않게 하세요. 구이용은 가위로 지느러미를 바짝 잘라 내고 소금 간을 해 30분 이상 재워 둡니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"볼락회. 손질한 살을 떠서 회로 먹습니다."},{"text":"볼락구이. 소금 간을 해 재운 볼락을 숯불에 굽고, 통째로 굽기도 합니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"볼락은 새끼를 낳는 난태생 어류로, 11월 하순~12월 초순에 교미해 이듬해 1~2월경에 새끼를 낳습니다. 거제시 관광 누리집은 볼락구이의 제철을 연중으로 안내합니다."}]}],"sources":[{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 볼락","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11748","checkedAt":"2026-11-13"},{"org":"부산광역시 수산자원연구소","title":"수산종자 생태특성 볼락","url":"https://www.busan.go.kr/fisheries/frfishpoint19","checkedAt":"2026-11-13"},{"org":"거제시 관광문화","title":"볼락구이","url":"https://tour.geoje.go.kr/index.geoje?menuCd=DOM_000008503006001005","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "green-bean": {"summary":"껍질콩은 4~10월이 제철이에요. 꼭지와 밑동이 시들지 않고 굵기가 비슷한 것을 고르세요. 양 끝과 질긴 실을 다듬는 손질법과 버터볶음, 무침을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"껍질콩은 어린 꼬투리를 통째로 먹을 수 있어 끝을 다듬은 뒤 볶음이나 조림에 씁니다. 농식품정보누리는 국내 재배지가 한정돼 있다고 안내하므로 구입할 때 포장에 적힌 원산지를 확인하세요. 같은 꼬투리라도 어린 것은 연하고, 알이 크게 불룩한 것은 씹었을 때 콩알과 껍질의 식감 차이가 커집니다. 한 접시에 볶을 때는 굵기가 비슷한 것을 고르면 익는 속도를 맞추기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"어린 꼬투리는 익혀도 가볍게 아삭하고 풋향이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼭지와 밑동이 시들지 않았는지 보세요."},{"text":"선명한 빛을 띠고 굵기가 비슷한 것을 고르세요."},{"text":"심하게 구부러져 마르거나 물러진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 닦아 냉장하고, 오래 두려면 데친 뒤 식혀 물기를 빼고 냉동하세요."},{"label":"손질법","text":"양 끝을 자르고 질긴 실이 있으면 벗긴 뒤 충분히 익혀 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"껍질콩 버터볶음. 익힌 콩을 버터에 짧게 볶습니다."},{"text":"껍질콩 무침. 데친 뒤 물기를 빼고 참깨를 넣어 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"어린 꼬투리째 먹는 용도와 성숙한 알을 말려 쓰는 용도가 있습니다. 볶음이나 무침에는 연한 꼬투리가 알맞습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘껍질콩’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219832&deleteCd=0&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"}]},
  "green-grape": {"summary":"포도는 8~10월이 제철이에요. 알이 고르고 촘촘하며 줄기가 푸르고 흰 가루가 덮인 송이를 고르세요. 국산 품종별 시기와 세척·보관법을 정리했어요.","origin":"김천·상주·영천·영동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"포도는 8~10월에 나오며 국내에서는 캠벨얼리와 거봉을 가장 많이 재배합니다. 송이째 팔기 때문에 알이 잘 붙어 있는지, 송이 안쪽까지 익었는지를 보고 고르세요. 최근에는 씨 없는 외국 품종도 많이 들어옵니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"꼭지 쪽이 가장 달고 아래쪽으로 갈수록 신맛이 납니다. 맛을 볼 때는 송이 아래쪽 알을 먹어 보세요."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 굵고 크기가 고르며 알 사이가 촘촘한 송이를 고르세요. 들었을 때 알이 후두둑 떨어지면 수확한 지 오래된 것입니다."},{"text":"줄기가 푸르고, 알 표면의 흰 가루가 뽀얗게 덮인 것이 좋습니다. 흰 가루는 천연 과실 왁스입니다."},{"text":"농촌진흥청은 송이 무게 400~500g 정도를 권합니다. 너무 크고 알이 많은 송이는 안쪽에 덜 익은 알이 있을 수 있습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비닐이나 신문지에 싸서 냉장하세요. 농촌진흥청은 포도를 0℃ 안팎에서 보관하라고 권하므로 김치냉장고가 알맞습니다. 오래 둘수록 단맛이 떨어집니다."},{"label":"손질법","text":"송이째 물에 1분 정도 담갔다가 흐르는 물에 꼼꼼히 씻으세요. 밀가루나 베이킹소다를 쓰면 더 잘 씻깁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"포도잼. 물러지려는 포도를 졸여 잼을 만듭니다."},{"text":"포도 주스. 냉동해 둔 포도를 갈아 마십니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 김천, 상주, 영천, 영동을, 품종으로 거봉, 캠벨얼리, 블랙올림피아, 델라웨어, 네오머스캣을 듭니다. 농촌진흥청은 국산 품종 진옥(8월 하순)과 흑보석(9월 상순)을 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘포도’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219905&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"이달의 농업기술 ‘추석 선물용 맛있는 과일 고르기’","url":"https://www.rda.go.kr/middlePopOpenPopNongsaroDBView.do?no=1049","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"보도자료 ‘더 오래 신선하게’ 똑똑한 과일, 채소 보관법","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&prgId=day_farmprmninfoEntry&mode=updateCnt&dataNo=100000790713","checkedAt":"2026-11-12"}]},
  "green-mandarin": {"summary":"청귤은 8~9월이 제철이에요. 진한 초록색이 돌고 단단한 풋귤을 고르세요. 풋귤과 재래 청귤의 차이, 얇게 써는 손질법과 풋귤청 활용을 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"8~9월에 초록 껍질째 나오는 제주 풋귤은 다 익기 전에 수확한 온주밀감입니다. 장볼날에서는 화면에 청귤로 표시하고, 농촌진흥청은 풋귤과 재래 귤인 청귤을 별도로 구분합니다. 풋귤은 산미가 강해 통째로 깎아 먹기보다 얇게 썰어 음료나 청에 씁니다. 껍질까지 사용하는 요리가 많으니 살 때 표면의 상처와 눌린 곳을 먼저 살피세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"신맛이 강하고 껍질에서 감귤 향이 납니다. 얇게 썰어 쓰면 껍질이 덜 질기게 느껴집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"진한 초록색이 돌고 단단한 열매를 고르세요."},{"text":"껍질이 갈라지거나 무른 것은 피하세요."},{"text":"포장에서 산지와 풋귤 표기를 살펴보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"구입한 뒤 냉장하고 빠르게 손질하세요. 음료용은 썰어 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"흐르는 물로 껍질을 씻고 양 끝을 다듬어 얇게 써세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"풋귤청 탄산수. 완성한 청을 탄산수에 풀어 마십니다."},{"text":"풋귤 드레싱. 짠 즙을 기름과 섞어 샐러드에 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"농촌진흥청은 제주 풋귤의 출하기를 8월 1일~9월 15일로 안내합니다. 같은 기관에서 설명하는 재래 청귤은 껍질이 거칠고 씨가 많으며 3~4월에 수확합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘청귤’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=227347&pageIndex=1&selectMonth=8","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"‘풋귤·청귤’ 이름 비슷해도 다른 귤","url":"https://www.rda.go.kr/board/board.do?dataNo=100000804147&mode=view&prgId=day_farmprmninfoEntry","checkedAt":"2026-11-12"}]},
  "green-onion": {"summary":"대파는 9~12월이 제철이에요. 흰 줄기가 탄탄하고 초록 잎이 누렇지 않은 것을 고르세요. 썰어서 소분 냉동하는 법과 대파기름, 대파된장무침을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"대파는 흰 줄기와 초록 잎을 모두 쓰는 향채입니다. 흰 부분을 기름에 볶으면 향이 올라오고, 얇게 썬 초록 잎은 국물에 넣거나 고명으로 쓸 수 있습니다. 한 단을 살 때 흰 줄기가 너무 억세거나 잎 끝이 누렇지 않은지 살펴보세요. 용도에 맞게 흰 부분과 초록 잎을 나눠 두면 손질한 대파를 국이나 볶음에 필요한 만큼 꺼내 쓰기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로는 알싸하고, 익히면 매운맛이 부드러워지면서 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"흰 줄기가 탄탄하고 너무 억세지 않은 것을 고르세요."},{"text":"초록 잎이 시들거나 누렇지 않은지 보세요."},{"text":"밑동이나 잎 사이에 짓무른 곳이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻지 않은 대파는 물기 없이 냉장하세요. 씻어서 썬 대파는 물기를 빼고 소분 냉동합니다."},{"label":"손질법","text":"뿌리와 마른 겉잎을 다듬고 잎 사이에 흙이 남지 않게 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"대파기름. 흰 부분을 썰어 기름에 천천히 볶습니다."},{"text":"대파된장무침. 데쳐 물기를 뺀 뒤 된장 양념에 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 봄에 꽃대가 오른 대파는 질겨질 수 있다고 안내합니다. 생으로 써는 양이 많으면 단면과 줄기의 단단함을 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘대파’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219944","checkedAt":"2026-11-12"}]},
  "green-pea": {"summary":"완두콩은 4~6월이 제철이에요. 꼬투리가 짙은 녹색이고 마르지 않았으며 콩알이 고른 것을 고르세요. 꼬투리째 냉장·냉동하는 법을 정리했어요.","origin":"경북 고령·경남 고성·인천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"완두콩은 긴 초록 꼬투리 속에 동그란 콩알이 든 콩으로, 꼬투리째 사거나 깐 콩으로 삽니다. 꼬투리째 먹는 연협종, 콩만 먹는 경협종, 둘 다 먹는 겸용종으로 나뉘니 먹는 방법에 맞춰 고르세요. 농촌진흥청은 국내에서 생산하는 완두가 대부분 풋협용이라고 설명합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"콩알이 입안에서 톡 터지고 고소합니다. 오래 삶으면 고소한 맛이 사라지고 색이 어두워집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼬투리가 짙은 녹색이고 마르지 않은 것을 고르세요."},{"text":"꼬투리를 열었을 때 낟알이 고르고 동글동글하며 진한 녹색인 것이 좋습니다."},{"text":"벌레 먹거나 상처 난 것, 물러진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"꼭지를 따지 않은 꼬투리째 봉지에 담아 냉장하거나, 급속 냉동했다가 밥이나 요리에 쓰세요."},{"label":"손질법","text":"풋내가 가실 정도로만 살짝 삶으세요. 꼬투리째 먹을 때는 소금을 넣은 끓는 물에 살짝 데칩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"완두콩밥. 밥을 지을 때 콩을 함께 넣습니다."},{"text":"완두콩 수프. 삶은 콩을 갈아 수프나 죽으로 끓입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"농촌진흥청은 완두를 남부지방은 2월, 중부지방은 3월에 파종하고 꽃이 핀 뒤 25~30일이면 수확할 수 있다고 설명합니다. 정보누리는 주산지로 경북 고령, 경남 고성, 인천 등을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘완두콩’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219848&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"웹진 ‘텃밭에서 완두 키우기’","url":"https://www.rda.go.kr/webzine/2021/04/sub4-2.html","checkedAt":"2026-11-12"}]},
  "green-plum": {"summary":"매실은 5~7월이 제철이에요. 장아찌용 청매실은 단단하고 눌린 곳이 없는 것을 고르세요. 청매실과 황매실 차이, 씨를 뺀 과육 냉동법을 정리했어요.","origin":"광양·순천·하동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"매실은 매화나무의 열매로 장아찌나 청에 두루 씁니다. 같은 매실도 녹색일 때 수확한 청매실과 노랗게 익은 뒤 따는 황매실은 향과 단단함이 다릅니다. 장아찌를 담글 때는 단단하고 흠이 적은 청매실을 고르세요. 황매실은 익으면서 향이 짙어지지만 쉽게 무르므로 사 온 뒤 오래 쌓아 두지 말고 바로 손질하기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"새콤한 맛이 강하고 청매실 과육은 단단합니다. 황매실은 향이 짙고 과육이 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색이 선명하고 크기가 고른 것을 살피세요."},{"text":"청매실은 단단하고 눌린 곳이 없는 것이 좋습니다."},{"text":"갈라짐이나 벌레 먹은 흔적이 있는 알은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생과는 오래 쌓아 두지 말고 빠르게 손질하세요. 씨를 뺀 과육은 가공용으로 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"흐르는 물에 씻어 물기를 말리고 꼭지를 떼세요. 씨는 먹지 않으며 덜 익은 열매는 생으로 먹지 않습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"매실장아찌. 단단한 청매실의 씨를 빼고 과육을 사용합니다."},{"text":"매실청 음료. 완성된 매실청을 물에 희석해 차갑게 마십니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"청매실과 황매실은 익은 정도에 따른 구분입니다. 재배 품종은 남고·앵숙·백가하 등이 있습니다. 농사로 구례 사례에서는 완숙 매실 수확 적기를 6월 10일 이후로 봅니다. 제주 재배 자료는 녹색 상태에서 수확한 매실을 바로 출하하는 관행을 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘매실’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219859&pageIndex=2&selectMonth=6","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"매실 수확 적기","url":"https://www.nongsaro.go.kr/portal/ps/psx/psxa/mlrdCurationDtl.ps?curationNo=33&menuId=PS03974","checkedAt":"2026-11-12"},{"org":"제주특별자치도 농업기술원","title":"매실 수확 자료","url":"https://www.agri.jeju.go.kr/jeju/local/resource.htm?act=download&no=1&page=30&seq=31053","checkedAt":"2026-11-12"}]},
  "gwamegi": {"summary":"과메기는 11월~이듬해 1월이 제철이에요. 꽁치인지 청어인지 원재료 표시를 확인하세요. 개봉 뒤 보관법과 과메기 미역쌈, 채소무침을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"과메기는 꽁치나 청어를 차가운 바람에 말려 만든 수산 가공품입니다. 해양수산부는 과메기를 12월 이달의 수산물로 선정했습니다. 사 올 때는 원료가 무엇인지, 껍질을 벗긴 손질품인지, 냉장이나 냉동 중 어느 방식으로 보관해야 하는지 확인하세요. 먹을 양만 덜어 얇은 미역과 쪽파를 곁들이면 씹는 맛과 향을 한입에 즐길 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"말린 살이 쫀득하며 원료 생선의 고소한 풍미가 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꽁치인지 청어인지 원재료 표시를 보세요."},{"text":"냉장·냉동 상태와 소비기한을 확인하세요."},{"text":"진공포장이 뜯기거나 액체가 새는 제품은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"제품의 보관 표시를 따르고, 개봉 후 남긴 양은 밀폐해 냉장하거나 제품 표시대로 냉동하세요."},{"label":"손질법","text":"손질품은 먹을 만큼 덜어 자르세요. 껍질이 붙은 것은 벗겨 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"과메기 미역쌈. 미역에 과메기와 쪽파를 얹습니다."},{"text":"과메기 채소무침. 먹기 직전에 채소와 양념을 섞습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"과메기의 제철은 말려 만든 제품이 나오는 시기를 뜻합니다. 원료 어종의 어획기와 완제품 판매 시기는 구분됩니다."}]}],"sources":[{"org":"해양수산부","title":"12월 이달의 수산물 ‘과메기·복어’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=59442&menuSeq=971","checkedAt":"2026-11-12"},{"org":"서울특별시 보건환경연구원","title":"계절별 안전하게 수산물 섭취하는 꿀정보","url":"https://sihe.seoul.go.kr/archives/557043","checkedAt":"2026-11-12"}]},
  "hairtail": {"summary":"갈치는 10~12월이 제철이에요. 은빛 표면에 윤기가 돌고 살이 도톰한 토막을 고르세요. 남은 토막을 물기 닦아 냉동하는 법과 무조림, 소금구이를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"갈치는 몸이 길고 납작하며 은빛이 도는 생선입니다. 수산물안전정보는 10~12월을 제철로 소개하고, 해양수산부는 갈치를 10월 이달의 수산물로 선정했습니다. 손질 갈치는 조림 냄비나 팬에 들어갈 만큼의 길이와 두께를 보고 고르세요. 무를 깔고 조릴 때는 무를 먼저 익힌 뒤 갈치를 얹으면 부드러운 흰살을 오래 끓이지 않아도 됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살이 부드럽고 제철 갈치는 구웠을 때 고소한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"은빛 표면에 윤기가 있고 상처가 적은 것을 고르세요."},{"text":"조림용은 살이 도톰한 토막이 편합니다."},{"text":"단면이 심하게 마르거나 살이 무른 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바로 조리할 토막은 냉장하고, 나머지는 물기를 닦아 소분해 냉동하세요."},{"label":"손질법","text":"내장을 제거한 토막의 배 안쪽을 다듬고 조리 전 물기를 닦습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"갈치 무조림. 무를 먼저 익힌 뒤 갈치를 얹습니다."},{"text":"갈치 소금구이. 물기를 닦고 앞뒤를 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"갈치의 은빛 표면은 일반 생선의 비늘과 다릅니다. 토막을 살 때는 은빛과 함께 단면과 살의 탄력도 보세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"은빛 옷 입은 대도어, 갈치","url":"https://fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=5651&select_list_no=159","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"10월 이달의 수산물 ‘갈치·꽃게’","url":"https://fsis.go.kr/front/api/totalView.do?cnts_id=28076&select_list_no=535&title=","checkedAt":"2026-11-12"}]},
  "halfbeak": {"summary":"학꽁치는 2월이 제철이에요. 작고 살이 통통하며 주둥이 주변이 노란빛인 것이 기름이 잘 오른 거예요. 뱃속 검은 막 벗기는 손질법과 회무침을 정리했어요.","origin":"남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"학꽁치는 아래턱이 앞으로 길게 뻗은 흰살 생선으로, 이름은 비슷해도 등푸른 생선인 꽁치와는 다른 어종입니다. 우리나라에서는 8월부터 이듬해 봄까지 연안에서 많이 잡히고, 겨울로 갈수록 몸집이 커지고 기름이 오릅니다. 잡으면 곧 죽어 수족관에서 살지 못하니 시장에서는 대개 죽은 상태로 만납니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적어 담백하고 향이 독특합니다. 살이 투명하고 맛이 깨끗해 봄철 횟감으로 씁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"작고 살이 통통하게 오른 것을 고르세요."},{"text":"주둥이 주변이 노란빛을 띠면 기름이 잘 오른 것입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"내장을 빼고 햇볕에 말려 두었다가 구워 먹기도 합니다. 꾸덕하게 말려 구우면 비린내가 적습니다."},{"label":"손질법","text":"배를 가르면 내장을 둘러싼 검은 막이 있습니다. 이 막을 잘 벗겨 내야 쓴맛이 나지 않습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"학꽁치회무침. 포를 떠서 5cm 길이로 썰고 채 썬 배, 양배추, 오이, 깻잎과 초고추장에 버무립니다."},{"text":"학꽁치조림. 무를 넣고 조립니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"줄꽁치는 학꽁치와 비슷하지만 크기가 작고 아가미뚜껑에 비늘이 있습니다. 수산물안전정보는 학꽁치를 2월 수산물로 소개합니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 학꽁치","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32299&select_list_no=57","checkedAt":"2026-11-12"}]},
  "hallabong": {"summary":"한라봉은 12월~이듬해 3월이 제철이에요. 껍질이 얇고 과육에서 들뜨지 않은 것을 고르세요. 수확 시기별 맛 차이와 상온 보관법, 껍질 활용법을 정리했어요.","origin":"제주·나주·밀양","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"한라봉은 꼭지가 툭 튀어나온 모양의 만감류로, 제주 특산물이며 전남 나주와 경남 밀양 등에서도 재배합니다. 12월부터 3월까지 수확하는데, 정보누리는 2~3월에 가장 맛있게 익는다고 설명합니다. 막 수확한 것은 푸석하고 즙이 적으니 수확 후 조금 지난 것을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"껍질이 얇은 것일수록 당도가 높고 맛이 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 얇은 것을 고르세요."},{"text":"껍질이 과육에서 들떠 있거나 주름이 많으면 신맛이 강하거나 싱거울 수 있습니다."},{"text":"제주 상품 기준은 한 개 200g 이상, 당도 12.0브릭스 이상입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"18~25℃ 정도에서 바람이 잘 통하는 곳에 두면 일주일 정도 먹을 수 있습니다."},{"label":"손질법","text":"소금으로 껍질을 문질러 씻고, 껍질은 먹기 직전에 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"한라봉 마멀레이드. 껍질과 과육을 섞어 설탕을 넣고 졸입니다."},{"text":"한라봉 껍질차. 깨끗이 씻은 껍질을 말려 차로 우립니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 비풍, 사가 34호를 듭니다. 제주농업기술원은 노지 한라봉은 3월에 수확하며, 1월에 수확하면 고유의 맛과 향이 부족하다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘한라봉’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219820&menuNo=300063","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원","title":"영농상담 ‘농지에 과수(감귤묘목) 식재에 따른 문의사항입니다’","url":"https://agri.jeju.go.kr/agri/communication/hardship.htm?page=4&act=view&seq=56845","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원 서귀포농업기술센터","title":"2020년 새해영농실용화교육 ‘고품질 만감류 재배기술’","url":"https://agri.jeju.go.kr/files/board/40a561f6-e5de-4e68-bdbd-1405b53c239d.pdf","checkedAt":"2026-11-12"}]},
  "herring": {"summary":"청어는 12월~이듬해 1월이 제철이에요. 아가미가 선홍색이고 배 쪽 살이 은백색으로 선명한 것을 고르세요. 알이 찬 청어가 나는 때와 보관 기한을 정리했어요.","origin":"동해, 남해 진해만","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"청어는 등이 푸른 청어과의 한류성 생선으로, 동해안 겨울 별미인 과메기 재료로도 씁니다. 산란기(3~4월) 전인 10월~이듬해 1월에 알이나 이리가 꽉 찬 것이 가장 맛있고 기름기도 많습니다. 산란 뒤에 잡은 청어는 속이 비고 살이 퍽퍽합니다. 20cm 이하 청어는 포획이 금지되어 있으니 너무 작은 것은 사지 마세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"제철에는 기름기가 많아 고소합니다. 봄에는 회로도 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"아가미가 선홍색이고 살에 탄력이 있는 것을 고르세요."},{"text":"내장이 흘러나오지 않고 배 쪽 살이 은백색으로 선명한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 뒤 냉장 보관하고 이틀을 넘기지 않는 것이 가장 좋습니다."},{"label":"손질법","text":"비늘은 긁으면 쉽게 떨어집니다. 배 쪽 가운데에 날카로운 모비늘이 한 줄 있으니 다듬을 때 조심하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"청어구이·조림. 기름진 살을 굽거나 조립니다."},{"text":"청어식해. 꾸덕하게 말린 청어를 채 썰어 무, 찰밥, 양념과 버무려 2~3일 삭힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"겨울에 잡은 청어를 배를 따지 않고 그늘에서 얼렸다 말리면 과메기가 됩니다. 어린 청어는 정어리, 멸치와 비슷해 ‘솔치’, ‘청어멸치’ 같은 이름으로 섞여 팔리기도 합니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 청어","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32949&select_list_no=48","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 5월 수산물 ‘청어’, ‘조피볼락’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34965&select_list_no=30","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"‘솔치, 청어멸치’라고 불리는 어린 청어 팔지도 사지도 마세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=46350&menuSeq=971","checkedAt":"2026-11-12"}]},
  "horse-mackerel": {"summary":"전갱이는 6~9월이 제철이에요. 몸이 팽팽하고 아가미가 밝은 선홍색이며 20cm 안팎인 것을 고르세요. 꼬리 쪽 모비늘 떼는 손질법과 냉동 보관법을 정리했어요.","origin":"제주, 남해·동해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"전갱이는 방어, 부시리와 같은 전갱이과의 회유성 어종으로, 고등어와 닮았지만 줄무늬가 없고 옆줄을 따라 단단한 비늘이 붙어 있습니다. 봄부터 가을까지 잡혀 연중 볼 수 있지만, 4~7월 산란을 마친 뒤부터 맛이 듭니다. 선도가 떨어지면 맛이 빠르게 나빠져 말리거나 통조림으로도 많이 가공합니다. 회로는 살아 있는 것만 먹습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"비린내가 거의 없고 단맛과 감칠맛이 있습니다. 살은 부드럽고 잔가시가 많지만 억세지 않으며, 기름기가 있어 구이에 알맞습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸 전체가 팽팽하고 탄력이 있으며 표면에 광택이 있는 것을 고르세요."},{"text":"아가미가 밝은 선홍색인지 보세요."},{"text":"크기는 20cm 안팎인 것이 큰 것보다 맛이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"쉽게 상하니 손질 후 되도록 빨리 드세요. 바로 먹지 못하면 포를 떠서 소금을 뿌리고 밀봉해 냉동합니다."},{"label":"손질법","text":"꼬리 쪽 옆줄을 따라 난 가시 같은 비늘(모비늘)을 칼로 껍질째 도려낸 뒤, 아가미 뚜껑을 벌려 아가미를 떼고 내장을 꺼냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"전갱이구이. 기름기가 있어 소금을 쳐서 굽기 좋습니다."},{"text":"전갱이 초밥. 비린내가 적어 초밥 재료로 많이 씁니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"지역에 따라 메가리(부산), 전광어(경남), 가라지(완도), 각재기(제주)라고 부릅니다. 고등어와 함께 진열되면 줄무늬가 없고 옆줄에 단단한 비늘이 있는 쪽이 전갱이입니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 전갱이","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32610&select_list_no=53","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 6월 수산물 ‘키조개’, ‘전갱이’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=39192&select_list_no=5","checkedAt":"2026-11-12"}]},
  "hyang-carp": {"summary":"향어는 9월이 제철이에요. 몸통에 탄력이 있고 눈이 투명하며 아가미가 선홍색인 것을 고르세요. 흙냄새가 적은 향어로 만드는 회와 매운탕, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"향어는 잉어과 민물고기로, 1973년 이스라엘을 통해 들여와 양식에 성공한 뒤 주요 내수면 양식 어종이 됐습니다. 육질이 탄력 있어 횟감으로 인기가 높습니다. 처음에는 독일잉어나 이스라엘잉어로도 불렸으니 이름이 달라도 같은 생선인지 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"민물고기 특유의 흙냄새가 비교적 적고 잔가시가 거의 없으며, 육질이 탄력 있고 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통을 눌렀을 때 탄력이 있는 것을 고르세요."},{"text":"눈알이 투명하고 튀어나와 있는지 보세요."},{"text":"아가미가 선홍색이고 비늘이 잘 붙어 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"아이스박스나 아이스팩으로 차갑게 운반하고, 머리와 내장을 떼어 냉장하거나 냉동하세요. 냉동은 6~12개월 안에 쓰는 것이 좋습니다."},{"label":"손질법","text":"찜으로 쓸 때는 통째로 손질해 칼집을 내고 소금에 살짝 절입니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"향어회. 얇게 저며 초장을 곁들입니다."},{"text":"향어 매운탕. 손질한 향어를 토막 내 얼큰하게 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"2025년 생산량은 약 1,700톤으로 내수면 어류 가운데 다섯 번째로 많습니다. 국립수산과학원은 출하까지 기르는 기간을 23개월에서 17개월로 줄인 육종 향어를 개발했습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"전어, 향어","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=39756","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"고단백 저지방 생선 ‘향어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=22213&select_list_no=88","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"수산물 구매, 운반, 보관 등 요령","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?bbs_no=bbs160617&menu_grp=MENU_NEW01&menu_no=4846&ntctxt_no=1096183","checkedAt":"2026-11-12"}]},
  "ixeris": {"summary":"씀바귀는 3~4월이 제철이에요. 뿌리에 잔털이 적고 너무 굵지 않으며 길게 뻗은 것을 고르세요. 쓴맛 우려내는 손질법과 초고추장무침을 정리했어요.","origin":"전국","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"씀바귀는 들판이나 논두렁에서 흔히 자라는 봄나물로, 뿌리와 어린잎을 함께 먹습니다. 땅속으로 길게 뻗은 희고 가는 뿌리를 주로 먹으며, 지역에 따라 쓴귀물, 싸랑부리, 쓴나물이라고도 부릅니다. 뿌리째 먹는 나물이니 고를 때 뿌리 상태부터 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쓴맛이 강합니다. 그래서 데친 뒤 찬물에 오래 우려서 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리에 잔털이 많지 않고, 너무 굵지 않으며 길게 쭉 뻗은 것을 고르세요."},{"text":"잎은 짙은 녹색이고 앞뒷면이 깨끗한 것이 좋습니다."},{"text":"잎이 말랐거나 곰팡이, 변색, 냄새가 있는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"젖은 종이에 싸서 비닐봉지에 넣고 공기를 불어 넣어 냉장하세요."},{"label":"손질법","text":"뿌리의 흙을 털고 누런 겉잎을 다듬어 흐르는 물에 여러 번 씻으세요. 자른 곳에서 쓴 흰 즙이 나오니 상처를 덜 내고, 데친 뒤 찬물에 헹궈 쓴맛을 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"씀바귀나물. 데쳐서 하루쯤 쓴맛을 우려낸 뒤 초고추장 양념에 무칩니다."},{"text":"씀바귀 생채. 찬물에 주물러 씻고 맑은 물에 잠시 담갔다가 초고추장에 버무립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지를 전국으로 적고, 선씀바귀, 냇씀바귀, 갯씀바귀, 노랑선씀바귀 등 여러 종을 소개합니다. 쓴맛을 줄이려면 쌀뜨물에 담가 두는 방법도 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘씀바귀’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219844&menuNo=300063","checkedAt":"2026-11-12"}]},
  "ixeris-root-greens": {"summary":"고들빼기는 10~12월이 제철이에요. 잎보다 뿌리가 실하고 약간 보랏빛이 도는 것을 고르세요. 쓴맛 빼는 소금물 절이기와 김치 담그는 법을 정리했어요.","origin":"고창·순천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"고들빼기는 10~12월에 많이 나오는 엽채류로, 가을에 김치를 담가 먹습니다. 쓴맛이 특징이라 재배한 것과 야생인 것을 구분해 손질 시간을 달리해야 합니다. 야생은 재배한 것보다 조금 작고 뿌리가 통통하고 짧으며 잎이 가늡니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쌉쌀한 맛이 납니다. 야생 고들빼기는 쓴맛이 훨씬 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리가 매끈하고 연하며 너무 굵지 않은 것을 고르세요."},{"text":"잔뿌리가 적고 잎이 연하며 약간 보랏빛을 띠는 것이 좋습니다."},{"text":"잎이 짓무른 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻지 말고 키친타월로 감싸 비닐봉지에 넣어 냉장하세요."},{"label":"손질법","text":"잎과 뿌리 사이의 묵은 때를 긁어내고 잔털을 정리해 씻으세요. 재배한 것은 소금물에 하루, 야생은 물을 두세 번 갈며 5일가량 담가 쓴맛을 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"고들빼기김치. 쓴맛을 뺀 고들빼기에 배와 들깨풀을 넣어 담급니다."},{"text":"고들빼기무침. 연한 고들빼기를 된장이나 고추장 양념에 무쳐 삼겹살에 곁들입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 이른 봄과 늦가을에 맛이 좋다고 소개합니다. 김치로 담그면 비교적 오래 두어도 맛이 잘 변하지 않아 한 번에 넉넉히 담그는 경우가 많습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘고들빼기’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219910&menuNo=300063","checkedAt":"2026-11-12"}]},
  "jaecheop-clam": {"summary":"재첩은 4~6월과 9~11월이 제철이에요. 껍데기가 깨지거나 벌어진 채 움직이지 않는 것은 피하세요. 국물을 체에 거르는 손질법과 재첩국, 재첩전을 정리했어요.","origin":"섬진강 일대","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"재첩은 섬진강 일대에서 주로 잡히는 작은 민물조개로 국을 끓이면 감칠맛이 납니다. 봄과 가을에 맛보기 좋으며, 껍데기째 산 재첩은 씻어 끓인 뒤 국물을 체에 거르면 모래가 남는 것을 줄일 수 있습니다. 국을 끓이고 건져낸 살은 전이나 수제비에도 쓰기 좋습니다. 조리할 시간이 부족하면 손질한 살과 국물이 들어 있는 제품을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살은 작고 부드러우며 국물은 담백하고 감칠맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍데기가 깨지거나 벌어진 상태로 움직임이 없는 것은 피하세요."},{"text":"비린내가 심하거나 냉장 포장이 새지 않는지 보세요."},{"text":"손질품은 원산지와 소비기한을 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생재첩은 냉장해 빠르게 조리하세요. 오래 보관할 때는 끓인 국물을 식혀 소분 냉동합니다."},{"label":"손질법","text":"껍데기를 비벼 씻고 충분히 익힌 다음 국물을 체에 거릅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"재첩국. 끓여 거른 국물에 부추를 더합니다."},{"text":"재첩전. 익혀 발라낸 살을 반죽에 섞어 부칩니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"생재첩과 손질 살·국물 제품의 보관법이 다릅니다. 섬진강 등 산지 표시는 판매처에서 확인하세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"6월의 수산물 ‘재첩’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33676&select_list_no=8","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"재첩 보관과 조리","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=15355","checkedAt":"2026-11-12"}]},
  "jeju-hanchi": {"summary":"제주한치는 6~8월이 제철이에요. 몸통에 탄력이 있고 광택이 도는 것을 고르세요. 동해한치와 다른 점, 껍질 벗겨 냉동하는 법과 한치물회를 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"한치는 오징어와 닮았지만 몸통이 길쭉하고 다리가 한 치(약 3cm)만큼 짧은 꼴뚜기 무리입니다. 제주한치의 표준명은 창꼴뚜기이고, 여름에 산란하며 이때 가장 많이 잡히고 맛도 좋습니다. 동해한치(화살꼴뚜기)는 겨울에서 봄이 제철이라 철이 다릅니다. 한치의 주 생산지는 제주도입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"오징어보다 살이 연하고 부드러우며 감칠맛이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통에 탄력이 있는 것을 고르세요."},{"text":"표면에 광택이 도는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생것을 얼려도 맛이 유지됩니다. 손질해 껍질을 벗기고 씻은 뒤 쓰기 좋게 썰어 밀봉해 냉동하세요."},{"label":"손질법","text":"내장이 터지지 않게 조심해서 떼어 낸 뒤 껍질을 벗깁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"한치물회. 가늘게 채 썬 한치와 풋고추를 양념에 무치고 차가운 물이나 육수를 부어 얼음을 띄웁니다."},{"text":"한치숙회와 구이. 살이 연해 데치거나 구워도 부드럽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"몸통은 큰 것이 30~40cm에 이르지만 다리는 3cm 안팎입니다. 주로 밤에 집어등을 켜고 줄낚시로 잡습니다. 값은 오징어의 두 배 이상입니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 오징어보다 한 수 위 ‘한치’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=18408&select_list_no=111","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 8월 수산물 ‘민어’, ‘한치’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33933&select_list_no=39","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"8월 어식백세 수산물 ‘장어류, 오징어, 한치’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=13035&menuSeq=971","checkedAt":"2026-11-12"}]},
  "jerusalem-artichoke": {"summary":"돼지감자는 12월이 제철이에요. 옅은 갈색에 주름 없이 매끄럽고 흠집이 적은 것을 고르세요. 흙째 보관하는 법과 껍질째 먹는 조리법을 정리했어요.","origin":"양평·진안·남원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"돼지감자는 뚱딴지라는 별명으로도 불리는 채소로, 12월에 많이 나옵니다. 껍질째 먹는 경우가 많아 표면 상태를 꼼꼼히 보고 고르세요. 흙이 묻은 채로 사면 보관하기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"아삭하고 시원하게 씹히며, 졸이면 단맛이 강해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"옅은 갈색을 띠는 것을 고르세요."},{"text":"주름 없이 매끄럽고 흠집이나 상처가 적은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"흙이 묻은 상태로 신문지를 덮어 상자에 담고, 햇빛을 피해 서늘한 곳에 두세요."},{"label":"손질법","text":"흐르는 물에 씻어 껍질째 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"돼지감자조림. 껍질째 썰어 졸이면 단맛이 강해집니다."},{"text":"돼지감자구이. 물을 쓰지 않고 껍질째 굽습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지로 경기 양평과 전북 진안, 남원을 듭니다. 껍질째 먹고 물을 쓰지 않는 조리법을 권합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘돼지감자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227360&menuNo=300063","checkedAt":"2026-11-12"}]},
  "jicama": {"summary":"히카마는 10월이 제철이에요. 단단하고 겉이 쭈그러지거나 멍들지 않은 것을 고르세요. 냉장하면 갈변하는 히카마의 실온 보관법과 손질법을 정리했어요.","origin":"합천·칠곡·진안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"히카마는 멕시코 감자, 얌빈이라고도 부르는 뿌리채소로, 속은 배나 감자와 비슷한 색입니다. 무 대신 쓸 수 있는 식재료로 소개됩니다. 냉장하면 갈변하므로 무나 감자처럼 냉장고에 넣지 말고 실온에 두는 채소로 알고 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"날것은 아삭하고 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"단단하고 겉이 건조한 것을 고르세요."},{"text":"표면이 쭈그러지지 않고 멍든 곳이 없는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장하면 갈변하니 서늘하고 건조한 실온에 두세요. 2~3개월까지 둘 수 있고, 10일쯤 지나면 맛이 더 좋아집니다."},{"label":"손질법","text":"양쪽 꼭지를 잘라 내고 껍질을 벗겨 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"히카마 생채. 무생채처럼 채 썰어 양념에 버무립니다."},{"text":"히카마 맑은국. 무 대신 썰어 넣고 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농사로의 2015년 재배 답변은 5월 초에 씨를 뿌려 30일 기른 모를 심고 150일 뒤에 수확하는 일정을 안내합니다. 같은 답변은 당시 국내 생산물이 출하된 적이 없다고 적었으니, 살 때 원산지 표시를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘히카마’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227349&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"멕시코 감자(히카마, 얌빈)의 재배방법","url":"https://www.nongsaro.go.kr/portal/ps/psz/psza/contentSub.ps?cntntsNo=200016&menuId=PS00078&totalSearchYn=Y","checkedAt":"2026-11-12"}]},
  "jujube": {"summary":"대추는 9~10월이 제철이에요. 생대추는 붉은빛이 밝고 벌레 먹은 구멍이 없는 것을 고르세요. 생대추·말린 대추 보관법과 대추차, 대추밥을 정리했어요.","origin":"보은·경산·제천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"가을에 거둔 대추는 생과로 먹거나 말려 차와 떡, 밥에 넣습니다. 한 봉지 안에서도 생대추는 크기가 고르고 껍질에 벌레 먹은 자국이 없는 것을 고르면 손질하기 편합니다. 말린 대추는 겉에 주름이 생기지만 알에 살이 남아 있는 것을 고르면 달여 차를 내거나 씨를 발라 떡에 얹을 때 쓰기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생대추는 아삭하고 씹을수록 단맛이 납니다. 말린 대추는 쫀득하고 단맛이 진합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생과는 밝은 붉은빛과 고른 크기를 보세요."},{"text":"반점이나 벌레 먹은 구멍이 없는지 확인하세요."},{"text":"말린 것은 알이 통통하고 상처가 없는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생대추는 밀폐해 냉장하세요. 말린 대추는 습기를 피하고, 오래 두려면 밀폐해 냉동하세요."},{"label":"손질법","text":"말린 대추는 주름에 낀 이물질을 털고 씻으세요. 썰어 쓸 때는 세로로 가른 뒤 씨를 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"대추차. 말린 대추에 칼집을 내어 끓입니다."},{"text":"대추밥. 씨를 뺀 대추를 밤과 함께 넣고 밥을 짓습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리가 소개하는 국내 품종에는 보은·경대추·연산 등이 있습니다. 생과와 건과의 식감 차이가 뚜렷하므로 용도를 먼저 정하고, 원산지는 표시를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘대추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219880&pageIndex=1&searchCnd=&searchWrd=&selectMonth=99","checkedAt":"2026-11-12"}]},
  "kara-mandarin": {"summary":"카라향은 4~6월이 제철이에요. 껍질이 과육에서 들뜨지 않고 주황빛이 바래지 않은 것을 고르세요. 품종 이름과 노지·하우스 출하 시기, 보관 기간을 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"카라향은 제주에서 봄에 나오는 만감류로, 품종 이름은 남진해입니다. 노지 재배는 4월 중순~5월 상순에, 하우스 재배는 3월 중순~4월 상순에 수확합니다. 껍질이 잘 벗겨지고 속껍질이 비교적 부드러워 속껍질째 먹을 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛이 진하고 향이 좋습니다. 수확할 때 당도는 13~14브릭스 정도입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"3월 이후 기온이 오르면 껍질이 과육에서 뜨는 과실(부피과)이 늘어납니다. 껍질과 과육 사이가 들뜬 것은 피하세요."},{"text":"5월 하순이 되면 껍질 색이 바래기 시작합니다. 껍질이 진한 주황빛(농등색)인 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"제주농업기술원 자료는 상온에서 1개월 정도, 5~8℃에 습도 85~90%면 그보다 오래 저장할 수 있다고 봅니다. 사 온 뒤에는 서늘한 곳에 두고 껍질이 들뜨기 전에 드세요."},{"label":"손질법","text":"껍질을 손으로 벗기세요. 한 개에 씨가 4~5개 들어 있을 수 있습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"생과. 껍질을 벗겨 속껍질째 먹습니다."},{"text":"과일 도시락. 껍질이 잘 벗겨져 쪽으로 나눠 담기 좋습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"남진해는 카라만다린에 길포폰칸을 교배해 육성한 품종이며, 제주에서는 카라향이라는 이름으로 출하됩니다. 제주농업기술원 영농정보지는 카라향을 제주 감귤 출하의 마지막인 5월을 맡는 과일로 소개합니다."}]}],"sources":[{"org":"제주특별자치도 서귀포농업기술센터","title":"영농상담 ‘감귤 품종에 대한 전반적인 정보가 필요합니다’","url":"https://agri.jeju.go.kr/seogwipo/communications/hardship.htm?act=view&seq=57272","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원","title":"감귤분야 품종 자료 ‘남진해’","url":"https://agri.jeju.go.kr/files/board/%EA%B0%90%EA%B7%A4%EB%B6%84%EC%95%BC%28%EB%82%A8%EC%A7%84%ED%95%B4%29.pdf","checkedAt":"2026-11-12"},{"org":"제주특별자치도농업기술원","title":"인터넷영농정보지 제주농업 18호","url":"https://agri.jeju.go.kr/jeju/local/resource.htm?page=26&act=download&seq=34067&no=1","checkedAt":"2026-11-12"}]},
  "kelp": {"summary":"다시마는 5~6월이 제철이에요. 마른 다시마는 검은빛에 녹갈색이 돌고 두껍고 빳빳한 것을 고르세요. 흰 가루를 씻지 않는 이유와 국물 내는 법을 정리했어요.","origin":"전남 완도·고흥, 부산 기장","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"다시마는 남해안에서 많이 양식하는 갈조류로, 주로 마른 다시마로 가공해 국물을 낼 때 씁니다. 양식 다시마는 11월부터 키워 장마 전인 5~6월경에 대부분 거둡니다. 생다시마는 데쳐서 쌈이나 무침으로 먹으니 쓰임에 맞춰 생물과 건조품을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"감칠맛이 깊어 국물 맛을 내는 데 씁니다. 잘 마른 다시마 표면의 흰 가루는 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"빛깔이 검고 녹갈색이 돌며, 한 장씩 반듯하게 겹쳐 말린 빳빳하고 두꺼운 것을 고르세요."},{"text":"붉게 변했거나 잔주름이 간 것, 누렇고 윤기가 없는 것은 피하세요."},{"text":"줄기가 두툼하고 바다 냄새가 나는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생다시마는 차갑게 운반해 냉장하세요. 마른 다시마 표면의 흰 가루는 맛을 내는 성분이니 털거나 씻어 내지 말고 그대로 두세요."},{"label":"손질법","text":"물기를 꼭 짠 수건으로 모래와 티를 닦아 냅니다. 국물은 찬물에 담가 여름에는 1시간, 겨울에는 3시간 넘게 우리고, 끓일 때는 물이 끓기 직전에 건져 내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"다시마부각. 다시마에 찹쌀밥을 펴 발라 바싹 말렸다가 기름에 튀깁니다."},{"text":"생다시마쌈. 끓는 물에 살짝 데친 생다시마에 초장을 곁들입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"국내 양식 다시마의 종자는 9~10월에 생산하고, 주요 양식 지역은 전남 고흥과 완도, 부산 기장입니다. 거둔 다시마는 대부분 식용과 전복 먹이로 쓰입니다."}]}],"sources":[{"org":"국립수산과학원","title":"다시마 양식방법 답변","url":"https://www.nifs.go.kr/board/actionBoard0008View.do?BBS_CL_CD=C&BBS_ID=20201228031217212TCY&MENU_ID=M0000054","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다시마, 조피볼락","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=39028","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"알아두면 좋은 다시마 tip","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=9097","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"수산물 구매, 운반, 보관 등 요령","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?bbs_no=bbs160617&menu_grp=MENU_NEW01&menu_no=4846&ntctxt_no=1096183","checkedAt":"2026-11-12"}]},
  "kidney-bean": {"summary":"강낭콩은 6~7월이 제철이에요. 알이 통통하고 크기가 고르며 금 간 알이 없는 것을 고르세요. 마른 콩을 불려 충분히 익히는 법과 강낭콩밥을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"강낭콩은 여름에 거두어 밥이나 조림, 앙금에 쓰는 콩입니다. 햇콩을 꼬투리째 사면 껍질을 벗겨 알을 꺼내고, 건조 제품은 물에 불려 속까지 익히세요. 마른 콩 한 봉지를 살 때는 알이 고르고 깨진 콩이나 이물질이 적은 것을 고르면 삶을 때 익는 정도가 고릅니다. 흰 강낭콩은 삶아 으깨면 앙금이나 수프에 쓰기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"푹 익히면 안이 포슬포슬하고 은은하게 달아요."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 통통하고 크기가 고른 것을 고르세요."},{"text":"금이 가거나 벌레 먹은 흔적을 보세요."},{"text":"건조 제품은 눅눅하거나 곰팡이 흔적이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"햇알은 밀폐해 냉장하고 오래 둘 분량은 소분 냉동하세요. 마른 콩은 습기 없는 곳에 밀폐합니다."},{"label":"손질법","text":"이물질을 골라 씻고, 마른 콩은 불린 물을 버린 뒤 새 물에 충분히 끓여 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"강낭콩밥. 불려 충분히 익힌 콩을 곁들입니다."},{"text":"흰 강낭콩 앙금. 푹 삶은 흰 콩을 으깨 졸입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농사로는 풋강낭콩 수확까지 파종 후 약 60일이 걸린다고 설명합니다. 풋콩과 마른 콩의 판매 시기는 다릅니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘강낭콩’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219948&deleteCd=0&pageIndex=1&selectMonth=7","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"강낭콩 농작업 일정","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbl/workScheduleDtl.ps?cntntsNo=30700&menuId=PS00087&sKidofcomdtySeCode=FC%29","checkedAt":"2026-11-12"}]},
  "king-oyster-mushroom": {"summary":"새송이버섯은 시설 재배로 1~12월 내내 나와요. 줄기가 굵고 마르지 않은 것을 고르세요. 냉장·냉동·말려서 보관하는 법과 구이를 정리했어요.","origin":"경남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"새송이버섯은 자연산 송이 대신 쓰려고 재배하는 큰느타리버섯으로, 송이만큼 맛과 향이 진하지는 않지만 질감이 비슷합니다. 정보누리 생산시기는 1~12월이고 주산지는 경남입니다. 이름에 송이가 들어가도 가을에 채취하는 자연산 송이와는 다른 버섯입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"육질이 단단하고 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"마르지 않고 줄기가 길고 굵으며 아래로 갈수록 통통한 것을 고르세요."},{"text":"육질이 단단하고 탄력 있으며 갓이 피지 않은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"헝겊이나 신문지에 싸서 냉장하세요. 오래 둘 것은 흙과 이물질을 닦아 비닐팩에 밀봉해 냉동하거나, 얇게 썰어 말려 두세요."},{"label":"손질법","text":"흐르는 물에 씻어 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"새송이 들기름구이. 두툼하게 썰어 들기름에 굽습니다."},{"text":"새송이전. 얇게 썰어 반죽을 입혀 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 큰느타리1호와 큰느타리2호를 듭니다. 새송이는 큰느타리버섯의 유통 이름입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘새송이버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219925&menuNo=300063","checkedAt":"2026-11-12"}]},
  "kiwi": {"summary":"키위는 10~12월이 제철이에요. 바로 먹을 것은 말랑한 것을, 두고 먹을 것은 단단한 것을 고르세요. 품종별 실온 후숙 기간과 빨리 익히는 법을 정리했어요.","origin":"제주 서귀포·제주시, 전남 순천·보성","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"키위는 나무에서 다 익기 전에 따서 일정 기간 익혀 먹는 후숙 과일입니다. 국산은 10~12월에 제주와 전남에서 나오며 참다래라고도 부릅니다. 속살 색에 따라 그린키위, 골드키위, 레드키위로 나뉘고 종류마다 익는 속도가 다르니 먹을 날짜에 맞춰 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단맛과 신맛이 함께 나고 수분이 많습니다. 익을수록 부드러워집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"바로 먹을 것은 말랑하게 익은 것을, 두고 먹을 것은 단단한 것을 고르세요."},{"text":"살짝 눌렀을 때 탄력이 있고 껍질에 윤기 있는 갈색 털이 빼곡한 것이 좋습니다."},{"text":"터진 곳이 없고 깨끗한 타원형인 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"단단한 키위는 실온에서 익히세요. 농촌진흥청은 그린키위 약 1주일, 레드키위 5일, 골드키위 3일이면 먹기 좋게 익는다고 설명합니다. 사과나 바나나와 함께 비닐팩에 넣으면 더 빨리 익고, 익은 것은 냉장하세요."},{"label":"손질법","text":"반으로 갈라 숟가락으로 떠먹거나 껍질을 벗겨 썰어 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"키위 샐러드. 여러 과일과 함께 썰어 냅니다."},{"text":"고기 양념. 키위를 갈아 양념장에 섞으면 고기가 부드러워집니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 그린키위, 골드키위, 레드키위, 한라키위, 메가그린키위를 듭니다. 같은 키위라도 품종마다 후숙 기간이 다르니 포장의 품종 이름을 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘키위’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219810&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"보도자료 ‘더 오래 신선하게’ 똑똑한 과일, 채소 보관법","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&prgId=day_farmprmninfoEntry&mode=updateCnt&dataNo=100000790713","checkedAt":"2026-11-12"}]},
  "kohlrabi": {"summary":"콜라비는 11~12월이 제철이에요. 테니스공만 하고 짙푸른 잎이 붙어 있는 것을 고르세요. 단단한 껍질 벗기는 법과 생채·깍두기 활용을 정리했어요.","origin":"강진·해남·제주·익산","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"콜라비는 양배추와 순무를 교배한 채소로, 흙 위에서 자라는 둥근 줄기를 먹습니다. 겉은 녹색과 보라색이 있지만 속은 똑같이 하얗습니다. 수확기를 지나면 나무처럼 딱딱해지니 너무 큰 것은 피하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"무와 비슷하지만 맵고 아린 맛이 적고 단맛이 강하며, 녹색이 보라색보다 약간 더 답니다. 익히면 감자와 비슷한 식감이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"섬유가 연하고 먹기 편한 테니스공 크기를 고르세요."},{"text":"잎이 붙어 있고 짙푸르며 노랗게 변한 잎이 없는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"하나씩 랩으로 싸서 냉장하세요."},{"label":"손질법","text":"잎과 뿌리 쪽을 칼로 먼저 잘라 내고 칼이나 필러로 껍질을 벗기세요. 보라색 콜라비는 껍질이 특히 단단하니 조심하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"콜라비생채. 양념에 무쳐도 쉽게 무르지 않아 아삭함이 남습니다."},{"text":"콜라비깍두기. 깍둑 썰어 깍두기나 물김치로 담급니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 강진, 해남, 제주, 익산을, 품종으로 루비캡, 아시아청콜, 퍼플퀸 등을 듭니다. 녹색과 보라색이 함께 팔리니, 단맛과 손질 난이도를 생각해 색을 고르세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘콜라비’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219812&menuNo=300063","checkedAt":"2026-11-12"}]},
  "korean-rockfish": {"summary":"우럭은 10~12월이 제철이에요. 통생선은 눈이 맑고 토막은 단면이 마르지 않은 것을 고르세요. 판매처에 손질을 맡기는 요령과 우럭 매운탕, 구이를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"우럭은 조피볼락으로 유통되는 흰살생선으로, 손질한 토막을 국이나 구이에 씁니다. 해양수산부는 11월의 수산물로 우럭을 선정했고, 태안 지역의 겨울 별미로 우럭젓국도 소개했습니다. 장에서는 생물과 말린 우럭을 구분해 요리에 맞는 것을 고르세요. 매운탕에는 뼈가 붙은 토막을, 팬에 굽기에는 두께가 비슷한 손질 살을 쓰면 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살은 담백하고 탄력이 있으며 구우면 겉은 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"통생선은 눈이 맑은지 보세요."},{"text":"손질한 토막의 단면이 마르지 않았는지 살피세요."},{"text":"냉장 포장과 원산지 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 빨리 조리하고, 남은 토막은 소분해 냉동하세요."},{"label":"손질법","text":"통생선은 비늘·아가미·내장 제거를 요청하고 남은 가시를 확인하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"우럭 매운탕. 토막과 무를 넣어 끓입니다."},{"text":"우럭 소금구이. 물기를 닦고 두께가 두꺼운 부분까지 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"조피볼락은 양식으로도 유통됩니다. 산지와 양식 여부는 판매 표시를 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"11월 이달의 수산물 ‘고등어·우럭’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=36077&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"12월 어촌여행지 ‘태안’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=63988&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"양식 수산물 물가 점검","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=68110&menuSeq=971","checkedAt":"2026-11-12"}]},
  "korean-zucchini": {"summary":"애호박은 6~10월이 제철이에요. 연두색에 윤기가 돌고 꼭지가 마르지 않았으며 묵직한 것을 고르세요. 자르고 남은 호박 보관법과 말리는 법을 정리했어요.","origin":"전국","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"우리나라 호박은 애호박과 늙은 호박으로 나뉘고, 돼지호박이라 부르는 주키니호박도 있습니다. 애호박은 된장찌개, 볶음, 전, 무침, 국수 고명까지 두루 쓰입니다. 주키니와 생김새가 비슷하니 연두색 껍질인지 보고 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"씹는 맛이 부드럽고 단맛이 돕니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"연두색에 윤기가 흐르고 꼭지가 마르지 않은 것을 고르세요."},{"text":"위아래 굵기가 고르고 크기에 비해 묵직하며, 꼭지 주변이 들어가 있는 것이 좋습니다."},{"text":"표면에 긁힌 자국이나 상한 곳이 있거나 꼭지가 부서진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 없애고 종이에 싸거나 랩을 씌워 냉장하세요. 자르고 남은 것은 단면에서 진액이 나오며 무르니 빨리 쓰세요."},{"label":"손질법","text":"깨끗이 씻어 꼭지를 자르고 용도에 맞게 써세요. 오래 두려면 3~5mm 두께로 동글납작하게 썰어 볕이 잘 들고 바람이 부는 곳에서 말리세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"호박전. 애호박을 썰어 전으로 부칩니다."},{"text":"애호박새우젓볶음. 애호박을 새우젓과 함께 볶아 밥반찬으로 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 전국에서 재배하며 6~10월에 나온다고 적습니다. 잘랐을 때 씨가 크거나 들떠 있으면 수확한 지 오래된 것이니, 잘라 파는 것을 살 때 단면을 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘애호박’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219863&menuNo=300063","checkedAt":"2026-11-12"}]},
  "kudzu-root": {"summary":"칡은 9~10월이 제철이에요. 갈색 털이 있고 들었을 때 무거우며 너무 가늘지도 굵지도 않은 뿌리를 고르세요. 생 칡과 칡즙 보관법, 칡국수를 정리했어요.","origin":"경북·강원·충북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"칡은 콩과의 여러해살이 덩굴식물로, 햇볕이 잘 드는 산지에서 흔히 자랍니다. 먹는 부분은 뿌리이며, 늦가을 낙엽이 진 뒤부터 이듬해 새싹이 나기 전까지 캡니다. 생 칡, 말린 칡, 진공포장한 칡즙으로 나뉘어 팔리니 무엇을 살지 먼저 정하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"겨울부터 이른 봄까지 캔 굵은 암칡은 진하면서 달달한 끝맛이 납니다. 녹말이 많아 국수에 넣으면 쫀득합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"전체에 갈색 털이 있고 들었을 때 무거운 것을 고르세요."},{"text":"너무 가늘면 맛과 향이 없고, 너무 굵어도 좋지 않습니다."},{"text":"국산인지, 제철에 캔 것인지, 생 칡인지 말린 칡인지 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통째로 신문지에 싸서 직사광선을 피해 통풍이 잘되는 서늘한 곳에 두면 10일 정도 갑니다. 칡즙은 상온에서 이틀, 냉장에서 5일이면 상하니 냉동해 두고 드세요."},{"label":"손질법","text":"흙탕물이 나오지 않을 때까지 흐르는 물에 씻어 털을 없애고 햇볕에 잘 말리세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"칡국수. 생 칡을 절구에 찧어 나온 앙금을 밀가루 반죽에 넣어 칼국수를 만듭니다."},{"text":"칡떡. 녹말이 많은 칡을 떡 반죽에 넣어 만듭니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경북, 강원, 충북을 들고, 암칡과 수칡을 구분합니다. 생산시기는 9~10월로 적혀 있지만, 같은 자료의 구입요령은 겨울부터 이른 봄까지 캔 칡을 좋은 것으로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘칡’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219849&menuNo=300063","checkedAt":"2026-11-12"}]},
  "kumquat": {"summary":"금귤은 3~5월이 제철이에요. 껍질째 먹으니 표면이 갈라지거나 눌려 무른 알이 없는지 보세요. 씨 빼는 손질법과 금귤 정과 만들기를 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"금감이라고도 하는 금귤은 제주에서 재배하는 작은 감귤류입니다. 제주농산물수급관리센터는 2~5월을 수확기로 안내하고, 바로정보는 3월의 제철 식재료로 소개합니다. 껍질까지 쓰는 과일이라 정과나 청을 담을 때는 흠이 있는지 꼼꼼히 보고, 샐러드에 넣을 때는 얇게 썰어 씨를 빼면 한입에 먹기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 짙은 껍질의 단맛과 과육의 신맛이 함께 납니다. 껍질이 톡 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질에 갈라진 곳이 없는지 보세요."},{"text":"눌려 물러진 알이 없는 것을 고르세요."},{"text":"정과용은 크기가 고른 것으로 고르면 익는 속도가 비슷합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기가 없는 상태로 냉장하고, 음료에 쓸 양은 씨를 뺀 뒤 소분해 냉동하세요."},{"label":"손질법","text":"껍질째 쓸 때는 흐르는 물에 씻고 반으로 갈라 씨를 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"금귤 정과. 씨를 뺀 금귤을 시럽에 조립니다."},{"text":"금귤 샐러드. 얇게 썬 금귤을 잎채소에 섞습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"제주의 2~5월 수확기와 3~4월 제철은 범위가 다릅니다. 구입할 때는 포장에 적힌 재배 산지를 확인하세요."}]}],"sources":[{"org":"제주농산물수급관리센터","title":"감귤(금귤)","url":"https://jasdc.or.kr/info/intro/tangerine.htm","checkedAt":"2026-11-12"},{"org":"한국농수산식품유통공사 바로정보","title":"동글동글~ 이름마저 귀여운 낑깡, 금귤편","url":"https://www.baroinfo.com/front/M000000734/board/view.do?articleId=AC00003590","checkedAt":"2026-11-12"}]},
  "laver": {"summary":"김은 12월~이듬해 3월이 제철이에요. 검은빛에 윤기가 나고 재래김은 두께가 얇은 것을 고르세요. 마른김 냉동 보관법과 채취 시기를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"김은 홍조류 해조류로, 대부분 얇게 말린 마른김이나 조미김으로 팔립니다. 채취는 10월 하순부터 이듬해 4월 초까지 이어지고, 12~3월에 딴 김이 빛깔이 검고 광택이 많으며 향과 맛이 진합니다. 4~5월에 딴 김은 수온이 올라 품질이 떨어집니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"재래김은 얇고 윤기가 나는 것이 고소합니다. 조미김은 만든 지 얼마 안 된 것이 맛과 향이 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"검은빛을 띠고 윤기가 나는 것을 고르세요."},{"text":"재래김은 두께가 얇은 것이 좋습니다."},{"text":"조미김은 제조일이 가까운 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"습기에 닿으면 질겨지고 맛과 향이 떨어지니, 마른김은 한지에 한 번 싸서 위생팩에 밀봉해 냉동하세요. 조미김은 유통기한이 12개월이어도 3개월 안에 드세요."},{"label":"손질법","text":"들기름을 발라 구울 때는 먹을 만큼만 재우고, 김에 나트륨이 많으니 소금은 뿌리지 않거나 줄이세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"김부각. 김에 찹쌀풀을 발라 말렸다가 튀기거나 굽습니다."},{"text":"김두부조림. 두부에 김을 붙이고 양념을 입혀 바싹하게 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"김 가공품 원료로 쓸 수 있는 종은 식품위생법상 참김, 방사무늬김, 잇바디돌김, 모무늬돌김, 둥근돌김 5종입니다. 국립수산과학원에 따르면 ‘곱창김’으로 불리는 잇바디돌김은 11월 초순부터, 방사무늬김은 12월부터 이듬해 5월까지, 모무늬돌김은 1~5월에 생산합니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"참돔, 김","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38461","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"영양이 풍부하고 맛이 좋은 ‘김, 과메기’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33147","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"바다를 품은 검붉은 해초, 김","url":"https://www.foodnuri.go.kr/portal/bbs/B0000277/view.do?nttId=214545&menuNo=300088&pageIndex=337","checkedAt":"2026-11-12"},{"org":"국립수산과학원","title":"김 양식 공정","url":"https://www.nifs.go.kr/board/actionBoard0018PopupPrevew.do?BBS_ID=20211228033803662RUO","checkedAt":"2026-11-12"}]},
  "lemon": {"summary":"레몬은 10월~이듬해 1월이 제철이에요. 껍질이 선명한 노란색으로 윤이 나고 꼭지가 초록색인 것을 고르세요. 껍질째 씻는 법과 실온·냉장 보관 기간을 정리했어요.","origin":"제주 서귀포·제주시","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"국산 레몬은 제주에서 나오며 정보누리 생산시기는 10월~이듬해 1월입니다. 과즙, 껍질, 과육을 모두 요리에 쓰기 때문에 껍질까지 쓸 때는 소금으로 문질러 씻는 손질이 필요합니다. 실온에서도 1~2주 두고 쓸 수 있어 한 번에 여러 개를 사도 됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"신맛과 향이 강해 고기와 생선의 비린내를 잡는 데 씁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 선명한 노란색이고 매끄럽게 윤이 나는 것을 고르세요."},{"text":"꼭지가 초록색이고 들었을 때 묵직하고 단단한 것이 좋습니다."},{"text":"멍이나 갈색 반점이 있거나 무른 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"실온에서 1~2주, 지퍼백에 담아 냉장하면 6주쯤 둘 수 있습니다. 즙은 얼음틀에 얼려 두면 필요할 때 꺼내 쓰기 좋습니다."},{"label":"손질법","text":"소금물에 3~4분 담갔다가 흐르는 물에 문질러 씻고, 껍질을 소금으로 문지른 뒤 끓는 물에 살짝 데치세요. 즙은 실온에 두었다가 손바닥으로 눌러 굴린 뒤 짜면 많이 나옵니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"레몬 곁들임. 반달이나 둥글게 썰어 생선회, 육류, 튀김에 뿌립니다."},{"text":"레몬 홍차. 얇게 썬 레몬을 홍차에 띄웁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 리스본, 유레카, 메이어를 듭니다. 국산은 10월부터 이듬해 1월까지 나옵니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘레몬’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219818&menuNo=300063","checkedAt":"2026-11-12"}]},
  "lettuce": {"summary":"상추는 5~8월이 제철이에요. 잎끝이 갈색으로 변하지 않고 잎맥에 힘이 있는 것을 고르세요. 한 장씩 씻는 손질법과 상추쌈, 상추겉절이를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"상추는 한 장씩 떼어 고기나 밥을 싸 먹거나 채 썰어 비빔밥에 넣는 잎채소입니다. 잎이 여린 것은 쉽게 접혀 쌈에 편하고, 잎맥에 힘이 있는 것은 아삭한 식감을 더합니다. 봉지에 든 상추는 바깥에서 보이는 잎뿐 아니라 아래쪽에 물러진 잎이 있는지도 확인하세요. 사 온 뒤 쌈으로 먹을 때까지 차갑게 두고, 씻은 뒤에는 물기를 털어 냅니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎은 부드럽고 잎맥이 아삭합니다. 쌉쌀한 정도는 품종과 잎에 따라 다릅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎끝에 갈색이나 누런 부분이 적은 것을 고르세요."},{"text":"잎맥이 힘 있고 잎이 축 늘어지지 않았는지 보세요."},{"text":"봉지 아래쪽의 물러진 잎을 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"젖은 잎은 물기를 빼고 냉장하세요. 쌈용은 얼리면 잎의 아삭함이 줄어듭니다."},{"label":"손질법","text":"잎을 한 장씩 떼어 밑동 쪽의 흙까지 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"상추쌈. 물기를 턴 잎에 밥과 쌈장을 얹습니다."},{"text":"상추겉절이. 먹기 직전에 양념에 가볍게 버무립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"잎 색과 모양이 다양한 상추가 있습니다. 쌈에는 잘 접히는 잎을, 샐러드에는 힘 있는 잎을 고르면 식감을 살릴 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘상추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219943&deleteCd=0&pageIndex=1&selectMonth=5","checkedAt":"2026-11-12"}]},
  "lions-mane": {"summary":"노루궁뎅이버섯은 8~10월이 제철이에요. 흰 돌기가 고르고 표면이 마르지 않은 것을 고르세요. 결대로 찢는 손질법과 생버섯·건조품 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"노루궁뎅이버섯은 둥근 덩어리에 실 같은 돌기가 촘촘히 달린 버섯입니다. 요리할 때는 밑동을 다듬고 결을 따라 찢으면 칼로 얇게 썰 때와 다른 식감이 납니다. 생버섯과 건조 제품, 분말이 판매되므로 찜이나 볶음에는 생버섯을, 국물에 넣을 때는 용도에 맞는 형태를 고르세요. 생버섯은 눌리지 않게 담아 구입 후 빨리 쓰는 편이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 살이 부드럽고 결을 따라 가볍게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"돌기가 고르게 나 있고 표면이 마르지 않은 것을 고르세요."},{"text":"눌려 짓무르거나 곰팡이가 있는 것은 피하세요."},{"text":"생물과 건조품의 표기를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생버섯은 종이로 감싸 냉장하고, 건조 제품은 밀폐해 습기를 피하세요."},{"label":"손질법","text":"밑동의 이물질을 털고 손으로 찢어 충분히 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"노루궁뎅이버섯찜. 덩어리를 나눠 익힌 뒤 양념을 곁들입니다."},{"text":"버섯볶음. 결대로 찢어 채소와 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 재배농장에서 생산하는 생버섯과 건조·분말 제품을 소개합니다. 건조 제품의 판매기는 생버섯 생산기와 다릅니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘노루궁뎅이버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219933&deleteCd=0&pageIndex=1&selectMonth=9","checkedAt":"2026-11-12"}]},
  "loach": {"summary":"미꾸라지는 8~11월이 제철이에요. 추어탕용은 손질 여부와 원산지를 먼저 확인하세요. 삶아 체에 걸러 잔뼈를 줄이는 법과 추어탕, 미꾸라지 튀김을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"미꾸라지는 논이나 하천 등에서 사는 민물고기로 추어탕에 많이 씁니다. 해양수산부는 가을에 살이 올라 맛이 좋다고 소개하며 여러 해의 8~10월에 이달의 수산물로 선정했습니다. 통으로 넣는 조리법과 삶아 갈거나 체에 내리는 조리법이 있어, 구입할 때 손질 형태를 먼저 정하면 편합니다. 집에서는 씻은 채소와 섞기 전에 생선을 충분히 익히세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 구수하며, 체에 내리면 국물이 부드럽고 걸쭉해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"손질 여부와 원산지를 확인하세요."},{"text":"냉장·냉동 포장이 손상되지 않았는지 보세요."},{"text":"생물은 살이 상하거나 이상한 냄새가 나는 것을 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질품은 포장 표시대로 보관하고 냉장 상태에서 해동하세요."},{"label":"손질법","text":"손질을 맡긴 뒤 충분히 삶아 국에 사용합니다. 잔뼈가 신경 쓰이면 체에 거르세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"추어탕. 익힌 미꾸라지를 걸러 시래기와 끓입니다."},{"text":"미꾸라지 튀김. 손질해 물기를 빼고 속까지 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"민물 양식으로도 유통됩니다. 어종과 원산지, 손질 상태를 포장이나 판매처에서 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"8월 이달의 수산물","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=42549&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"9월 이달의 수산물","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=53034&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"10월 이달의 수산물","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=68834&menuSeq=971","checkedAt":"2026-11-12"}]},
  "long-arm-octopus": {"summary":"낙지는 4~6월, 9~11월이 제철이에요. 산낙지는 빨판 흡착력이 강하고 활발하게 움직이는 것을 고르세요. 세발낙지·꽃낙지 구분과 보관법을 정리했어요.","origin":"무안·영암·목포 등 전남 해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"낙지는 갯벌과 연안 바위틈에 사는 연체동물로, 전라도 해안에서 많이 잡힙니다. “봄 주꾸미, 가을 낙지”라는 말처럼 9~11월 낙지가 맛이 좋고, 이때의 낙지를 꽃낙지라고도 부릅니다. 봄에 태어난 새끼가 5~6월에 자란 것은 발이 가늘어 세발낙지라 부르며 목포 일대 특산물로 팔립니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"뼈가 없고 살이 야들야들합니다. 날로도 먹고 탕, 볶음, 구이로도 익혀 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"산낙지는 빨판의 흡착력이 강하고 활발하게 움직이는 것을 고르세요."},{"text":"회로 먹을 낙지는 가는 다리의 세발낙지를 찾는 경우가 많습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"내장을 빼고 씻어 물기를 뺀 뒤 다리와 머리를 나눠 밀봉하세요. 냉장은 1~2일 안에 먹고, 더 둘 때는 냉동하세요."},{"label":"손질법","text":"산낙지는 소금물에 담가 훑어 내리면서 찬물에 깨끗이 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"낙지연포탕. 미나리, 대파와 함께 맑게 끓입니다."},{"text":"낙지탕탕이. 산낙지를 회로 먹는 방식입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"낙지는 초봄인 4~5월에 산란합니다. 해양수산부는 4월 이달의 수산물로 낙지를 소개했고, 수산물안전정보는 9~11월을 제철로 소개합니다. 무안 낙지골목과 영암 독천낙지거리가 산지 낙지 요리로 알려져 있습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"제철수산물- 가을 ‘낙지’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=16222","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"4월 이달의 수산물 ‘낙지와 홍어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33420","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"‘갯벌의 산삼’ 낙지","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=5392","checkedAt":"2026-11-13"}]},
  "longtail-blackfish": {"summary":"긴꼬리벵에돔은 10월에 회로 즐기기 좋은 생선이에요. 벵에돔과 이름이 비슷하니 판매 이름을 꼭 확인하세요. 제주 양식 소식과 고르는 법, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"긴꼬리벵에돔은 제주 바다에 사는 아열대 어종으로, 벵에돔과 비슷한 가까운 종입니다. 제주에서는 고급 횟감으로 찾는 사람이 많습니다. 벵에돔과는 다른 종이니 살 때 판매 이름을 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"제주에서는 고급 횟감으로 꼽힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈알이 밝고 투명하며 툭 튀어나온 것을 고르세요."},{"text":"아가미가 선홍색이고, 살을 손가락으로 눌렀을 때 바로 되돌아오는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 생선은 0℃에 가까운 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"통생선은 꼬리를 잡지 말고 양손으로 들어 옮기세요. 비늘과 내장을 뺀 뒤 살을 떠서 회로 먹습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"긴꼬리벵에돔회. 손질한 살을 떠서 회로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"긴꼬리벵에돔은 최적 서식 수온이 24℃ 전후로, 높은 수온에 잘 견딥니다. 제주특별자치도 해양수산연구원이 자연산 어미에서 종자 생산에 성공해 도내 양식장에서 양식 실증을 시작했습니다."}]}],"sources":[{"org":"제주특별자치도 해양수산연구원","title":"고수온 돌파구 찾는다…신어종 혼합양식 추진","url":"https://jeju.go.kr/jori/news/report.htm?act=view&seq=1524456","checkedAt":"2026-11-13"},{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 긴꼬리벵에돔","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=10405","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "longtooth-grouper": {"summary":"자바리는 11월에 회로 즐기기 좋은 생선이에요. 제주에서 다금바리라 부르는 생선의 표준 이름이 자바리예요. 이름 구분과 고르는 법, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"자바리는 자바리과의 바다 생선으로, 제주에서는 다금바리라고 부릅니다. 제주 연안에 머무는 고급 토착 어종이며, 식용어로 선호도가 높은 고가 어종입니다. 자원이 줄어 제주특별자치도 해양수산연구원이 종자를 생산해 방류하고 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸은 긴 타원형으로 체고가 높고 옆으로 납작하며, 입이 크고 아래턱이 앞으로 튀어나와 있습니다."},{"text":"눈알이 밝고 투명하며 튀어나와 있고, 아가미가 선홍색이나 분홍색인 것을 고르세요."},{"text":"손가락으로 살짝 눌렀을 때 살이 원래대로 돌아오고, 몸에 점액이 없는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"포장되지 않은 생선은 흐르는 찬물에 씻고 종이타월로 물기를 닦은 뒤 랩으로 싸서 조리 전까지 냉장합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"자바리회. 이 달력에서 11월 회로 소개하는 생선입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"표준 이름이 다금바리인 생선(다금바리과)은 따로 있어, 제주에서 부르는 다금바리(자바리)와 이름이 겹칩니다. 자바리 같은 능성어류는 자연에서 생후 10년쯤 지나야 암컷 일부가 수컷으로 성전환하고, 제주 주변 해역에서는 어획이 점차 줄고 있습니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산생물종 정보 자바리","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=10296","checkedAt":"2026-11-13"},{"org":"국립수산과학원","title":"수산생물종 정보 다금바리","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11052","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다금바리 등 제주 특산 능성어류 대량 종묘생산 착수","url":"https://www.fsis.go.kr/front/api/totalView.do?cnts_id=8825","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "lotus-root": {"summary":"연근은 9월~이듬해 3월이 제철이에요. 마디가 굵고 단단하며 구멍 안쪽이 검게 무르지 않은 것을 고르세요. 식초물로 갈변 줄이는 법과 연근조림을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"연근은 연의 땅속줄기로, 가로로 자르면 둥근 구멍이 여러 개 드러납니다. 얇게 썰어 데치면 아삭하고, 두껍게 썰어 조리면 양념이 배면서 씹는 맛이 남습니다. 통으로 살 때는 굵기가 고르고 묵직한 마디를 고르세요. 자른 연근을 구입할 때는 구멍 안쪽과 단면에 물러진 부분이 없는지 살피고, 집에 와서 바로 쓸 양만 손질합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛은 담백하고 살짝 달며, 짧게 익히면 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"굵고 단단한 마디를 고르세요."},{"text":"자른 면이 지나치게 마르거나 무르지 않았는지 보세요."},{"text":"구멍에 검게 물러진 부분이 있는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"흙이 묻은 통연근은 종이에 싸 서늘하게 두고, 자른 것은 싸서 냉장하세요. 조림용은 썰어 데친 뒤 얼릴 수 있습니다."},{"label":"손질법","text":"흙을 씻어 껍질을 벗기고 써세요. 바로 요리하지 않으면 식초물에 잠깐 담가 갈변을 줄입니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"연근조림. 두께를 일정하게 맞춰 간장 양념에 조립니다."},{"text":"연근전. 얇게 썰어 반죽을 묻혀 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"연근은 뿌리처럼 보이는 땅속줄기입니다. 얇은 조각은 데침에, 두꺼운 조각은 조림에 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘연근’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219819&deleteCd=0&pageIndex=1&selectMonth=2","checkedAt":"2026-11-12"}]},
  "luffa": {"summary":"수세미는 9~11월이 제철이에요. 너무 메마르지 않고 눌렀을 때 쑥 들어가지 않는 것을 고르세요. 오이와 구별하는 법과 썰어 말려 두는 법을 정리했어요.","origin":"전남·전북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"수세미는 오이를 닮은 열매채소로, 열대 아시아가 원산지입니다. 오이처럼 반찬으로 흔히 먹기보다는 즙을 내거나 청, 차로 만들어 먹습니다. 겉모습이 오이와 비슷하니 살 때 주름과 단단한 정도로 구분하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"큰 오이처럼 생긴 열매는 속살이 부드럽습니다. 덜 자란 초록색 어린 수세미는 단단한 껍질을 벗겨 익히면 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"너무 메마르지 않은 것을 고르되, 눌렀을 때 부드럽게 들어가는 것은 피하세요."},{"text":"오이보다 겉이 더 주름져 있고, 눌러 보면 오이보다 덜 단단한 것이 수세미입니다."},{"text":"익혀 먹으려면 덜 자란 초록색 어린 수세미를 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지로 돌돌 말아 0~5℃ 냉장고 채소칸에 두세요. 오래 두려면 어슷하게 썰어 건조기나 햇볕에 말리세요."},{"label":"손질법","text":"소금을 푼 물에 잘 문질러 씻은 뒤 흐르는 물에 여러 번 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"수세미청. 수세미와 설탕을 1대 1로 재워 숙성합니다."},{"text":"수세미차. 말린 수세미 10g에 물 1~2L를 붓고 약한 불에서 한 시간쯤 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전라남도와 전라북도를, 품종으로 후도헤치마, 학머리모양형, 달마형을 듭니다. 잘 말린 열매는 생활용품으로도 쓰이니, 먹을 것을 살 때는 어린 열매인지 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘수세미’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219935&menuNo=300063","checkedAt":"2026-11-12"}]},
  "lumpfish": {"summary":"도치는 1월이 제철이에요. 몸 밖으로 미끌미끌한 진이 나온 것은 신선도가 떨어진 것이니 피하세요. 숙회·알탕 손질법과 두루치기를 정리했어요.","origin":"강원 영동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"도치는 표준명이 뚝지인 바닷물고기로, 영동에서는 심퉁이라고도 부릅니다. 산란기인 12~2월에 연안으로 와서 강원도에서는 겨울에 흔히 잡히지만 남해와 서해에서는 잡히지 않습니다. 보통 수컷은 숙회로, 암컷은 알과 함께 탕으로 먹으니 요리에 맞춰 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살은 기름기 없이 담백하고 쫄깃하며, 알은 오도독 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸 밖으로 미끌미끌한 진이 나온 것은 신선도가 떨어진 것이니 피하세요."},{"text":"숙회용은 수컷, 탕용은 알이 든 암컷을 찾으세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 얼음 위에 올려 포장해 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"입을 잘라내고 배를 갈라 내장을 뺀 뒤 흐르는 물에 씻어 물기를 닦고 토막 내세요. 숙회는 뜨거운 물에 살짝 담갔다 꺼내 껍질의 진액을 완전히 걷어 내고 썰어서 다시 데칩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"도치 두루치기(도치알탕). 묵은 김치 위에 알과 살을 얹고 물을 조금 넣어 졸입니다."},{"text":"도치숙회. 데친 도치를 초장에 찍어 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"도치는 북태평양의 한대성 어종으로, 국내 주산지가 북부 동해안에 한정됩니다. 예전에는 그물에 걸려도 버려지던 생선이었지만 지금은 겨울 별미로 찾는 사람이 많습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"못생겨도 맛은 좋은 ‘뚝지’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=28389","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "mackerel": {"summary":"고등어는 9~11월이 제철이에요. 은빛이 선명하고 배가 터지거나 무르지 않은 것을 고르세요. 생고등어와 자반의 차이, 고등어구이와 묵은지찜을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"고등어는 가을에 구이와 조림으로 먹기 좋은 등푸른 생선입니다. 해양수산부는 여러 해의 9월, 10월, 11월에 고등어를 이달의 수산물로 선정했습니다. 장에서는 같은 고등어라도 생물, 냉동, 자반을 구분해 고르세요. 특히 소금에 절인 자반은 간을 더하기 전에 염장 여부를 확인하고, 무나 묵은지를 곁들일 생물은 구입 뒤 냉장 상태를 유지해 조리하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"기름진 감칠맛과 고소한 향이 나며, 속살이 잘 부서집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"은빛이 선명하고 배가 터지거나 무르지 않은 것을 고르세요."},{"text":"통생선은 눈과 아가미가 탁하지 않은지 살피세요."},{"text":"포장 제품은 생물·냉동·염장과 원산지 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 즉시 냉장하고 빠르게 조리하세요. 냉동품은 냉장 해동합니다."},{"label":"손질법","text":"내장과 가시를 다듬고 표면의 물기를 닦아 속까지 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"고등어구이. 자반은 소금을 추가하기 전에 간을 확인합니다."},{"text":"고등어 묵은지찜. 묵은지와 함께 속까지 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"생고등어와 자반은 간과 보관 조건이 다릅니다. 해수부 선정 월은 구입 추천의 근거이며 연중 출하 범위와는 구분됩니다."}]}],"sources":[{"org":"해양수산부","title":"9월 이달의 수산물 ‘고등어·새우’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=2210&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"10월의 해양수산 어벤져스","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=43329&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"11월의 수산물 ‘고등어·우럭’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=36077&menuSeq=971","checkedAt":"2026-11-12"}]},
  "maesaengi": {"summary":"매생이는 12월~이듬해 2월이 제철이에요. 광택이 있고 선명한 녹색을 띤 것을 고르세요. 풀어 씻는 법과 한 번 먹을 만큼 나눠 냉동하는 법을 정리했어요.","origin":"남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"매생이는 실처럼 가는 해조류로, 파래와 비슷해 보이지만 훨씬 가늘고 부드럽습니다. 남도 앞바다에서 12월 중순부터 2월 말까지 생산됩니다. 예전에는 한겨울에만 먹었지만 냉동 보관이 일반화되어 지금은 연중 살 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"가늘고 부드러우며 윤기와 탄력이 있고 특유의 감칠맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"광택이 있고 선명한 녹색을 띤 것을 고르세요."},{"text":"파래보다 훨씬 가늘고 윤기와 탄력이 있는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"먹을 만큼씩 덜어 용기에 담아 냉동하고, 쓸 때 실온에서 녹여 조리하세요."},{"label":"손질법","text":"넉넉한 물에 담가 살살 풀고 조금씩 집어 흔들어 가며 씻으세요. 서너 번 헹군 뒤 고운 체에 밭쳐 물기를 뺍니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"매생이굴국. 굴의 향이 우러나면 매생이를 넣고 살짝 끓입니다. 끓어도 김이 잘 나지 않고 열이 잘 식지 않으니 입천장을 데지 않게 조심하세요."},{"text":"매생이전. 매생이를 반죽에 섞어 부칩니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"매생이는 생육 적온이 8℃ 정도로 낮아 겨울에 자라고, 물이 탁해지면 생육이 떨어질 만큼 환경에 민감합니다. 양식 어가가 늘어 생산량은 2000년 770톤에서 해마다 3,000톤 이상으로 늘었고, 냉동과 동결건조 제품으로 연중 유통됩니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"1월 이달의 수산물 ‘매생이, 민물장어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38255","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"나사에서 지정한 우주식량 ‘매생이’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=23564","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"2024년 1월의 수산물, 어촌여행지, 해양생물, 등대 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=54690&menuSeq=971","checkedAt":"2026-11-13"}]},
  "mallow": {"summary":"아욱은 7~8월이 제철이에요. 잎이 넓고 부드러우며 대가 통통하고 연한 것을 고르세요. 껍질 벗기고 치대서 풋내 빼는 손질법과 아욱국을 정리했어요.","origin":"경기·나주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"아욱은 고려 이전부터 재배해 온 오래된 채소로, 따뜻한 기후에서 잘 자랍니다. 주로 된장을 푼 국에 넣어 먹습니다. 억센 아욱을 쓰면 식감이 나쁘고 텁텁한 맛이 나니 연한 것을 고르는 것이 중요합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"연한 잎은 부드럽고, 억센 것은 거칠고 텁텁합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 넓고 부드러우며 대가 통통하고 연한 것을 고르세요."},{"text":"눈으로 봤을 때 짙은 연두색을 띠는 것이 싱싱합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바로 먹지 않으면 신문지에 싸서 냉장하세요."},{"label":"손질법","text":"아주 억센 줄기는 버리고, 줄기를 윗부분에서 꺾어 얇은 껍질을 벗기세요. 큰 잎은 물속에서 푸른 물이 나오도록 주물러 치댄 뒤 찬물에 2~3번 헹궈 풋내를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"아욱국. 된장을 푼 국물에 부드러운 아욱 잎을 넣어 끓입니다."},{"text":"아욱죽. 아욱을 넣어 죽으로 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 치마아욱을 듭니다. 생산시기는 7~8월로 적혀 있지만, '가을 아욱국은 사위에게만 준다'는 속담을 들어 가을 아욱도 맛있다고 함께 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘아욱’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219957&menuNo=300063","checkedAt":"2026-11-12"}]},
  "mandarin": {"summary":"귤은 10월~이듬해 3월이 제철이에요. 같은 크기라면 손에 들어 묵직한 것을 고르세요. 상자로 산 귤을 오래 두는 보관법과 귤 셔벗을 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"제주에서 재배하는 귤은 재배 방식에 따라 시장에 나오는 때가 다릅니다. 가을부터 겨울까지는 노지에서 거둔 온주밀감을 만날 수 있고, 비가림 시설에서 겨울을 난 귤이나 가온 시설에서 재배한 귤은 다른 시기에도 나옵니다. 상자로 살 때는 위에 놓인 귤을 보는 데 그치지 말고 아래쪽에 눌린 과실이 없는지 살펴보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"알맹이를 씹으면 과즙이 터지고 단맛 뒤에 산미가 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"같은 크기라면 손에 들어 묵직한 것을 고르세요."},{"text":"껍질이 과육에 붙어 있고 지나치게 쭈글쭈글하지 않은지 보세요."},{"text":"상자 아래쪽에 눌리거나 곰팡이 핀 과실이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"상한 과실은 골라내고, 물기가 없는 귤을 겹치지 않게 서늘한 곳이나 냉장고에 두세요. 남은 과육은 낱알로 나눠 냉동할 수 있습니다."},{"label":"손질법","text":"껍질을 벗기기 전에 흐르는 물로 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"귤 샐러드. 낱알을 나눠 어린잎에 얹습니다."},{"text":"귤 셔벗. 얼린 과육을 갈아 차갑게 먹습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"제주농산물수급관리센터는 노지·타이벡·비가림 귤의 제철을 10월~이듬해 2월로 소개합니다. 극조생 온주밀감은 10월 이후 완숙과를 수확·출하한다는 지도 사례가 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘감귤’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219815&pageIndex=1&searchCnd=3&searchWrd=%EA%B0%90&selectMonth=1","checkedAt":"2026-11-12"},{"org":"제주농산물수급관리센터","title":"감귤","url":"https://jasdc.or.kr/info/intro/tangerine.htm","checkedAt":"2026-11-12"},{"org":"기장군 농업기술센터","title":"과수 영농정보","url":"https://www.gijang.go.kr/agri/board/view.gijang?boardId=BBS_0000014&dataSid=230851&menuCd=DOM_000000605003000000&paging=ok&startPage=13","checkedAt":"2026-11-12"}]},
  "manila-clam": {"summary":"바지락은 3~5월이 제철이에요. 껍데기가 깨지지 않고 윤기가 있으며 입을 다물고 있는 살아 있는 것을 고르세요. 해감하는 법과 냉동 보관법을 정리했어요.","origin":"서해안 갯벌","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"바지락은 모래와 펄이 섞인 얕은 바다에 사는 작은 조개로, 양식이 쉬워 산란기인 7월 초순~8월 중순을 빼고는 늘 출하됩니다. 여름 산란에 대비해 크게 자라는 3~4월에 맛이 가장 좋습니다. 여름 바지락은 껍데기는 커 보여도 살이 차지 않았으니 봄에 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"국물을 내면 시원한 맛과 감칠맛이 나고, 살은 쫄깃하고 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍데기가 깨지지 않고 윤기가 나며 입을 다물고 있는 살아 있는 것을 고르세요."},{"text":"채취한 지 오래된 바지락은 껍데기가 탁한 갈색을 띱니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"해감을 마친 바지락은 밀봉해 냉동하세요. 살아 있는 조개는 물속이나 밀폐용기에 두면 질식하니 얕은 접시에 담고 젖은 행주나 종이타월을 덮어 냉장하세요."},{"label":"손질법","text":"맑은 물이 나올 때까지 문질러 씻은 뒤 바닷물이나 소금물에 30분 이상 담가 펄과 모래를 뱉어 내게 하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"바지락 칼국수. 바지락으로 국물을 내 칼국수를 끓입니다."},{"text":"바지락 회무침. 데친 바지락살을 애호박, 오이, 미나리와 초고추장에 무칩니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"우리나라는 1912년부터 바지락을 양식했습니다. 해양수산부는 3월 이달의 수산물로 바지락을 선정하며 봄 바지락이 가장 크고 맛이 좋다고 소개했습니다. 지역에 따라 빤지락, 반지래기라고도 부릅니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"단백질 왕 ‘바지락’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=20153","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"3월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=55827&menuSeq=971","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"추운 겨울 잘 견뎌낸 바지락이 제철","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=9284","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "marbled-rockfish": {"summary":"쏨뱅이는 1월이 제철이에요. 등지느러미 가시에 약한 독이 있으니 맨손으로 만지지 마세요. 회와 매운탕으로 먹는 법과 손질 요령을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쏨뱅이는 우리나라 전 연안의 암초 지대에 사는 흰살 생선입니다. 양식이 되지 않고 어획량이 적어 대부분 산지에서 소비되므로, 도시 마트보다 산지 시장에서 만나기 쉽습니다. 지역마다 삼뱅이, 쏨팽이, 자우레기 등 부르는 이름이 다릅니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 단단하고 담백하며, 씹으면 서걱하고 탱글한 식감이 있습니다. 오래 씹으면 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"연안에서 잡힌 것은 거뭇하고, 깊은 곳에서 잡힌 것일수록 붉은빛이 강합니다. 색은 신선도가 아니라 사는 곳의 차이입니다."},{"text":"머리와 등지느러미에 가시가 있으니 고를 때 맨손으로 들지 마세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 밀봉해 냉장고에서 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"등지느러미 가시에 찔리면 약한 독으로 손이 붓고 쓰라리니 장갑을 끼고 다루세요. 비늘과 내장을 빼고 몸에 어슷하게 칼집을 넣어 조리합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"쏨뱅이 매운탕. 칼집 낸 쏨뱅이를 무, 미나리, 고추와 함께 끓입니다."},{"text":"쏨뱅이회. 단단한 살을 얇게 떠서 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"쏨뱅이는 새끼를 낳는 난태생 어종으로 11~3월경에 출산합니다. 한곳에 머무는 정착성 어종이라 큰 이동 없이 겨울에는 깊은 곳, 봄에는 얕은 곳으로 옮겨 갑니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 얼마나 맛있길래 ‘죽어도 쏨뱅이’일까?","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=31664","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "matsutake": {"summary":"송이버섯은 9~10월이 제철이에요. 향이 나고 자루가 탄탄하며 밑동이 무르지 않은 것을 고르세요. 흙 털어 내는 손질법과 송이구이, 송이밥을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"송이버섯은 소나무 숲에서 나는 가을 버섯으로 특유의 향을 즐기려고 구이나 밥에 씁니다. 산림청 자료에서 채취와 생산 시기는 기상과 산지에 따라 달라집니다. 장에서는 향과 갓의 상태를 함께 보고, 당장 먹을 만큼을 사 두는 것이 손질에 편합니다. 밑동에 붙은 흙을 제거하고 자루의 결을 따라 찢으면 두께를 비슷하게 맞춰 구울 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 뚜렷하고 익혀도 자루에 씹는 맛이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"향이 나고 자루가 탄탄한 것을 고르세요."},{"text":"밑동에 물러지거나 눌린 곳이 없는지 보세요."},{"text":"산지와 포장 상태를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"종이로 감싸 냉장하고 빠르게 조리하세요. 오래 둘 것은 손질해 소분 냉동할 수 있습니다."},{"label":"손질법","text":"밑동의 흙을 털거나 얇게 잘라내고 조리 직전에 필요한 만큼 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"송이구이. 결대로 찢어 익힙니다."},{"text":"송이밥. 얇게 썬 송이를 얹어 향을 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"산림청 임산버섯 자료는 송이 발생림과 채취 후 관리 시기를 구분합니다. 9~10월은 대표 소비철이며 산지와 날씨에 따라 실제 채취·공판 시기는 달라집니다."}]}],"sources":[{"org":"산림청","title":"임산버섯 재배 자료","url":"https://www.forest.go.kr/newkfsweb/cmm/fms/BoardFileDown.do?atchFileId=FILE_000000000356337&bbsId=BBSMSTR_1130&dwldHistYn=N&fileSn=1&fn=1+%EC%9E%84%EC%82%B0%EB%B2%84%EC%84%AF.pdf","checkedAt":"2026-11-12"},{"org":"산림청","title":"9월의 임업인과 송이 생산","url":"https://www.forest.go.kr/kfsweb/cop/bbs/selectBoardArticle.do?bbsId=BBSMSTR_1036&mn=NKFS_04_02_01&nttId=3210884","checkedAt":"2026-11-12"}]},
  "melon": {"summary":"멜론은 7~10월이 제철이에요. 그물무늬가 끊기지 않고 촘촘하며 들었을 때 묵직한 것을 고르세요. 후숙 기간과 자른 뒤 보관법을 정리했어요.","origin":"나주·담양·곡성·진주·김해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"멜론은 7~10월에 많이 나옵니다. 흔히 멜론이라 부르는 것은 껍질에 그물무늬가 있는 머스크멜론(네트멜론)입니다. 사 온 멜론은 바로 먹기보다 서늘한 곳에서 며칠 익힌 뒤 먹는 경우가 많으니, 언제 먹을지에 맞춰 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잘 익은 과육은 부드럽고 과즙이 많으며 향이 진합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"모양이 찌그러지지 않고 둥근 것을 고르세요."},{"text":"그물무늬가 촘촘하고 중간에 끊긴 곳이나 껍질 상처가 없는지 보세요."},{"text":"꼭지가 시들지 않았고 들었을 때 묵직한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"서늘한 곳에서 3~5일 익히고, 먹기 몇 시간 전에 냉장하세요. 자른 멜론은 단면을 랩으로 싸서 냉장합니다."},{"label":"손질법","text":"꼭지를 자르고 세로로 반 가른 뒤 씨를 긁어내고, 조각배 모양으로 잘라 껍질과 과육을 분리하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"멜론 요거트볼. 한 입 크기로 썬 멜론을 요구르트에 올립니다."},{"text":"멜론 화채. 과육을 동그랗게 떠서 다른 과일과 함께 시원한 음료에 띄웁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 감로, 머스크, 화이트를 듭니다. 후숙이 길어지면 맛이 떨어지므로 한꺼번에 여러 통을 살 때는 먹을 날짜를 나눠 익히세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘멜론’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219878&menuNo=300063","checkedAt":"2026-11-12"}]},
  "mideodeok": {"summary":"미더덕은 3~5월이 제철이에요. 판매명이 미더덕인지 오만둥이인지 확인하세요. 몸통이 터진 것을 피하는 요령과 미더덕 된장찌개, 해물찜을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"미더덕은 씹었을 때 오도독한 식감과 짙은 바다 향이 나는 수산물입니다. 수산물안전정보는 미더덕을 4월 제철수산물로 소개하며 모양이 비슷한 오만둥이와 구분합니다. 된장찌개나 해물찜을 만들 때는 씻은 미더덕을 넣어 충분히 익히세요. 뜨거울 때 바로 깨물면 안에 고인 국물에 데일 수 있으니 건져 잠깐 식힌 다음 먹는 편이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"오도독 씹히고 짭짤한 바다 향이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"판매명이 미더덕인지 오만둥이인지 확인하세요."},{"text":"몸통이 터져 물이 많이 빠진 것은 피하세요."},{"text":"냉장 상태와 포장 손상을 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장 상태로 구입해 빨리 조리하고, 냉동품은 포장 표시를 따르세요."},{"label":"손질법","text":"흐르는 물에 이물질을 씻어내고 익혀 사용하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"미더덕 된장찌개. 국물에 넣고 끓여 향을 냅니다."},{"text":"미더덕 해물찜. 익혀 양념과 버무리고 살짝 식혀 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"오만둥이는 미더덕과 다른 종입니다. 봄에는 채취 해역 관리가 이루어지므로 시중에 유통되는 제품을 사용하세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"4월 제철수산물 ‘미더덕’","url":"https://fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=23950&select_list_no=90","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"봄철 수산물 패류독소 안전관리 강화","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=25003&menuSeq=971","checkedAt":"2026-11-12"}]},
  "monkfish": {"summary":"아귀는 1~2월이 제철이에요. 찜용은 토막 두께가 비슷하고 잘린 면이 마르지 않은 것을 고르세요. 통아귀 손질을 맡기는 요령과 아귀찜, 맑은탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"아귀는 머리가 크고 몸이 납작한 생선으로, 아귀찜이나 맑은탕에 많이 씁니다. 수산물안전정보는 한겨울인 12~2월을 제철로 안내합니다. 손질한 토막을 사면 내장을 따로 정리하는 수고를 덜 수 있고, 껍질이 붙은 토막은 살과 다른 식감을 냅니다. 콩나물과 함께 찔 때는 두께가 비슷한 토막을 골라 속까지 고르게 익히세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살은 담백하고 부드러우며 껍질은 익으면 쫀득합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"토막의 두께가 비슷한 것을 고르세요."},{"text":"잘린 면이 마르거나 물러지지 않았는지 보세요."},{"text":"찜용은 껍질을 붙여 손질했는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 뒤 냉장하고 빨리 조리하세요. 남는 토막은 물기를 닦고 소분 냉동합니다."},{"label":"손질법","text":"통아귀는 내장과 아가미 제거를 판매처에 요청하고 조리 전에 남은 이물질을 확인하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"아귀찜. 콩나물과 함께 익히고 양념에 버무립니다."},{"text":"아귀 맑은탕. 무를 끓인 국물에 토막을 넣어 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"인천에서는 아귀를 물텀벙이라고 부릅니다. 지역 이름을 볼 때 실제 어종 표시를 함께 확인하세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"12월 제철수산물 ‘아귀’","url":"https://fsis.go.kr/front/api/totalView.do?cnts_id=19599&select_list_no=18749&title=","checkedAt":"2026-11-12"},{"org":"인천광역시 굿모닝인천","title":"물텀벙이","url":"https://www.incheon.go.kr/goodmorning/GOOD010401/view?curPage=1&nttNo=2042522&srchPblicteIssnoCode=202602","checkedAt":"2026-11-12"}]},
  "mouse-eye-bean": {"summary":"쥐눈이콩은 10~11월이 제철이에요. 콩알이 고르고 검은색에 윤기가 나는 것을 고르세요. 서리태와 구별하는 법, 볶은 콩 고르는 법과 보관법을 정리했어요.","origin":"충북·강원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쥐눈이콩은 쥐의 눈알처럼 생겼다고 붙은 이름으로 서목태라고도 합니다. 검은콩인 서리태와 헷갈리기 쉽지만 알맹이가 훨씬 작습니다. 서리가 온 뒤에 익어 10~11월에 거둡니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"볶으면 검은 껍질이 톡 터지면서 푸른 알맹이가 드러납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"콩알이 고르고 검은색을 띠며 윤기가 나는 것을 고르세요."},{"text":"볶은 쥐눈이콩은 푸른 알맹이가 노릇하게 볶아진 것을 고르세요. 너무 어두운 색은 탄 것일 수 있고 냄새도 좋지 않습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"오래 둘 것은 비닐봉지에 담아 냉동했다가 먹기 전에 실온에서 해동하세요. 볶은 콩은 실온에서 쉽게 변하니 밀폐용기에 담아 냉장하세요."},{"label":"손질법","text":"깨끗이 씻어 불려 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"콩밥. 불린 콩을 밥에 넣어 짓습니다."},{"text":"쥐눈이콩 콩국수. 콩을 갈아 국물로 씁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 충청북도와 강원도, 품종으로 소청2호를 듭니다. 떡 고명으로도 쓰입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘쥐눈이콩’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219947&menuNo=300063","checkedAt":"2026-11-12"}]},
  "mugwort": {"summary":"쑥은 3~4월이 제철이에요. 길이 4~5cm로 작고 흰 털이 있으며 만졌을 때 부드러운 어린 쑥을 고르세요. 독한 맛 빼는 손질법과 떡·국 활용을 정리했어요.","origin":"전국","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쑥은 봄철 산과 들에서 잘 자라는 나물로, 어린잎을 국이나 떡에 넣어 먹습니다. 향과 맛이 독해 삶은 뒤 물에 담가 우려서 쓰는 경우가 많습니다. 말려 두면 한 해 내내 먹을 수 있어 제철에 넉넉히 사서 손질해 두기도 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"이른 봄에 올라온 연둣빛 어린 쑥이 맛과 향이 좋습니다. 녹색이 진할수록 쓴맛이 강하고 식감이 떨어집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"길이 4~5cm 정도로 잎과 줄기가 크지 않고, 잎 앞뒤와 줄기에 흰 털이 있는 것을 고르세요."},{"text":"만졌을 때 부드럽고, 손으로 비볐을 때 향이 은은한 것이 좋습니다."},{"text":"이물질이 섞이지 않았는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"삶아서 냉동하거나 잘 말려 두면 철이 지나도 쓸 수 있습니다."},{"label":"손질법","text":"칼로 밑동을 잘라 내고 소금물에 헹구세요. 색을 살리려면 데치기 전에 소금물에 잠깐 담그고, 삶은 뒤 하룻밤쯤 물에 담가 독한 맛을 빼세요. 직접 캔다면 도로변이나 하천변의 쑥은 중금속 함량이 높다는 조사 결과가 있으니 피하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"쑥버무리. 햇쑥으로 만드는 떡으로, 쑥송편이나 쑥인절미로도 만듭니다."},{"text":"쑥국. 어린잎을 넣어 국을 끓이고, 양념은 적게 해 향을 살립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지를 전국으로 적습니다. 산과 들에서 흔히 자라는 야생 식물이라 크기와 연한 정도가 제각각이니, 이른 봄에 나온 어린 쑥인지 확인하세요. 말린 쑥은 뜨거운 물에 우려 차로 마시기도 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘쑥’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219842&menuNo=300063","checkedAt":"2026-11-12"}]},
  "mulberry": {"summary":"오디는 5월이 제철이에요. 검붉게 익고 용기 바닥에 즙이 많이 고이지 않은 것을 고르세요. 얕은 용기에 냉장하는 법과 오디 요거트, 잼을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"오디는 뽕나무에 달리는 열매로, 잘 익을수록 색이 짙어지고 단맛이 납니다. 생과로 먹을 양은 눌리지 않게 담아 두고, 음료나 잼에 쓸 양은 따로 덜어 냉동하면 꺼내 쓰기 편합니다. 농식품정보누리는 5월을 생산기로 안내하지만 실제로는 품종에 따라 익는 때가 달라, 농촌진흥청이 소개한 수향은 6월 중순까지 익습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잘 익은 과육은 달고 부드러우며 터지기 쉽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"바로 먹을 것은 검붉게 익은 알을 고르세요."},{"text":"아래쪽에 눌려 터진 알이 없는지 보세요."},{"text":"용기에 즙이 많이 고여 있으면 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"얕은 용기에 냉장해 빨리 먹고, 남은 것은 씻어 물기를 뺀 뒤 소분해 냉동하세요."},{"label":"손질법","text":"체에 받쳐 가볍게 씻고 꼭지나 이물질을 골라내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"오디 요거트. 먹기 직전에 오디를 얹습니다."},{"text":"오디잼. 과육을 약한 불에서 설탕과 함께 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"농촌진흥청에 따르면 수향의 성숙기는 5월 하순~6월 중순이며 청일뽕보다 약 일주일 빠릅니다. 대성뽕은 알이 큰 편이고 익는 시기에 차이가 있어 손으로 따 생과용으로 출하하기도 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘오디’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219843&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"더 빨리 익고 당도 높은 오디 나온다","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&dataNo=100000688650&mode=view&prgId=day_farmprmninfoEntry","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"오디 생산용 뽕나무 재배","url":"https://www.nongsaro.go.kr/portal/ps/psb/psby/vodPlay.ps?cntntsNo=93227&menuId=PS00069&mvpNo=494","checkedAt":"2026-11-12"}]},
  "mullet": {"summary":"숭어는 3~5월이 제철이에요. 몸에 상처가 없고 비늘 크기가 고른 것을 고르고, 눈이 검고 꼬리가 뾰족한지 보세요. 가숭어와 구별법, 손질법을 정리했어요.","origin":"전 연안(자연산), 하동(양식)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"숭어는 바닥 펄의 유기물을 먹고 사는 생선으로, 봄에 연안으로 돌아옵니다. 보리 이삭이 패는 4~5월에 잡히는 것을 보리숭어라 부르며 맛이 좋다고 칩니다. 시장에서는 생김새가 비슷한 가숭어(참숭어)와 함께 팔리는데, 가숭어는 겨울(11월~이듬해 2월)이 제철이라 철이 다릅니다. 여름에는 둘 다 살이 무르고 흙냄새가 납니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 단단하고 기름이 많아 회로 먹으면 씹는 맛이 좋습니다. 익히면 담백하고 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸에 상처가 없고 표면에 광택이 있으며 비늘 크기가 고른 것을 고르세요. 상처를 통해 기생충에 감염될 수 있습니다."},{"text":"숭어는 눈이 검고 꼬리가 뾰족하며, 가숭어는 눈이 노랗고 꼬리가 뭉툭합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비늘, 지느러미, 내장을 떼고 깨끗이 씻어 냉장 보관합니다."},{"label":"손질법","text":"내장이 터지면 금세 흙냄새가 배니 내장을 터뜨리지 않게 조심해서 꺼내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"숭어회. 단단한 살을 회로 뜹니다."},{"text":"숭어 만두. 숭어살을 얇게 저며 고기와 두부로 만든 소를 싸서 만듭니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"국내산 숭어는 자연산이 약 5천 톤, 양식산이 약 9천 톤 전후이며 양식산은 주로 횟감으로 나갑니다. 가숭어는 대부분 양식이라 ‘참숭어’라는 이름으로 많이 팔리니, 봄에 숭어를 찾는다면 눈 색과 꼬리 모양을 확인하세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 이름부자 ‘숭어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=28836&select_list_no=69","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 3월 수산물 ‘도다리와 숭어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33271&select_list_no=44","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"3월 어식백세 수산물 ‘숭어·멍게’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=15282&menuSeq=971","checkedAt":"2026-11-12"}]},
  "mung-bean": {"summary":"녹두는 9~10월이 제철이에요. 알이 단단하고 눅눅하거나 냄새가 변하지 않은 것을 고르세요. 불려서 껍질 벗기는 법과 녹두 빈대떡, 녹두죽을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"녹두는 작고 둥근 콩으로 빈대떡이나 죽을 만드는 데 씁니다. 통녹두는 불린 뒤 껍질을 문질러 벗기면 갈아서 부칠 때 반죽이 매끄럽고, 손질 시간을 줄이려면 깐 녹두를 살 수 있습니다. 녹두죽은 낟알이 퍼질 때까지 익히고, 빈대떡은 불린 녹두에 물을 조금씩 넣어 갈아 팬에 부칠 수 있는 농도로 맞춥니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 구수하고 부드러우며, 갈아 부치면 겉은 바삭하고 속은 포슬포슬합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알 크기가 고르고 단단한 것을 고르세요."},{"text":"눅눅하거나 냄새가 변하지 않았는지 보세요."},{"text":"부스러기와 이물질이 적은지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"마른 녹두는 밀폐해 습기를 피하고, 불려 놓은 것은 빠르게 익히세요."},{"label":"손질법","text":"통녹두는 물에 불려 껍질을 문질러 벗기고 여러 번 헹굽니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"녹두 빈대떡. 불린 녹두를 갈아 부칩니다."},{"text":"녹두죽. 알이 퍼질 때까지 충분히 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"통녹두와 깐 녹두는 손질 정도가 다릅니다. 9~10월은 생산기이며 마른 녹두는 저장해 유통합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘녹두’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219914&deleteCd=0&pageIndex=1&selectMonth=10","checkedAt":"2026-11-12"}]},
  "mussel": {"summary":"홍합은 2~3월이 제철이에요. 살이 통통하고 윤기가 나며 비린내 없는 것을 고르고, 5~9월 것은 패류독소에 주의하세요. 수염 떼는 손질법과 보관법을 정리했어요.","origin":"전 연안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"홍합은 담치라고도 부르는 조개로, 지금 많이 먹는 것은 외래종인 진주담치이고 토종은 참담치입니다. 산란기인 늦봄부터 여름에는 맛이 떨어져 늦겨울에서 초봄을 제철로 칩니다. 해양수산부는 홍합을 1월과 11월의 수산물로도 골랐습니다. 날로는 먹지 않고 익히거나 말려서 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"바다에서 자라도 짜지 않고 담백하며 단맛이 납니다. 국물을 내면 시원합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"살이 통통하고 윤기가 나며 비린내가 나지 않는 것을 고르세요."},{"text":"껍데기를 벗겼을 때 살이 붉은빛을 띠는 것이 좋습니다."},{"text":"참담치는 진주담치보다 크고 껍데기가 두꺼우며 보랏빛 도는 검은 광택이 납니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 홍합살은 소금물에 헹궈 냉동하거나 살짝 데쳐 냉장합니다."},{"label":"손질법","text":"껍데기를 문질러 씻습니다. 살만 쓸 때는 연한 소금물에 흔들어 씻고 가장자리 검은 수염을 자른 뒤 가위로 내장을 뗍니다. 5~9월에 채취한 홍합에는 마비 등을 일으키는 독소(삭시톡신)가 있을 수 있으니 이 시기에는 먹지 않는 것이 좋습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"홍합탕. 껍데기째 끓이고 청주를 넣으면 비린내가 줄고 감칠맛이 납니다."},{"text":"홍합밥. 불린 쌀에 씻은 홍합을 넣어 밥을 짓고 강된장과 초고추장을 곁들입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"영남에서는 참담치를 합자·열합, 강원도에서는 섭이라고 부릅니다. 말린 홍합(담채)은 국물이나 조림에 쓰고, 냉동하면 오래 둘 수 있습니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 보약 ‘홍합’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=22711&select_list_no=95","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"겨울철 자연 영양소 ‘굴, 홍합, 피조개’ 맛보세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=24336&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"11월 어식백세 수산물 ‘삼치·홍합’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=13772&menuSeq=971","checkedAt":"2026-11-12"}]},
  "mustard-greens": {"summary":"갓은 9~12월이 제철이에요. 갓김치용은 청색갓, 김장 양념용은 잎이 얇고 붉은 갓을 고르세요. 용도별 고르는 법과 냉장 보관법을 정리했어요.","origin":"고양·남양주·여수·김해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"갓은 9~12월에 나오는 엽채류로, 김장철에 많이 찾습니다. 품종에 따라 갓김치를 담그는 갓과 김장 양념에 넣는 갓이 나뉘므로, 무엇을 만들지 정하고 사야 합니다. 갓김치나 겉절이는 청색갓, 김장 양념은 붉은 갓이 맞습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎과 줄기가 맵고 상쾌한 맛이 나며 향과 단맛도 있습니다. 뜨거운 물에 살짝 데치면 매운맛이 더 강해지고 빛깔이 선명해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"줄기가 가늘고 연하며 솜털 같은 가시가 살아 있는 것을 고르세요."},{"text":"갓 특유의 향이 나는 것이 좋습니다."},{"text":"김장 양념용은 잎이 두껍지 않고 붉은색을 띠는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"종이나 키친타월에 싸서 물을 뿌린 뒤 밑동이 아래로 가게 세워 냉장하세요. 씻어서 키친타월로 감싸 밀봉해 냉장해도 됩니다."},{"label":"손질법","text":"시들거나 상한 부분을 다듬고 깨끗이 씻으세요. 톡 쏘는 맛을 살리려면 익히지 말고 생으로 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"갓김치. 청색갓으로 담그며, 시게 잘 익어야 맛이 납니다."},{"text":"갓 겉절이. 생갓을 양념에 바로 무쳐 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"돌산갓은 맛이 부드럽고 매운맛이 덜해 갓김치용으로 쓰고, 얼청갓은 김장 양념에 넣습니다. 정보누리는 돌산갓도 청색갓의 한 계통이라고 설명합니다. 씨앗은 갈아서 겨자를 만듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘갓’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219907&menuNo=300063","checkedAt":"2026-11-12"}]},
  "napa-cabbage": {"summary":"배추는 11~12월이 제철이에요. 잎이 얇고 흰 줄기를 눌렀을 때 단단한 장구형 배추를 고르세요. 속 색으로 고르는 법과 세워서 보관하는 법을 정리했어요.","origin":"제천·홍성·당진·고창·나주·영암","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"배추는 사계절 지역과 품종을 바꿔 나오지만, 김장철인 11~12월 배추를 제철 배추로 봅니다. 김장용으로 여러 포기를 살 때는 모양과 단단함, 속 색을 함께 확인하세요. 겉잎과 속 심까지 버릴 데 없이 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎이 얇고 부드러우며, 속잎은 달고 고소합니다. 안쪽 심 부분은 단맛이 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리와 줄기 둘레가 비슷한 장구형이고, 흰 부분을 눌렀을 때 단단하고 수분이 많은 것을 고르세요."},{"text":"잎 두께와 잎맥이 얇아 부드러운 것이 좋습니다."},{"text":"잘랐을 때 속이 꽉 차 있고 노란색을 띠는 것이 좋으며, 너무 진한 노란색이나 흰색은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"서늘한 곳에 두고, 날이 더울 때는 키친타월이나 종이에 싸서 냉장고에 세워 두세요. 세워 두면 덜 무릅니다."},{"label":"손질법","text":"한꺼번에 쓰지 않을 배추는 밑동만 잘라 두고 겉잎부터 필요한 만큼 떼어 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"배추김치. 김장철 배추로 고춧가루 양념을 해 담급니다."},{"text":"배춧국. 푸른 겉잎을 버리지 말고 국에 넣어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 봄, 여름, 가을, 겨울마다 생산 지역과 품종이 다르다고 설명하고, 김장철 주요산지로 충청 제천·홍성·당진, 전북 고창, 전남 나주·영암을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘배추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219884&menuNo=300063","checkedAt":"2026-11-12"}]},
  "neungi-mushroom": {"summary":"능이버섯은 9~10월이 제철이에요. 갓이 연갈색으로 넓게 퍼진 것을 고르고 원산지를 확인하세요. 날로 먹지 않는 이유와 데쳐서 냉동하는 보관법을 정리했어요.","origin":"전북·경기","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"능이버섯은 참나무 뿌리 근처에서 자라며 인공 재배가 되지 않아 시장에 나오는 것은 모두 자연산입니다. 산림청은 9월 초부터 10월 초까지 가을에만 잠깐 만날 수 있다고 설명합니다. 원산지에 따라 값 차이가 크니 국산인지 확인하고 여러 판매처 가격을 비교하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 독특하고 진해 향버섯이라고도 부릅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"갓이 연갈색이고 넓게 퍼진 것을 고르세요."},{"text":"원산지 표시를 확인하세요. 중국산도 유통됩니다."},{"text":"자연산이라 벌레가 있을 수 있으니 갓 안쪽을 살펴보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질해 찢은 뒤 끓는 물에 살짝 데쳐 냉동하거나 소금에 절여 두세요. 씻지 않고 쪼개 말려도 되지만 곰팡이가 피지 않게 주의합니다."},{"label":"손질법","text":"나뭇잎과 검불을 떼고 뿌리의 흙을 털어 낸 뒤 흙 묻은 부분을 칼로 얇게 벗겨 냅니다. 생으로 먹으면 중독 증상이 생길 수 있으니 반드시 익혀 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"능이백숙. 닭이나 오리에 능이를 넣어 끓입니다."},{"text":"능이 두부전골. 두부전골에 능이를 넣어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 생산시기를 1~12월로 적었지만, 산림청은 생버섯을 만날 수 있는 때를 9월 초~10월 초로 설명합니다. 정보누리는 지역 상품으로 곡성 능이버섯과 진안 능이버섯을 소개합니다."}]}],"sources":[{"org":"산림청","title":"능이버섯 품목 자료","url":"https://nfsv.forest.go.kr/kfs/images/data/down/imsan/%EB%8A%A5%EC%9D%B4%EB%B2%84%EC%84%AF.pdf","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘능이버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219929&menuNo=300063","checkedAt":"2026-11-12"}]},
  "oat": {"summary":"귀리는 9~10월이 제철이에요. 밥용 통귀리는 낟알이 고르고 껍질 붙은 뉘가 적은 것을 고르세요. 통귀리와 압착 귀리 차이, 귀리밥과 오트밀 죽을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"귀리는 통곡으로 밥에 섞어 먹거나 낟알을 납작하게 눌러 오트밀로 씁니다. 통귀리를 밥에 넣으면 씹는 맛이 뚜렷하고, 압착 귀리는 끓이는 시간이 짧아 죽을 만들기 편합니다. 통귀리에는 껍질이 붙은 뉘가 섞일 수 있으므로 조리 전에 살펴 골라내세요. 한꺼번에 많이 사기보다 쌀에 섞을 양과 죽으로 먹을 양을 생각해 형태를 고르면 쓰기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"통귀리는 고소하고 씹는 맛이 남으며, 압착 귀리는 끓이면 부드럽고 걸쭉합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"밥용은 낟알이 고르고 깨진 알이 적은 것을 고르세요."},{"text":"껍질이 붙은 뉘가 많이 섞였는지 보세요."},{"text":"가공 제품은 눅눅하지 않고 포장이 온전한지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀폐해 습기와 직사광선을 피하고, 개봉 후 오래 둘 양은 냉장 또는 냉동하세요."},{"label":"손질법","text":"통귀리는 뉘를 골라내고 씻어 불립니다. 압착 귀리는 제품의 조리 안내를 따르세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"귀리밥. 불린 통귀리를 쌀에 섞습니다."},{"text":"오트밀 죽. 압착 귀리를 물에 넣고 저으면서 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"통귀리와 압착 귀리는 가공 형태입니다. 9~10월은 정보누리의 대표 생산기이며 가공 제품은 연중 유통됩니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘귀리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219924","checkedAt":"2026-11-12"}]},
  "octopus": {"summary":"문어는 7~9월이 제철이에요. 다리가 마르지 않고 탄력 있는 것을 고르고 생물과 자숙을 구분하세요. 생문어 손질법과 문어숙회, 초무침을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"문어는 탕이나 숙회에 다리를 썰어 쓰는 수산물입니다. 해양수산부는 여러 해의 7월과 8월, 9월에 문어를 이달의 수산물로 선정했습니다. 구입할 때는 생문어와 자숙 문어의 표시를 확인하세요. 생문어는 내장과 입을 제거한 뒤 충분히 익히고, 자숙 제품은 해동이나 재가열 방법을 포장 안내에서 확인하면 손질 시간을 줄일 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익힌 문어는 감칠맛과 은은한 단맛이 나며 다리는 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"다리가 마르지 않고 탄력 있는 것을 고르세요."},{"text":"생물과 자숙을 구분해 보세요."},{"text":"포장에 액체가 새거나 냉장 상태가 나쁜 제품은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 빨리 조리하세요. 삶은 문어는 한 번에 쓸 양씩 나눠 냉동할 수 있습니다."},{"label":"손질법","text":"생문어는 내장, 눈과 입을 제거하고 빨판에 남은 이물질을 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"문어숙회. 충분히 익혀 식힌 다리를 얇게 썹니다."},{"text":"문어초무침. 익힌 문어와 채소를 먹기 직전에 버무립니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"문어라는 유통명으로 여러 종이 팔립니다. 구입 시 어종과 원산지, 생물·자숙 여부를 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"7월의 수산물 ‘붕장어·문어’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=62134&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"8월 이달의 수산물 ‘민어·문어·미꾸라지’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=42549&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"9월의 수산물 ‘미꾸라지·문어’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=53034&menuSeq=971","checkedAt":"2026-11-12"}]},
  "old-cucumber": {"summary":"노각은 4~7월이 제철이에요. 크기에 비해 묵직하고 노란빛이 고른 것을 고르세요. 껍질과 씨를 걷어 내는 손질법과 노각무침, 노각냉국을 정리했어요.","origin":"천안·진천·상주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"노각은 오이를 밭에서 더 자라게 한 뒤 수확한 것으로 어린 오이보다 굵고 껍질이 질깁니다. 노각무침을 만들 때는 껍질을 깎고 가운데 씨를 긁어낸 다음 썰어 소금에 절이세요. 물기를 짜서 양념하면 접시에 물이 덜 고이고 아삭한 식감을 살릴 수 있습니다. 노란빛이 돌더라도 눌러 무르거나 겉에 깊이 갈라진 자국이 있는 것은 피하는 편이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛은 담백하고 수분이 많습니다. 절인 뒤 물기를 빼면 과육이 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기에 비해 묵직한 것을 고르세요."},{"text":"손에 들었을 때 단단한지 확인하세요."},{"text":"노란빛이 고르고 깊게 갈라진 곳이 없는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 노각은 절여 물기를 빼고 밀폐해 냉장하세요."},{"label":"손질법","text":"껍질을 벗겨 길게 가른 뒤 숟가락으로 씨와 속을 걷어냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"노각무침. 절인 노각을 짜서 고추장 양념에 무칩니다."},{"text":"노각냉국. 얇게 썰어 식초를 넣은 찬 국물에 담습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"노각은 조선 오이 계통의 열매를 충분히 키워 수확합니다. 굵은 열매라도 껍질과 씨를 덜어낸 뒤의 양을 생각해 고르세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘노각’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227363&deleteCd=0&pageIndex=1&selectMonth=4","checkedAt":"2026-11-12"}]},
  "olive-flounder": {"summary":"광어는 11월~이듬해 2월이 제철이에요. 손질 살은 단면이 마르지 않고 물러지지 않은 것을 고르세요. 표준명 넙치와 양식 유통, 광어구이와 맑은탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"광어는 몸이 납작한 넙치로, 담백한 흰살을 구이나 국에 쓸 수 있습니다. 수산물안전정보는 가을과 겨울 사이에 맛이 좋고 양식으로 연중 공급된다고 설명합니다. 해양수산부는 5월과 6월에도 넙치를 월별 수산물로 선정한 적이 있습니다. 구입할 때는 계절 정보와 함께 원산지와 양식 여부를 살피고, 요리에 쓸 만큼 손질한 살을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살이 담백하며 익히면 부드러운 결이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"손질 살의 단면이 마르지 않은 것을 고르세요."},{"text":"살이 눌려 물러지거나 포장에 물이 많이 고이지 않았는지 보세요."},{"text":"양식·자연산과 원산지는 판매 정보를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질 살은 냉장해 빨리 조리하고 오래 둘 분량은 소분 냉동하세요."},{"label":"손질법","text":"비늘과 내장을 손질한 살을 구입하고, 조리 전에 남은 가시를 확인하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"광어구이. 물기를 닦고 두꺼운 쪽까지 익힙니다."},{"text":"광어 맑은탕. 무를 먼저 끓이고 광어를 넣습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"표준명은 넙치입니다. 양식으로 연중 공급되며, 외형 한 가지로 자연산 여부를 판단하기 어렵습니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"이달의 수산물 ‘넙치’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=28151&select_list_no=62","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"5월 이달의 수산물 ‘갑오징어·넙치’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=45819&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"6월의 어식백세 제철 수산물, 광어와 농어","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=1955&menuSeq=971","checkedAt":"2026-11-12"}]},
  "omija": {"summary":"오미자는 9~10월이 제철이에요. 청을 담글 생과는 알이 붉게 익고 과육이 충실한 송이를 고르세요. 생과·건과 보관법과 오미자차, 화채를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"오미자는 붉은 열매가 송이로 달리는 가을 식재료로, 신맛이 강해 차나 청으로 우려 마시는 경우가 많습니다. 생과는 알이 충실한 송이를 골라 씻고 물기를 뺀 뒤 가지를 떼어 쓰며, 바로 쓸 분량만 남기고 나머지를 얼리면 한 번에 필요한 양을 덜기 편합니다. 말린 오미자는 냉장고에서 찬물에 우려 음료로 만들 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛이 여럿 섞이지만 신맛이 먼저 느껴집니다. 생과는 즙이 많고, 말린 열매는 차로 우려 향과 색을 씁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"청을 담글 생과는 알이 붉게 익고 과육이 충실한 것을 고르세요."},{"text":"송이 아래에 눌려 즙이 샌 알이 많이 섞였는지 보세요."},{"text":"건과는 눅눅하지 않고 포장이 온전한 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바로 쓸 생과는 냉장하고 나머지는 소분해 냉동하세요. 건과는 습기를 피해 밀폐 보관합니다."},{"label":"손질법","text":"체에 받쳐 씻고 물기를 뺀 뒤 가지를 떼어내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"오미자차. 씻은 건오미자를 찬물에 담가 냉장고에서 우립니다."},{"text":"오미자화채. 우린 물을 체에 거르고 배를 얇게 썰어 띄웁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"농사로는 수확 뒤 생오미자와 건오미자의 처리 방법을 구분합니다. 9~10월은 생과 생산기이며 건과나 청은 별도로 유통됩니다. 포장에 적힌 원산지와 가공 형태를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘오미자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219893&pageIndex=10&selectMonth=99","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"오미자 농작업 일정","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbl/workScheduleDtl.ps?cntntsNo=30749&menuId=PS00087&sKidofcomdtySeCode=IC03","checkedAt":"2026-11-12"}]},
  "onion": {"summary":"양파는 4~7월이 제철이에요. 단단하고 껍질이 잘 말랐으며 들었을 때 묵직하고 싹이 나지 않은 것을 고르세요. 서늘한 곳에 두는 보관법을 정리했어요.","origin":"전남 무안·고흥·신안, 경남 창녕·합천, 대구","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"양파는 찌개, 볶음, 국, 샐러드에 두루 쓰이고, 고기 요리의 잡냄새를 잡는 데도 많이 씁니다. 흰 양파는 연하고 부드러운 맛이 나고, 노란 양파는 단맛이 강합니다. 노란 양파를 뺀 나머지는 수분이 많아 보관에 더 신경 써야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"날것은 알싸하고, 익히면 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"무르지 않고 단단하며 껍질 색이 선명하고 잘 마른 것을 고르세요."},{"text":"들었을 때 무겁고 크기가 고른 것이 좋습니다."},{"text":"싹이 났거나 어두운 색을 띠는 것, 껍질이 너무 적거나 잘 찢어지는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"열과 습기에 약하니 어둡고 통풍이 잘되는 곳에 서로 눌리지 않게 간격을 두고 보관하세요. 오래 둘 때는 냉장하고, 쓰고 남은 자투리는 냉동해 찌개나 양념에 쓰세요."},{"label":"손질법","text":"생으로 먹을 때는 물에 담가 매운맛을 줄이되, 너무 오래 담그지는 마세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"양파 샐러드. 얇게 썰어 물에 잠깐 담가 매운맛을 줄인 뒤 샐러드로 냅니다."},{"text":"양파 고기볶음. 고기와 함께 볶아 잡냄새를 줄이고 단맛을 더합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전남 무안·고흥·신안, 경남 창녕·합천, 대구를 들고, 품종을 조생종과 만생종으로 나눕니다. 수입 양파는 파란 부분이 많고 매운맛이 강하다고 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘양파’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219865&menuNo=300063","checkedAt":"2026-11-12"}]},
  "oriental-melon": {"summary":"참외는 5~8월이 제철이에요. 노란빛이 선명하고 골이 곧으며 꼭지가 시들지 않은 것을 고르세요. 작형별 수확 시기와 참외화채, 샐러드를 정리했어요.","origin":"성주·김천·고령","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"참외는 노란 껍질에 흰 골이 난 여름 과일로, 시설에서 일찍 기른 것은 한여름보다 앞서 장에 나옵니다. 농식품정보누리는 대표 생산기를 6~8월로 안내하고 농사로는 시설 조기재배 수확이 2~3월에 시작한다고 설명합니다. 과육이 아삭한 참외를 고를 때는 표면의 색과 골을 보고, 손으로 들어 무르거나 눌린 곳이 없는지도 살펴보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과육은 달고 아삭하며, 익은 열매에서 참외 향이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"노란빛이 선명하고 골이 곧은 것을 고르세요."},{"text":"꼭지가 시들지 않았는지 살피세요."},{"text":"손에 들었을 때 무른 곳이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통참외는 냉장하고 자른 것은 밀폐해 냉장하세요. 갈아 마실 용도라면 손질한 과육을 얼릴 수 있습니다."},{"label":"손질법","text":"껍질을 흐르는 물에 씻은 뒤 깎으세요. 요리에 따라 가운데 속을 덜어냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"참외화채. 과육을 깍둑 썰어 차가운 국물에 띄웁니다."},{"text":"참외샐러드. 얇게 썰어 식초나 레몬즙을 넣은 드레싱을 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"성주군 자료에서 터널조숙 작형은 6월 하순~7월 상순 수확을 안내합니다. 농사로의 시설 조기재배는 2~3월 수확이 가능하므로 판매 시작과 달력의 제철 범위를 구분해 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘참외’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219900&pageIndex=1&selectMonth=6","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"참외 본포관리","url":"https://www.nongsaro.go.kr/portal/ps/psb/psby/vodPlay.ps?menuId=PS65512&mvpNo=443","checkedAt":"2026-11-12"},{"org":"성주군","title":"참외 재배방법별 파종기·정식기·수확기","url":"https://sj.go.kr/page.do?mnu_uid=2995","checkedAt":"2026-11-12"}]},
  "oyster": {"summary":"굴은 11월~이듬해 3월이 제철이에요. 살 가장자리의 검은 테가 또렷하고 눌렀을 때 탄력 있는 것을 고르세요. 생굴 씻는 법과 안전하게 먹는 법을 정리했어요.","origin":"통영·거제 등 남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"굴은 겨울에 생굴, 굴국, 굴전으로 많이 먹는 패류로, 기온이 내려가는 11월부터 이듬해 3월경까지 생산과 판매가 활발합니다. 자연산은 수확량이 적어 시장에 나오는 굴은 대부분 양식입니다. 깐 굴은 껍질을 깐 지 얼마 안 된 것일수록 좋으니 살의 빛깔과 테두리를 보고 고르세요. '가열조리용' 표시가 붙은 굴은 익혀서 먹는 용도입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"싱싱한 굴은 살이 오돌오돌하고 탱탱합니다. 수분이 많아 오래 가열하면 물기가 빠지며 단단해집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"빛깔이 밝고 우윳빛 광택이 나며 눌렀을 때 탄력이 있는 것을 고르세요."},{"text":"살 가장자리의 검은 테가 또렷한 것이 껍질을 깐 지 얼마 안 된 굴입니다."},{"text":"색이 선명하지 않고 희끄무레한 굴은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"깐 굴은 바닷물에 담가 밀봉해 보관하세요."},{"label":"손질법","text":"먹기 전에 소금물에 여러 번 헹궈 껍질 조각 같은 이물을 걸러내세요. '가열조리용' 굴은 반드시 익혀 드세요. 해양수산부는 노로바이러스가 중심온도 85℃에서 1분 이상 가열하면 사멸한다고 안내합니다. 국이나 전에 넣을 때는 마지막에 넣어 살짝 익히면 식감이 좋습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"굴국. 매생이와 함께 끓이면 겨울 별미가 됩니다."},{"text":"굴전. 손질한 굴에 밀가루와 달걀물을 입혀 부칩니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"남해안에서는 주로 바다에 줄을 매다는 수하식으로, 서해안에서는 갯벌에 종패를 뿌리는 갯벌양식으로 기릅니다. 굴은 5~8월에 산란하고 가을부터 살이 차오릅니다. 해양수산부는 생굴 소비가 몰리는 11월~이듬해 4월에 생산 해역의 노로바이러스를 조사하고, 검출되면 해당 굴에 '가열조리용'을 표시해 유통하도록 지도합니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"12월 이달의 수산물 ‘방어, 미역, 굴’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34360","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"영양만점 ‘굴’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=13869","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"제철 맞은 굴, 안전하게 드세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?docSeq=36166&menuSeq=971&bbsSeq=10","checkedAt":"2026-11-13"}]},
  "oyster-mushroom": {"summary":"느타리버섯은 시설 재배로 1~12월 내내 나와요. 갓 뒷면 빗살무늬가 선명하고 덩어리가 갈라지지 않은 것을 고르세요. 데쳐서 찢는 손질법을 정리했어요.","origin":"경기","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"느타리버섯은 국내에서 가장 많이 생산되는 버섯으로, 굴처럼 생겨 굴버섯이라고도 부릅니다. 정보누리 생산시기는 1~12월이고 주산지는 경기입니다. 덩어리째 팔리는 것이 싱싱하고, 쪼개지거나 갈라진 것은 오래된 것입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쫄깃한 식감이 특징이고, 몸통 길이보다 두께가 도톰할수록 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"갓 표면에 약간 회색빛이 도는 것을 고르세요."},{"text":"갓 뒷면 빗살무늬가 뭉개지지 않고 선명하며 흰빛을 띠는 것이 좋습니다."},{"text":"덩어리가 쪼개지거나 갈라진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"짧게는 냉장하세요. 오래 둘 것은 살짝 데쳐 찢은 뒤 물기를 꼭 짜서 지퍼백에 담아 냉동하고, 쓸 때는 자연스럽게 해동합니다."},{"label":"손질법","text":"물에 가볍게 흔들어 씻고 끓는 물에 살짝 데쳐 물기를 짠 뒤, 작은 것은 그대로 두고 큰 것은 결대로 찢습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"느타리버섯무침. 살짝 데쳐 찢은 버섯을 양념에 무칩니다."},{"text":"느타리버섯볶음. 데친 버섯을 양파와 함께 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 곤지2호와 부형대동2호를 듭니다. 연중 생산되지만 정보누리는 10월의 제철농식품으로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘느타리버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219932&menuNo=300063","checkedAt":"2026-11-12"}]},
  "paprika": {"summary":"파프리카는 5~11월이 제철이에요. 꼭지가 마르지 않고 표피가 두꺼우며 광택 나고 단단한 것을 고르세요. 씨 빼는 법과 너무 차갑지 않게 두는 법을 정리했어요.","origin":"진주·고성·창녕·강진·밀양","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"파프리카는 피망을 달고 과육이 많도록 개량한 것으로, 자라면서 초록색에서 품종별 색으로 바뀝니다. 국내에서는 노란색, 주황색, 빨간색, 초록색이 주로 팔립니다. 생으로 먹거나 볶음, 조림, 샐러드에 두루 쓰니 여러 색을 섞어 사도 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"피망보다 달고 과육이 많습니다. 생으로 먹거나 짧게 볶아 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼭지가 선명한 색을 띠고 마르지 않은 것을 고르세요."},{"text":"표피가 두껍고 광택이 나며 과육이 단단한 것이 신선합니다."},{"text":"뒤틀렸거나 통통하지 않은 것, 겉에 흠집이 있는 것은 피하세요. 무른 것은 숙성기를 놓쳤거나 오래된 것입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"하나씩 랩을 씌워 두면 오래 갑니다. 5℃ 이하에 두면 반점이 생기고 씨가 변하니, 오래 둘 때는 표면 물기를 완전히 없앤 뒤 비닐봉지에 담아 냉장하세요."},{"label":"손질법","text":"깨끗한 물에 씻어 꼭지를 떼세요. 위아래를 칼로 자르고 씨를 칼로 돌려 파낸 뒤 몸통을 펼쳐 써세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"파프리카 샐러드. 여러 색을 섞어 생으로 썰어 넣습니다."},{"text":"파프리카볶음. 기름에 짧게 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 진주, 고성, 창녕, 강진, 밀양 등을 듭니다. 오래된 것은 꼭지부터 상하니 진열대에서 꼭지 상태를 먼저 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘파프리카’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219876&menuNo=300063","checkedAt":"2026-11-12"}]},
  "peach": {"summary":"복숭아는 6~8월이 제철이에요. 꼭지 안쪽까지 푸른 기 없이 노르스름하고 향이 진한 것을 고르세요. 백도·황도·천도 차이와 보관법을 정리했어요.","origin":"경산·영천·음성·이천·남원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"복숭아는 한여름에 주로 맛보는 과일입니다. 크게 백도, 황도, 천도로 나뉘고, 생으로 먹을지 통조림이나 조림에 쓸지에 따라 고르는 품종이 다릅니다. 실온에서 쉽게 무르니 한 번에 너무 많이 사지 마세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"백도는 수분이 많고 부드럽습니다. 황도는 과육이 단단합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"흠이 없고 향이 진한 것을 고르세요."},{"text":"모양이 둥글고 전체적으로 붉은색이 진한 것이 잘 익은 것입니다."},{"text":"꼭지 안쪽까지 푸른 기 없이 노르스름한지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"한여름 실온에서는 금방 무르니 사 온 뒤 빨리 드세요. 냉장고에 오래 두면 단맛이 떨어지므로 꺼내서 30분쯤 두었다 드세요."},{"label":"손질법","text":"복숭아 알레르기가 있으면 껍질의 털이 피부에 닿지 않게 장갑을 끼고 손질하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"구운 복숭아. 반으로 갈라 팬에 구워 단맛을 끌어올립니다."},{"text":"복숭아잼. 무른 복숭아를 설탕과 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"백도는 생식용, 단단한 황도는 통조림과 가공용으로 많이 쓰입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘복숭아’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219885&menuNo=300063","checkedAt":"2026-11-12"}]},
  "peanut": {"summary":"땅콩은 10~11월이 제철이에요. 껍데기가 깨지거나 곰팡이 흔적이 없는 것을 고르세요. 생땅콩과 볶은 땅콩의 쓰임 차이, 삶은 땅콩과 땅콩조림을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"땅콩은 가을에 수확하고 생것을 삶거나 말려 볶아 먹습니다. 껍데기가 붙은 생땅콩은 삶아 먹을 때 촉촉하고, 볶은 땅콩은 바삭해서 간식이나 고명으로 쓰기 좋습니다. 용도가 다르므로 포장에 생땅콩인지 볶은 땅콩인지 표시를 살피세요. 껍데기를 깐 땅콩은 습기를 덜 먹도록 개봉 뒤 밀폐하고, 오래 둘 양은 한 번에 쓸 만큼씩 나눠 둡니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"삶은 것은 부드럽고, 볶은 것은 바삭하며 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍데기가 깨지지 않았는지 보세요."},{"text":"곰팡이 흔적이나 기름 냄새가 변한 제품은 피하세요."},{"text":"생것·볶은 것과 원산지 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"껍데기째인 건조품은 밀폐해 습기를 피하고, 깐 땅콩은 냉장이나 냉동하세요."},{"label":"손질법","text":"생땅콩은 겉의 흙을 씻어 충분히 익힙니다. 조림용은 껍데기를 벗깁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"삶은 땅콩. 껍데기째 씻어 속까지 삶습니다."},{"text":"땅콩조림. 껍데기를 벗겨 간장 양념에 조립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"생땅콩은 수확기에 사기 쉽고 볶은 제품은 저장해 유통합니다. 땅콩 알레르기가 있다면 원재료 표시를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘땅콩’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219920&deleteCd=0&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"}]},
  "pear": {"summary":"배는 8~10월이 제철이에요. 껍질이 얇고 매끄러우며 꼭지가 끈적이지 않는 것을 고르세요. 신고·원황 등 품종과 바람 들지 않게 보관하는 법을 정리했어요.","origin":"상주·청도·하동·밀양·영암·장성","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"배는 사과와 함께 가을에 가장 많이 찾는 과일이고 추석 차례상에도 오릅니다. 품종에 따라 나오는 때가 달라 8월부터 10월까지 이어집니다. 상자로 살 때는 겉면 색과 껍질 상태를 함께 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과즙이 많고 시원하며, 씹으면 사각거립니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 얇고 매끄러우며 상처가 없는 것을 고르세요."},{"text":"꼭지 부분이 끈적거리지 않고 과육이 단단한 것이 좋습니다."},{"text":"짙은 황색에 엷은 붉은 기운이 도는 것을 고르고, 주름지거나 푸르게 보이는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"하나씩 비닐이나 신문지에 싸서 얼지 않을 정도로 냉장하세요. 사과와 같이 두면 빨리 무르니 따로 보관합니다."},{"label":"손질법","text":"깎은 배는 갈변을 막으려면 소금물에 잠깐 담그세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"배꿀찜. 속을 파낸 배에 꿀을 넣어 찝니다."},{"text":"불고기 양념. 간 배를 넣어 고기를 재웁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 신고, 원황, 추황배, 화산배, 만수, 황금배를 소개합니다. 품종마다 수확 시기가 달라 같은 가을 배라도 맛과 저장성이 다릅니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘배’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219886&menuNo=300063","checkedAt":"2026-11-12"}]},
  "pearl-spot-chromis": {"summary":"자리돔은 5~6월이 제철이에요. 눈이 맑고 배가 터지지 않은 것을 고르고, 구이용은 크기가 고른 것으로 사세요. 손질법과 자리구이, 된장탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"자리돔은 제주 자리물회와 자리구이에 쓰는 작은 생선입니다. 제주 관광정보는 서귀포 보목동의 자리돔 축제가 5월 말~6월 초에 열린다고 소개합니다. 제주도 어업 기록에도 5~6월에 어획량이 많았던 해의 사례가 나옵니다. 집에서 구울 때는 크기가 비슷한 것을 골라 손질을 맡기고, 먹을 때 잔가시가 남아 있지 않은지 살피세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"구우면 담백하고 고소하며 작은 생선 특유의 잔가시가 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈이 맑고 표면이 마르지 않은 것을 고르세요."},{"text":"살에 탄력이 있고 배가 터지지 않았는지 보세요."},{"text":"한꺼번에 구울 양은 크기가 고른 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 빨리 익히고, 남는 생선은 손질해 소분 냉동하세요."},{"label":"손질법","text":"내장과 비늘을 다듬은 뒤 물기를 닦고 충분히 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"자리구이. 크기가 비슷한 생선을 골라 속까지 굽습니다."},{"text":"자리돔 된장탕. 토막 내어 된장 국물에 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"제주 자리돔 들망 어업 기록은 어획 사례이며, 축제 시기는 산지에서 맛보기 좋은 때의 참고 자료입니다."}]}],"sources":[{"org":"제주관광공사 비짓제주","title":"보목해녀의집","url":"https://visitjeju.net/kr/detail/view?contentsid=CNTS_000000000018358","checkedAt":"2026-11-12"},{"org":"제주특별자치도","title":"제주도 어업의 발자취","url":"https://jeju.go.kr/jori/reference/report.htm?act=download&no=1&page=1&seq=1479413","checkedAt":"2026-11-12"}]},
  "pen-shell": {"summary":"키조개는 3~5월이 제철이에요. 껍데기가 깨지지 않고 색이 진하며 겉이 끈적이지 않는 것을 고르세요. 관자 버터구이와 산란기 채취 금지 기간을 정리했어요.","origin":"충남, 전남 장흥","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"키조개는 곡식을 고르는 농기구 ‘키’를 닮은 큰 조개로, 껍데기가 25~30cm에 이릅니다. 7~8월 산란을 앞둔 봄에 살이 연해 4~5월을 제철로 칩니다. 산란기인 7월 1일~8월 31일에는 채취가 금지됩니다. 껍데기를 까기 어려워 손질한 관자나 살로 많이 팝니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 고소하고 담백하며, 쫄깃하면서도 연합니다. 큰 관자는 부드럽고 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기가 크고 껍데기가 깨지지 않은 살아 있는 것을 고르세요."},{"text":"껍데기 색이 진하고 투명한 느낌이 있는 것이 신선합니다. 표면이 끈적끈적하면 신선도가 떨어진 것입니다."},{"text":"껍데기를 까기 어려우니 깐 것을 사는 것도 방법입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"껍질 벗긴 조갯살은 뚜껑 있는 용기에 담아 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"껍데기가 얇아 잘 부스러지니 조심해서 다루고, 관자와 조갯살을 나눠 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"관자 버터구이. 버터를 발라 구우면 아이들도 잘 먹습니다."},{"text":"키조개 샤브샤브·회. 비린내가 적어 얇게 썰어 회로 먹거나 샤브샤브로 데쳐 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"2022년 키조개 생산량의 65% 이상이 충남, 35% 이상이 전남에서 나왔고, 전남은 양식 생산이 많습니다. 장흥에서는 해마다 5월 초 키조개 축제가 열립니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 조개의 왕 ‘키조개’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=20359&select_list_no=102","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 4월 수산물 ‘키조개’, ‘멍게’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34834&select_list_no=31","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "perilla-leaf": {"summary":"깻잎은 시설 재배로 1~12월 내내 나와요. 잎이 짙은 녹색이고 반점이나 얼룩이 없는 것을 고르세요. 잎이 마르지 않게 보관하는 법을 정리했어요.","origin":"경남·전남·충북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"깻잎은 들깨의 잎으로, 정보누리 생산시기가 1~12월이라 연중 살 수 있습니다. 생으로 쌈과 무침에 쓰고, 장아찌와 부각을 만들거나 찌개와 볶음에 향을 더할 때 넣습니다. 사 두면 남기 쉽고 냉장해도 금방 상하니 쓸 만큼만 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 진하고 잎이 부드럽습니다. 향이 강할수록 싱싱한 잎입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 짙은 녹색이고 크기가 고른 것을 고르세요."},{"text":"줄기가 마르지 않았는지, 붉은 반점이나 검게 변한 곳이 없는지 보세요."},{"text":"솜털과 잔가시가 선명하고 만졌을 때 까칠한 것이 갓 딴 잎입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"쉽게 마르므로 종이 타월로 물기를 닦고 종이로 싼 뒤 랩을 씌워 냉장하세요. 수분이 모자라면 검게 변합니다."},{"label":"손질법","text":"잔털에 이물질이 붙기 쉬우니 한 장씩 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"깻잎김치. 씻어 물기를 뺀 잎에 고춧가루, 액젓, 간장, 파, 마늘, 설탕으로 만든 양념장을 바릅니다."},{"text":"깻잎쌈. 생잎을 쌈 채소로 씁니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 잎들깨1호와 남천들깨를 듭니다. 연중 생산되지만 정보누리는 7월의 제철농식품으로 깻잎을 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘깻잎’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219945&menuNo=300063","checkedAt":"2026-11-12"}]},
  "perilla-seed": {"summary":"들깨는 10월이 제철이에요. 통들깨는 색이 고르고 잔돌과 흙이 적은 것을 고르세요. 들깻가루를 소분해 냉장·냉동하는 법과 들깨수제비를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"들깨는 씨를 갈아 국이나 탕에 넣거나 기름을 짜 쓰는 작물입니다. 통들깨는 이물질을 골라낸 뒤 갈아서 쓸 수 있고, 가루는 바로 넣을 수 있어 국을 끓이기 편합니다. 들깨가루로 국물 농도를 낼 때는 물이나 국물에 먼저 풀어 넣으면 덩어리가 덜 생깁니다. 장에서는 껍질이 포함된 가루인지 확인해 요리에 원하는 색과 식감에 맞춰 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"고소한 향이 진하고 통들깨를 갈면 껍질의 씹히는 느낌이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색이 고르고 이물질이 적은 통들깨를 고르세요."},{"text":"눅눅하거나 기름 냄새가 변한 것은 피하세요."},{"text":"가루는 포장이 밀봉돼 있는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통들깨는 습기를 피해 밀폐하고, 들깻가루는 소분해 밀폐 냉장이나 냉동하세요."},{"label":"손질법","text":"통들깨에 섞인 잔돌과 흙을 골라내고 용도에 맞게 갈아 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"들깨수제비. 가루를 국물에 풀어 농도를 냅니다."},{"text":"들깨버섯탕. 버섯을 익힌 뒤 들깨를 섞습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농사로는 들깻잎용과 씨를 거두는 종실용 품종을 구분합니다. 이 페이지의 생산기는 씨를 기준으로 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘들깨’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219917&deleteCd=0&pageIndex=1&selectMonth=10","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"들깨 농작업 일정","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbl/workScheduleDtl.ps?cntntsNo=259524&menuId=PS00087&sKidofcomdtySeCode=210004&totalSearchYn=Y","checkedAt":"2026-11-12"}]},
  "persimmon": {"summary":"감은 9~11월이 제철이에요. 단감은 꼭지가 붙어 있고 눌린 자국이 없는 것을 고르세요. 단감·홍시 고르는 법과 보관법, 추천 요리를 정리했어요.","origin":"상주·청도·영암","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"가을에 나는 감은 단단할 때 깎아 먹는 단감과 떫은맛이 빠지도록 익히거나 말려 먹는 떫은감으로 크게 나뉩니다. 같은 단감이라도 일찍 나오는 품종과 늦게 여무는 품종이 있으니, 장에서 감을 고를 때는 품종명과 먹을 때 원하는 식감을 함께 보세요. 홍시는 과육이 부드러워 숟가락으로 떠먹기 좋고, 단감은 얇게 썰어 샐러드에 넣기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단감은 씹으면 아삭하고 은근히 달아요. 충분히 익은 홍시는 과육이 젤리처럼 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"단감은 꼭지가 붙어 있고 껍질의 색이 고른 것을 고르세요."},{"text":"눌린 자국이나 깊은 갈라짐이 없는지 살피세요."},{"text":"홍시는 껍질이 터져 즙이 새는 것을 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"단감은 물기를 없애 냉장하고, 익은 홍시는 눌리지 않게 따로 담으세요. 홍시는 소분해 냉동해도 좋습니다."},{"label":"손질법","text":"흐르는 물에 씻고 꼭지와 씨를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"단감 샐러드. 얇게 썰어 잎채소와 견과류를 곁들입니다."},{"text":"홍시 셔벗. 씨를 뺀 과육을 얼려 살짝 녹여 떠먹습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"농촌진흥청은 남부지방에서 상서조생을 10월 상순에 수확하고 10월 9일 무렵부터 출하할 수 있다고 안내합니다. 부유의 수확 적기는 대체로 11월 상순입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘감’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219864&pageIndex=1&searchCnd=&searchWrd=&selectMonth=99","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"단감 적기 수확","url":"https://www.rda.go.kr/middlePopOpenPopNongsaroDBView.do?no=1996","checkedAt":"2026-11-12"}]},
  "pike-conger": {"summary":"갯장어는 8월이 제철이에요. 하모라는 이름으로 팔리니 어종과 원산지를 확인하세요. 잔가시 손질과 칼집을 부탁하는 요령, 갯장어 데침과 탕을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"갯장어는 하모라는 이름으로도 알려진 바닷물고기로 서남부 연해에 분포합니다. 전라남도 해양수산과학원은 여름에 추천하는 수산물로 갯장어를 소개했습니다. 살에 잔가시가 있어 집에서 직접 손질하기보다 가시를 다듬고 칼집을 낸 것으로 구입하면 국물에 익혀 먹기 편합니다. 장어라는 이름을 단 상품 가운데 어종을 확인하고 필요한 손질을 요청하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살은 담백하고 익히면 부드럽게 풀리면서 씹는 맛이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"하모 표기와 함께 어종·원산지를 확인하세요."},{"text":"손질한 살이 마르거나 물러지지 않았는지 보세요."},{"text":"데침용은 가시 손질과 칼집 여부를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질 살은 냉장 상태로 가져와 빨리 조리하세요. 남는 양은 소분 냉동합니다."},{"label":"손질법","text":"전문 판매처에서 뼈와 잔가시를 손질해 달라고 요청하고 속까지 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"갯장어 데침. 칼집 낸 살을 뜨거운 육수에서 완전히 익힙니다."},{"text":"갯장어탕. 가시를 손질한 살에 채소를 넣어 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"갯장어와 붕장어는 구분되는 어종입니다. 수산물안전정보는 갯장어가 서남부 연해와 서해 등에 분포한다고 안내합니다."}]}],"sources":[{"org":"전라남도 해양수산과학원","title":"여름 추천 수산물(수산물안전정보)","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0302&cnts_id=9613&select_list_no=81","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"장어 종류와 요리","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=15585&select_list_no=1","checkedAt":"2026-11-12"}]},
  "pine-chive": {"summary":"솔부추는 12월~이듬해 1월이 제철이에요. 줄기가 곧게 뻗고 짙은 녹색이 고르게 든 것을 고르세요. 흙째 냉장하는 보관법과 겉절이 활용을 정리했어요.","origin":"경기 양주·연천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"솔부추는 조선부추, 실부추로도 불리는 가는 부추입니다. 향과 아삭한 식감이 있어 겉절이와 무침에 주로 쓰고, 다른 요리의 부재료로도 넣습니다. 겨울에 나오는 잎채소라 시든 줄기가 섞이지 않았는지 꼼꼼히 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쌉싸름한 맛에 단맛이 더해지고, 씹으면 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"줄기가 곧게 뻗어 있고 잎이 싱싱한 것을 고르세요."},{"text":"고유의 짙은 녹색이 고르게 든 것이 좋고, 시들한 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"뿌리에 흙이 남아 있는 상태 그대로 밀봉해 냉장하세요."},{"label":"손질법","text":"물에 담가 흔들어 씻은 뒤 흐르는 물에 줄기와 잎을 다시 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"솔부추 겉절이. 썬 솔부추를 양념에 가볍게 버무려 고기 요리에 곁들입니다."},{"text":"솔부추무침. 손질한 솔부추를 양념에 무쳐 반찬으로 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경기 양주와 연천을 들고, 생산시기를 12~1월로 적습니다. 품목은 부추로 분류되며, 장에서는 조선부추나 실부추라는 이름으로 팔리기도 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘솔부추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227351&menuNo=300063","checkedAt":"2026-11-12"}]},
  "pine-nut": {"summary":"잣은 8~12월이 제철이에요. 크기가 고르고 진노란색이며 눌러도 부서지지 않는 것을 고르세요. 중국산과 구별하는 법과 산패를 막는 보관법을 정리했어요.","origin":"경기 가평","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"잣은 잣나무 열매 속 단단한 씨앗의 껍질을 벗긴 노란 알갱이입니다. 지방이 많아 오래 두면 진한 갈색으로 변하며 산패하기 쉽습니다. 수입 잣은 중국산이 많으니 국산과 구별하는 법을 알아 두세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"고소합니다. 정보누리는 수입산이 텁텁한 맛이 난다고 설명합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기가 고르고 윤기가 나며 물기 없이 잘 마른 것을 고르세요."},{"text":"진노란색이고 손으로 눌렀을 때 버석거리거나 부서지지 않으며 기름이 묻어나는 것이 좋습니다."},{"text":"국산은 씨눈이 거의 없고 진한 노란색입니다. 중국산은 윤기가 적고 씨눈이 덮인 것이 많으며 연노란색에 흰 반점이 많습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"속껍질이 붙은 상태로 공기가 통하지 않게 밀봉해 건조하고 통풍이 잘 되는 곳이나 냉장고에 두세요. 0℃에서 영하 20℃ 사이로 냉동해도 됩니다."},{"label":"손질법","text":"요리에 쓸 때 속껍질을 벗기세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"잣죽. 잣을 갈아 죽을 끓입니다."},{"text":"고명. 수정과 같은 음식에 띄웁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경기 가평을 들고, 잣을 우리나라 고유 특산품으로 소개합니다. 대표 달은 11월입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘잣’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219903&menuNo=300063","checkedAt":"2026-11-12"}]},
  "pineapple": {"summary":"파인애플은 3~9월이 제철이에요. 잎이 작고 단단하며 껍질의 3분의 1쯤이 노랗게 바뀐 것을 고르세요. 후숙 요령과 억센 껍질 손질법을 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"파인애플은 열대 과일이지만 국내에서도 제주를 중심으로 비닐하우스에서 재배하며, 정보누리 생산시기는 3~9월입니다. 사 온 뒤 후숙해야 더 맛있으니 먹을 날짜에 맞춰 익은 정도를 고르세요. 껍질이 억세 손질할 때 칼을 잘 골라야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단맛과 신맛이 어우러진 상쾌한 맛입니다. 잘랐을 때 단 향이 강할수록 당도가 높습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 작고 단단한 것을 고르세요."},{"text":"껍질의 3분의 1쯤이 녹색에서 노란색으로 바뀐 것이 좋습니다."},{"text":"덜 익으면 초록색, 익으면 주황빛이 도는 노란색이니 먹을 날짜에 맞춰 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"초록색인 것은 서늘하고 햇빛이 들지 않는 곳에서 일주일쯤 후숙하세요. 잎 쪽을 아래로 하루쯤 두었다 먹으면 좋고, 껍질을 벗긴 과육은 통에 담아 냉장합니다."},{"label":"손질법","text":"꼭지를 자르고 겉껍질을 오려 낸 뒤 심을 뺍니다. 과도보다 식칼로 껍질을 뭉텅뭉텅 잘라 내는 편이 쉽습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"파인애플 고기 재우기. 고기를 재울 때 함께 넣으면 고기가 연해집니다."},{"text":"파인애플 구이. 스테이크를 구울 때 그릴에 함께 올려 굽습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 스무스카이엔과 레드스패니시를 들고, 제주뿐 아니라 중부지방과 강원도에서도 하우스 재배를 한다고 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘파인애플’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219954&menuNo=300063","checkedAt":"2026-11-12"}]},
  "plum": {"summary":"자두는 7~8월이 제철이에요. 며칠 뒤 먹을 자두는 단단한 알을 고르세요. 덜 익은 자두를 실온에서 익히는 법과 자두잼, 샐러드를 정리했어요.","origin":"김천·의성·영동","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"자두는 여름에 나오는 과즙 많은 열매로 신맛과 단맛이 함께 납니다. 품종에 따라 익었을 때 껍질이 노랗거나 짙은 자줏빛이므로 붉은색만 보고 숙도를 판단하기 어렵습니다. 먹을 때가 며칠 남았다면 단단한 열매를 고르고, 바로 먹을 때는 꼭지 주변까지 색이 돌면서 눌린 자국이나 갈라짐이 없는 열매를 살펴보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"껍질 가까이에 산미가 느껴지고, 익은 과육은 달고 즙이 많습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"품종 고유의 색이 고르게 돌고 상처가 없는 것을 고르세요."},{"text":"며칠 뒤 먹을 것은 단단한 알이 좋습니다."},{"text":"과즙이 새거나 껍질이 터진 과실은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"덜 익은 것은 실온에서 익힌 뒤 냉장하세요. 잼에 쓸 양은 씨를 빼서 냉동할 수 있습니다."},{"label":"손질법","text":"먹기 직전 흐르는 물에 씻고 씨를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"자두잼. 씨를 뺀 과육을 졸입니다."},{"text":"자두 샐러드. 단단한 자두를 얇게 썰어 치즈나 잎채소와 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"농촌진흥청은 젤리하트를 당도가 높고 모양이 독특한 품종으로, 추희를 늦게 익는 만생종으로 소개합니다. 농사로의 여러 조·중생 품종 수확 안내와 정보누리의 7~8월 생산기는 적용 범위가 다릅니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘자두’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219874&pageIndex=1&selectMonth=7","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"자두 품종 젤리하트","url":"https://www.rda.go.kr/middlePopOpenPopNongsaroDBView.do?no=1726","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"만생종 자두, 폭염으로 생리장해 우려","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&dataNo=100000804680&mode=updateCnt&prgId=day_farmprmninfoEntry","checkedAt":"2026-11-12"}]},
  "plumcot": {"summary":"플럼코트는 6~7월이 제철이에요. 바탕색이 밝은 연두로 바뀌고 붉은빛이 든 것이 알맞게 익은 것이에요. 국산 품종과 잼 만드는 법을 정리했어요.","origin":"전남 나주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"플럼코트는 자두와 살구를 교잡해 만든 과일로, 이름도 두 과일의 영어 이름을 합친 것입니다. 표면에 미세한 털이 있어 살구와 비슷해 보입니다. 수확기는 6월 하순~7월 상순입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살구의 단맛과 자두의 과즙이 함께 납니다. 신맛과 단맛이 어울려 생으로도 먹고 잼으로도 만듭니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"바탕색이 짙은 초록에서 밝은 연두로 바뀌고 붉은색이 든 것을 고르세요. 농촌진흥청이 제시하는 하모니 수확 기준입니다."},{"text":"완전히 익은 과실은 유통 중 품질이 떨어지기 쉬우니 무른 곳이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"무르기 전에 드시고, 남으면 잼으로 만드세요."},{"label":"손질법","text":"씻은 뒤 씨를 발라내고 과육을 도려내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"플럼코트잼. 완전히 익은 과실의 씨를 빼고 과육을 갈거나 썰어, 과일과 설탕을 2대 1로 섞어 졸입니다."},{"text":"섞어 만드는 과일잼. 산이 많아 다른 과일잼에 과육을 조금 넣으면 산도를 맞추기 좋습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"국내 품종으로 하모니, 티파니, 심포니, 샤이니가 있고 하모니가 국내 생산의 80%를 차지합니다(2016년 농사로 영상). 하모니는 6월 중·하순에 수확합니다. 국내 재배는 2011년 전남 나주에서 시작됐습니다."}]}],"sources":[{"org":"농촌진흥청","title":"이달의 농업기술 ‘자두와 살구를 모두 느낄 수 있는 플럼코트’","url":"https://www.rda.go.kr/middlePopOpenPopNongsaroDBView.do?no=1396","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"농(農)영상 ‘플럼코트 인공수분기술’","url":"https://www.nongsaro.go.kr/portal/ps/psb/psby/vodPlay.ps?mvpNo=1163","checkedAt":"2026-11-12"}]},
  "pointhead-flounder": {"summary":"기름가자미는 5월이 제철이에요. 물가자미라는 이름으로도 팔리니 눈 없는 쪽 배가 하얗고 탄력 있는 것을 고르세요. 손질법과 식해 같은 요리를 정리했어요.","origin":"동해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"기름가자미는 동해안에서 많이 잡히는 가자미로, 표면의 점액 때문에 기름칠을 한 듯 미끈거려 이런 이름이 붙었습니다. 지역에 따라 물가자미, 물가재미라고 부르므로 판매명이 달라도 같은 생선일 수 있습니다. 해양수산부가 5월 이달의 수산물로 소개한 어종입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"특유의 고소한 맛이 있어 회, 찜, 탕, 구이로 두루 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"비늘이 단단하게 붙어 있고 윤기가 있는 것을 고르세요."},{"text":"눈이 없는 쪽 배가 하얗고 눌렀을 때 탄력이 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"넉넉히 샀다면 손질한 뒤 된장을 발라 냉장하거나 바람이 잘 통하는 날 말려 두세요."},{"label":"손질법","text":"비늘을 조심해서 긁어내고, 칼끝을 세워 꼬리 쪽부터 내장이 터지지 않게 긁어내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"가자미식해. 밥과 고춧가루, 엿기름을 넣어 삭힙니다."},{"text":"기름가자미 찜. 손질한 가자미를 양념해 찝니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"기름가자미의 산란기는 1~4월입니다. 우리 바다에는 돌가자미, 문치가자미, 홍가자미, 노랑가자미 등 여러 가자미가 함께 잡히니 판매명과 어종 표시를 함께 보세요."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"5월 이달의 수산물 ‘전복, 기름가자미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33539","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"9월 이달의 수산물 ‘가자미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32809","checkedAt":"2026-11-13"}]},
  "pollock": {"summary":"명태는 12월~이듬해 2월이 제철이에요. 맑은 국에는 생태, 찌개에는 동태를 고르세요. 생태·동태·북어 구분과 냉장 해동법, 동태찌개와 북엇국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"명태는 찬 바다에 사는 대구과 생선입니다. 생것은 생태, 얼린 것은 동태, 말린 것은 북어로 부릅니다. 겨울에 동태찌개를 끓일 때는 손질한 토막을 냉장고에서 해동하고, 맑은 국에는 살이 마르지 않은 생태를 고르세요. 수산물안전정보는 12월 제철 수산물로 소개하면서 여러 달에 걸쳐 포획이 이루어진다고 설명합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살은 담백하고 익히면 결을 따라 부서집니다. 북어는 마른 살의 씹는 맛이 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생태는 표면이 마르거나 살이 물러지지 않았는지 보세요."},{"text":"동태는 포장이 찢어지지 않았는지 확인하세요."},{"text":"북어는 곰팡이와 눅눅한 부분이 없는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생태는 냉장해 빨리 조리하고 동태는 냉동 상태로 두었다가 냉장 해동하세요."},{"label":"손질법","text":"손질 토막은 남은 내장과 지느러미를 확인하고 충분히 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"동태찌개. 무를 먼저 끓인 뒤 동태를 넣습니다."},{"text":"북엇국. 북어채를 불려 무와 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"생태·동태·북어는 가공 상태의 이름입니다. 원산지는 가공 이름과 별도로 포장에 표시된 내용을 확인하세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"12월 제철수산물 ‘명태’","url":"https://fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=23140&select_list_no=90","checkedAt":"2026-11-12"}]},
  "pomegranate": {"summary":"석류는 9~12월이 제철이에요. 겉껍질이 약간 거칠면서 단단하고 들었을 때 묵직한 것을 고르세요. 알갱이 발라내는 법과 냉장·냉동 보관법을 정리했어요.","origin":"전남 고흥·경남 거제","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"석류는 단단한 껍질 안에 붉은 알갱이가 가득 찬 과일로, 국내산은 9~12월에 나옵니다. 속이 완전히 익었을 때 수확하므로 껍질 색은 짙은 루비색, 분홍빛, 빨강 등으로 다양합니다. 껍질 색보다 무게와 상처를 보고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"알갱이에 과즙이 많습니다. 즙을 낼 때 씨를 걸러 내지 않으면 쓴맛이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"겉껍질이 약간 거친 듯하면서 단단하고 상처가 없는 것을 고르세요."},{"text":"들었을 때 묵직한 것이 과즙이 많습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"하나씩 랩으로 싸서 냉장하면 보름에서 20일 정도 둘 수 있습니다. 알갱이만 발라 밀폐용기에 담으면 냉장 3주 정도, 냉동하면 더 오래 둘 수 있습니다."},{"label":"손질법","text":"윗부분을 잘라 내고 반으로 가른 뒤 알갱이를 골라내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"석류즙. 끓여 식힌 설탕물을 알갱이에 붓고 열흘쯤 두었다가 체에 걸러 씨를 뺍니다."},{"text":"석류차. 껍질까지 씻어 조각낸 석류에 설탕을 섞어 둡니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전남 고흥과 경남 거제, 품종으로 꽃향 1호와 꽃향 2호를 듭니다. 대표 달은 11월로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘석류’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219889&menuNo=300063","checkedAt":"2026-11-12"}]},
  "pomfret": {"summary":"병어는 5~8월이 제철이에요. 푸른빛이 도는 은색으로 반짝이고 살짝 눌렀을 때 탄력 있는 것을 고르세요. 뼈째 먹는 병어회와 조림, 손질법을 정리했어요.","origin":"신안·목포","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"병어는 납작한 마름모꼴의 은빛 생선으로, 5월부터 8월까지 많이 잡힙니다. 6월 산란을 앞둔 병어가 살이 부드럽고 감칠맛이 납니다. 성인 손바닥 둘을 합친 크기면 최상품이고, 작은 것은 뼈가 연해 회로, 큰 것은 찜이나 탕으로 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적어 담백하면서 고소하고, 살이 연해 부드럽습니다. 잔가시가 없습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"푸른색이 돌며 은빛으로 반짝이는 것을 고르세요."},{"text":"살짝 눌렀을 때 탄력이 있는 것이 좋습니다."},{"text":"회로 먹을 것은 작은 것, 찜이나 탕은 큰 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 얼음 위에 올려 포장해 냉장하고 1~2일 안에 드세요. 오래 두려면 손질해 밀봉한 뒤 냉동하세요."},{"label":"손질법","text":"잔비늘이 많으니 칼로 긁어 깨끗이 손질하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"병어회. 뼈째 썰어 된장에 찍어 먹습니다."},{"text":"병어 고추장조림. 냄비에 감자를 깔고 병어를 올려 양념장을 끼얹어 졸입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"우리 바다의 병어류에는 병어와 덕대가 있는데 일반인은 거의 구분하기 어렵습니다. 연근해에서 잡자마자 냉동해 유통하는 경우가 많고, 신안과 목포 위판장에서 많이 거래됩니다. 해양수산부는 6월 이달의 수산물로 병어를 선정했습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"6월 이달의 수산물 ‘병어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=27210","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"6월 이달의 수산물 ‘병어, 다시마’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=37068","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"6월 이달의 수산물 ‘재첩, 병어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=33676","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "potato": {"summary":"감자는 6~10월이 제철이에요. 초록빛이 돌거나 싹이 난 것은 피하고 묵직하고 단단한 것을 고르세요. 싹 손질법과 서늘한 곳 보관법을 정리했어요.","origin":"강원·경기","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"감자는 6~10월이 제철인 서류로, 쪄 먹거나 볶음·국·찌개에 두루 씁니다. 수입 감자도 함께 유통되니 원산지 표시와 모양, 흙 상태를 함께 보세요. 초록빛이 돌거나 싹이 난 감자는 피해야 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쪄서 그대로 먹어도 포만감이 큽니다. 서늘하고 어두운 곳에 저장하는 동안 단맛이 조금씩 올라갑니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"들었을 때 묵직하고 단단하며 흠집이 적은 것을 고르세요."},{"text":"껍질에 물기나 주름이 없는 것이 좋습니다."},{"text":"초록빛을 띠거나 싹이 난 것, 물렁한 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통풍이 잘 되고 서늘하며 어두운 곳에 두세요. 상자에 보관할 때 사과를 한두 개 넣으면 싹이 덜 납니다."},{"label":"손질법","text":"싹에는 솔라닌이라는 독성 물질이 있으니 조리 전에 반드시 도려내세요. 초록빛으로 변한 감자도 쓴맛과 독성 물질이 있을 수 있어 사지 않는 것이 좋습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"찐감자. 껍질째 쪄서 그대로 먹습니다."},{"text":"감자볶음. 채 썬 감자를 기름에 볶아 반찬으로 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 제주산은 흙이 검고 알이 크며, 수입 감자는 크고 긴 타원형에 흙이 깨끗이 털린 경우가 많다고 설명합니다. 주요 품종으로 수원백종, 춘천재래, 두마2호 등을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘감자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219856&menuNo=300063","checkedAt":"2026-11-12"}]},
  "proso-millet": {"summary":"기장은 8~10월이 제철이에요. 낟알 크기와 색이 고르고 부스러기가 적은 것을 고르세요. 작은 알을 촘촘한 체로 씻는 법과 기장밥, 기장죽을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"기장은 작은 낟알을 쌀과 섞어 밥을 짓거나 죽과 떡에 쓰는 잡곡입니다. 알이 작아 손으로만 씻으면 헹굼물을 버릴 때 같이 빠져나갈 수 있습니다. 촘촘한 체에 받쳐 헹군 뒤 쌀에 섞으면 손질이 한결 편합니다. 한 봉지를 고를 때는 원산지 표시를 살피고, 부서진 알과 이물질이 적고 전체 색이 고른 것을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 은은히 고소하고 작은 낟알이 부드럽게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"낟알 크기와 색이 고른 것을 고르세요."},{"text":"부스러기와 이물질이 적은지 보세요."},{"text":"원산지와 포장 상태를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀폐해 습기와 직사광선을 피하세요. 오래 둘 양은 냉장 보관할 수 있습니다."},{"label":"손질법","text":"촘촘한 체에 받쳐 헹구고 돌이나 껍질이 있으면 골라냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"기장밥. 씻은 기장을 쌀에 섞어 짓습니다."},{"text":"기장죽. 쌀과 함께 끓이고 저어가며 농도를 맞춥니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"낟알 생김새보다 포장에 적힌 원산지를 확인하는 편이 정확합니다. 기장은 건곡으로 보관해 생산기 밖에도 유통됩니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘기장’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219967&deleteCd=0&pageIndex=1&selectMonth=9","checkedAt":"2026-11-12"}]},
  "pufferfish": {"summary":"복어는 12월~이듬해 1월이 제철이에요. 독이 있어 집에서 손질하면 안 되니 반드시 전문가가 손질한 복어를 사세요. 안전하게 먹는 법과 복어국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"복어는 감칠맛이 좋아 고급 식재료로 쓰이지만, 알·간·창자·혈액·껍질 등에 맹독인 테트로도톡신이 있습니다. 우리나라에서 먹을 수 있는 복어는 졸복, 황복, 자주복, 까치복, 흰밀복 등 21종입니다. 식용과 맹독성 종을 일반인이 구별하기 어려우니 반드시 손질이 끝난 복어를 사거나 전문음식점에서 드세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 희고 맑으며 기름기가 거의 없어 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"국가 자격을 갖춘 복어조리사가 손질한 복어만 사세요."},{"text":"몸이 단단하고 눈동자가 선명한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질된 복어는 얼음 위에 올려 포장해 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"집에서 직접 손질하지 마세요. 복어독은 색, 냄새, 맛이 없고 몇 시간 가열하거나 오래 얼려도 파괴되지 않습니다. 낚시로 잡은 복어를 먹고 중독되는 사고가 많으니 드시지 마세요. 먹은 뒤 입술 마비 같은 증상이 나타나면 바로 병원에 가서 복어를 먹었다고 알리세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"복어국. 전문가가 손질한 복어를 찬물에 1시간쯤 담가 핏물을 빼고 콩나물, 무, 미나리와 끓입니다."},{"text":"복어 전문음식점 요리. 복어조리사가 조리하는 전문음식점에서 먹는 것이 가장 안전합니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"복어독은 종류와 부위, 개체, 계절, 잡힌 바다에 따라 세기가 다릅니다. 산란기인 5~7월에 독이 가장 강해 “나비가 날면 복어를 먹지 않는다”는 말이 있습니다. 해양수산부는 12월 이달의 수산물로 복어를 선정하며 반드시 자격을 갖춘 조리사가 요리해야 한다고 안내했습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"12월 이달의 수산물 ‘과메기, 복어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=36088","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"바다의 육류 ‘복어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=19984","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"복어는 전문식당에서 드시면 안전해요","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0302&cnts_id=14399","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"12월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=59442&menuSeq=971","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "pumpkin-leaf": {"summary":"호박잎은 5~9월이 제철이에요. 잎이 연한 녹색이고 잎과 줄기에 솜털이 보송한 어린잎을 고르세요. 겉껍질 벗겨 찌는 법과 호박잎쌈을 정리했어요.","origin":"함평·해남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"호박잎은 호박의 어린잎으로, 쪄서 된장과 함께 쌈으로 주로 먹습니다. 5월에 나오는 잎이 가장 연하고 맛이 좋습니다. 빨리 시드는 채소라 살 때 싱싱한지 꼼꼼히 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쪄서 쌈으로 먹으면 구수하고 향긋합니다. 물에 데치면 흐물흐물해지고 맛이 묽어집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 연하고 연한 녹색이며 줄기가 질기지 않은 어린잎을 고르세요."},{"text":"만졌을 때 부드럽고 잎과 줄기에 보송보송한 솜털이 있는 것이 좋습니다."},{"text":"줄기 끝 절단면이 가지런하고 잎과 줄기 크기가 고른지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기가 있으면 상하기 쉬우니 신문지에 싸서 냉장하세요. 데친 것은 냉동해 두었다가 된장국에 넣어도 됩니다."},{"label":"손질법","text":"잎자루 끝을 살짝 꺾어 겉껍질을 벗기고 물로 씻은 뒤, 삶지 말고 찜통에 살짝 찌세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"호박잎쌈. 찐 호박잎에 된장을 곁들여 쌈으로 먹습니다."},{"text":"호박잎된장국. 호박잎을 넣어 된장국을 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 함평과 해남을 들고, 생산시기를 5~9월로 적습니다. 잎이 클수록 질기니 여름 끝 무렵에는 특히 잎 크기를 보고 고르세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘호박잎’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219852&menuNo=300063","checkedAt":"2026-11-12"}]},
  "pumpkin-seed": {"summary":"호박씨는 3~10월이 제철이에요. 알이 통통하고 묵은 기름 냄새가 나지 않는 것을 고르세요. 껍질 제거·소금 첨가 표시 보는 법과 볶은 호박씨를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"호박씨는 호박의 속에서 씨를 분리해 씻고 말리거나 볶아 먹는 재료입니다. 겉껍질이 붙은 씨와 껍질을 벗긴 알은 보이는 색과 먹는 방법이 다릅니다. 샐러드나 요거트에 바로 얹으려면 손질한 볶은 제품이 편하고, 빵에 넣을 때는 소금이나 양념이 들어갔는지 먼저 확인하세요. 건조한 호박씨는 호박 생산기와 별개로 연중 유통될 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"볶으면 고소하고 바삭하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 통통하고 부서진 것이 적은 제품을 고르세요."},{"text":"눅눅함과 묵은 기름 냄새가 없는지 보세요."},{"text":"껍질 제거 여부와 소금 첨가 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀폐해 건조하고 서늘하게 두고, 오래 둘 분량은 소분해 냉동하세요."},{"label":"손질법","text":"호박에서 직접 꺼낸 씨는 붙은 속을 씻어내고 물기를 없앤 뒤 충분히 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"볶은 호박씨. 물기가 없는 씨를 골고루 익힙니다."},{"text":"호박씨 샐러드. 볶은 씨를 먹기 직전 고명으로 뿌립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"3~10월은 정보누리의 생산기입니다. 건조·볶음 제품의 구매 기간과 호박 품종별 수확기는 이 범위와 구분됩니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘호박씨’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219952&deleteCd=0&pageIndex=1&selectMonth=99","checkedAt":"2026-11-12"}]},
  "quince": {"summary":"모과는 9~10월이 제철이에요. 색이 노랗고 향이 진하며 표면이 미끈한 것을 고르세요. 모과청·모과차 만드는 법과 말려서 보관하는 법을 정리했어요.","origin":"의성·청도·군위·공주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"모과는 생으로 먹기보다 청, 차, 술로 만들어 먹는 과일입니다. 그래서 장에서는 바로 먹을 맛보다 썰어서 가공하기 좋은 상태인지 보고 고르세요. 덜 익어 딱딱하거나 지나치게 익어 무른 것은 손질이 불편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과육이 단단하고 신맛과 떫은맛이 강합니다. 향이 진해 썰어 두기만 해도 냄새가 퍼집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색이 노랗고 향이 진한 것을 고르세요."},{"text":"표면이 너무 울퉁불퉁하지 않고 미끈한 것이 좋습니다."},{"text":"병충해 자국이나 상처가 있는 것, 과육이 물러진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생모과는 종이봉투나 신문지에 싸서 냉장하세요. 말린 모과는 밀폐용기에 담아 냉동하면 오래 둘 수 있습니다."},{"label":"손질법","text":"껍질이 미끄럽고 단단하니 도마에 고정해 조심해서 자르고, 씨를 빼고 얇게 써세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"모과청. 씨를 뺀 모과를 얇게 저며 설탕이나 꿀에 재웁니다."},{"text":"모과차. 껍질째 얇게 썰어 말린 모과를 물에 끓입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 천성을 소개합니다. 청을 담글 양을 한 번에 사는 경우가 많으니 상자 아래쪽 과실도 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘모과’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219913&menuNo=300063","checkedAt":"2026-11-12"}]},
  "rabbitfish": {"summary":"독가시치는 10월에 회로 즐기기 좋은 생선이에요. 등·배·뒷지느러미 가시에 독이 있으니 맨손으로 만지지 마세요. 손질 요령과 쏘였을 때 대처법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"독가시치는 우리나라 남부 연안에서 태평양과 인도양까지 사는 연안성 어류로, 암초 주위에서 무리를 지어 삽니다. 몸은 옆으로 심하게 납작하고 꼬리자루가 몹시 가늘며, 주둥이가 매우 작고 입술이 두껍습니다. 등·배·뒷지느러미 가시에 독이 있어 다룰 때 주의해야 합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"지느러미 가시에 독이 있으니 고를 때 맨손으로 들지 마세요."},{"text":"눈알이 밝고 투명하며 아가미가 선홍색인 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 얼음 위에 올려 포장한 뒤 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"배지느러미 가시의 독이 가장 강하고, 죽은 뒤에도 가시에 독이 오래 남으니 장갑을 끼고 가시에 손이 닿지 않게 다루세요. 쏘이면 통증이 심하고 하루에서 며칠씩 이어지기도 하니, 40~45℃의 뜨거운 물로 찜질하고 가까운 응급실에 가세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"독가시치회. 가시를 조심해 손질한 뒤 살을 떠서 회로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"독가시치는 최대 체장 25cm 정도까지 자라는 작은 생선입니다. 우리나라는 분포 범위의 북쪽 끝인 남부 연안에서 볼 수 있습니다."}]}],"sources":[{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 독가시치","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11822","checkedAt":"2026-11-13"},{"org":"대한민국 정책브리핑","title":"바다낚시할 때 만지면 안 되는 물고기 5","url":"https://www.korea.kr/news/cultureColumnView.do?newsId=148902640","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "radish": {"summary":"무는 10~12월이 제철이에요. 잔뿌리가 적고 묵직해야 바람이 들지 않은 무예요. 부위별 쓰임새와 바람 들지 않게 보관하는 법을 정리했어요.","origin":"홍천·평창·여주·당진","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"무는 배추와 함께 김장에 빠지지 않는 뿌리채소로, 가을무가 10~11월에 가장 많이 나옵니다. 장에서는 무청이 달린 것과 잘린 것이 함께 나오며, 무청이 달린 것이 싱싱합니다. 바람이 든 무는 맛이 떨어지니 무게를 꼭 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"윗부분 푸른 쪽은 단맛이 많고, 가운데는 달면서 살짝 맵고, 뿌리 끝은 매운맛이 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리가 하얗게 윤기가 나고 단단하며 매끈한 것을 고르세요."},{"text":"잔뿌리가 많지 않고 묵직한 것이 바람이 들지 않은 것입니다."},{"text":"무청이 잘린 무는 잘린 쪽에 구멍이 있거나 변색된 것을 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"잎이 뿌리의 수분을 빼앗으니 잎을 잘라 내고, 흙 묻은 채 랩이나 종이에 싸서 그늘지고 바람 잘 통하는 곳에 두면 5~7일 갑니다. 오래 두려면 4~5℃로 냉장하세요."},{"label":"손질법","text":"쓸 만큼 잘라 비닐 팩에 넣어 냉장하고, 남는 무는 썰어 햇볕에 말려 무말랭이로 만드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"무생채. 단맛이 많은 윗부분을 채 썰어 무칩니다."},{"text":"무조림. 가운데 부분을 큼직하게 썰어 조립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농사로 작형표를 보면 가을무는 9월 상순~12월 중순에 수확하고 10월 중순~11월 하순에 가장 많이 나오며, 봄무는 5월 중순~7월 상순에 수확합니다. 무청은 삶아 된장에 무치거나 말려서 시래기로 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘무’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219879&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"농작업일정 ‘무’","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbl/workScheduleDtl.ps?menuId=PS00087&cntntsNo=30614","checkedAt":"2026-11-12"}]},
  "rapeseed-greens": {"summary":"유채나물은 2~3월이 제철이에요. 꽃이 피기 전의 어린잎과 질기지 않은 줄기를 고르세요. 짧게 데치는 손질법과 유채나물 무침, 된장국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"유채나물은 노란 유채꽃이 피기 전에 어린잎과 줄기를 거두어 먹는 봄나물입니다. 줄기가 가늘고 잎이 어린 것은 함께 데쳐 무쳐도 연하고, 굵어진 줄기는 데치기 전에 잘라 내거나 따로 익히는 편이 좋습니다. 장에서 한 단을 고를 때는 잎이 싱싱한지와 줄기 아래쪽이 지나치게 질기지 않은지 살피세요. 데친 뒤에는 물기를 짜고 양념합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"어린잎은 데치면 부드럽고, 줄기는 가볍게 씹히며 끝에 쌉쌀한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꽃이 피기 전의 어린잎을 고르세요."},{"text":"줄기가 굵고 질기지 않은지 보세요."},{"text":"누렇게 뜨거나 짓무른 잎이 적은 단을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장하고 빠르게 드세요. 데친 것은 물기를 짜서 소분해 얼릴 수 있습니다."},{"label":"손질법","text":"누런 잎을 떼고 흙을 씻은 뒤 끓는 물에 짧게 데칩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"유채나물 무침. 데쳐 물기를 짜고 된장에 무칩니다."},{"text":"유채나물 된장국. 연한 잎을 국물에 넣어 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"꽃이 피기 전의 잎을 나물로 씁니다. 장에서 잎과 줄기의 연한 정도를 함께 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘유채’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219828","checkedAt":"2026-11-12"}]},
  "raspberry": {"summary":"산딸기는 6월이 제철이에요. 열매 끝이 뾰족하고 모양이 온전하며 탱탱한 것을 고르세요. 물에 오래 담그지 않는 세척법과 냉동 보관 요령을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"산딸기는 6월에 붉고 검게 익는 작은 열매입니다. 자연산은 시중에서 구하기 어렵고, 매장에 나오는 것은 대부분 시설에서 재배한 것입니다. 생으로 먹을지, 화채나 떡에 쓸지 정한 뒤 양을 맞춰 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 진하고 신맛이 많습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붉은색을 띠고 열매 끝이 뾰족하며 국화 봉오리처럼 모양이 온전하고 탱탱한 것을 고르세요."},{"text":"알이 너무 작으면 맛이 덜하고 먹기 불편하니 큰 것을 고르세요."},{"text":"전체적으로 무른 곳이 없는지 살펴보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비닐팩에 넣어 냉장하고 되도록 빨리 드세요. 오래 둘 때는 씻어서 물기를 충분히 뺀 뒤 설탕을 사이사이 조금씩 뿌려 냉동하면 서로 엉겨 붙지 않습니다."},{"label":"손질법","text":"흐르는 물에 빨리 씻고, 30~40초 넘게 물에 담가 두지 마세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"산딸기 화채. 설탕물에 산딸기를 넣고 오미자나 다른 과일, 잣을 띄웁니다."},{"text":"산딸기 떡. 과육을 으깨 멥쌀가루에 섞어 찝니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 청복분자딸기, 청수리딸기, 천도딸기, 나무딸기, 덩굴딸기를 듭니다. 외국 개량 품종이 들어와 대량생산되고 있어, 매장의 산딸기는 대부분 재배한 것입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘산딸기’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219867&menuNo=300063","checkedAt":"2026-11-12"}]},
  "red-bean": {"summary":"팥은 9~10월이 제철이에요. 붉은팥은 색이 진하고 윤기가 흐르며 껍질이 얇은 것을 고르세요. 수입산과 구별하는 법과 쓴맛 없이 삶는 요령을 정리했어요.","origin":"전남 나주·장흥, 강원 횡성·홍천, 경북 경주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"팥은 쌀, 콩과 함께 흔히 먹는 곡물로 9~10월에 거둡니다. 흔히 아는 적갈색 외에 회백색, 담황색, 갈색, 흑색 팥도 있습니다. 수입산이 함께 팔리니 낟알 크기와 배꼽의 흰 띠를 보고 구별하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"팥 자체는 그리 달지 않습니다. 팥죽이나 팥빙수의 단맛은 대부분 설탕을 넣은 것입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붉은팥은 색이 진하고 윤기가 흐르는 것을 고르세요."},{"text":"껍질이 얇고 손상된 낟알이 없는지 보세요."},{"text":"국산은 낟알이 크고 고르지 않으며 배꼽 속 흰 띠가 뚜렷합니다. 수입산은 낟알이 작고 고르며 흰 띠가 짧고 흐립니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"벌레가 생기기 쉬우니 물기가 거의 없는 상태로 바람이 잘 통하는 서늘한 그늘에 두세요. 삶은 팥은 한 번 쓸 양씩 나눠 냉동하면 편합니다."},{"label":"손질법","text":"콩보다 불리는 시간이 2~3배 걸리니 조금 으깨서 불리세요. 처음 삶은 물은 따라 버리면 쓴맛이 줄고 붉은색이 유지됩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"팥죽. 동지에 쑤어 먹는 죽입니다."},{"text":"팥빙수. 삶은 팥을 달게 졸여 얼음 위에 올립니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전남 나주와 장흥, 강원 횡성과 홍천, 경북 경주를, 품종으로 충주팥, 중원팥, 중부팥, 칠보팥, 예팥, 거피팥을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘팥’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219904&menuNo=300063","checkedAt":"2026-11-12"}]},
  "red-cabbage": {"summary":"적채는 3~6월이 제철이에요. 잎이 촘촘하게 여물고 같은 크기 중 묵직한 것을 고르세요. 자른 적채 보관법과 적채 샐러드, 피클을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"적채는 보라색 잎이 겹겹이 말리는 양배추입니다. 생으로 채 썰면 아삭하고, 식초가 들어간 절임에 넣으면 색이 달라져 피클이나 물김치에 쓰입니다. 통으로 살 때는 속이 단단히 찬 느낌이 들고 겉잎이 물러지지 않은 것을 고르세요. 샐러드에 쓸 때는 심을 떼고 결을 가로질러 얇게 썰면 한입에 씹기 편하며 다른 잎채소와도 잘 섞입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛은 순하고 은근히 달며 생으로 먹을 때 잎맥이 아삭합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 촘촘하고 단단히 여문 것을 고르세요."},{"text":"같은 크기 중 묵직한 것을 골라 보세요."},{"text":"겉잎이 물러지거나 절단면이 지나치게 마르지 않았는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"자른 적채는 단면을 싸서 냉장하세요. 볶음용으로 얼릴 경우 생채의 아삭함은 줄어듭니다."},{"label":"손질법","text":"겉잎을 걷어내고 씻은 뒤 심을 잘라 채 썹니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"적채 샐러드. 가늘게 채 썰어 잎채소와 섞습니다."},{"text":"적채 피클. 식초 절임에 담가 곁들임으로 씁니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"잎의 보라색을 물김치와 피클에 활용합니다. 다른 재료에 물들 수 있어 샐러드에는 마지막에 섞으세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘적채’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219940","checkedAt":"2026-11-12"}]},
  "red-chili": {"summary":"홍고추는 6~11월이 제철이에요. 생것은 매끈하고 탱탱하며 끝이 살짝 굽은 것을 고르세요. 태양초와 화건 구별법, 말린 고추 보관법을 정리했어요.","origin":"영양·의성·청양·음성","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"홍고추는 고추가 다 익어 빨갛게 된 것으로, 생으로도 쓰지만 대부분 말려서 고춧가루나 실고추로 만듭니다. 햇볕에 말린 것을 태양초(양건), 건조기에 말린 것을 화건이라고 부릅니다. 생홍고추를 살지 말린 고추를 살지에 따라 고르는 기준이 다릅니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맵고 입안이 얼얼합니다. 생것은 끝이 통통하고 뭉툭할수록 단맛이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생것은 전체가 매끈하고 탱탱하며, 색이 고르고 선명하게 윤기가 흐르고 끝이 살짝 굽은 것을 고르세요."},{"text":"말린 것은 빛깔이 붉고 광택이 나며 껍질이 두껍고 잘 마른 것이 좋습니다. 꼭지가 부러지거나 빠진 것은 피하세요."},{"text":"화건은 꼭지가 푸른빛, 태양초는 노란빛을 띠는 것이 좋고, 태양초는 잘랐을 때 속심까지 붉어야 합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생것은 수분이 많아 오래 두기 어렵고, 물기가 있으면 꼭지가 쉽게 상하니 물기를 잘 말려 두세요. 말린 고추는 종이봉투나 검은 봉지에 싸서 밀폐용기에 넣어 냉장하세요."},{"label":"손질법","text":"김치를 담글 때는 말린 고추를 물에 불려 갈아 써도 됩니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"김치 양념. 말린 홍고추를 불려 갈거나 고춧가루로 만들어 김치를 담급니다."},{"text":"홍고추볶음. 생홍고추를 볶음이나 절임에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 영양, 의성, 청양, 음성을, 품종으로 금탑, 조홍, 청양, 왕고추, 오륜을 듭니다. 숙성시키지 않은 고추를 햇볕에 말리면 하얗게 변하는 희나리가 생기니, 말린 고추를 살 때 색이 고른지 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘홍고추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219909&menuNo=300063","checkedAt":"2026-11-12"}]},
  "red-crab": {"summary":"홍게는 2월이 제철이에요. 아가미와 관절이 거뭇하게 변하지 않고 다리가 잘 붙어 있는 것을 고르세요. 대게와 구별하는 법과 금어기를 정리했어요.","origin":"경북 포항~강원 속초 동해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"홍게는 붉은대게를 흔히 부르는 이름으로, 경북 포항부터 강원 속초까지 동해안에서 대게와 함께 잡힙니다. 대게보다 많이 잡혀 같은 크기라도 값이 싸고, 게맛살이나 게장 같은 가공식품 원료로도 널리 쓰입니다. 생김새가 대게와 비슷하니 이름표와 껍질 색을 보고 구별하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적어 맛이 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"아가미 부분이나 관절이 어둡게 변색된 것은 피하세요."},{"text":"다리가 떨어지지 않고 잘 붙어 있는 것을 고르세요."},{"text":"홍게는 날것일 때도 등과 다리, 배 전체가 진한 주홍빛이고 대게보다 작으며 껍질이 단단합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"아이스박스나 아이스팩으로 차갑게 운반하고, 한 번에 조리할 만큼만 사세요."},{"label":"손질법","text":"신선한 홍게는 통째로 찌거나 삶아 먹습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"홍게찜. 통째로 쪄서 살을 발라 먹습니다."},{"text":"삶은 홍게. 끓는 물에 통째로 삶아 냅니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"홍게는 대게와 달리 등면뿐 아니라 다리와 배까지 진한 주홍빛이고, 갑각 옆 가장자리 뒷부분에 날카로운 가시가 있습니다. 산란기를 고려해 6월 1일부터 8월 25일까지는 금어기입니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"꼬막, 대게, 홍게(붉은대게)","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34597","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"2월엔 살이 꽉 찬 붉은대게와 꼬막 맛보세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=24653&menuSeq=971","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"수산물 구매, 운반, 보관 등 요령","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?bbs_no=bbs160617&menu_grp=MENU_NEW01&menu_no=4846&ntctxt_no=1096183","checkedAt":"2026-11-12"}]},
  "red-hyang": {"summary":"레드향은 1월이 제철이에요. 붉은 기가 도는 납작한 과실 중 배꼽 쪽이 진한 담홍색인 것을 고르세요. 천혜향과 다른 점과 보관법을 정리했어요.","origin":"제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"레드향은 제주에서 재배하는 만감류로 일반 귤보다 납작하고 익으면 붉은빛이 돕니다. 한 조각을 베어 물면 굵은 알맹이가 씹혀 부드러운 귤과는 다른 식감을 느낄 수 있습니다. 농식품정보누리는 1월을 생산기로 안내하며 그중 1월 중순 출하분을 추천합니다. 껍질에 윤기가 적을 수 있으니 광택보다 눌린 곳이나 갈라짐이 있는지 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단맛이 뚜렷하고 과육의 알맹이가 굵고 탄탄합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"붉은 기가 도는 납작한 과실을 살펴보세요."},{"text":"배꼽 쪽이 진한 담홍색인지 확인하세요."},{"text":"깊게 갈라지거나 눌려 무른 곳이 없는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"과실에 물기가 있으면 닦고 눌리지 않게 서늘한 곳에 두세요. 과육은 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"흐르는 물에 씻은 뒤 껍질을 벗겨 조각을 나눕니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"레드향 샐러드. 과육을 떼어 어린잎과 섞습니다."},{"text":"레드향 요거트. 먹기 직전에 조각을 얹어 굵은 알맹이 식감을 살립니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"레드향은 한라봉과 서지향을 교배한 품종입니다. 농식품정보누리는 천혜향과 비교해 레드향의 모양이 더 납작하다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘레드향’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=227335&pageIndex=1&searchCnd=&searchWrd=&selectMonth=1","checkedAt":"2026-11-12"}]},
  "red-rockfish": {"summary":"불볼락(열기)은 3~4월에 회로 즐기기 좋은 생선이에요. 아가미뚜껑과 눈 앞에 가시가 있으니 맨손으로 잡지 마세요. 생김새와 고르는 법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"불볼락은 시장과 식당에서 흔히 열기라고 부르는 양볼락과의 바다 생선으로, 우리나라 연근해와 일본 남부, 동중국해에 분포합니다. 수심 80~150m의 암초 지대 바닥 가까이에 삽니다. 국립수산과학원은 불볼락을 볼락, 조피볼락, 황점볼락 등과 함께 볼락류로 묶어 소개합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"아가미뚜껑 쪽 뼈에 가시가 여러 개 있고 눈 앞 뼈에 아래로 향한 가시 2개가 있으며, 꼬리지느러미 끝은 거의 곧게 잘린 모양입니다."},{"text":"눈알이 밝고 투명하며 튀어나와 있고, 아가미가 선홍색이나 분홍색인 것을 고르세요."},{"text":"손가락으로 살짝 눌렀을 때 살이 원래대로 돌아오고, 몸에 점액이 없는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"아가미뚜껑과 눈 앞에 가시가 있으니 장갑을 끼고 다루세요. 통생선은 꼬리를 잡지 말고 양손으로 듭니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"불볼락회. 이 달력에서 3~4월 회로 소개하는 생선입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"불볼락의 산란은 2~6월에 이루어지며 성기는 2~3월입니다. 같은 볼락류인 볼락, 조피볼락과는 다른 종입니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산생물종 정보 불볼락","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11762","checkedAt":"2026-11-13"},{"org":"국립수산과학원","title":"수산물이야기 볼락 - 왕고집 새침데기","url":"https://www.nifs.go.kr/portal/cmmnAtchFile/getAtchFileGroup.do?atchFileGroupId=PBLC20251204105339231UErZ131s&siteId=","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "red-scallop": {"summary":"홍가리비는 11월이 제철이에요. 껍질이 단단히 닫혀 있는 것을 고르고 두드려도 열린 채인 것은 피하세요. 해만가리비·큰가리비와 구별하는 법을 정리했어요.","origin":"경남 고성·통영","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"홍가리비는 껍질이 붉어 단풍 가리비라고도 부르며, 해만가리비를 개량한 종입니다. 주산지는 경남 고성과 통영이고 모두 양식산입니다. 시장에는 해만가리비, 큰가리비, 비단가리비도 함께 나오니 껍질 색과 크기로 구분하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"크기는 작지만 살이 달고 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 단단히 닫혀 있는 것을 고르세요."},{"text":"약간 벌어진 것은 가볍게 두드려 보고 닫히지 않으면 사지 마세요."},{"text":"원형에 가까운 부채꼴에 껍질이 붉은 것이 홍가리비입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"아이스박스나 아이스팩으로 차갑게 운반하고 한 번에 조리할 만큼만 사세요. 남으면 냉장하거나 냉동합니다."},{"label":"손질법","text":"탕, 찜, 구이 모두 껍질째 조리합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"홍가리비찜. 껍질째 쪄서 냅니다."},{"text":"홍가리비 치즈구이. 치즈와 버터를 올려 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"가리비 가운데 큰가리비는 폭이 15cm를 넘기도 하지만 양식산은 보통 10cm 안팎이고, 주로 동해안에서 양식하며 참가리비라는 이름으로도 팝니다. 해만가리비도 고성만이 주산지인 양식산입니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"삼치, 홍가리비","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=37914","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"11월의 수산물 삼치·홍가리비 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=63636&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"대구, 가리비류","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=35881","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"수산물 구매, 운반, 보관 등 요령","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?bbs_no=bbs160617&menu_grp=MENU_NEW01&menu_no=4846&ntctxt_no=1096183","checkedAt":"2026-11-12"}]},
  "red-seabream": {"summary":"참돔은 11월~이듬해 3월이 제철이에요. 눌러 봐서 살이 단단하고 눈동자가 까맣고 선명한 것을 고르세요. 집에서 쓰기 좋은 크기와 도미찜 만드는 법을 정리했어요.","origin":"전 연안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"참돔은 등이 붉은 도미과의 고급 생선으로, 도미류 가운데 으뜸으로 칩니다. 산란기(4~6월) 전인 봄까지 맛이 좋고, 산란을 마친 뒤에는 살이 여위어 맛이 떨어집니다. 대부분 활어로 팔리지만 반건조 상품도 나옵니다. 틸라피아가 ‘역돔’이라는 이름으로 팔리기도 하니 도미와 헷갈리지 마세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 희고 단단하며 비린 맛이 적고 담백합니다. 쫀득한 식감 때문에 회로 가장 많이 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눌러 보았을 때 살이 단단하고 비린내가 없는 것을 고르세요."},{"text":"눈동자가 까맣고 선명하며, 표면에 광택이 있고 비늘이 온전히 붙어 상처가 없는 것이 신선합니다."},{"text":"구이, 탕, 찜, 튀김용으로 집에서 쓸 때는 1kg 정도가 알맞습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질해 씻은 뒤 알맞은 크기로 잘라 랩을 씌워 냉동합니다."},{"label":"손질법","text":"칼등으로 비늘을 긁어내고 내장을 뺍니다. 통으로 조리할 때는 아가미를 벌려 내장을 꺼냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"도미찜. 칼집에 양념한 쇠고기를 채워 찐 뒤 지단과 버섯 고명을 올립니다."},{"text":"참돔회. 쫀득한 식감 덕에 회로 가장 많이 먹고, 탕·찜·조림으로도 씁니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"어릴 때는 몸에 붉은 띠가 있다가 자라면서 없어지고, 측선 주위에 푸른 반점이 흩어져 있습니다. 감성돔, 돌돔과 함께 양식도 됩니다. 돗돔은 이름이 돔으로 끝나지만 도미과가 아닙니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 여왕 ‘도미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=19812&select_list_no=105","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 여왕 ‘참돔’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=27707&select_list_no=74","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 2월 수산물 ‘참돔’, ‘김’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38461&select_list_no=9","checkedAt":"2026-11-12"}]},
  "red-spotted-grouper": {"summary":"붉바리는 11월에 회로 즐기기 좋은 생선이에요. 입이 커서 위턱 끝이 눈 뒤를 훨씬 지나는 것이 특징이에요. 생김새와 고르는 법, 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"붉바리는 자바리과의 바다 생선으로, 우리나라 남해와 제주도, 일본, 중국, 대만에 분포합니다. 제주에서는 자바리(다금바리)와 함께 연안에 머무는 특산 능성어류로 꼽힙니다. 식용어로 선호도가 높은 고가 어종이지만 자원이 줄어, 제주특별자치도 해양수산연구원이 종자를 생산해 방류하고 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸은 긴 타원형이고, 입이 커서 위턱 뒤끝이 눈 뒤끝을 훨씬 지나며, 꼬리지느러미 끝은 약간 둥급니다."},{"text":"눈알이 밝고 투명하며 튀어나와 있고, 아가미가 선홍색이나 분홍색인 것을 고르세요."},{"text":"손가락으로 살짝 눌렀을 때 살이 원래대로 돌아오고, 몸에 점액이 없는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"포장되지 않은 생선은 흐르는 찬물에 씻고 종이타월로 물기를 닦은 뒤 랩으로 싸서 조리 전까지 냉장합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"붉바리회. 이 달력에서 11월 회로 소개하는 생선입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"붉바리 같은 능성어류는 자연에서 생후 10년쯤 지나야 암컷 일부가 수컷으로 성전환해, 양식용 수컷 어미를 구하기 어렵습니다. 제주 주변 해역에서는 어획이 점차 줄고 있습니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산생물종 정보 붉바리","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=10288","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다금바리 등 제주 특산 능성어류 대량 종묘생산 착수","url":"https://www.fsis.go.kr/front/api/totalView.do?cnts_id=8825","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "redlip-mullet": {"summary":"가숭어는 2월이 제철이에요. 밀치나 참숭어라는 이름으로도 팔리니 실제 어종 표시를 확인하세요. 숭어와 다른 제철, 소금구이와 무조림을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"가숭어는 시장에서 밀치나 참숭어라고 부르는 어종입니다. 이름이 비슷한 숭어도 함께 판매되므로 장에서는 판매명에 이어 어종과 원산지를 확인하세요. 겨울에 먹는 가숭어는 지방이 풍부하고 씹는 맛이 있어 소금구이처럼 양념을 적게 넣는 요리에도 잘 어울립니다. 손질 살을 살 때는 조각마다 두께가 비슷해야 굽는 시간을 맞추기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"겨울에는 지방이 올라 고소하고 살에 탄력이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"밀치나 참숭어 표기에서 실제 어종을 확인하세요."},{"text":"구이용 살은 표면이 마르거나 물러지지 않았는지 보세요."},{"text":"냉장 포장 안에 핏물이 많이 고인 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"구입 후 곧 냉장하고, 오래 둘 양은 손질해 냉동하세요."},{"label":"손질법","text":"통생선은 판매처에서 비늘·아가미·내장을 제거해 달라고 요청하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"가숭어 소금구이. 물기를 닦고 완전히 익힙니다."},{"text":"가숭어 무조림. 무에 양념이 밴 뒤 생선을 넣습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"수산물안전정보는 가숭어가 주로 양식으로 유통된다고 안내합니다. 숭어의 4~5월 제철과 가숭어의 11~2월 제철은 어종별 자료입니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"이달의 수산물 ‘이름부자 숭어’","url":"https://fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=28836&select_list_no=65","checkedAt":"2026-11-12"}]},
  "rice": {"summary":"쌀은 9~10월이 제철이에요. 올해 수확한 햅쌀인지, 도정일자가 최근인지 포장 표시부터 보세요. 좋은 쌀 고르는 법과 벌레 막는 보관법을 정리했어요.","origin":"경기·충청","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쌀은 벼의 왕겨와 겨층을 벗겨 먹을 수 있게 가공한 것입니다. 햅쌀은 9~10월에 수확해 나오고, 포장에는 도정일자가 적혀 있습니다. 도정일자가 최근일수록 밥맛이 좋으니 날짜를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"올해 수확해 최근에 도정한 쌀일수록 밥맛이 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"쌀알 모양이 고르고 투명하며 광택이 나는 것을 고르세요."},{"text":"싸라기 같은 이물질이 섞이지 않았고, 쌀알에 찹쌀처럼 흰 부분이 생기지 않은 것이 좋습니다."},{"text":"금이 가거나 부러진 쌀이 많은 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀봉해 직사광선을 피해 서늘한 곳(10~15℃)에 두세요. 통마늘이나 숯을 함께 넣으면 벌레를 막는 데 도움이 됩니다. 벌레가 생기면 굵은 체에 쳐서 성한 쌀만 새 통에 옮기세요."},{"label":"손질법","text":"이물질을 골라낸 뒤 문질러 씻고 여러 번 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"떡. 쌀가루로 떡을 쪄서 명절이나 제사 때 씁니다."},{"text":"식혜. 쌀로 식혜나 엿을 만듭니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경기도와 충청도, 품종으로 운광, 고품, 하이아미, 미품을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘쌀’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219963&menuNo=300063","checkedAt":"2026-11-12"}]},
  "rock-bream": {"summary":"돌돔은 9월에 회로 즐기기 좋은 생선이에요. 검은 띠 7개가 뚜렷하지만 다 자란 수컷은 띠가 흐려지기도 해요. 생김새로 구별하는 법과 손질법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"돌돔은 우리나라 전 연안의 암초 지대에 사는 온대성 어류입니다. 몸은 체고가 높고 옆으로 납작한 타원형이며, 청색을 띤 연한 흑색 바탕에 눈에서 꼬리까지 검은 띠 7개가 있습니다. 양턱의 이빨이 새의 부리처럼 단단해 성게, 소라, 전복 같은 껍데기가 단단한 먹이도 깨 먹습니다. 지역에 따라 줄돔, 청돔, 갓돔, 아홉동가리 등으로 부릅니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"참돔, 감성돔, 벵에돔과 함께 주로 횟감으로 쓰는 고급 어종으로 꼽힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"수컷은 자라면서 줄무늬가 흐려지고 산란기에는 거의 사라지니, 띠가 흐린 것도 돌돔일 수 있습니다. 판매 이름을 함께 확인하세요."},{"text":"눈알이 투명하고 비늘이 단단히 붙어 반짝이는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 생선은 0℃에 가까운 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"등지느러미에 강한 가시가 10~12개, 뒷지느러미에 3개 있으니 장갑을 끼고 다루세요. 비늘과 내장을 뺀 뒤 살을 떠서 회로 먹습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"돌돔회. 손질한 살을 떠서 회로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"돌돔의 산란기는 국립수산과학원 자료에서 4~7월, 부산광역시 수산자원연구소 자료에서 5~8월로 조금 다릅니다. 양식산은 부화 후 만 1년이면 가랑이체장 20cm, 2년이면 26cm 정도로 자랍니다."}]}],"sources":[{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 돌돔","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11116","checkedAt":"2026-11-13"},{"org":"부산광역시 수산자원연구소","title":"수산종자 생태특성 돌돔","url":"https://www.busan.go.kr/fisheries/frfishpoint01","checkedAt":"2026-11-13"},{"org":"대한민국 정책브리핑","title":"영양가 풍부한 8월 수산물 2가지","url":"https://www.korea.kr/news/healthView.do?newsId=148906075","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "roughscale-flounder": {"summary":"줄가자미는 1월에 회로 즐기기 좋은 생선이에요. 몸 전체에 올록볼록한 돌기가 줄지어 있으면 줄가자미예요. 이시가리·돌가자미와 구별하는 법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"줄가자미는 수심 150~1,000m의 펄이나 모래 바닥에 사는 심해성 가자미입니다. 시장과 횟집에서는 '이시가리'라는 이름으로 더 많이 알려져 있고, 지역에 따라 돌도다리, 옴도다리, 꺼칠가자미로도 부릅니다. 일부 어판장과 횟집에서는 줄가자미를 '돌가자미'라고 부르기도 하지만, 돌가자미는 맛과 가격이 다른 별개의 어종입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"회로 뜨면 살이 약간 분홍빛이 도는 흰색입니다. 쫄깃한 식감과 지방의 고소한 맛이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈이 있는 쪽 몸 전체에 올록볼록한 돌기가 줄지어 있고 피부가 거칠면 줄가자미입니다. 눈이 없는 쪽은 매끈합니다."},{"text":"물집처럼 생긴 돌기가 등과 옆줄, 배 부분에 나란히 줄지어 있으면 돌가자미이니 이름표와 함께 확인하세요."},{"text":"눈알이 밝고 투명하며, 아가미가 선홍색이나 분홍색인 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"회는 뼈째 길게 썰고, 초고추장 같은 진한 양념 없이 그대로 씹어 먹는 방법이 소개되어 있습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"줄가자미회. 분홍빛이 도는 흰 살을 뼈째 길게 썰어 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"'이시가리'는 일본 일부 지역에서 줄가자미를 부르던 방언 '이시가레이'가 잘못 전해진 이름으로, 실제로는 줄가자미를 가리킵니다. 줄가자미는 비늘이 없고, 산란기는 10~6월(성기 12~2월)입니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산물이야기 가자미 - 바다의 카멜레온","url":"https://www.nifs.go.kr/portal/cmmnAtchFile/getAtchFileGroup.do?atchFileGroupId=PBLC20251204105339231EaG2M6f1&siteId=","checkedAt":"2026-11-13"},{"org":"국립수산과학원","title":"수산생물종 정보 줄가자미","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=10032","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "rye": {"summary":"호밀은 8~9월이 제철이에요. 가루는 원재료 표시에서 호밀 함량과 다른 곡물 혼합 여부를 보세요. 통알 손질법과 호밀빵, 호밀 곡물밥을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"호밀은 낟알을 빻아 빵을 만드는 데 많이 쓰는 곡물입니다. 빵용 호밀가루를 살 때는 통호밀을 갈았는지와 다른 곡물가루가 혼합됐는지 확인하면 반죽에 넣을 양을 정하기 쉽습니다. 농식품정보누리는 8~9월을 생산기로 안내하지만 종자용 씨알과 조사료를 거두는 시기는 다릅니다. 포장 제품은 생산 월보다 포장의 보관 상태와 원재료를 살펴 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"호밀가루를 구우면 구수한 향이 나고, 통알은 익혀도 씹는 느낌이 남습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"가루의 원재료와 호밀 함량을 보세요."},{"text":"통알은 크기와 색이 고른 것을 고르세요."},{"text":"눅눅하거나 포장이 손상된 제품은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"건조한 곳에 밀폐해 두고 오래 둘 가루는 소분해 냉동하세요."},{"label":"손질법","text":"통알은 이물질을 골라 씻고 충분히 익힙니다. 가루는 반죽에 섞어 사용합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"호밀빵. 배합에 맞춰 밀가루와 호밀가루를 섞어 굽습니다."},{"text":"호밀 곡물밥. 불린 통알을 쌀과 함께 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"농촌진흥청 자료는 씨알이 단단해졌을 때 채종한다고 안내합니다. 조사료용 봄 수확과 정보누리의 식품 생산 월은 용도가 다릅니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘호밀’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227345&deleteCd=0&pageIndex=1&selectMonth=8","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"호밀 씨알, 노랗게 익고 단단해지면 수확하세요","url":"https://www.rda.go.kr/board/board.do?dataNo=100000755892&mode=updateCnt&prgId=day_farmprmninfoEntry","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"사료작물 재배와 이용","url":"https://www.nongsaro.go.kr/portal/ps/psb/psby/vodPlay.ps?menuId=PS65512&mvpNo=2267","checkedAt":"2026-11-12"}]},
  "samchae": {"summary":"삼채는 6월이 제철이에요. 줄기가 억세지 않고 뿌리가 시들지 않은 것을 고르세요. 뿌리 사이 흙을 씻는 법과 뿌리째 종이에 싸는 보관법, 삼채볶음을 정리했어요.","origin":"하동·함양·거창","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"삼채는 잎이 부추처럼 가늘고, 아래에는 여러 갈래의 가는 뿌리가 달리는 채소입니다. 잎과 뿌리를 모두 먹을 수 있어 잎은 무침에 넣고 뿌리는 잘게 썰어 볶음에 쓸 수 있습니다. 뿌리가 많은 만큼 흙도 틈에 남기 쉬우므로 한 번에 씻어내려 하지 말고 뿌리 사이를 벌려 헹구세요. 바로 요리할 분량만 손질하고 남은 것은 뿌리가 달린 채 보관합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"알싸한 맛과 단맛, 쌉쌀한 맛이 나고 뿌리는 씹는 맛이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"줄기가 너무 억세지 않은 것을 고르세요."},{"text":"뿌리가 시들거나 검게 무르지 않았는지 보세요."},{"text":"잎 끝이 누렇게 마른 단은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"뿌리를 붙인 채 종이로 싸고 봉지에 담아 냉장하세요."},{"label":"손질법","text":"뿌리에 붙은 흙을 털고 사이를 벌려 흐르는 물에 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"삼채무침. 잎과 연한 줄기를 다듬어 양념에 버무립니다."},{"text":"삼채볶음. 손질한 뿌리를 잘게 썰어 다른 채소와 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"뿌리부추라고도 부르며 잎·줄기·꽃·뿌리를 씁니다. 부위별로 굵기가 달라 볶을 때는 뿌리부터 넣기 좋습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘삼채’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227362&deleteCd=0&pageIndex=1&selectMonth=6","checkedAt":"2026-11-12"}]},
  "sandfish": {"summary":"도루묵은 11월이 제철이에요. 몸통에 탄력이 있고 눈이 투명하며 아가미가 선홍색인 것을 고르세요. 도루묵 솥밥 만드는 법과 손질 뒤 냉동 보관법을 정리했어요.","origin":"강원 고성~경북 구룡포 동해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"도루묵은 동해안에서 주로 잡히는 냉수성 어종으로, 수분이 많은 흰살생선입니다. 해양수산부는 11월 이달의 수산물로 도루묵을 선정했습니다. 구이, 찌개, 조림으로 두루 쓰니 요리에 맞춰 양을 정해 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맛이 담백하고 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통을 눌렀을 때 탄력이 있는 것을 고르세요."},{"text":"눈알이 투명하고 튀어나와 있는지 보세요."},{"text":"아가미가 선홍색이고 비늘이 잘 붙어 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"차갑게 운반해 바로 냉장하고, 오래 둘 것은 냉동해 6~12개월 안에 드세요."},{"label":"손질법","text":"보관할 것은 머리와 내장처럼 먹지 않는 부위를 떼어 냅니다. 냉동한 것은 냉장고나 전자레인지에서 해동하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"도루묵 솥밥. 노릇하게 구운 도루묵을 솥밥에 얹어 뜸을 들인 뒤 간장, 고춧가루, 부추 양념장에 비빕니다."},{"text":"도루묵찌개. 토막 낸 도루묵을 찌개로 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"수산물안전정보의 어황 자료에 따르면 11월에는 강원 고성부터 경북 구룡포 해역의 저인망 어업이 도루묵을 잡았고, 12월에도 강원 연안을 따라 도루묵 어장이 형성될 것으로 전망됐습니다."}]}],"sources":[{"org":"해양수산부","title":"11월의 해양수산 어벤져스를 소개합니다(고등어·도루묵)","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=47769&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"11월 어황","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0610&cnts_id=13930&select_list_no=2004","checkedAt":"2026-11-12"},{"org":"식품의약품안전처 식품안전나라","title":"수산물 구매, 운반, 보관 등 요령","url":"https://www.foodsafetykorea.go.kr/portal/board/boardDetail.do?bbs_no=bbs160617&menu_grp=MENU_NEW01&menu_no=4846&ntctxt_no=1096183","checkedAt":"2026-11-12"}]},
  "sardinella": {"summary":"밴댕이는 5~6월이 제철이에요. 회로 먹을 것은 작은 것, 구이용은 큰 것으로 은빛과 윤기가 있는 것을 고르세요. 반지와 디포리 구분법과 보관법을 정리했어요.","origin":"서해·남해, 강화도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"시장에서 밴댕이로 팔리는 생선은 대부분 멸치과의 반지입니다. 경기·인천과 강화도에서는 반지를 밴댕이라 부르고, 회와 젓갈로 먹습니다. 진짜 밴댕이는 청어과로, 말려서 국물을 내는 디포리입니다. 반지는 산란을 앞두고 살이 오르는 5~6월에 가장 맛이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"봄 반지는 기름이 올라 고소합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"회로 먹을 것은 작은 것, 구이용은 큰 것을 고르세요."},{"text":"은빛이 나고 윤기가 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"잡힌 뒤 신선도가 빨리 떨어지니 바로 조리하고, 둘 때는 밀봉해 냉동하세요."},{"label":"손질법","text":"머리와 내장을 떼고 깨끗이 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"밴댕이회. 얇게 포를 떠서 하루쯤 냉장 숙성해 먹습니다."},{"text":"순무밴댕이김치. 강화도에서 순무와 밴댕이젓으로 담급니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"반지는 그물에 걸리면 금방 죽어 활어회로는 먹지 못하고, 하루가 지나면 보통 젓갈을 담급니다. 양식이 안 되므로 서해나 남해 산지에서 맛보기를 권합니다. 7월 중순부터는 산란기라 금어기입니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"밴댕이 아닌 밴댕이 ‘반지’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=15796","checkedAt":"2026-11-13"}]},
  "saury": {"summary":"꽁치는 9~11월이 제철이에요. 주둥이 주변이 노랗고 꼬리 부분이 노란빛을 띠는 것이 기름이 잘 오른 싱싱한 꽁치예요. 손질법과 구이·조림을 정리했어요.","origin":"포항","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"꽁치는 북태평양에 널리 사는 등푸른 생선으로, 통조림으로도 사철 나옵니다. 봄에 잡힌 꽁치는 기름기가 적고, 겨울을 앞둔 10~11월 꽁치는 지방이 많아 가장 맛이 좋습니다. 부패가 빨라 생물은 산 날 조리할 양만 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"가을 꽁치는 기름이 올라 고소합니다. 위가 없어 내장까지 먹을 수 있고, 먹은 먹이에 따라 내장 맛이 다릅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"작고 살이 통통하게 오른 것을 고르세요."},{"text":"주둥이 주변이 노란빛이면 기름이 잘 오른 것입니다."},{"text":"몸 전체가 밝은 빛을 띠고 꼬리 부분이 노란 것이 싱싱합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 오면 바로 조리하고, 곧 먹지 않을 때는 반드시 냉장하거나 냉동하세요."},{"label":"손질법","text":"꼬리를 자르고 배를 갈라 내장을 꺼낸 뒤 소금물에 씻어 토막 내고 소금을 뿌려 두세요. 껍질은 벗기지 않습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"꽁치 소금구이. 소금을 뿌려 굽는 가장 흔한 방법입니다."},{"text":"꽁치국(꽁치육개장). 포항 향토음식으로, 꽁치를 뼈째 갈아 완자로 빚어 채소와 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"산란기는 5~8월입니다. 생물 꽁치는 가을에 많이 나오고, 그 밖의 계절에는 통조림으로 많이 씁니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"제철수산물- 가을 ‘꽁치’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=16712","checkedAt":"2026-11-13"}]},
  "scallion": {"summary":"쪽파는 5월이 제철이에요. 잎 끝이 마르지 않고 흰 머리 부분이 통통한 것을 고르세요. 흙 묻은 뿌리 손질법과 오래 두는 보관 요령, 파김치·파강회를 정리했어요.","origin":"예산·아산·서천·당진·거제","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쪽파는 파와 샬롯의 잡종으로 밝혀진 채소로, 파보다 맛이 순하고 냄새가 덜 자극적입니다. 오래 끓이는 국물 요리를 빼면 거의 모든 요리에 양념으로 쓰입니다. 한 단을 사면 물러지거나 누렇게 변해 버리기 쉬우니 보관법을 함께 챙기세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"대파보다 향이 은은하고 전체적으로 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎 끝이 마르지 않고, 흰 머리 부분이 통통한 것을 고르세요."},{"text":"선명한 녹색에 윤기가 있고 줄기가 탄력 있는 것이 좋습니다."},{"text":"줄기가 노랗게 시들었거나 꺾이고 부러진 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질해서 냉장하거나, 뿌리 밑동을 조금 남기고 잘라 두면 싱싱함이 오래 갑니다."},{"label":"손질법","text":"뿌리의 흙을 털고 밑바닥의 까맣고 단단한 부분을 떼어 낸 뒤, 물에 잠깐 담갔다가 비벼 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"파김치. 고춧가루와 젓국으로 버무려 담급니다."},{"text":"파강회. 데친 쪽파를 댕기처럼 묶어 초고추장에 찍어 먹습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 예산, 아산, 서천, 당진, 거제를 듭니다. 흰 대가 둥글고 잎이 짧은 것이 재래종이며, 오래 둘 김장용은 길이가 짧은 것을 고르라고 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘쪽파’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219847&menuNo=300063","checkedAt":"2026-11-12"}]},
  "scallop": {"summary":"해만가리비는 11월이 제철이에요. 껍데기에 광택이 있고 두드리면 속살이 움츠러드는 것을 고르세요. 해감하는 법과 찜·구이, 홍가리비와 다른 점을 정리했어요.","origin":"경남 고성만(양식)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"해만가리비는 미국 대서양 연안이 원산인 가리비로, 고수온에 강하고 빨리 자라 2000년대부터 국내에서 양식합니다. 껍데기는 원형에 가까운 부채꼴이고, 주산지는 경남 고성만이며 모두 양식산입니다. 해양수산부는 해만가리비를 11월의 수산물로 골랐습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"감칠맛이 진해 국물 요리와 구이에 두루 씁니다. 너무 오래 익히면 질겨집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍데기에 광택이 있는 것을 고르세요."},{"text":"껍데기를 두드렸을 때 속살이 움츠러드는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장 보관하고 되도록 빨리 드세요."},{"label":"손질법","text":"소금물에 1시간 이상 담가 해감한 뒤 깨끗이 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"가리비찜. 손질한 가리비를 찜기에 쪄서 입이 벌어지면 꺼냅니다."},{"text":"가리비구이. 불에 굽다가 입이 벌어지면 바로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"시장에서는 큰가리비(참가리비), 해만가리비, 홍가리비, 비단가리비를 흔히 봅니다. 껍데기가 붉은 홍가리비는 해만가리비의 개량종으로, 경남 고성과 통영에서 양식합니다."}]}],"sources":[{"org":"해양수산부","title":"11월엔 제철 맞은 ‘삼치’와 ‘해만가리비’ 맛보세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=23748&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 11월 수산물 ‘대구’, ‘가리비류’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=35881&select_list_no=24","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 헤엄치는 조개 가리비","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=19420&select_list_no=107","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 11월 수산물 ‘삼치’, ‘홍가리비’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=37914&select_list_no=12","checkedAt":"2026-11-12"}]},
  "sea-bass": {"summary":"농어는 6~8월이 제철이에요. 등은 푸르고 배는 은백색이며 눈알이 또렷하고 살에 탄력 있는 것을 고르세요. 피 빼는 손질법과 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"농어는 “여름 농어”라는 말이 있을 만큼 여름을 대표하는 흰살 생선입니다. 봄부터 여름까지 먹이를 찾아 연안 얕은 바다로 오고, 겨울에는 깊은 곳으로 옮겨 갑니다. 대부분 30~40cm 크기로 팔리며, 큰 것은 살이 많아 여러 요리로 나눠 쓰기 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적어 맛이 담백하고, 살은 부드러우면서도 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"등은 푸른색, 배는 은백색이 선명한 것을 고르세요."},{"text":"살에 탄력이 있고 눈알이 또렷한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장으로 1~2일 둘 수 있고, 더 오래 두려면 냉동하세요."},{"label":"손질법","text":"아가미와 꼬리 쪽에 칼을 넣어 피를 뺀 뒤 비늘을 긁고 내장을 꺼내 물로 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"농어회. 여름 횟감으로 가장 많이 먹습니다."},{"text":"농어 튀김. 튀김가루를 입혀 바삭하게 튀깁니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"해양수산부는 8월 이달의 수산물로 농어를 선정하며 회 외에 구이와 탕에도 잘 어울린다고 소개했습니다. 큰 농어는 살이 많아 탕수나 스테이크로도 씁니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"여름 대표 생선 ‘농어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=15989","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"8월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=62602&menuSeq=971","checkedAt":"2026-11-13"}]},
  "sea-cucumber": {"summary":"해삼은 10월~이듬해 2월이 제철이에요. 돌기가 고르게 많이 돋고 썰었을 때 딱딱한 것이 신선해요. 홍해삼·청해삼 차이와 생해삼·건해삼 손질법을 정리했어요.","origin":"전 연안, 제주·울릉도·독도(홍해삼)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"해삼은 등에 혹 모양 돌기가 난 원통형 극피동물입니다. 수온이 오르면 여름잠을 자고 가을부터 다시 활동해 가을부터 겨울에 맛이 좋으며, 동지 전후를 가장 맛있는 때로 칩니다. 먹이와 사는 곳에 따라 홍해삼, 청해삼, 흑해삼으로 나뉘고, 그중 홍해삼을 으뜸으로 칩니다. 날것뿐 아니라 말린 건해삼으로도 팝니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"신선할수록 살이 단단하고 육질이 쫄깃합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"가시(돌기)가 고르게 많이 돋아 울퉁불퉁한 것을 고르세요. 표면이 밋밋한 것은 품질이 떨어집니다."},{"text":"썰었을 때 딱딱한 것이 신선합니다. 늘어지거나 물이 생기거나 냄새가 나면 상했을 가능성이 높습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"오래 두고 쓸 때는 건해삼을 사서 필요할 때 불려 쓰세요."},{"label":"손질법","text":"양쪽 끝의 입과 항문을 자르고 내장을 뺀 뒤 연한 소금물에 흔들어 씻습니다. 건해삼은 하룻밤 불려 솔로 씻고 반으로 갈라 내장을 뺀 뒤 끓는 물에 삶아 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"해삼회. 손질한 해삼을 썰어 양념과 함께 먹습니다."},{"text":"해삼전. 불린 해삼 안에 다진 쇠고기와 두부 소를 채워 지집니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"대개 제주와 울릉도·독도 주변에서는 홍해삼, 다른 바다에서는 청해삼과 흑해삼이 잡힙니다. 자연산은 해녀가 수심 10m 이내에서 채취하며 4~5월에 많이 잡힙니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 인삼 ‘해삼’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=22479&select_list_no=96","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 11월 수산물 ‘참조기’, ‘해삼’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34244&select_list_no=36","checkedAt":"2026-11-12"}]},
  "sea-squirt": {"summary":"멍게는 4~6월이 제철이에요. 손질품은 살이 선명한 주황색이고 포장이 새지 않는 것을 고르세요. 껍질과 내장 손질법과 멍게 비빔밥, 미역국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"멍게는 우렁쉥이라고도 부르는 바다 생물입니다. 겉껍질은 두껍고 안쪽에 주황색 살이 있어 통으로 사면 먹을 부분만 분리해야 합니다. 해양수산부는 봄철 할인 행사에서 제철 양식 멍게를 소개하고, 6월 수산물로도 선정했습니다. 손질이 어렵다면 포장이 온전하고 냉장 상태를 유지한 손질품을 골라 먹을 양만 꺼내 조리하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"바다 향과 짭짤한 맛이 강하고 살은 말랑합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"살이 선명한 주황색인지 보세요."},{"text":"냉장 포장이 새거나 팽팽하게 부풀지 않았는지 살피세요."},{"text":"손질 일자와 보관 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장하고 빠르게 조리하세요. 냉동 보관은 포장 표시를 따릅니다."},{"label":"손질법","text":"겉껍질과 내장을 제거한 살을 준비하고 조리 전에 이물질을 확인하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"멍게 비빔밥. 익힌 살을 썰어 밥에 얹습니다."},{"text":"멍게 미역국. 국물을 끓인 뒤 살을 넣어 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"우렁쉥이와 멍게는 같은 이름입니다. 국내에서 양식한 멍게가 유통되므로 산지 표기를 확인하세요."}]}],"sources":[{"org":"해양수산부","title":"제철 양식 수산물 온라인 판매 행사","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=31921&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"6월의 수산물 농어·멍게","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=1095&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"멍게","url":"https://fsis.go.kr/front/api/totalView.do?cnts_id=38629&select_list_no=424&title=","checkedAt":"2026-11-12"}]},
  "sea-urchin": {"summary":"성게는 3~8월이 제철이에요. 깐 성게알은 풀어지지 않고 진한 노란색에 윤기가 도는 것을 고르세요. 가시 다루는 요령과 성게미역국 끓이는 법을 정리했어요.","origin":"제주 등 전 연안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"성게는 가시 돋친 극피동물로, 우리가 먹는 부분은 성게알이라 부르는 노란 생식선입니다. 우리 바다에는 보라성게와 말똥성게가 주로 삽니다. 보라성게는 봄부터 여름, 말똥성게는 겨울부터 봄이 제철이라 계절에 따라 나오는 종이 다릅니다. 해양수산부는 성게를 6월과 7월의 수산물로 골랐습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"바다 향이 진하고 부드럽습니다. 국에 넣으면 국물에 고소한 맛이 뱁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"깐 성게알은 알이 풀어지지 않고 모양이 살아 있는 것을 고르세요."},{"text":"진한 노란색을 띠고 윤기가 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"오래 둘 때는 성게알젓이나 통조림 같은 가공품을 고르세요."},{"label":"손질법","text":"가시에 찔리면 피부가 붓고 아플 수 있으니 껍데기째 다룰 때 조심하세요. 깐 알은 깨끗이 씻어 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"성게미역국. 불린 미역을 살짝 볶아 물을 붓고 끓이다가 성게를 넣고 국간장과 소금으로 간합니다. 담백하게 하려면 참기름을 줄이세요."},{"text":"성게알 비빔밥. 밥 위에 채 썬 오이, 부추, 깻잎을 두르고 가운데 성게알과 달걀노른자를 올려 양념장과 냅니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"보라성게는 몸이 검은 보라색이고 가시가 길어 밤송이처럼 생겼고, 말똥성게는 펑퍼짐하고 가시가 약합니다. 성게알젓, 성게알 통조림, 성게미역국 같은 가공품도 대형마트에서 팝니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 호르몬 ‘성게’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=26539&select_list_no=79","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"6월 어식백세 수산물 ‘참돔·성게’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=12416&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"여름철 보양식 ‘갯장어’와 바다 향 가득한 ‘성게’를 즐겨보자","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=21119&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 요리법 성게알 비빔밥","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0303&cnts_id=9473&select_list_no=67","checkedAt":"2026-11-13"}]},
  "searobin": {"summary":"성대는 1월에 회로 즐기기 좋은 생선이에요. 머리는 단단한 골판이고 등에 날카로운 가시가 있으니 조심해 다루세요. 회와 찌개로 먹는 법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"성대는 성대과의 바다 생선으로, 우리나라 남부와 일본 남부, 동중국해, 대만에 분포합니다. 머리는 단단한 골질판으로 덮여 있고, 크게 발달한 가슴지느러미를 펼치면 푸른빛 날개처럼 보입니다. 가슴지느러미 아래에 따로 떨어진 지느러미 줄기 3개로 바닥을 기어 다니며 먹이를 찾습니다. 주로 저인망이나 자망으로 잡힙니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살에 탄력이 있고 씹는 맛이 좋으며, 맛은 겨울철에 가장 좋습니다. 삶으면 살이 단단해지고 냄새가 없어집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈알이 밝고 투명하며 튀어나와 있고, 아가미가 선홍색이나 분홍색인 것을 고르세요."},{"text":"손가락으로 살짝 눌렀을 때 살이 원래대로 돌아오고, 몸에 점액이 없는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"머리가 단단한 골질판이고 등 가운데를 따라 날카로운 가시가 한 줄 있으니 장갑을 끼고 다루세요. 작은 성대는 머리와 등뼈, 껍질까지 찌개 국물에 함께 넣습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"성대회. 탄력 있는 살을 회로 떠서 먹습니다."},{"text":"성대 찌개. 작은 성대는 머리와 등뼈, 껍질에서 국물이 우러나 찌개에 알맞습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"성대는 다른 생선보다 머리가 단단하고 각져 갑두어라고도 불렸습니다. 우리나라에는 성대 말고도 밑성대, 쌍뿔달재, 가시달갱이 등 성대과 어류 10종류가 분포합니다. 회 말고도 소금구이, 찜, 튀김으로 먹습니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산물이야기 성대 - 춤추는 바다의 공작새","url":"https://www.nifs.go.kr/portal/cmmnAtchFile/getAtchFileGroup.do?atchFileGroupId=PBLC20251204105339231BEAUqQAd&siteId=","checkedAt":"2026-11-13"},{"org":"국립수산과학원","title":"수산생물종 정보 성대","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=9967","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "sebal-namul": {"summary":"세발나물은 12월~이듬해 3월이 제철이에요. 맛을 볼 수 있다면 지나치게 짜지 않고 아삭한 것을 고르세요. 간 맞추는 요령과 오래 두는 보관법을 정리했어요.","origin":"해남·신안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"세발나물은 바닷가나 염전 주변, 간척지 논처럼 소금기 있는 땅에서 자라는 갯나물입니다. 가늘고 뾰족한 잎이 새의 발을 닮아 이런 이름이 붙었습니다. 나물 자체에 소금기가 들어 있어 간을 덜 해도 되므로, 살 때부터 짠 정도를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"한입 씹으면 바다 향이 나고 아삭하게 씹힙니다. 맛은 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"지나치게 짜지 않고 아삭하게 씹히는 것을 고르세요."},{"text":"잎과 뿌리가 잘 붙어 있고 이물질이 섞이지 않았는지 보세요."},{"text":"연녹색이 살아 있고 탄력이 있으며, 자른 밑동과 잎 끝이 시들지 않은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지로 싼 뒤 위생팩에 담아 온도가 낮은 김치냉장고에 넣으면 오래 둘 수 있습니다. 뿌리째 씻어 먹을 만큼 나눠 담아 냉동해도 됩니다."},{"label":"손질법","text":"깨끗이 씻어 살짝 데친 뒤 찬물에 여러 번 헹궈 물기를 짜세요. 소금기가 있으니 양념할 때 소금은 넣지 않거나 적게 넣으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"세발나물 초고추장무침. 데친 세발나물을 초고추장에 무칩니다."},{"text":"세발나물 된장국. 손질한 세발나물을 된장국에 넣어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 해남과 신안을, 생산시기를 12~3월로 적습니다. 바닷가 사람들이 이른 봄에 뜯어 먹던 나물로 소개되며, 나트륨 함량이 비교적 높아 조리할 때 소금을 줄이라고 안내합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘세발나물’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219831&menuNo=300063","checkedAt":"2026-11-12"}]},
  "seomcho": {"summary":"섬초는 11월~이듬해 3월이 제철이에요. 뿌리의 붉은색이 선명하고 잎이 두꺼우며 윤기 나는 것을 고르세요. 냉장 보관법과 데쳐서 냉동하는 법을 정리했어요.","origin":"전남 신안 도초도·비금도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"섬초는 전남 신안 지역에서 품종개량한 시금치를 부르는 이름입니다. 해풍을 맞고 자라 일반 시금치보다 길이가 짧습니다. 장에서는 일반 시금치와 나란히 놓이는 경우가 많으니 산지 표시와 짧은 길이를 보고 구분하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"일반 시금치보다 단맛이 더 납니다. 데치거나 무쳐 먹고, 생으로도 먹을 수 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 두껍고 싱싱하며 표면에 윤기가 도는 것을 고르세요."},{"text":"뿌리의 붉은색이 선명하고 만졌을 때 단단한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"흙먼지를 털어 낸 뒤 신문지나 타월로 감싸 밀봉해 냉장하고, 되도록 빨리 드세요. 먹을 만큼 나눠 데친 뒤 냉동해도 됩니다."},{"label":"손질법","text":"시든 잎을 떼어 내고 씻으세요. 데칠 때 물에 소금을 1% 정도 넣으면 색이 선명해집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"섬초무침. 살짝 데친 섬초를 양념에 무칩니다."},{"text":"섬초국. 손질한 섬초를 국 재료로 넣어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 섬초의 주산지를 신안 도초도와 비금도로, 생산시기를 11~3월로 적습니다. 시금치 자료에서는 포항초, 육지초와 함께 시금치 주요품종으로 섬초를 듭니다. 일반 시금치(11~2월)보다 한 달 더 늦게까지 나옵니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘섬초’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227358&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘시금치’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219817&menuNo=300063","checkedAt":"2026-11-12"}]},
  "seoritae": {"summary":"서리태는 10~11월이 제철이에요. 껍질이 짙고 윤기 나며 안쪽이 밝은 자주색인 것을 고르세요. 수입 검정콩과 구별하는 법, 불리기와 보관법을 정리했어요.","origin":"장단·평창·정선·예천·군위·태안·부여","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"서리태는 생육 기간이 길어 첫서리가 내릴 무렵 수확해 붙은 이름의 검정콩입니다. 10~11월에 거두며, 수입 검정콩과 함께 팔리므로 국산인지 구별하는 방법을 알아 두면 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"당도가 높고 맛이 구수합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질의 검은색이 짙고 선명하며 윤기가 흐르고, 알이 단단하게 영근 것을 고르세요."},{"text":"낟알이 굵고 둥글며 손상된 낟알이 섞이지 않은 것이 좋습니다."},{"text":"국산은 껍질 안쪽이 밝은 자주색이고 배꼽 속 눈이 회색 타원형입니다. 수입산은 껍질 안쪽이 황갈색입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"습기를 잘 흡수해 곰팡이가 생기기 쉬우니 햇볕에 충분히 말려 보관하세요. 용기에 습기가 차지 않았는지 확인하고 바닥에 소금을 뿌려 두면 벌레를 막을 수 있습니다."},{"label":"손질법","text":"물에 5~6시간 충분히 불린 뒤 흐르는 물에 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"콩밥. 불린 서리태를 밥에 넣어 짓습니다."},{"text":"서리태 콩국수. 삶은 콩을 갈아 국물로 씁니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 장단, 평창, 정선, 예천, 군위, 태안, 부여를, 품종으로 흑청콩, 청자, 귀족, 늦서리태 등을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘서리태’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219918&menuNo=300063","checkedAt":"2026-11-12"}]},
  "sesame-seed": {"summary":"참깨는 8~9월이 제철이에요. 색이 맑고 알맹이가 통통하며 껍질 벗겨진 낟알이 거의 없는 것을 고르세요. 깨 씻고 볶는 법과 참기름 보관법을 정리했어요.","origin":"안동·해남·의성·예천·신안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"참깨는 5~7월에 파종해 8~9월에 수확하는 기름작물입니다. 성분의 절반 안팎이 기름이라 참기름을 짜거나 볶아서 깨소금으로 씁니다. 통깨로 살지, 볶은 깨나 참기름으로 살지 먼저 정하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"고소한 향과 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색깔이 맑고 알맹이가 통통한 것을 고르세요."},{"text":"껍질이 벗겨진 낟알이 거의 없고 씨눈이 뾰족한 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"참기름은 입구가 작은 갈색병에 담아 밀봉하고, 온도 변화가 적은 18~22℃의 어둡고 서늘한 곳에 두세요. 실온에 둔 참기름은 6개월 안에 드세요."},{"label":"손질법","text":"깨를 찬물에 담가 흙과 잔돌을 가라앉히고 물 위로 뜬 깨를 걸러 버리기를 세 번쯤 한 뒤, 깨보다 작은 구멍의 망으로 건지세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"볶은 깨. 거른 깨를 센 불에서 물기가 없어질 때까지 볶다가, 불을 줄여 통통하게 부풀 때까지 노릇하게 볶습니다."},{"text":"깨강정. 볶은 깨로 강정을 만듭니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 안동, 해남, 의성, 예천, 신안 등을, 품종으로 안산깨, 고품깨, 검은깨, 강흑깨, 진기깨를 듭니다. 참기름은 볶은 참깨를 압착하는 온압법과 차가운 상태로 짜는 냉압법으로 만듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘참깨’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219923&menuNo=300063","checkedAt":"2026-11-12"}]},
  "shepherds-purse": {"summary":"냉이는 3~4월이 제철이에요. 뿌리가 희고 곧으며 잎이 누렇지 않은 것을 고르세요. 뿌리와 잎 사이 흙을 씻는 법과 데쳐 냉동하는 법, 냉이 된장국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"냉이는 이른 봄에 캐어 잎과 뿌리를 함께 먹는 나물입니다. 뿌리에 향이 있어 된장국을 끓일 때는 뿌리를 잘라 버리기보다 흙이 남은 부분을 골라 씻으세요. 잎이 어리고 뿌리가 연한 것은 짧게 데쳐 나물로 먹기 좋습니다. 손질한 냉이를 한 번에 다 쓰기 어렵다면 국에 한 번 넣을 분량씩 나눠 데쳐 두면 다음에 꺼내 쓰기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잎과 뿌리에서 향긋한 풀 향이 나며 어린 뿌리는 씹는 맛이 연합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"뿌리가 희고 곧은 것을 보세요."},{"text":"자른 단면이 마르지 않았는지 살피세요."},{"text":"잎이 시들거나 누렇게 변한 단은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"흙을 털어 냉장하고, 오래 둘 양은 데쳐 물기를 빼고 소분해 냉동하세요."},{"label":"손질법","text":"누런 잎을 떼고 뿌리와 잎 사이에 낀 흙을 물에서 살살 흔들어 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"냉이 된장국. 국물에 냉이를 넣어 향을 냅니다."},{"text":"냉이무침. 짧게 데쳐 된장에 무칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"어린 뿌리와 잎을 함께 먹을 수 있습니다. 뿌리가 굵은 것은 길이로 갈라 국에 넣으면 익히기 편합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘냉이’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219834","checkedAt":"2026-11-12"},{"org":"농촌진흥청 그린매거진","title":"냉이 손질과 요리","url":"https://www.rda.go.kr/webzine/2022/03/sub4-2.html","checkedAt":"2026-11-12"}]},
  "shiitake-mushroom": {"summary":"표고버섯은 9~10월이 제철이에요. 생표고는 갓이 도톰하고 주름이 젖지 않은 것을 고르세요. 백화고·흑화고 표기와 건표고 불린 물 활용법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"표고버섯은 생것은 구이와 볶음에, 말린 것은 향을 우려내는 국물과 밥에 자주 씁니다. 생표고는 갓 아래의 주름까지 보고 눅눅한 곳이 없는 것을 고르세요. 건표고를 쓸 때는 깨끗이 씻어 불리고, 불린 물을 체에 거르면 밥이나 탕에 감칠맛을 더할 수 있습니다. 갓은 썰어 조리하고 질긴 자루는 국물용으로 따로 모아 두어도 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생표고는 익히면 쫄깃하고, 건표고는 불려 쓰면 향과 감칠맛이 진합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생표고는 갓이 도톰하고 탄탄한 것을 고르세요."},{"text":"주름이 지나치게 젖거나 짓무르지 않았는지 보세요."},{"text":"건표고는 말린 상태가 고르고 곰팡이가 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생것은 종이를 깔아 냉장하고, 오래 둘 것은 썰어 냉동하세요. 건표고는 밀폐해 습기를 피하세요."},{"label":"손질법","text":"갓에 남은 이물질을 털고 질긴 자루를 떼세요. 건표고는 씻어 불려 사용합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"표고구이. 도톰한 갓을 썰어 굽습니다."},{"text":"표고밥. 건표고와 거른 불린 물을 밥에 사용합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"백화고와 흑화고는 건표고에서 갓 표면에 나타나는 상태와 관련한 등급·유통 표기입니다. 생표고의 신선도를 보는 기준과 구분하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘표고버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219906&deleteCd=0&pageIndex=1&selectMonth=9","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"9월 제철 포스터 ‘표고버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000299/view.do?deleteCd=0&menuNo=300106&nttId=234980&pageIndex=1","checkedAt":"2026-11-12"}]},
  "shinbi-peach": {"summary":"신비복숭아는 6~7월이 제철이에요. 흠이 없고 향이 진하며 꼭지 안쪽까지 푸른기가 없는 것을 고르세요. 천도복숭아 보관 온도와 손질 주의점을 정리했어요.","origin":"경북 경산","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"신비복숭아는 껍질에 털이 없는 천도 계통이면서 과육이 흰 조생종 복숭아입니다. 농촌진흥청은 숙기를 6월 하순으로 소개합니다. 농촌진흥청 브리핑에 따르면 국산 육성 품종은 아니며 경산 일부 지역에서 재배됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"신맛이 적고 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질에 흠이 없고 향을 맡았을 때 진한 향이 나는 것을 고르세요."},{"text":"모양이 둥글고 꼭지 안쪽까지 푸른기 없이 익은 색을 띠는 것이 잘 익은 것입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"복숭아는 저온에 약해 천도 계통은 5~8℃가 알맞습니다. 김치냉장고보다 일반 냉장실에 넣고, 실온에서는 쉽게 무르니 빨리 드세요."},{"label":"손질법","text":"복숭아 알레르기가 있으면 손질하거나 먹을 때 주의하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"구운 복숭아. 반으로 갈라 구우면 단맛이 더해집니다."},{"text":"복숭아잼. 물러진 복숭아를 설탕과 함께 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"같은 시기 매장에는 이름이 비슷한 신선복숭아도 나옵니다. 농촌진흥청은 신비처럼 과육이 흰 국산 천도 품종 ‘이노센스’(8월 상순 수확)를 보급했습니다."}]}],"sources":[{"org":"농촌진흥청","title":"보도자료 ‘털 없는 복숭아’ 더 달고 덜 신 새 품종 첫 보급","url":"https://www.rda.go.kr/board/board.do?mode=view&prgId=day_farmprmninfoEntry&dataNo=100000757526","checkedAt":"2026-11-12"},{"org":"대한민국 정책브리핑","title":"복숭아, 국산 품종으로 여름 과일 시장 시선몰이(농촌진흥청 브리핑)","url":"https://korea.kr/news/policyBriefingView.do?newsId=156286938","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘복숭아’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219885&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"보도자료 ‘더 오래 신선하게’ 똑똑한 과일, 채소 보관법","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&prgId=day_farmprmninfoEntry&mode=updateCnt&dataNo=100000790713","checkedAt":"2026-11-12"}]},
  "shine-muscat": {"summary":"샤인머스캣은 8~11월이 제철이에요. 머스캣 향이 뚜렷하고 송이가 지나치게 크지 않은 것을 고르세요. 덜 익은 송이를 피하는 법과 보관 온도를 정리했어요.","origin":"경북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"샤인머스캣은 머스캣 향이 나고 껍질째 먹을 수 있는 청포도 품종입니다. 충남도농업기술원에 따르면 수확은 평년 9월 상순에 시작하고, 추석 무렵 출하가 본격화됩니다. 값이 좋은 이른 시기에 덜 익은 송이가 나와 소비자 실망이 컸다는 농업기술원 지적이 있으니, 이른 물량은 향을 확인하고 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"충분히 익으면 껍질이 얇고 식감이 아삭하며 머스캣 향이 납니다. 충남도농업기술원은 당도 18브릭스 이상일 때 향이 가장 풍부하다고 설명합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"머스캣 향이 뚜렷한 송이를 고르세요. 덜 익은 송이는 향이 약합니다."},{"text":"경북농업기술원은 송이 무게 700g 이하를 품질 기준으로 둡니다. 지나치게 큰 송이는 피하세요."},{"text":"알이 촘촘하게 붙어 있고 들었을 때 알이 후두둑 떨어지지 않는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"농촌진흥청은 포도를 0℃ 안팎에서 보관하라고 권합니다. 일반 냉장실보다 김치냉장고에 두세요."},{"label":"손질법","text":"송이째 물에 1분 정도 담갔다가 흐르는 물에 꼼꼼히 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"청포도 화채. 알을 떼어 다른 여름 과일과 함께 시원하게 띄웁니다."},{"text":"포도 주스. 물러지려는 알을 냉동해 두었다가 갈아 마십니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"경북의 샤인머스캣 재배면적은 4,770ha로 도내 포도 면적의 62%입니다(2025년 경북농업기술원 자료). 농업기술원은 꽃이 핀 뒤 최소 120일, 당도 18브릭스 이상을 출하 기준으로 제시합니다."}]}],"sources":[{"org":"농촌진흥청","title":"농촌지방소식 ‘수확기 빨라진 샤인머스켓 품질관리 주의’(충청남도농업기술원)","url":"https://www.rda.go.kr/board/board.do?mode=view&prgId=day_farmlcltinfoEntry&dataNo=100000773321","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"농촌지방소식 ‘추석용 샤인머스켓 출하 시작’(경상북도농업기술원)","url":"https://rda.go.kr/board/board.do?mode=view&prgId=day_farmlcltinfoEntry&dataNo=100000805287","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘포도’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219905&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"보도자료 ‘더 오래 신선하게’ 똑똑한 과일, 채소 보관법","url":"https://www.rda.go.kr/board/board.do?boardId=farmprmninfo&prgId=day_farmprmninfoEntry&mode=updateCnt&dataNo=100000790713","checkedAt":"2026-11-12"}]},
  "shishito-pepper": {"summary":"꽈리고추는 7~8월이 제철이에요. 주름 사이에 윤기가 돌고 꼭지가 마르지 않은 것을 고르세요. 구멍 내어 양념 배게 하는 법과 멸치볶음, 장조림을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"꽈리고추는 표면이 주름지고 과피가 얇은 고추로 여름에 볶음과 조림 반찬에 자주 씁니다. 통째로 넣으면 국물과 어울리고, 길이가 긴 것은 먹기 좋은 길이로 잘라 볶기 편합니다. 한 봉지에서도 매운 정도가 다를 수 있으니 매운맛을 조절해야 하는 요리에는 손질할 때 조금 잘라 확인하세요. 풋향을 살리려면 멸치가 익은 뒤 고추를 넣습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"풋고추 향이 나고 익히면 껍질이 부드러워집니다. 매운 정도는 알마다 다를 수 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"주름 사이에 윤기가 도는 초록색 고추를 고르세요."},{"text":"꼭지가 마르거나 검게 변하지 않았는지 보세요."},{"text":"볶음용은 길이와 굵기가 고른 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기를 닦아 냉장하세요. 조림용은 꼭지를 떼고 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"흐르는 물에 씻어 꼭지를 떼고, 통째로 조릴 것은 구멍을 내 양념이 스며들게 합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"꽈리고추 멸치볶음. 멸치를 볶은 뒤 고추를 넣어 짧게 익힙니다."},{"text":"꽈리고추 장조림. 고기나 달걀이 익은 뒤 넣어 함께 조립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"표면의 주름은 꽈리고추의 특징입니다. 생기를 보려면 주름만 보지 말고 꼭지와 전체의 탄력을 살피세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘꽈리고추’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219857&deleteCd=0&pageIndex=1&selectMonth=7","checkedAt":"2026-11-12"}]},
  "shrimp": {"summary":"대하는 9~10월이 제철이에요. 이마뿔과 수염이 길고 꼬리가 초록빛이면 대하, 짧으면 흰다리새우예요. 고르는 법과 손질·보관법을 정리했어요.","origin":"서해안(홍성 남당항, 태안 백사장항)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"대하는 몸집이 큰 새우로, 우리나라에서는 서해안에 주로 삽니다. 살이 오르는 9~10월에 육질이 부드럽고 쫄깃해 이 무렵 산지에서 축제가 열립니다. 양식 흰다리새우와 생김새가 비슷해 섞여 팔리기 쉬우니 이마뿔, 수염, 꼬리 색으로 구분하세요. 성질이 급해 잡히면 금방 죽으므로 살아 있는 대하는 보기 어렵습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"육질이 부드럽고 쫄깃하며, 회로 먹으면 달콤한 감칠맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸이 투명하고 윤기가 나며 껍질이 단단한 것을 고르세요."},{"text":"껍질 가장자리가 검게 변했거나 검은 점이 있으면 신선도가 떨어진 것입니다."},{"text":"이마뿔이 코끝보다 길고 수염이 몸통보다 길며 꼬리가 초록빛이면 대하입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"새지 않는 봉투나 뚜껑 있는 용기에 담아 냉장하고 2~3일 안에 드세요. 시중 새우는 대부분 한 번 얼렸던 것이라 집에서 다시 얼리면 향과 식감이 달라질 수 있습니다."},{"label":"손질법","text":"뿔과 수염을 가위로 자르고, 첫째와 둘째 마디 사이에 이쑤시개를 넣어 내장을 당겨 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"대하 소금구이. 소금 위에 대하를 올려 굽습니다."},{"text":"대하 머리 버터구이. 먹고 남은 머리를 버터에 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"대하는 1년생으로 깊은 바다에 살다가 산란기에 연안으로 옵니다. 홍성 남당항과 태안 백사장항이 산지로 알려져 이르면 10월부터 겨울까지 찾는 사람이 많습니다. 수입 흰다리새우는 대하보다 이마뿔과 수염이 짧고 몸이 덜 날씬합니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"지금이 제철, 대하","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=13440","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"9월 이달의 수산물 ‘대하, 전어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=35570","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"10월 이달의 수산물 ‘삼치, 대하’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34130","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "silverberry": {"summary":"보리수열매는 6월 한 달이 제철이에요. 반점 없이 선명한 붉은빛을 띠는 열매를 고르세요. 짧은 제철에 맞춘 세척·보관법과 담금 활용을 정리했어요.","origin":"강원·충남·경기·경남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"보리수열매는 6월에 잠깐 나오는 작은 붉은 열매입니다. 산수유보다 조금 길고 크며, 예전부터 술이나 절임으로 즐겨 먹었습니다. 제철이 짧아 보이면 그때 사 두는 것이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"씹으면 젤리처럼 말캉한 식감이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"반점이 없고 선명한 붉은빛을 띠는 열매를 고르세요."},{"text":"물러서 즙이 새는 열매가 섞이지 않았는지 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀봉해서 냉장하세요."},{"label":"손질법","text":"먹기 직전에 흐르는 물에 깨끗이 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"보리수청. 씻어 물기를 뺀 열매를 설탕에 재웁니다."},{"text":"보리수잼. 씨를 걸러 낸 과육을 설탕과 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 강원, 충남, 경기, 경남 일대를 들고, 생산시기를 6월로 적습니다. 별도 품종 정보는 없습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘보리수열매’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227343&menuNo=300063","checkedAt":"2026-11-12"}]},
  "sixbar-sandperch": {"summary":"쌍동가리(도토래미)는 5~9월에 회로 즐기기 좋은 생선이에요. 몸이 원통형으로 길고 눈이 머리 등 쪽에 붙어 있어요. 생김새와 고르는 법을 정리했어요.","origin":"남해안·제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"쌍동가리는 통영 등에서 도토래미라고도 부르는 양동미리과의 바다 생선으로, 우리나라와 일본, 동중국해, 대만에 분포합니다. 몸이 원통형으로 길고 체고가 낮으며, 머리 등 쪽이 납작하고 눈은 약간 튀어나와 등 쪽에 있습니다. 이름이 비슷한 열쌍동가리는 같은 과의 다른 종입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"양턱 길이가 거의 같고, 등지느러미는 가시 부분과 부드러운 줄기 부분이 끊김 없이 이어지며 다섯째 가시가 가장 깁니다."},{"text":"눈알이 밝고 투명하며 튀어나와 있고, 아가미가 선홍색이나 분홍색인 것을 고르세요."},{"text":"손가락으로 살짝 눌렀을 때 살이 원래대로 돌아오고, 몸에 점액이 없는 것이 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"집에 오면 바로 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"포장되지 않은 생선은 흐르는 찬물에 씻고 종이타월로 물기를 닦은 뒤 랩으로 싸서 조리 전까지 냉장합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"쌍동가리회. 이 달력에서 5월 회로 소개하는 생선입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"쌍동가리는 2~6월과 10~11월 두 차례 산란하며, 몸길이 13cm 이상이면 대부분 산란에 참여합니다."}]}],"sources":[{"org":"국립수산과학원","title":"수산생물종 정보 쌍동가리","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11237","checkedAt":"2026-11-13"},{"org":"국립수산과학원","title":"수산생물종 정보 열쌍동가리","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11235","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "skate": {"summary":"홍어는 12월~이듬해 4월이 제철이에요. 살을 눌러 봐서 단단한 것을 고르고, 가오리와는 가슴지느러미의 검은 테 반점으로 구별하세요. 손질법과 삼합을 정리했어요.","origin":"흑산도 등 서해·남해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"홍어(표준명 참홍어)는 마름모꼴의 넓은 몸을 가진 가오리 무리 생선으로, 흑산도 연안 홍어를 가장 귀하게 칩니다. 산란기인 겨울에서 이른 봄까지가 제철입니다. 암컷이 수컷보다 크고 맛이 좋아 값도 비쌉니다. 생김새가 비슷한 가오리류가 많아 많이 다뤄 본 사람이 아니면 구별이 어렵습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쫄깃한 식감에 알싸한 향이 있습니다. 큰 것은 삭혀서 톡 쏘는 맛을 즐깁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"살을 눌러 보아 단단한 것을 고르세요."},{"text":"가슴지느러미 밑동 양쪽에 검은 테를 두른 큰 반점이 하나씩 있으면 홍어입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"사 온 홍어는 껍질을 벗기지 말고 물기를 거즈로 닦아 둡니다."},{"label":"손질법","text":"내장을 떼고 코와 꼬리 부분을 자른 뒤 양쪽 날개를 갈라 손질합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"홍어삼합. 홍어회에 묵은지와 돼지고기 수육을 곁들입니다."},{"text":"홍어회무침. 납작하게 썬 홍어와 절인 무, 미나리를 초고추장 양념에 버무립니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"흑산 홍어잡이 어업은 2021년 국가중요어업유산으로 지정됐습니다. 이른 봄에는 보리싹과 홍어 내장으로 홍어앳국을 끓이기도 합니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 전라도 잔칫상에 빠지지 않는 ‘홍어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32453&select_list_no=55","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 4월 수산물 ‘가자미’, ‘홍어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38820&select_list_no=7","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"3월 어식백세 수산물 ‘홍어·가오리·주꾸미’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=11177&menuSeq=971","checkedAt":"2026-11-12"}]},
  "snailfish": {"summary":"물메기는 12월~이듬해 2월이 제철이에요. 손질 토막은 단면이 마르지 않고 껍질이 깨끗한 것을 고르세요. 무를 먼저 끓이는 물메기탕과 물메기 떡국을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"물메기는 겨울에 맑은탕으로 끓여 먹는 바닷물고기입니다. 익으면 살이 쉽게 풀어지므로 무와 대파를 먼저 끓이고 생선을 넣은 뒤에는 젓는 횟수를 줄이세요. 부산시보는 물메기탕에서 부드러운 속살과 씹는 맛이 있는 껍질을 함께 즐긴다고 소개합니다. 곰치나 물곰으로 부르는 지역도 있어 사기 전에 판매처에서 실제 어종을 확인하는 편이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"국물 맛은 담백하고 살은 부드럽습니다. 익힌 껍질은 살보다 꼬들합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"단면이 말라 색이 변하지 않았는지 보세요."},{"text":"껍질이 심하게 찢어지지 않은 것을 고르세요."},{"text":"포장에 액체가 새는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"냉장해 구입 당일 조리하는 편이 좋습니다. 남는 양은 손질해 냉동하세요."},{"label":"손질법","text":"아가미와 내장을 손질한 토막을 구입해 껍질의 이물질을 확인하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"물메기탕. 무를 먼저 익힌 뒤 생선을 넣어 끓입니다."},{"text":"물메기 떡국. 살을 부서뜨리지 않도록 마지막에 넣어 익힙니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"물메기는 바다에서 사는 꼼치과 생선입니다. 지역 유통명은 꼼치류의 다른 어종과도 겹칠 수 있으니 표시를 확인하세요."}]}],"sources":[{"org":"부산광역시 부산시보","title":"제철 맞은 물메기, 못생겨도 맛은 일품","url":"https://www.busan.go.kr/news/snsbusan04/view?dataNo=43335","checkedAt":"2026-11-12"},{"org":"국립식량과학원","title":"설 명절 떡국 자료","url":"https://www.nics.go.kr/bbs/view.do?bbsId=news&bbsSn=13777&homepageSeCode=nics&m=100000020","checkedAt":"2026-11-12"}]},
  "snow-crab": {"summary":"대게는 12월~이듬해 5월이 제철이에요. 생김새가 비슷한 홍게와 헷갈리기 쉬우니 색과 껍질을 보고 구분하세요. 찌는 요령과 원산지 확인법을 정리했어요.","origin":"울진·영덕 등 경북 동해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"대게는 몸통에서 뻗은 다리가 대나무 마디처럼 곧아 붙은 이름으로, 동해 깊은 바다에서 잡힙니다. 겨울에서 봄으로 넘어가는 12~3월에 살이 가장 많이 찹니다. 영덕대게가 유명하지만 주 서식지는 울진 근해입니다. 홍게(붉은대게)와 생김새가 비슷하고 값이 다르니 살 때 구분하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"양념 없이 찌거나 삶기만 해도 살이 부드럽고 단맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"홍게는 대게보다 작고 껍질이 단단하며, 날것일 때부터 등딱지와 다리, 배 전체가 진한 주홍빛이니 색으로 구분하세요."},{"text":"살아 있는 게는 다리가 움직이는지 확인하세요."},{"text":"암컷 대게는 연중 포획이 금지되어 있으니 수컷인지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"살아 있는 게는 산 날 조리하세요. 익힌 게는 밀폐용기에 넣어 냉장하고 2~3일 안에 드세요."},{"label":"손질법","text":"찌기 전에 얼음물에 잠시 담가 두면 게가 움직여 다리가 떨어지거나 게장이 쏟아지는 것을 막을 수 있습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"대게찜. 통째로 쪄서 다리와 몸통 살을 발라 먹습니다."},{"text":"대게 딱지밥. 살을 먹고 남은 등딱지에 밥과 김, 참기름을 넣어 비빕니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"대게는 자원 보호를 위해 연중 암컷 포획이 금지되고, 수컷도 갑폭 9cm 미만은 잡을 수 없습니다. 홍게는 비교적 흔히 잡혀 같은 크기라도 더 싸게 팔리고 게맛살, 게장 같은 가공품 재료로도 쓰입니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"진정한 겨울별미, 대게","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=8530","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"12월 이달의 수산물 ‘대게류, 대구’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38077","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"2월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=55289&menuSeq=971","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"다양한 수산물의 올바른 구입 방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16950","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "sorghum": {"summary":"수수는 9~10월이 제철이에요. 낟알이 둥글고 붉은 속껍질이 남아 있으며 곰팡이가 없는 것을 고르세요. 국산 구별법과 습기 막는 보관법을 정리했어요.","origin":"강원·경기","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"수수는 쌀, 밀, 옥수수에 이어 중요한 곡물로 꼽히지만 지금은 주로 잡곡으로 먹습니다. 도정한 수수는 관리가 소홀하면 곰팡이가 생기거나 품질이 변하기 쉬우니 사기 전에 꼼꼼히 보세요. 돌이나 생일에 먹는 수수팥떡의 재료이기도 합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"쌀과 섞어 잡곡밥으로 먹거나 떡을 만들어 먹습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"국산은 중국산보다 낟알이 둥근 편이고 반투명한 낟알이 거의 없으며 붉은 속껍질이 남아 있습니다."},{"text":"곰팡이가 피었거나 변질된 곳이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀봉해 서늘하고 건조한 곳에 두세요. 습도 50% 이하에서 보관하면 더 오래 갑니다."},{"label":"손질법","text":"흐르는 물에 씻어 돌 같은 이물질을 골라내고 채반에 받쳐 물기를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"수수팥떡. 돌이나 생일에 만들어 먹는 떡입니다."},{"text":"잡곡밥. 쌀과 섞어 짓고, 콩을 함께 넣기도 합니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 강원도와 경기도, 품종으로 단간종, 중간종, 장간종을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘수수’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219964&menuNo=300063","checkedAt":"2026-11-12"}]},
  "soybean": {"summary":"대두는 10월이 제철이에요. 알이 둥글고 벌레 구멍이나 검게 상한 알이 없는 것을 고르세요. 마른 콩 불리는 법과 삶은 콩 냉동, 콩국수를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"대두는 메주, 두부, 두유를 만들거나 밥에 섞어 먹는 콩입니다. 가을에 거둔 햇콩을 사거나 말린 제품을 구입할 수 있고, 가공할 때는 콩의 크기가 고르면 불리고 익히기가 편합니다. 콩국을 만들 때는 불린 대두를 삶아 물을 조금씩 넣어 갈고, 밥에 넣을 때는 콩과 쌀의 익는 속도가 다르므로 콩을 먼저 불려 준비하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"익히면 고소하고 속이 부드러우며 갈면 걸쭉합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 둥글고 크기가 고른 것을 보세요."},{"text":"벌레 구멍과 검게 상한 알이 없는지 확인하세요."},{"text":"포장에 적힌 원산지와 가공 여부를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"마른 콩은 밀폐해 서늘하고 건조한 곳에 두세요. 삶은 콩은 식혀 소분 냉동할 수 있습니다."},{"label":"손질법","text":"돌과 깨진 알을 골라 씻고 물에 불린 뒤 충분히 익히세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"콩국수. 삶은 콩을 갈아 국물을 만듭니다."},{"text":"대두밥. 불린 콩을 쌀과 함께 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"10월은 정보누리의 생산기입니다. 대두는 말린 알과 가공품이 연중 유통되므로 제품별 원산지 표시를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘대두’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219950&deleteCd=0&pageIndex=1&selectMonth=10","checkedAt":"2026-11-12"}]},
  "soybean-leaf": {"summary":"콩잎은 9~10월이 제철이에요. 잎이 크지 않고 색이 고우며 꼭지까지 부드러운 어린잎을 고르세요. 경상도식 콩잎물김치와 장아찌 담그는 법을 정리했어요.","origin":"경남","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"콩잎은 예전부터 장아찌(절임)나 쌈으로 먹어 온 잎채소입니다. 주산지는 경상남도이며, 그곳에서는 콩잎김치와 콩잎장아찌로 많이 담급니다. 연한 어린잎이 질기지 않아 먹기 좋으니 잎 크기와 연한 정도를 먼저 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"연한 어린잎은 질기지 않고 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 크지 않고 색이 선명하며 만졌을 때 부드러운 어린잎을 고르세요."},{"text":"꼭지를 만져 억세지 않은지 확인하세요."},{"text":"벌레 먹거나 찢어진 것, 붉은 반점이나 검은 얼룩이 있고 냄새가 이상한 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비닐봉지에 담아 냉장하고, 오래 두려면 절이거나 장아찌로 담그세요."},{"label":"손질법","text":"줄기째 딴 것은 줄기를 떼고 연한 잎만 씻어 차곡차곡 개어 물기를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"콩잎물김치. 밀가루 푼 물을 끓여 식혀 소금 간을 하고, 20장씩 묶은 콩잎에 마늘, 생강, 풋고추, 붉은 고추를 넣어 담급니다."},{"text":"콩잎쌈. 콩잎을 밥 위에 쪄서 된장, 간장을 곁들여 쌈으로 먹습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 경상남도를, 주요품종으로 청엽 1호, 대원, 대풍, 황금, 서리태를 듭니다. 단풍 든 콩잎은 말려 두었다가 겨울에 생선과 지지거나 나물로 무쳐 먹습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘콩잎’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219936&menuNo=300063","checkedAt":"2026-11-12"}]},
  "spanish-mackerel": {"summary":"삼치는 10월~이듬해 3월이 제철이에요. 눈동자가 선명하고 꼬리가 마르지 않았으며 윤기 도는 것을 고르세요. 쉽게 무르는 삼치 다루는 법과 조림을 정리했어요.","origin":"서해·남해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"삼치는 고등어과의 등푸른 생선으로 몸길이가 1m까지 자랍니다. 계절에 따라 지방 함량이 크게 달라져 지방이 쌓이는 겨울과 봄에 맛이 가장 좋습니다. 우리나라 서해와 남해에 살며, 여름에는 얕은 곳, 겨울에는 깊은 곳으로 옮겨 삽니다. 살이 무르고 상하기 쉬우니 먹을 날짜에 맞춰 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 부드럽고 비린내가 적으며 담백하고 고소합니다. 껍질과 살 사이의 향이 좋아 회는 껍질째 뜹니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈동자가 선명하고 꼬리가 마르지 않은 것을 고르세요."},{"text":"몸통을 눌렀을 때 탄력이 있고 윤기가 흐르는 것이 좋습니다."},{"text":"크기가 클수록 맛이 좋다고 알려져 있습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"살이 쉽게 무르고 다른 생선보다 빨리 상하니 사 온 뒤 되도록 빨리 드세요."},{"label":"손질법","text":"3~4토막으로 잘라 소금을 뿌린 뒤 물기를 닦아 조리합니다. 살이 연해 회를 뜰 때는 살짝 얼린 뒤 뜨기도 합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"삼치무조림. 납작하게 썬 무 위에 삼치 토막을 얹고 간장 양념으로 국물을 끼얹으며 조립니다."},{"text":"삼치구이. 소금을 살짝 뿌려 노릇하게 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"해양수산부는 삼치를 2월, 10월, 11월의 수산물로 여러 차례 골랐습니다. 4~5월에 내만으로 몰려와 산란하므로 봄 늦게부터는 지방이 빠집니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 최고의 생선 삼치","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=19173&select_list_no=108","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 11월 수산물 ‘삼치’, ‘홍가리비’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=37914&select_list_no=12","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"11월엔 제철 맞은 ‘삼치’와 ‘해만가리비’ 맛보세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=23748&menuSeq=971","checkedAt":"2026-11-12"}]},
  "spinach": {"summary":"시금치는 11월~이듬해 2월이 제철이에요. 나물용은 짧고 통통한 것, 국용은 줄기가 연하고 긴 것을 고르세요. 용도별 고르는 법과 세워 두는 보관법을 정리했어요.","origin":"전남 신안·경남 남해·경북 포항·경기 포천","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"시금치는 사계절 재배되지만 서늘한 기후에 잘 맞아 겨울에 많이 나옵니다. 장에서는 포항초, 섬초처럼 산지 이름이 붙은 시금치도 함께 팔립니다. 쌈·샐러드, 나물, 국 가운데 어디에 쓸지 정하고 고르면 알맞은 것을 사기 쉽습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생으로도 먹지만 쓴맛을 내는 수산이 있어, 데쳐서 조리하면 단맛을 살릴 수 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"길이가 짧고 잎이 선명한 녹색에 윤기가 흐르며, 뿌리의 붉은빛이 선명하고 굵은 것을 고르세요."},{"text":"잎이 흐트러졌거나 마른 것, 황갈색 잎이 섞인 것은 피하세요."},{"text":"쌈·샐러드용은 잎이 뾰족하게 각이 선 것, 나물용은 짧고 통통한 것, 국용은 줄기가 연하고 긴 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바로 먹지 않을 때는 흙이 묻은 그대로 종이나 키친타월에 싸서 냉장고 채소칸에 세워 두세요. 오래 두지 말고 빨리 조리하세요."},{"label":"손질법","text":"데칠 때 물에 소금을 1% 정도 넣으면 색이 선명해집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"시금치나물. 소금을 조금 넣은 물에 데쳐 양념에 무칩니다."},{"text":"시금치 샐러드. 잎이 뾰족한 시금치를 생으로 샐러드에 넣습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 포항초, 섬초, 육지초를, 주산지로 전남 신안, 경남 남해, 경북 포항, 경기 포천을 듭니다. 섬초는 신안에서 나는 시금치로 따로 이름을 달고 팔리며, 생산시기가 3월까지로 조금 더 깁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘시금치’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219817&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘섬초’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227358&menuNo=300063","checkedAt":"2026-11-12"}]},
  "spring-flounder": {"summary":"봄 도다리는 3~4월이 제철이에요. 정면에서 봐서 눈이 오른쪽에 있으면 도다리, 왼쪽이면 광어예요. 고르는 법과 도다리쑥국 끓이는 법을 정리했어요.","origin":"거제·통영 등 남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"도다리는 남해안 일대에서 3~4월에 많이 잡히는 가자미과 생선입니다. 광어는 양식으로 사철 나오지만 도다리는 자라는 데 3~4년이 걸려 양식을 많이 하지 않아 봄에 찾아 먹는 생선입니다. 가을~겨울 산란을 마친 지 얼마 안 된 봄 도다리는 살이 무른 편이라 회보다 쑥국으로 많이 먹습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"흰살 생선으로 지방이 적어 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸에 윤기와 탄력이 있고 비늘이 단단하며 냄새가 나지 않는 것을 고르세요."},{"text":"몸 전체에 흑색 반점이 있는 것이 좋습니다."},{"text":"정면에서 볼 때 눈이 오른쪽에 있으면 도다리, 왼쪽에 있으면 광어입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 뒤 밀폐해 냉동하면 오래 둘 수 있습니다."},{"label":"손질법","text":"단단한 비늘을 꼬리에서 머리 쪽으로 긁어내고 내장을 뺀 뒤 지느러미를 자르세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"도다리쑥국. 쌀뜨물에 무와 도다리를 끓이다 햇쑥을 넣고 양념을 약하게 합니다."},{"text":"도다리 세꼬시회. 뼈째 썬 회를 막장에 찍어 상추에 싸 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"가자미와 도다리는 학술적으로 구별되지만 가자미를 도다리로 통칭하는 경우가 많습니다. 해양수산부는 3월 이달의 수산물로 도다리를 선정했습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"단백질이 풍부한 봄 대표 생선 ‘도다리’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=17689","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"3월 이달의 수산물 ‘도다리, 멍게’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38629","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"3월의 수산물, 어촌여행지, 해양생물, 등대, 무인도서 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=65442&menuSeq=971","checkedAt":"2026-11-13"}]},
  "squid": {"summary":"오징어는 8월이 제철이에요. 통오징어는 눈이 맑고 몸통이 찢어지지 않은 것을 고르세요. 몸통 안 투명한 지지대를 빼는 손질법과 오징어볶음을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"오징어는 몸통과 다리를 함께 먹는 수산물로 볶음과 찜에 자주 씁니다. 해양수산부는 8월 이달의 수산물로 오징어를 선정했으며, 가을 수산대전에서도 오징어를 소개했습니다. 살 때는 생물인지 냉동인지 구분해 필요한 양을 고르세요. 통으로 산 경우에는 몸통 안쪽의 투명한 지지대와 내장을 빼고, 다리는 빨판에 이물질이 남지 않게 씻습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"몸통은 익히면 탄력 있고, 다리는 더 쫄깃하며 감칠맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"몸통이 흐물거리거나 마르지 않은 것을 고르세요."},{"text":"통오징어는 눈이 맑고 몸통이 찢어지지 않았는지 보세요."},{"text":"냉동 제품은 포장 파손과 원산지 표시를 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생물은 냉장해 빨리 쓰고, 남는 양은 손질해 냉동하세요."},{"label":"손질법","text":"내장과 몸통 안쪽의 투명한 지지대를 빼고, 다리 쪽의 눈과 입을 떼어 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"오징어볶음. 두께를 맞춰 썬 뒤 채소와 볶습니다."},{"text":"오징어해물찜. 손질해 충분히 익힌 다음 양념합니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"오징어는 생물·냉동·건조 제품이 있습니다. 시중 공급량은 어획분 외에 냉동 비축 방출에도 영향을 받을 수 있습니다."}]}],"sources":[{"org":"해양수산부","title":"8월 이달의 수산물 ‘미꾸라지·오징어’","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=2119&menuSeq=971","checkedAt":"2026-11-12"},{"org":"전북특별자치도 음식문화플라자","title":"오징어해물찜","url":"https://www.jbfood.go.kr/ai/recipe/tbf_news-279.html","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"수산물 수급 설명자료","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=11&docSeq=58918&menuSeq=972","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"수산대전 가을특별전","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=32033&select_list_no=25","checkedAt":"2026-11-12"}]},
  "stone-flounder": {"summary":"돌가자미는 10월에 회로 즐기기 좋은 생선이에요. 비늘 없이 매끈하고 눈 있는 쪽에 돌기가 줄지어 있어 구별하기 쉬워요. 고르는 법과 손질법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"돌가자미는 우리나라 전 연안에 사는 가자미류로, 눈이 몸 오른쪽에 있습니다. 비늘이 없어 피부가 매끈하고, 다 자라면 눈 있는 쪽 옆줄 위아래와 등·배 가운데에 골질 돌기가 줄지어 납니다. 눈 있는 쪽은 황갈색이나 녹색 바탕에 흰 둥근 반점이 많고, 눈 없는 쪽은 흰색입니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"가자미류는 살이 쫄깃하고 단단해 씹는 감촉이 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈 없는 쪽 배가 하얗고 탄력 있는 것을 고르세요."},{"text":"비늘 대신 골질 돌기가 줄지어 있는지 보고 판매 이름과 함께 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 얼음 위에 올려 포장한 뒤 냉장고의 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"가자미를 단단히 잡고 칼끝을 세워 꼬리 쪽부터 내장을 긁어내되, 내장이 터지지 않게 하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"돌가자미회. 손질한 살을 떠서 회로 먹습니다."},{"text":"돌가자미구이. 가자미류는 회 말고도 구이나 찜으로 조리합니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"돌가자미의 산란기는 12~3월로, 연안의 얕은 바다에서 알을 낳습니다. 서해에서는 여름에 백령도 북쪽에 머물다 가을에 남쪽으로 내려가 겨울을 나고, 봄에 다시 올라갑니다. 경상북도 수산자원연구원은 동해안 가자미 자원을 늘리려고 돌가자미 종자를 생산하고 있습니다."}]}],"sources":[{"org":"국립수산과학원","title":"e-연구바다 생물종 정보 돌가자미","url":"https://www.nifs.go.kr/portal/bt/frctA/actionSpeciesSearchView.do?taxonId=11357","checkedAt":"2026-11-13"},{"org":"경상북도 수산자원연구원","title":"돌가자미 종자생산","url":"https://www.gb.go.kr/Main/finace/page.do?mnu_uid=15825&LARGE_CODE=1100&MEDIUM_CODE=20&SMALL_CODE=30&SMALL_CODE2=30&SMALL_CODE3=60","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"9월 이달의 수산물 ‘가자미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32809","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "strawberry": {"summary":"딸기는 12월~이듬해 5월이 제철이에요. 꼭지가 초록색이고 꼭지 주변까지 붉게 익은 것을 고르세요. 씻지 않고 냉장하는 요령과 딸기잼을 정리했어요.","origin":"진주·밀양·논산","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"딸기는 늦봄에 주로 먹던 과일이지만 시설에서 재배하면서 겨울부터 봄까지 장에서 쉽게 볼 수 있게 됐습니다. 빨갛게 익은 과실은 그대로 먹거나 요거트에 곁들이기 좋습니다. 한 팩을 살 때는 위쪽에 놓인 알의 색과 꼭지를 살피고, 바닥에 과즙이 고였는지도 확인하세요. 과육이 부드러워 다른 장바구니 물건에 눌리면 쉽게 물러집니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"달콤한 향에 산미가 섞이고, 과육이 부드럽고 즙이 많습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"꼭지가 초록색이고 시들지 않았는지 보세요."},{"text":"꼭지 주변까지 붉게 익은 과실을 고르세요."},{"text":"팩 바닥에 과즙이 고이거나 눌린 알이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻지 않은 상태로 눌리지 않게 냉장하세요. 오래 두려면 씻고 물기를 닦아 꼭지를 뗀 뒤 낱알로 얼립니다."},{"label":"손질법","text":"먹기 직전에 꼭지를 붙인 채로 흐르는 물에 씻고 꼭지를 떼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"딸기 요거트. 큼직하게 썰어 플레인 요거트에 얹습니다."},{"text":"딸기잼. 잘 익은 딸기를 잘라 설탕과 함께 졸입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"경북농업기술원은 싼타가 10월 말부터 수확 가능한 조기 품종이라고 소개합니다. 경남농업기술원은 수출용 금실에서 착색이 너무 적을 때 수확하면 당도와 색이 떨어진다고 설명합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘딸기’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219823","checkedAt":"2026-11-12"},{"org":"경북농업기술원","title":"상큼 달달 ‘싼타’ 딸기 경북에서 첫 출하","url":"https://www.rda.go.kr/board/board.do?boardId=farmlcltinfo&dataNo=100000759630&mode=updateCnt&prgId=day_farmlcltinfoEntry","checkedAt":"2026-11-12"},{"org":"경남농업기술원","title":"딸기 수출, 품질과 저장성 하나도 놓치지 않는다","url":"https://www.rda.go.kr/board/board.do?boardId=farmlcltinfo&dataNo=100000802488&mode=updateCnt&prgId=day_farmlcltinfoEntry","checkedAt":"2026-11-12"}]},
  "stringy-stonecrop": {"summary":"돌나물은 3~4월이 제철이에요. 사 두면 줄기가 계속 자라 모양이 흐트러지니 먹을 만큼만 사세요. 짓무르지 않게 씻는 법과 물김치를 정리했어요.","origin":"남양주·이천·안동·진안·인제","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"돌나물은 3~4월에 나오는 봄나물로, 연한 순과 어린잎을 주로 날로 먹습니다. 잎이 매우 연해 쉽게 짓무르고, 사 둔 뒤에도 줄기가 계속 자라 모양이 흐트러집니다. 그래서 한 번에 먹을 양만 사는 것이 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"수분이 많아 아삭하고 새콤한 신맛이 있습니다. 데치기보다 날로 먹을 때 맛이 산뜻합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"마디 사이가 짧고 잎이 통통하며 윤기가 나는 것을 고르세요."},{"text":"잎이 상하거나 전체가 무른 것, 잡티가 섞인 것은 피하세요."},{"text":"잎이 짓눌렸거나 색이 흐리고 꽃이 핀 것은 신선도가 떨어집니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밀폐용기에 키친타월을 깔고 담아 냉장하세요."},{"label":"손질법","text":"흐르는 물에 가볍게 씻고 바구니에 밭쳐 물기를 빼세요. 씻은 뒤 오래 두면 짓무르고, 오래 주무르면 풋내가 나니 살짝 무쳐 바로 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"돌나물 물김치. 돌미나리나 오이와 함께 담급니다."},{"text":"돌나물 초무침. 씻은 돌나물에 초고추장을 얹어 냅니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"양지바른 돌 사이에서 잘 자라 돌나물이라고 불립니다. 샐러드, 비빔밥 고명, 비빔국수 같은 날것 요리에 많이 씁니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘돌나물’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219826&menuNo=300063","checkedAt":"2026-11-12"}]},
  "summer-orange": {"summary":"하귤은 4~5월이 제철이에요. 크고 색이 진하며 껍질에 탄력과 윤기가 있는 것을 고르세요. 두꺼운 껍질 벗기는 법과 상온·냉장 보관법을 정리했어요.","origin":"제주시·서귀포시","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"하귤은 제주에서 나는 여름귤로, 하밀감·나쓰미깡·제주자몽이라고도 부릅니다. 하우스에서 재배한 귤을 줄여 하귤이라 부르기도 하지만 이 하귤과는 다른 품종이니 이름만 보고 헷갈리지 마세요. 껍질이 두꺼워 일반 귤처럼 손으로 까기 어렵습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"새콤하면서 쌉싸래합니다. 흰 속껍질은 쓴맛이 강합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"크기가 크고 색이 진한 것을 고르세요."},{"text":"표면에 탄력과 윤기가 있고 꼭지가 시들지 않았으며 들었을 때 무게감이 있는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"그늘진 상온에서 1주일 정도 두고, 씻어서 냉장하면 몇 주간 둘 수 있습니다."},{"label":"손질법","text":"먼지가 많으니 하룻밤 물에 불려 씻으세요. 칼로 반을 자르고 돌려 가며 칼집을 넣어 껍질을 벗기고, 쓴맛을 줄이려면 흰 속껍질도 떼어 내세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"하귤 주스. 알맹이를 얼음과 함께 곱게 갑니다."},{"text":"하귤청. 청을 담가 차로 마십니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 아마나스를 듭니다. 제주에서 조경수로 많이 심던 나무라 대량 재배 과일이 아니며, 모양이 울퉁불퉁할 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘하귤’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219851&menuNo=300063","checkedAt":"2026-11-12"}]},
  "sweet-potato": {"summary":"고구마는 9~10월이 제철이에요. 추위에 약하니 냉장고 말고 10~20℃의 어둡고 통풍 좋은 곳에 두세요. 고르는 법과 수입산 구별법을 정리했어요.","origin":"영암·해남·익산·고창·여주·논산","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"고구마는 가을이 시작될 무렵인 9~10월에 수확합니다. 장에서는 당도가 높은 호박고구마, 수분이 적고 구수한 밤고구마, 둘의 맛이 섞인 황금고구마 등이 나오니 취향에 맞는 품종을 먼저 정하세요. 수입산도 유통되니 겉색과 크기를 함께 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"열을 가할수록 단맛이 강해집니다. 밤고구마는 수분이 적고 구수하며, 호박고구마는 당도가 높습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질은 홍자색, 속은 담황색이고 겉이 패인 곳 없이 매끄러운 것을 고르세요."},{"text":"모양이 고르고 단단하며 잔뿌리가 적은 것이 좋습니다."},{"text":"겉이 쭈글쭈글하거나 크기에 비해 가벼운 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"차가운 곳에 두면 쉽게 상하니 냉장하지 말고, 두세 개씩 신문지에 싸서 10~20℃의 어둡고 통풍 좋은 곳에 두세요."},{"label":"손질법","text":"흙을 털고 깨끗이 씻어 껍질째 굽거나 삶으세요. 껍질을 벗긴 채 두면 검게 변하니 엷은 설탕물에 담가 두세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"군고구마. 씻은 고구마를 껍질째 굽습니다."},{"text":"찐고구마와 동치미. 삶은 고구마에 동치미를 곁들입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 수입 고구마가 크고 잘랐을 때 수분이 적으며 겉면이 탁한 적색이라고 설명합니다. 상처 난 고구마는 쉽게 썩으니 상자째 살 때 상처를 확인하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘고구마’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219875&menuNo=300063","checkedAt":"2026-11-12"}]},
  "sweet-potato-stem": {"summary":"고구마순은 5~6월이 제철이에요. 연한 소금물에 담갔다가 가는 쪽부터 까면 껍질이 쉽게 벗겨져요. 고르는 법과 말려서 보관하는 법을 정리했어요.","origin":"영암·해남·익산·고창·김제","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"고구마순은 고구마의 줄기로, 5~6월에 나물거리로 나옵니다. 장에서는 껍질째 묶음으로 파는 것과 껍질을 벗겨 파는 것이 함께 나옵니다. 손질 시간이 부족하면 껍질 깐 것을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"데쳐서 나물로 먹으면 아삭하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"대가 시들지 않고 탄력 있으며 연한 녹색에 윤기가 도는 것을 고르세요."},{"text":"묶음이 고르고 흙, 돌 같은 이물질이 없는 것이 좋습니다."},{"text":"부러지거나 짓눌린 것, 마르거나 변색된 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"껍질을 벗겨 소금물에 살짝 삶아 찬물에 헹구고 물기를 짜서 말려 두세요. 김치나 반찬용은 삶아서 냉동합니다."},{"label":"손질법","text":"연한 소금물에 담갔다가 줄기가 가는 쪽부터 까면 껍질이 쉽게 벗겨집니다. 깐 줄기는 끓는 물에 살짝 데쳐 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"고구마순볶음. 데친 줄기를 간장, 파, 마늘, 육수로 약한 불에 볶고 들깨를 넣습니다."},{"text":"고구마순김치. 소금물에 절인 줄기에 다진 풋고추와 마늘을 넣어 버무립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요 품종으로 물고구마와 밤고구마를 듭니다. 잎만 따로 골라 장아찌를 담그기도 합니다. 머위대와 비슷해 보이지만 고구마순이 더 가늘고 잎색이 진합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘고구마순’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219833&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘머위대’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219951&menuNo=300063","checkedAt":"2026-11-12"}]},
  "sweet-pumpkin": {"summary":"단호박은 6~12월이 제철이에요. 같은 크기 중 묵직하고 꼭지 주변이 무르지 않은 것을 고르세요. 씨와 속을 긁어내는 손질법과 단호박찜, 수프를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"단호박은 쪄 먹으면 달고 포슬포슬해 찜과 샐러드에 두루 쓰입니다. 수프를 만들 때는 익힌 과육을 으깨면 농도를 내기 편하고, 샐러드에 넣을 때는 너무 오래 익히지 않아야 모양이 남습니다. 통째로 살 때는 크기에 비해 묵직한지 확인하고, 꼭지 주변이 물러지지 않았는지 살펴보세요. 자른 뒤 남는 과육은 씨를 빼고 조리하기 좋은 크기로 나눠 둡니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"단맛이 진하고 잘 익히면 밤처럼 포슬포슬하거나 부드럽게 으깨집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"같은 크기 중 묵직한 것을 고르세요."},{"text":"껍질이 단단하고 상처가 없는지 보세요."},{"text":"꼭지 주변이 무르거나 젖은 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통단호박은 서늘하고 통풍되는 곳에 두세요. 씨를 뺀 과육은 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"껍질을 씻고 안정된 도마 위에서 반으로 잘라 씨와 섬유질을 긁어냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"단호박찜. 비슷한 두께로 잘라 고르게 익힙니다."},{"text":"단호박수프. 익힌 과육을 으깨 육수로 농도를 맞춥니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"통째로 보관한 단호박과 잘라 판매하는 단호박은 손질 뒤 보관 방식이 다릅니다. 자른 단호박은 단면이 말라 있거나 물러지지 않았는지 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘단호박’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219877&deleteCd=0&pageIndex=1&selectMonth=11","checkedAt":"2026-11-12"}]},
  "taro": {"summary":"토란은 10월이 제철이에요. 흙이 묻어 있고 껍질이 촉촉하며 눌렀을 때 단단한 것을 고르세요. 날로 먹으면 안 되는 토란의 손질법과 실온 보관법을 정리했어요.","origin":"충남 서천·부여·예산·당진·보령, 전남 곡성·순천·보성","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"토란은 땅에서 나는 알이라는 뜻의 이름을 가진 서류 채소로, 줄기는 8월 이후에, 알줄기는 서리가 내리기 전에 거둡니다. 추석 전후에 거둔 것이 가장 맛이 좋다고 알려져 있습니다. 날것에는 독성이 있어 반드시 익혀 먹어야 하니 손질 방법을 알고 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"날것은 아린 맛이 강하고 표면이 미끈거립니다. 껍질을 벗겨 쌀뜨물에 담그면 미끈거림과 아린 맛이 줄고, 다시마와 함께 끓이면 떫은맛이 잡힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"표면에 흙이 묻어 있고 껍질이 촉촉한 것을 고르세요."},{"text":"머리 부분에 푸른색이 없고, 쉰내가 나거나 갈색으로 변한 것은 피하세요."},{"text":"껍질을 벗긴 속이 희고, 눌렀을 때 단단하며 갈라지지 않는 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"추위와 건조에 약해 냉장고에 넣으면 잘 썩습니다. 흙이 묻은 채로 젖은 신문지에 싸서 10~15℃의 서늘하고 바람이 통하는 곳에 두세요."},{"label":"손질법","text":"날로 먹으면 안 됩니다. 옥살산칼슘(수산칼슘) 때문에 손이 따갑거나 가려울 수 있으니 장갑을 끼고 껍질을 벗기세요. 쌀뜨물에 담가 두거나, 끓는 물에 5분 이상 삶은 뒤 물에 담갔다가 조리하세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"토란탕. 육수에 손질한 토란과 다시마를 넣고 끓입니다."},{"text":"토란조림. 아린 맛을 뺀 토란을 양념에 조립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 충남 서천·부여·예산·당진·보령, 서울, 전남 곡성·순천·보성을, 품종으로 알토란, 재생종, 조생종을 듭니다. 농촌진흥청 자료는 국내산이 중국산보다 길쭉하고 껍질이 잘 벗겨지며 수염뿌리가 적다고 설명하니, 원산지 표시와 함께 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘토란’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219911&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"그린매거진 2022년 9월 ‘땅 속의 계란 토란’","url":"https://www.rda.go.kr/webzine/2022/09/sub4-2.html","checkedAt":"2026-11-13"},{"org":"대한민국 정책브리핑","title":"추석 음식 건강하게 즐기기","url":"https://www.korea.kr/news/cardnewsView.do?newsId=148878365","checkedAt":"2026-11-13"}]},
  "taro-stem": {"summary":"토란대는 9~10월이 제철이에요. 대가 너무 굵거나 단단하지 않고 표면이 깨끗한 것을 고르세요. 껍질 벗기는 법과 말린 토란대 불리는 법을 정리했어요.","origin":"전라도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"토란대는 토란의 줄기로, 생것과 말린 것, 데친 것으로 나뉘어 팔립니다. 데친 토란대는 손이 덜 가서 조리하기 편하고, 말린 것은 하루쯤 불려야 쓸 수 있습니다. 바로 쓸지 두고 쓸지에 따라 형태를 골라 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"날것에는 아린 맛이 있어 삶은 뒤 물에 담가 빼고 씁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"대가 너무 굵지 않고 단단하지 않으며 표면이 깨끗한 것을 고르세요."},{"text":"데친 토란대는 짓무르거나 공기에 오래 닿아 마르고 변색된 것이 없는지 꼼꼼히 보세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 토란대는 밀봉해 냉동하거나, 데친 뒤 물기가 있는 채로 냉동하세요."},{"label":"손질법","text":"겉의 질긴 섬유질을 벗기고 칼로 갈라 손질하세요. 너무 싱싱해 껍질이 잘 안 벗겨지면 하루 이틀 두었다가 벗기세요. 삶은 뒤 물에 담가 아린 맛을 빼고, 말린 것은 충분히 잠길 만큼 물을 부어 상온에서 하루쯤 불리세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"토란대들깨무침. 데친 토란대에 들깻가루와 들기름을 넣고 살짝 볶아 무칩니다."},{"text":"토란대국. 말렸다 불린 토란대를 국이나 탕에 넣어 끓입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 전라도를, 품종으로 블랙매직, 알토란, 조생종을 듭니다. 토란 줄기는 8월 이후에 거두며, 말려 두면 오래 두고 쓸 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘토란대’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219937&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청","title":"그린매거진 2022년 9월 ‘땅 속의 계란 토란’","url":"https://www.rda.go.kr/webzine/2022/09/sub4-2.html","checkedAt":"2026-11-13"}]},
  "thistle-greens": {"summary":"엉겅퀴는 5~7월이 제철이에요. 잎이 연하고 뿌리가 곧게 펴진 것을 고르세요. 생뿌리를 꼭 말려서 써야 하는 이유와 어린 순 나물, 차 끓이는 법을 정리했어요.","origin":"강원","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"엉겅퀴는 온통 가시로 덮여 있어 가시나물, 뿌리가 우엉을 닮아 산우엉이라고도 부릅니다. 예전에는 흔했지만 지금은 깨끗한 농촌이나 산간 지역에서 주로 자랍니다. 어린 순은 나물로 먹고, 줄기와 잎, 뿌리는 말려서 차나 즙으로 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"어린 순은 나물로 먹을 만큼 연하지만, 자란 줄기와 잎은 가시로 덮여 다루기 어렵습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 연하고 뿌리가 곧게 펴진 것을 고르세요."},{"text":"뿌리를 따로 산다면 크게 자란 자연산 엉겅퀴의 뿌리만 모은 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질해 말린 뒤 밀봉해 냉장하면 30일 정도 둘 수 있습니다."},{"label":"손질법","text":"잔뿌리를 정리하고 질긴 잎을 잘라 깨끗이 씻은 뒤 말리세요. 생뿌리는 독성이 있어 반드시 말려서 써야 하며, 말린 것은 쓰기 전에 흐르는 물에 한 번 씻으세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"엉겅퀴나물. 어린 순을 나물로 무칩니다."},{"text":"엉겅퀴차. 말린 엉겅퀴에 3배 정도의 물을 붓고 약한 불에서 연하게 우립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 강원도를, 품종으로 밀크시슬, 가시엉겅퀴, 고려엉겅퀴, 흰가시엉겅퀴를 듭니다. 가을에 줄기와 잎을 그늘에 말려 쓰기도 합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘엉겅퀴’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219941&menuNo=300063","checkedAt":"2026-11-12"}]},
  "tomato": {"summary":"토마토는 7~9월이 제철이에요. 붉은색이 고르고 단단하며 꼭지가 마르지 않고 초록색인 것을 고르세요. 껍질 쉽게 벗기는 법과 상온·냉장 보관법을 정리했어요.","origin":"강원·충남·전북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"토마토는 채소지만 우리나라에서는 과일처럼 생으로 먹는 경우가 대부분이고, 주스나 소스로도 만듭니다. 크게 일반토마토와 방울토마토로 나누며, 크기에 따라 쓰임이 달라집니다. 기름에 볶아 푹 익혀 먹기도 하니 쓰임을 정하고 사세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"새콤한 맛을 내는 유기산과 감칠맛을 내는 글루탐산이 많아, 요리에 넣으면 기름진 맛이나 쓴맛을 누그러뜨립니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"모양이 일정하고 표면이 매끄러우며 빨간색이 고르게 든 것을 고르세요."},{"text":"무르지 않고 단단하며 묵직한 것이 좋습니다."},{"text":"꼭지가 오그라들거나 마르지 않고 초록색을 띠는 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"바로 먹을 것은 햇빛을 피해 통풍이 잘되는 상온(15~25℃)에 두세요. 냉장할 때는 꼭지가 아래로 가게 놓고 서로 겹치지 않게 하세요."},{"label":"손질법","text":"흐르는 물에 표면과 꼭지 부분을 씻으세요. 껍질을 벗기려면 밑부분에 열십자로 칼집을 내고 끓는 물에 살짝 데치세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"토마토 샐러드. 생으로 썰어 샐러드에 넣습니다."},{"text":"토마토볶음. 기름에 볶아 푹 익혀 먹거나 소스로 씁니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 강원도, 충청남도, 전라북도를 들고, 생산시기를 7~9월로 적습니다. 농사로는 대과종(200g 이상), 중과종(60~200g), 송이형 같은 소과종(30~60g), 방울토마토 같은 미니종(30g 이하)으로 크기를 나눕니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘토마토’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227340&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"이달의 식재료 ‘방울토마토’","url":"https://www.nongsaro.go.kr/mfood/kfi/foodMonth/view?menuId=PS03924&cntntsNo=200784&code=&tabCode=1&dtlCode=2&month=03","checkedAt":"2026-11-13"}]},
  "tongue-sole": {"summary":"서대는 6~10월이 제철이에요. 눈이 있는 쪽은 갈색, 반대쪽은 흰색인 혀 모양 생선으로 참서대가 가장 맛있다고 해요. 서대회무침과 말린 서대 조림을 정리했어요.","origin":"여수 등 전남 남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"서대는 가자미목 참서대과의 바닷물고기로, 생김새가 소의 혀를 닮았습니다. 수심 70m 이내 펄과 모래가 섞인 바닥에 살며, 여수를 중심으로 한 전남 남해안에서 주로 잡힙니다. 산란기는 6~8월이고, 여름에서 가을(6~10월)이 맛이 가장 좋은 때입니다. 우리 바다에 여러 종이 있으니 이름표에 참서대인지 적혀 있는지 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"비린내가 거의 없는 흰살 생선입니다. 날것은 새콤달콤하게 무치고, 말리면 조림과 찜에 씁니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"눈이 있는 쪽은 갈색, 눈이 없는 쪽은 흰색입니다. 머리가 둥글고 뒤로 갈수록 가늘어집니다."},{"text":"참서대, 개서대, 각시서대 가운데 참서대를 가장 맛있다고 봅니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 밀봉해 냉장고에서 가장 차가운 곳에 두고 1~2일 안에 드세요. 오래 두고 먹을 때는 말린 서대를 사서 조림이나 찜에 쓰세요."},{"label":"손질법","text":"비늘이 쉽게 떨어지는 생선입니다. 회는 새콤달콤한 양념에 무치고, 말린 것은 조림이나 찜에 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"서대회무침. 회를 떠서 새콤달콤한 양념에 무칩니다."},{"text":"말린 서대 조림. 말린 서대를 양념에 조리거나 찝니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"여수에서는 제사상에 올리기도 하는 생선입니다. 생물보다 말린 것이 많이 팔리니 용도에 맞게 고르세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 서대가 엎드려 있는 개펄도 맛있다","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=6884&select_list_no=155","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 6월 수산물 ‘서대’, ‘전복’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=35105&select_list_no=29","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "trout": {"summary":"송어는 1~2월이 제철이에요. 국내산은 모두 양식이고 주로 800g 크기로 출하돼요. 붉은 살을 회로 먹는 법과 찜·구이, 산지 정보를 정리했어요.","origin":"강원, 경북, 충북(양식)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"송어는 연어과의 냉수성 어류로, 살이 소나무처럼 붉다고 해서 송어라는 이름이 붙었습니다. 국내에서 파는 송어는 양식산이고, 생산량의 약 56%가 강원도에서 나옵니다. 겨울에는 생산량의 10% 정도가 낚시터와 축제용으로 나갑니다. 해양수산부는 송어를 1월과 2월의 수산물로 골랐습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"지방이 적고 육질에 탄력이 있어 회로 많이 먹습니다. 익혀도 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"살빛이 붉고 선명한 것을 고르세요."},{"text":"연어보다 몸이 둥글고 작으며, 등은 짙은 남색, 배는 은백색, 옆구리에 암갈색 반점이 있습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 밀봉해 냉장고에서 가장 차가운 곳에 두고 1~2일 안에 드세요."},{"label":"손질법","text":"탄력 있는 살은 회로 먹고, 담백한 맛을 살리려면 찜이나 구이로 조리합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"송어회. 탄력 있는 붉은 살을 얇게 떠서 먹습니다."},{"text":"송어 찜·구이. 담백한 맛을 살려 찌거나 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"출하 규격은 주로 800g이고 kg 단위로 거래됩니다. 양식장에서 유통업자를 거쳐 횟집으로 가거나 양식장에서 횟집으로 바로 갑니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 1월 수산물 ‘방어’, ‘송어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=36208&select_list_no=22","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"입맛 돋우는 겨울 별미 ‘송어’와 ‘김’을 맛보세요","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=28410&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"2월엔 평창의 맛 ‘송어’와 ‘미역’을 즐겨보자","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=18745&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "turmeric": {"summary":"강황은 11~12월이 제철이에요. 생강황은 얼면 못 쓰게 되니 종이에 싸서 얼지 않는 서늘한 곳에 두세요. 분말 보관법과 수확 시기 차이를 정리했어요.","origin":"진도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"강황은 뿌리줄기를 쓰는 향신 채소로, 노란색을 내는 카레 재료로 쓰입니다. 국내에서는 전남 진도가 첫 주산지로 알려졌습니다. 장에서는 생강황과 분말이 함께 나오며, 수확 시기에 따라 색이 다르니 수확일을 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"맵고 쓴맛이 나는 향신료입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"수확일자와 겉표면 색을 확인하세요."},{"text":"분말은 가을 수확분이 연노랑, 봄 수확분이 진노랑을 띱니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생강황은 신문지나 종이에 싸서 물기를 빼고 비닐봉지에 넣어 아이스박스 등에 얼지 않게 두세요. 가끔 종이를 축여 너무 마르지 않게 합니다. 분말은 습기에 뭉치므로 사자마자 냉동하세요."},{"label":"손질법","text":"얼면 못 쓰게 되니 보관 중 얼지 않았는지 확인하고 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"카레라이스. 강황으로 노란색과 매운맛을 냅니다."},{"text":"요구르트 카레. 강황 카레를 만들 때 우유나 요구르트를 더합니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 생산시기를 10~11월로 소개하고, 봄에 캔 강황은 겨울을 나며 수확량이 줄지만 더 좋은 품질로 취급한다고 설명합니다. 농사로의 진도 재배 시험에서는 수량과 성분을 함께 볼 때 11월 하순~12월 상순 수확이 알맞았습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘강황’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219946&menuNo=300063","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"강황 재배시 남부지방의 최적 수확시기","url":"https://www.nongsaro.go.kr/portal/ps/psb/psbb/farmUseTechDtl.ps?menuId=PS00072&farmPrcuseSeqNo=100000151996&totalSearchYn=Y","checkedAt":"2026-11-12"}]},
  "turnip": {"summary":"순무는 10~11월이 제철이에요. 껍질이 매끄럽고 겉이 갈라지지 않았으며 잎이 싱싱한 것을 고르세요. 잎과 뿌리를 나눠 보관하는 법과 순무김치를 정리했어요.","origin":"강화","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"순무는 무와 가까운 뿌리채소지만, 뿌리가 자란 무와 달리 뿌리 위 배(胚) 부분이 굵어진 것입니다. 진짜 뿌리는 끝에 달린 가늘고 긴 수염입니다. 주산지는 강화이며, 흰 순무 외에 보라색 순무도 있어 쓰임에 따라 고를 수 있습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"부드러운 단맛에 쌉쌀한 매운맛이 어우러져 무와는 다른 맛을 냅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 매끄럽고 상처가 없으며 잎이 싱싱한 것을 고르세요."},{"text":"겉이 갈라진 것은 자랄 때 수분이 모자라 발육이 멈춘 것이니 피하세요."},{"text":"뿌리 수염이 크지 않은 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"잎부터 쉽게 상하니 사 오면 바로 잎을 잘라 비닐봉지에 싸서 냉장하고, 뿌리는 밀봉해 냉장하세요. 오래 두면 냄새가 강해지니 빨리 드세요."},{"label":"손질법","text":"수분을 빨아들이는 수염뿌리부터 잘라 두세요. 김치를 담글 때는 순무에 수분이 적으니 고춧가루를 물에 개어 버무리세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"순무김치. 깍두기처럼 썰어 담그거나 물김치, 동치미로 담급니다."},{"text":"순무 샐러드. 생것을 얇게 썰어 샐러드로 먹습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 품종으로 소순무, 황순무, 비탄홍순무 등을 소개합니다. 간식이나 장식용으로 쓰려면 보라색 순무를 사는 방법도 있다고 안내합니다. 잎은 살짝 데치면 푸른색이 살아나 함께 먹을 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘순무’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219915&menuNo=300063","checkedAt":"2026-11-12"}]},
  "ulgeum-rhizome": {"summary":"울금은 11월이 제철이에요. 생뿌리는 잘랐을 때 단면이 연노랑이고 지나치게 마르지 않은 것을 고르세요. 생울금 손질과 갈아서 냉동하는 법을 정리했어요.","origin":"진도·옥천·청양·제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"울금은 덩이뿌리를 먹는 작물로, 생뿌리, 말린 것, 분말, 진액 형태로 팔립니다. 진도는 2014년 울금 지리적 표시 지역으로 지정됐고 국내 생산량 대부분이 진도에서 나옵니다. 비슷한 강황과 말린 상태로는 구분하기 어려우니 품목명과 원산지 표시를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"특유의 냄새와 자극적인 맛이 있고 씹으면 침이 누렇게 물듭니다. 생으로 그냥 먹기는 어렵습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생뿌리는 싱싱하고 잘랐을 때 단면이 연노랑인 것을 고르세요."},{"text":"지나치게 말랐거나 상처가 있는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻어서 잘라 비닐봉지에 넣어 냉동하거나, 강판에 갈아 비닐팩에 얇게 펴서 냉동해 필요한 만큼 떼어 쓰세요. 냉장하면 쉽게 상하니 빨리 쓰세요."},{"label":"손질법","text":"줄기와 잔뿌리를 떼고 껍질을 벗긴 뒤 물에 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"울금차. 얇게 저민 울금을 대추와 함께 물에 끓입니다."},{"text":"울금 생선구이. 간 생울금을 생선에 곁들여 구워 비린내를 줄입니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리 생산시기는 11월입니다. 생울금은 갈아서 찌개에 넣거나 김장 때 생강 대신 쓰기도 하고, 말리거나 가루로 낸 울금은 카레나 피클에 넣습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘울금’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219896&menuNo=300063","checkedAt":"2026-11-12"}]},
  "uloe-melon": {"summary":"울외는 3~7월이 제철이에요. 생울외는 껍질에 흠이 적고 손에 들었을 때 단단한 것을 고르세요. 씨와 속을 긁어내는 손질법과 울외장아찌를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"울외는 참외를 닮은 길쭉한 열매로, 주로 절여 반찬으로 먹습니다. 장아찌를 담글 때는 묽고 부드러운 속을 덜어내고, 단단한 과육을 절여 씹는 맛을 살립니다. 생열매와 완성된 장아찌가 모두 울외라는 이름으로 팔릴 수 있으니 주문할 때 어떤 형태인지 확인하세요. 절임을 사 온 경우에는 포장에 적힌 보관법을 따르고 먹을 만큼만 덜어 썹니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생과는 맛이 순하고 수분이 많으며 절이면 아삭하게 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질에 흠이 적은 것을 고르세요."},{"text":"손으로 들었을 때 단단한지 확인하세요."},{"text":"눌리거나 갈라져 즙이 새는 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생과는 물기를 닦아 냉장하고 빠르게 사용하세요. 절임 제품은 표시대로 보관합니다."},{"label":"손질법","text":"흐르는 물에 씻은 뒤 길게 갈라 씨와 속을 긁어냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"울외장아찌. 속을 걷어낸 과육을 절여 반찬으로 씁니다."},{"text":"울외장아찌 주먹밥. 장아찌를 잘게 썰어 밥에 섞습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"울외는 과육의 씹는 맛을 살려 절임에 쓰는 경우가 많습니다. 생울외와 절임 완제품을 구입할 때 구분하세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘울외’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227365&deleteCd=0&pageIndex=1&selectMonth=6","checkedAt":"2026-11-12"}]},
  "wakame": {"summary":"미역은 12월이 제철이에요. 마른 미역은 흑갈색으로 잘 마르고 꽉 쥐었을 때 딱딱한 것을 고르세요. 생미역 고르는 법과 미역줄기 냉동 보관법을 정리했어요.","origin":"전남, 부산 기장, 울산 울주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"미역은 겨울부터 여름까지 자라는 갈조류로, 채취는 주로 겨울에서 봄 사이에 이뤄집니다. 생미역, 마른 미역, 염장 미역줄기로 나뉘어 팔리니 쓰임에 맞는 형태를 고르세요. 일찍 채취한 부드럽고 어린 미역은 나물용으로 따로 팔립니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"미끈거리는 점액질이 있고, 일찍 채취한 어린 미역일수록 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생미역은 잡티가 없고 녹색이 짙으며 광택과 탄력이 있는 두꺼운 것을 고르세요."},{"text":"마른 미역은 흑갈색으로 눅눅하지 않고, 꽉 쥐었을 때 딱딱하며 줄기 심이 가는 것이 좋습니다."},{"text":"누렇게 변했거나 흰 반점, 이물질이 붙은 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"미역줄기는 밀봉해 냉동하면 1년쯤 둘 수 있습니다. 갓 딴 생미역은 데쳐서 식히면 초록색이 살고 더 오래 둘 수 있습니다."},{"label":"손질법","text":"마른 미역은 찬물에 불리세요. 따뜻한 물에 불리면 점액질이 너무 빨리 빠져나옵니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"미역줄기볶음. 염장 미역줄기를 헹궈 데친 뒤 양파, 당근과 함께 볶습니다."},{"text":"미역냉국. 불린 미역을 차가운 국물에 넣어 냅니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"국내 미역 생산량은 50~60만 톤이고 그중 60%가 식용, 40%가 전복 먹이용입니다. 주산지 전남이 90%를 차지하는데, 완도 미역은 대부분 전복 먹이용이고 고흥 미역은 식용으로 많이 쓰입니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"방어, 미역, 굴","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34360","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"사시사철 즐기는 바다의 채소 ‘미역’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=24223","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"12월의 수산물, 명태와 미역 선정","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0307&cnts_id=8244&select_list_no=19","checkedAt":"2026-11-12"}]},
  "walnut": {"summary":"호두는 9~10월이 제철이에요. 껍질이 얇고 연한 황색이며 흔들었을 때 달그락거리지 않는 것을 고르세요. 껍데기 까는 법과 산패 막는 냉장 보관법을 정리했어요.","origin":"천안·김천·영동·무주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"호두는 단단한 껍데기째 팔거나 속을 깐 상태로 팝니다. 기름이 많아 깐 호두는 공기 중에서 쉽게 산패하므로, 오래 두고 먹을 것은 껍데기째 사세요. 정월대보름 부럼으로도 많이 찾습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"고소한 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 얇고 연한 황색이며 모양이 온전한 것을 고르세요."},{"text":"흔들었을 때 달그락 소리가 나거나 너무 가벼우면 속이 마른 것입니다."},{"text":"크기가 너무 작고 구멍이 뚫린 것은 벌레 먹은 것이니 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"껍데기째 냉장하면 오래 둘 수 있고, 깐 호두는 밀폐용기에 담아 냉장하세요."},{"label":"손질법","text":"전용 도구가 없으면 소금물에 하루쯤 담가 두세요. 껍데기가 잘 부서집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"호두 멸치볶음. 잘게 부순 호두를 멸치볶음에 넣습니다."},{"text":"호두밥. 속껍질을 벗긴 호두를 넣어 밥을 짓습니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 천안, 김천, 영동, 무주를, 품종으로 백호두, 흑호두, 페르샤호두를 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘호두’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219908&menuNo=300063","checkedAt":"2026-11-12"}]},
  "water-dropwort": {"summary":"미나리는 3~4월이 제철이에요. 줄기가 굵지 않고 연하며 잎이 끝까지 초록빛인 것을 고르세요. 논미나리 거머리 없애는 법과 세워 보관하는 법을 정리했어요.","origin":"태안·청주·의령·창원·구미·청도","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"미나리는 3~4월에 많이 나오는 봄나물로, 봄 미나리는 연해서 생으로도 먹습니다. 장에서는 논미나리, 밭미나리, 돌미나리가 나오며 쓰는 부위가 다릅니다. 논미나리는 주로 줄기를, 돌미나리는 잎과 줄기를 함께 씁니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"향이 독특하고 아삭아삭하게 씹힙니다. 줄기가 얇을수록 식감이 좋습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 선명한 초록빛이고 길이가 고르며, 줄기가 굵지 않고 연한 것을 고르세요."},{"text":"줄기 밑부분은 연한 적갈색이 돌고 잔털이 많지 않은 것이 좋습니다."},{"text":"줄기에 탄력이 없거나 잎 끝이 마른 것, 마디가 굵고 억센 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"밑동을 물에 적신 타월로 감싸 비닐봉투에 넣거나 종이에 싸서 비닐봉지에 넣고, 냉장고에 세워 두세요."},{"label":"손질법","text":"논미나리는 습지에서 자라 거머리가 있을 수 있으니 조리 전에 식초물에 담가 두세요. 떫은맛이 있어 살짝 데쳐 쓰기도 합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"미나리강회. 파강회와는 또 다른 향긋한 맛을 냅니다."},{"text":"미나리전. 미나리를 썰어 반죽에 넣고 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요품종으로 논미나리, 밭미나리, 돌미나리를 듭니다. 생채, 무침, 전골, 생선찌개에 두루 넣습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘미나리’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219825&menuNo=300063","checkedAt":"2026-11-12"}]},
  "watermelon": {"summary":"수박은 6~8월이 제철이에요. 줄무늬가 뚜렷하고 두드렸을 때 둔탁한 소리가 나는 것을 고르세요. 잘라 파는 수박 고르는 법과 냉장 보관법을 정리했어요.","origin":"함안·고창·고령·영동·단양","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"수박은 6~8월에 나오는 여름 과일로, 한 통으로 사거나 잘라 파는 조각으로 삽니다. 줄무늬수박 외에 흑수박, 복수박, 노란수박, 미니수박 등 종류가 다양하니 먹을 양과 냉장고 자리를 생각해 고르세요. 장마철에는 무른 수박이 나오니 더 꼼꼼히 보세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과육이 달고 수분이 많습니다. 차게 하면 단맛이 더 강하게 느껴집니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"색이 선명하고 줄무늬가 뚜렷하며 꼭지 쪽이 움푹 들어간 것을 고르세요."},{"text":"두드렸을 때 맑은 소리보다 둔탁한 소리가 나는 것이 잘 익은 것입니다. 꼭지가 없거나 갈색으로 마른 것은 피하세요."},{"text":"잘라 파는 수박은 단면이 매끈하고 씨가 넓게 퍼진 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"잘라서 단면을 랩으로 싸 냉장하거나, 과육을 깍둑썰어 밀폐용기에 담아 냉장하세요. 며칠 안에 드세요."},{"label":"손질법","text":"자르기 전에 껍질을 깨끗이 씻으세요. 자른 면을 통해 세균이 번식할 수 있습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"수박화채. 스쿱으로 과육을 동그랗게 떠서 다른 과일과 함께 띄웁니다."},{"text":"수박껍질 나물. 껍질의 흰 부분을 채 썰어 양념에 무칩니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 함안, 고창, 고령, 영동, 단양을, 품종으로 태극, 샛별, 백두산, 환호성, 복수박, 기린을 듭니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘수박’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219887&menuNo=300063","checkedAt":"2026-11-12"}]},
  "webfoot-octopus": {"summary":"주꾸미는 3~4월이 제철이에요. 알이 꽉 차고 머리와 몸통이 탱탱하며 다리 빨판이 뚜렷한 것을 고르세요. 먹통 떼는 손질법과 주꾸미무침을 정리했어요.","origin":"서해 연안(보령·서천)","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"주꾸미는 문어과의 연체동물로 낙지와 닮았지만 몸길이가 20cm 정도로 작고, 8개 다리 길이가 거의 같습니다. 봄에 수온이 오르면 서해 연안으로 몰려들고, 산란기(5~6월) 직전인 3~4월에 알이 차서 가장 맛있습니다. 좌우 셋째 다리 사이에 금색 고리 무늬가 있어 낙지와 구분됩니다. 소라 껍데기로 잡은 것은 살아서, 그물로 잡은 것은 죽은 채 올라오는 경우가 많습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 연하고 쫄깃하며, 삶은 알은 밥알처럼 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"알이 가득 찬 것을 고르세요."},{"text":"머리와 몸통이 탱탱하고 다리 빨판이 뚜렷할수록 신선합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"뚜껑 있는 용기에 담아 냉장하고 1~2일 안에 드세요. 싱싱한 것은 회로도 먹습니다."},{"label":"손질법","text":"연한 소금물에 잠시 담근 뒤 머리를 뒤집어 먹통을 떼어 내고, 너무 세게 문지르지 말고 훑으면서 씻습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"주꾸미무침. 끓는 소금물에 살짝 데쳐 썰고 양파, 미나리, 오이와 초고추장 양념에 버무립니다."},{"text":"주꾸미볶음. 고추장 양념으로 볶거나 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"‘봄 주꾸미, 가을 낙지’라는 말처럼 봄에 많이 찾습니다. 3월 중순 보령 무창포, 3월 말~4월 초 서천 마량포에서 주꾸미 축제가 열린 적이 있습니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 쫄깃쫄깃 봄철 ‘주꾸미’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=14818&select_list_no=124","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 봄철 입맛 살리는 주꾸미","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=6600&select_list_no=157","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"봄을 알리는 맛있는 신호, 도다리와 주꾸미","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=30835&menuSeq=971","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "wheat": {"summary":"밀은 5월이 제철이에요. 빵은 강력분, 칼국수는 중력분처럼 요리에 맞는 가루를 고르세요. 강력분·중력분·박력분 구분과 개봉 뒤 보관법을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"밀은 낟알을 제분해 빵이나 국수, 전을 만드는 곡물입니다. 통밀가루는 껍질 부분이 섞여 색과 향이 진하고, 반죽할 때는 제품에 적힌 용도와 원재료를 살피는 것이 좋습니다. 정보누리는 5월을 생산기로 안내하지만 농사로에는 6월에 수확하는 재배 사례도 있습니다. 장에서는 햇곡 수확 시기와 가루 제품의 판매 시기를 구분해 보고 한 번에 쓸 양을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"밀을 익히면 구수한 향이 나고 반죽의 종류와 조리법에 따라 쫄깃하거나 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"요리에 맞는 밀가루의 종류를 확인하세요."},{"text":"원산지와 제분·포장 표시를 보세요."},{"text":"습기에 굳었거나 벌레가 생긴 것은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"개봉한 가루는 밀폐해 서늘하고 건조한 곳에 두세요. 오래 둘 양은 소분해 냉동할 수 있습니다."},{"label":"손질법","text":"가루는 필요할 때 체에 치고 날반죽은 충분히 익혀 드세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"밀빵. 강력분을 반죽해 발효 후 굽습니다."},{"text":"칼국수. 중력분 반죽을 밀어 썰고 국물에서 익힙니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"강력분·중력분·박력분은 제분한 가루의 구분입니다. 밀의 수확과 제분 제품의 출하는 다른 단계입니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘밀’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219966&deleteCd=0&pageIndex=1&selectMonth=5","checkedAt":"2026-11-12"},{"org":"농촌진흥청 농사로","title":"밀 농업소득 향상 운영 매뉴얼","url":"https://nongsaro.go.kr/cms_contents/937/100161_MF_ATTACH_01.pdf","checkedAt":"2026-11-12"}]},
  "wild-chive": {"summary":"달래는 3~4월이 제철이에요. 잎이 진한 초록색이고 알뿌리가 단단한 것을 고르세요. 알뿌리 아래 흙덩이를 떼는 손질법과 달래장, 된장찌개를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"달래는 잎이 가늘고 아래에 작은 알뿌리가 달리는 봄나물입니다. 파나 마늘을 닮은 알싸한 향이 있어 잘게 썰어 양념장을 만들거나 된장찌개에 넣습니다. 한 묶음을 손질할 때는 알뿌리 아래와 잎 사이에 낀 흙을 먼저 살피세요. 알뿌리가 굵은 것은 가볍게 눌러 썰고 잎은 끝의 마른 부분을 골라내면 양념장에 섞었을 때 먹기 편합니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"알뿌리의 매운 향이 또렷하고 잎은 부드럽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 진한 초록색이고 끝이 시들지 않았는지 보세요."},{"text":"알뿌리가 단단한 것을 고르세요."},{"text":"누렇게 변하거나 짓무른 잎이 많은 단은 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"짧게 냉장하고, 찌개에 쓸 양은 씻어 물기를 빼고 잘라 냉동하세요."},{"label":"손질법","text":"알뿌리 아래의 흙덩이와 마른 겉껍질을 떼어낸 뒤 잎 사이를 물에 헹굽니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"달래장. 잘게 썬 달래를 간장에 섞어 밥이나 두부에 곁들입니다."},{"text":"달래 된장찌개. 마지막에 넣어 향을 살립니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"잎과 알뿌리 모두 씁니다. 생으로 넣는 양념장에는 알뿌리를 잘게 썰면 한입마다 향이 고르게 납니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘달래’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219824&deleteCd=0&pageIndex=1&selectMonth=3","checkedAt":"2026-11-12"}]},
  "wild-grape": {"summary":"머루는 9~10월이 제철이에요. 진한 흑자색에 흰 가루가 얇게 덮이고 줄기가 싱싱한 송이를 고르세요. 머루 주스와 잼, 냉동 보관법을 정리했어요.","origin":"파주·평창·무주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"머루는 작은 알이 송이로 달리는 가을 열매입니다. 정보누리는 파주, 평창, 무주 등을 산지로 들고 9~10월을 생산기로 안내합니다. 산림청 자료에 따르면 머루는 나무에서 딴 뒤 성숙이 거의 멈춥니다. 잼이나 주스를 만들려고 한 송이씩 살 때도 줄기와 알의 상태를 살피고, 송이 위쪽부터 아래쪽까지 검붉게 익은 열매가 많은 것을 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"잘 익으면 단맛과 산미가 함께 나며, 작은 알에 껍질과 씨가 씹힙니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"진한 흑자색을 띠고 흰 가루가 얇게 덮인 송이를 고르세요."},{"text":"줄기가 시들지 않았는지 보세요."},{"text":"송이 아래 알까지 잘 익었는지 살피세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"물기가 없는 상태로 눌리지 않게 냉장하세요. 주스용은 송이에서 떼어 씻고 물기를 닦아 소분해 얼릴 수 있습니다."},{"label":"손질법","text":"조리 직전에 씻고 알을 떼세요. 주스로 만들 때는 씨와 껍질을 체로 거르면 부드럽습니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"머루 주스. 알을 으깨 즙을 거릅니다."},{"text":"머루잼. 씨를 걸러낸 과육을 졸여 빵에 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"재배 머루는 알과 색이 비교적 고른 편입니다. 산림청 자료에서 중부지방 수확 시작은 대체로 9월 중순입니다. 수확 뒤 익혀 먹는 과일처럼 두기보다 살 때 숙도를 살피세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘머루’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?deleteCd=0&menuNo=300063&nttId=219922&pageIndex=1&searchCnd=&searchWrd=&selectMonth=10","checkedAt":"2026-11-12"},{"org":"산림청","title":"임산물 재배 자료 ‘머루’","url":"https://www.forest.go.kr/kfs/images/data/down/imsan/imsan_01_08.pdf","checkedAt":"2026-11-12"}]},
  "winter-melon": {"summary":"동아는 9~11월이 제철이에요. 겉을 두드렸을 때 맑은 소리가 나고 들었을 때 묵직한 것을 고르세요. 씨 손질법과 서늘한 곳 보관법을 정리했어요.","origin":"충북","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"동아는 박과의 한해살이 덩굴식물 열매로, 동과라고도 부릅니다. 인도가 원산지이며 우리나라에서는 삶거나 김치, 죽에 넣어 먹습니다. 통째로 살 때는 두드려 본 소리와 무게로 상태를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"날로 먹기보다 삶거나 김치·죽에 넣어 익혀 먹는 채소입니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"겉면을 두드렸을 때 맑은 소리가 나는 것을 고르세요."},{"text":"들었을 때 무거운 것이 좋습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"신문지로 싸서 직사광선을 피해 서늘한 곳에 두세요."},{"label":"손질법","text":"깨끗이 씻어 반으로 자른 뒤 씨를 발라내고 쓰세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"동아김치. 씨를 발라낸 동아를 썰어 김치로 담급니다."},{"text":"동아죽. 손질한 동아를 넣고 죽을 쑵니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주요산지를 충청북도로 소개합니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘동아’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=227348&menuNo=300063","checkedAt":"2026-11-12"}]},
  "wood-ear": {"summary":"목이버섯은 3~6월이 제철이에요. 마른 목이는 눅눅하지 않고 부스러기가 적은 것을 고르세요. 필요한 만큼만 불리는 손질법과 목이버섯 잡채를 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"목이버섯은 얇고 귀처럼 굽은 모양의 버섯으로 잡채나 볶음에 씁니다. 마른 제품은 물을 먹으면 부피가 커져 한 번에 많이 불릴 필요가 없습니다. 불린 뒤에는 딱딱한 밑동을 떼어내고 남은 부분을 한입 크기로 잘라 익히세요. 생목이를 살 때는 탄력이 있고 짓무르지 않은지 보고, 건목이는 포장이 습기를 먹지 않았는지 살피면 좋습니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"생목이와 불린 건목이는 둘 다 오독오독하고 탄력이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"생목이는 표면이 짓무르지 않은 것을 고르세요."},{"text":"건목이는 눅눅하거나 곰팡이가 없는지 보세요."},{"text":"부스러기가 적고 포장이 온전한 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"생목이는 냉장하고 빨리 쓰세요. 건목이는 밀폐해 건조한 곳에 두고, 불린 것은 즉시 익히세요."},{"label":"손질법","text":"건목이는 필요한 만큼만 불려 씻고 딱딱한 밑동을 제거해 익힙니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"목이버섯 잡채. 불린 목이를 한입 크기로 썰어 볶아 섞습니다."},{"text":"목이버섯 달걀볶음. 익힌 목이를 달걀과 볶습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"3~6월은 정보누리 생산기입니다. 마른 제품은 보관해 판매하므로 구매 시기가 더 넓습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘목이버섯’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=227338&deleteCd=0&pageIndex=1&selectMonth=3","checkedAt":"2026-11-12"}]},
  "yacon": {"summary":"야콘은 9~10월이 제철이에요. 껍질이 자줏빛이고 속살이 노랗고 겉이 미끈한 타원형을 고르세요. 단맛을 올리는 숙성 요령과 오래 두는 보관법을 정리했어요.","origin":"괴산·상주·강화·강릉·화천·봉화","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"야콘은 안데스 지역에서 들어온 뿌리채소로, 우리나라에서는 1985년부터 재배했습니다. 생김새는 고구마와 비슷합니다. 갓 캔 것은 단맛이 거의 없어 숙성시켜야 달아지므로, 조리용인지 간식용인지에 따라 고르세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"숙성되면 달콤해지고, 껍질을 벗겨 생으로 먹으면 배 같은 맛이 납니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"껍질이 자줏빛이고 속살이 노란 것이 달고 맛있습니다."},{"text":"알이 통통하고 상처가 없으며, 원만한 타원형에 표면이 미끈한 것을 고르세요."},{"text":"조리용은 신선한 것을, 간식용은 후숙된 것을 고르세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"씻어서 물기를 말린 뒤 랩으로 싸서 냉장하거나, 신문지에 싸서 통풍이 잘되는 곳에 두세요. 양이 많으면 흙이나 모래에 묻어 두면 오래 갑니다."},{"label":"손질법","text":"갓 캔 야콘은 햇볕에 3~4일 두거나 그늘에서 15일쯤 숙성시키세요. 햇볕에 너무 오래 두면 신선도가 떨어집니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"야콘 샐러드. 한 입 크기로 썰어 과일과 함께 마요네즈에 버무립니다."},{"text":"야콘전. 밀가루 반죽에 야콘을 갈아 넣고 부칩니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"정보누리는 주산지로 괴산, 상주, 강화, 강릉, 화천, 봉화를, 품종으로 백야와 옥천을 듭니다. 수확 직후와 숙성 뒤의 맛이 크게 다르니, 산 날 바로 먹을지 며칠 둘지 정하고 사세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘야콘’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?nttId=219890&menuNo=300063","checkedAt":"2026-11-12"}]},
  "yellow-croaker": {"summary":"조기는 9월~이듬해 2월이 제철이에요. 배가 황금색을 띠고 꼬리가 짧고 두툼하며 살에 탄력 있는 것을 고르세요. 부세와 구별법과 손질 후 냉동법을 정리했어요.","origin":"서해·남해, 추자도 근해","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"우리나라에서 조기라 하면 보통 민어과의 참조기를 말합니다. 참조기는 9월부터 이듬해 2월까지가 제철이고, 겨울을 남쪽 바다에서 난 뒤 봄에 서해로 북상해 산란합니다. 생물로 오래 유통하기 어려워 소금에 절여 말린 굴비나 간조기로 많이 팝니다. 생김새가 비슷한 부세, 황강달이 등이 함께 팔리니 이름표를 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 부드럽고 비린내가 거의 없습니다. 잔가시가 많아 큰 것이 살을 바르기 쉽습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"배가 황금색을 띠고 꼬리가 짧고 두툼한 것을 고르세요."},{"text":"살에 탄력이 있어야 합니다."},{"text":"국산 참조기는 몸이 두툼하고 짧으며, 몸통 가운데 옆줄이 굵고 선명하고, 머리 위에 다이아몬드 모양 돌기가 있습니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"비늘, 지느러미, 내장을 떼고 씻어 물기를 뺀 뒤 소금 간을 해서 잘 싸서 냉동하면 오래 먹을 수 있습니다."},{"label":"손질법","text":"비늘을 긁고 내장을 뺀 뒤 찌개용은 5cm 정도로 토막 내어 소금을 살짝 뿌립니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"조기고추장찌개. 쇠고기 육수에 고추장 양념을 풀고 조기 토막과 대파를 넣어 끓입니다."},{"text":"굴비구이. 말린 굴비를 굽거나 찢어서 고추장에 재워 반찬으로 먹습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"부세와 황강달이는 몸 색이 참조기처럼 황금색이라 헷갈리기 쉽고, 대서양산 긴가이석태는 ‘침조기’라는 이름으로 팝니다. 참조기 새끼는 황석어라고 부르며 서해안에서는 젓갈로 담급니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 기운을 북돋워주는 참조기","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=18587&select_list_no=110","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 11월 수산물 ‘참조기’, ‘해삼’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34244&select_list_no=36","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 제사상의 단골 생선, 조기","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=6435&select_list_no=158","checkedAt":"2026-11-12"}]},
  "yellowfin-flounder": {"summary":"참가자미는 4월이 제철이에요. 비늘이 단단히 붙어 윤기가 있고 눈 없는 쪽 배가 하얗고 탄력 있는 것을 고르세요. 노란 띠로 구별하는 법과 손질법을 정리했어요.","origin":"전 연안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"참가자미는 우리 바다 어디서나 흔한 가자미류의 하나입니다. 눈이 있는 쪽은 황갈색 바탕에 흰 점이 흩어져 있고, 눈 없는 쪽은 흰색이며 꼬리자루 부위가 노랗습니다. 해양수산부는 가자미를 4월의 수산물로 여러 차례 골랐습니다. 시장에서는 여러 가자미가 섞여 팔리니 노란 띠로 참가자미를 구분하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"살이 쫄깃하고 단단해 씹는 맛이 좋고 담백합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"비늘이 단단하게 붙어 있고 윤기가 있는 것을 고르세요."},{"text":"눈이 없는 쪽 배가 하얗고 탄력이 있어야 합니다."},{"text":"등지느러미와 배지느러미 가장자리, 꼬리자루에 노란 띠가 있으면 참가자미입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 뒤 된장을 발라 냉장했다가 굽거나 조리고, 볕 좋고 바람 잘 통하는 날 바싹 말려 두기도 합니다."},{"label":"손질법","text":"비늘이 단단히 붙어 있으니 조심해서 긁어내고, 칼끝을 세워 꼬리 쪽부터 내장이 터지지 않게 긁어냅니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"가자미구이. 소금과 후추로 간하고 밀가루를 입혀 노릇하게 굽습니다."},{"text":"가자미두부찌개. 가자미 토막 위에 지진 두부를 얹고 고추장 양념으로 끓입니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"우리 바다에는 돌가자미, 문치가자미, 기름가자미, 노랑가자미 등 20여 종의 가자미가 삽니다. 가자미는 4~6월에 산란합니다. 넙치(광어)와 헷갈리면 눈 쪽을 앞에 두고 봤을 때 눈이 오른쪽에 몰려 있고 입이 작은 쪽이 가자미입니다."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 4월 수산물 ‘가자미’, ‘홍어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=38820&select_list_no=7","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원","title":"수산물안전정보 가자미","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32809&select_list_no=50","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"4월의 어식백세 제철 수산물, 가자미와 미역·다시마","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=1766&menuSeq=971","checkedAt":"2026-11-12"},{"org":"해양수산부","title":"5월 이달의 수산물 ‘바지락, 가자미’ 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=26108&menuSeq=971","checkedAt":"2026-11-12"}]},
  "yellowstripe-jack": {"summary":"부시리는 8월이 제철이에요. 주둥이부터 꼬리까지 이어진 노란 세로띠가 진하고 위턱 모서리가 둥글면 부시리예요. 방어와 구별하는 법과 구이·조림을 정리했어요.","origin":"남해안 먼바다, 제주","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"부시리는 전갱이과의 대형 바닷물고기로 몸길이가 1m를 넘고 2m 가까이 자랍니다. 동해와 제주를 포함한 남해, 서해 남부에 살며 정치망과 낚시로 잡습니다. 생김새가 방어와 비슷해 전문가가 아니면 구분이 어렵고, 흔히 부시리는 여름, 방어는 겨울이 제철로 알려져 있습니다. 여름에 방어처럼 보이는 생선을 살 때는 어느 쪽인지 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"빠르게 헤엄치는 근육질 생선이라 살이 단단합니다. 지질은 방어의 4분의 1 정도로 적습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"주둥이에서 꼬리지느러미까지 이어진 노란 세로띠가 진하면 부시리입니다."},{"text":"위턱 뒤 모서리가 둥글고, 배지느러미가 가슴지느러미보다 길게 뻗은 것을 확인하세요."},{"text":"방어보다 몸이 가늘고 약간 납작합니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 밀봉해 냉장고에서 가장 차가운 곳에 두고 1~2일 안에 드세요. 크기가 큰 생선이라 토막 단위로 조리합니다."},{"label":"손질법","text":"씻은 뒤 토막을 내어 구이, 조림, 찜에 씁니다. 살이 많아 발라서 고로케나 어묵 반죽으로도 씁니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"부시리 소금구이. 씻은 부시리에 기름을 바르고 굵은 소금을 쳐서 굽습니다."},{"text":"부시리 조림. 토막을 팬에 구운 뒤 간장, 조리용 술, 설탕을 같은 양으로 섞은 양념으로 윤기 나게 조립니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"전북에서는 부수리·평방어, 포항에서는 납작방어, 강원도에서는 나분대라고도 부릅니다. 방어와 함께 팔리는 경우가 많으니 노란 띠와 위턱 모양으로 확인하세요."}]}],"sources":[{"org":"국립수산물품질관리원","title":"수산물안전정보 바다의 미사일 ‘부시리’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=31917&select_list_no=61","checkedAt":"2026-11-12"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "yellowtail": {"summary":"방어는 11월~이듬해 2월이 제철이에요. 위턱 끝 모서리가 각지면 방어, 둥글면 부시리예요. 토막 고르는 법과 부위별로 먹는 순서를 정리했어요.","origin":"제주, 부산, 거제, 남해, 여수","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"방어는 기름이 많은 붉은살 생선으로, 산란 직전인 11월부터 2월까지 가장 맛이 좋습니다. 다른 생선과 달리 클수록 맛이 좋아 10kg에 가까운 것은 대방어라는 이름으로 따로 팝니다. 생김새가 비슷한 부시리와 잿방어가 있으니 어종을 확인하세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"겨울 방어는 지방이 올라 살점이 두툼하고 부드럽습니다. 대방어는 부위마다 기름기가 달라 맛이 다릅니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"단단하고 탄력이 있으며 광택이 나고 눈이 투명한 것을 고르세요."},{"text":"토막은 자른 단면이 깨끗하고 상처가 없는 것이 좋습니다."},{"text":"위턱 뒤끝 모서리가 각져 있으면 방어, 둥글면 부시리입니다."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"손질한 생선은 얼음 위에 올려 포장해 냉장하고 1~2일 안에 드세요."},{"label":"손질법","text":"칼등으로 표면을 다듬고 씻은 뒤 아가미 쪽에 칼집을 넣어 내장을 꺼내세요. 수산물안전정보는 봄~여름 방어는 살 속에 기생충이 생기므로 먹지 않는 것이 좋다고 안내합니다."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"방어회. 대방어는 기름기가 적은 몸통부터 기름진 부위까지 번갈아 먹습니다."},{"text":"방어 소금구이. 지방이 많으니 기름을 적게 둘러 굽습니다."}]}]},{"title":"어종과 유통 특성","blocks":[{"kind":"paragraph","text":"방어는 가을부터 겨울 사이 다 자란 개체가 산란을 위해 남쪽으로 내려옵니다. 활어나 선도 높은 선어 수요가 많아 값이 비쌉니다. 해양수산부는 12월과 1월 이달의 수산물로 방어를 여러 차례 선정했습니다."}]}],"sources":[{"org":"국립수산물품질관리원 수산물안전정보","title":"클수록 맛있는 생선 ‘방어’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=32241","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"12월 이달의 수산물 ‘방어, 미역, 굴’","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0301&cnts_id=34360","checkedAt":"2026-11-13"},{"org":"해양수산부","title":"1월의 수산물, 어촌여행지, 해양생물, 등대 선정","url":"https://www.mof.go.kr/doc/ko/selectDoc.do?bbsSeq=10&docSeq=59808&menuSeq=971","checkedAt":"2026-11-13"},{"org":"국립수산물품질관리원 수산물안전정보","title":"신선/냉동 수산물의 적정 보관방법","url":"https://www.fsis.go.kr/front/contents/cmsView.do?cate_id=0101&cnts_id=16951","checkedAt":"2026-11-13"}]},
  "young-radish": {"summary":"열무는 5~7월이 제철이에요. 잎이 시들지 않고 줄기가 가는 단을 고르세요. 뿌리와 줄기 사이 흙을 걷어 내는 손질법과 열무김치, 열무비빔밥을 정리했어요.","origin":null,"sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"열무는 어린 무를 잎과 줄기째 먹는 채소입니다. 어린 줄기는 아삭해 김치나 국수 고명에 쓰고, 굵어진 겉잎은 데쳐 국에 넣을 수 있습니다. 김치를 담글 때는 줄기와 뿌리가 만나는 부분의 흙을 칼로 가볍게 다듬으세요. 잎을 세게 문지르면 상처가 나기 쉬우므로, 물을 갈아 가며 흔들어 씻으면 풋내를 줄이는 데 도움이 됩니다."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"줄기는 아삭하고 잎에는 풋맛과 약간의 쌉쌀함이 있습니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"잎이 시들지 않고 초록색인 것을 고르세요."},{"text":"연하게 먹으려면 줄기가 가는 단이 좋습니다."},{"text":"뿌리나 밑동에 물러진 곳이 없는지 확인하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"흙을 털고 냉장하세요. 국에 넣을 양은 데쳐 물기를 짠 뒤 냉동할 수 있습니다."},{"label":"손질법","text":"겉잎을 다듬고 뿌리와 줄기 사이의 흙을 걷어낸 뒤 헹구세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"열무김치. 잎이 상하지 않게 절여 양념합니다."},{"text":"열무비빔밥. 익은 김치를 잘라 밥에 얹습니다."}]}]},{"title":"재배와 활용 특성","blocks":[{"kind":"paragraph","text":"여린 잎과 줄기는 김치에 쓰고, 비교적 굵은 겉잎은 데쳐 국에 넣을 수 있습니다."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘열무’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219872&deleteCd=0&pageIndex=1&selectMonth=6","checkedAt":"2026-11-12"}]},
  "yuzu": {"summary":"유자는 11~12월이 제철이에요. 노란빛이 고르고 향이 나며 껍질에 깊은 상처가 없는 것을 고르세요. 씨 빼는 손질법과 유자차, 유자 드레싱을 정리했어요.","origin":"완도 등 남해안","sections":[{"title":"개요 및 특징","blocks":[{"kind":"paragraph","text":"유자는 날씨가 추워질 무렵 남해안에서 거두는 향이 짙은 감귤류입니다. 과육은 신맛이 강해 즙을 양념에 섞기 좋고, 껍질은 향이 진해 가늘게 썰어 차나 청에 씁니다. 완도군은 해양성 기후에서 재배한 유자의 두꺼운 껍질을 차와 잼 등에 활용한다고 소개합니다. 껍질을 쓰는 요리라면 살 때 상처나 갈라진 자국을 먼저 살피세요."}]},{"title":"맛과 식감","blocks":[{"kind":"paragraph","text":"과즙의 신맛이 강하고 껍질 향이 짙습니다. 껍질은 가늘게 썰어야 씹기 편합니다."}]},{"title":"고르는 방법","blocks":[{"kind":"list","items":[{"text":"노란빛이 고르고 유자 향이 나는 것을 고르세요."},{"text":"껍질에 깊은 상처나 눌린 곳이 없는지 보세요."},{"text":"청을 담글 때는 껍질이 심하게 마른 것을 피하세요."}]}]},{"title":"보관 및 손질법","blocks":[{"kind":"list","items":[{"label":"보관법","text":"통유자는 물기를 닦아 냉장하세요. 나중에 양념으로 쓸 즙은 작은 틀에 나눠 얼릴 수 있습니다."},{"label":"손질법","text":"흐르는 물로 껍질을 씻고 가른 뒤 씨를 빼세요."}]}]},{"title":"추천 요리","blocks":[{"kind":"list","items":[{"text":"유자차. 얇게 썬 유자로 만든 청을 물에 풀어 마십니다."},{"text":"유자 드레싱. 유자즙을 기름과 섞어 잎채소에 곁들입니다."}]}]},{"title":"품종과 유통 특성","blocks":[{"kind":"paragraph","text":"국립민속박물관은 유자를 국내에서 산업적으로 재배하는 재래 감귤류로 소개합니다. 껍질을 많이 쓰는 청에는 과피 상태를, 드레싱에는 과즙 향을 먼저 보세요."}]}],"sources":[{"org":"농림수산식품교육문화정보원","title":"제철농식품 ‘유자’","url":"https://www.foodnuri.go.kr/portal/bbs/B0000283/view.do?menuNo=300063&nttId=219901","checkedAt":"2026-11-12"},{"org":"국립민속박물관","title":"한국민속대백과사전 ‘유자’","url":"https://folkency.nfm.go.kr/topic/%EC%9C%A0%EC%9E%90","checkedAt":"2026-11-12"},{"org":"전라남도 귀농산어촌 종합지원센터","title":"완도 유자 수확","url":"https://jnfarm.jeonnam.go.kr/board/FARM_BOARD_008/boardView.do?bdId=BD_00000000000014133&menuCd=farm004002","checkedAt":"2026-11-12"}]},
}
